def _atomic_write_text(path, text, encoding="utf-8"):
    """V30.38: запись через временный файл + os.replace.
    При сбое/нехватке места старый файл остаётся целым (не обрезается до 0 байт)."""
    path = Path(path)
    tmp = path.with_name(path.name + ".tmp")
    with open(tmp, "w", encoding=encoding) as fh:
        fh.write(text)
        fh.flush()
        try:
            os.fsync(fh.fileno())
        except OSError:
            pass
    os.replace(tmp, path)


_PADDLE_OCR_ENGINE = None

def _get_paddle_ocr():
    """V30.38: PaddleOCR загружается один раз на процесс (раньше — при каждом вызове OCR)."""
    global _PADDLE_OCR_ENGINE
    if _PADDLE_OCR_ENGINE is None:
        from paddleocr import PaddleOCR
        try:
            _PADDLE_OCR_ENGINE = PaddleOCR(lang="ru")
        except Exception:
            _PADDLE_OCR_ENGINE = PaddleOCR(lang="en")
    return _PADDLE_OCR_ENGINE


