MONTHS = {
    "января": 1, "февраля": 2, "марта": 3, "апреля": 4,
    "мая": 5, "июня": 6, "июля": 7, "августа": 8,
    "сентября": 9, "октября": 10, "ноября": 11, "декабря": 12,
}


@dataclass
class RowData:
    # Текущие/effective значения, которые отображаются в таблице и экспортах.
    position: str = ""
    recognition_seconds: str = ""
    buyer: str = ""
    supplier: str = ""
    date: str = ""
    invoice: str = ""
    item: str = ""
    qty: str = ""
    unit: str = ""
    price: str = ""
    amount: str = ""

    # Явная связь позиции с исходным документом.
    source_path: str = ""
    source_file_id: str = ""
    page_number: int = 0
    bbox: object = None

    # Контроль качества.
    confidence: int = 0
    validation_errors: object = None

    # Исходные автоматические значения. Ручные правки хранятся отдельно.
    original_item: str = ""
    original_qty: str = ""
    original_unit: str = ""
    original_price: str = ""
    original_amount: str = ""
    manual_item: str = ""
    manual_qty: str = ""
    manual_unit: str = ""
    manual_price: str = ""
    manual_amount: str = ""
    edited_fields: object = None
    is_manual_edited: bool = False
    is_manual_added: bool = False
    conflict: bool = False

    def __post_init__(self):
        if self.validation_errors is None:
            self.validation_errors = []
        if self.edited_fields is None:
            self.edited_fields = []
        if self.bbox in ("", None):
            self.bbox = None
        # Ручная строка не имеет OCR-оригинала: не подменять original_* effective-значениями.
        if self.is_manual_added:
            return
        # Старые проекты не содержат original_*. Заполняем их текущим авто-значением.
        for field_name in ("item", "qty", "unit", "price", "amount"):
            original_name = "original_" + field_name
            if not getattr(self, original_name, ""):
                setattr(self, original_name, str(getattr(self, field_name, "") or ""))


def source_file_id_for_path(path) -> str:
    """Стабильный ID документа; не зависит от поставщика/номера счета."""
    try:
        key = os.path.normcase(os.path.abspath(str(path)))
    except Exception:
        key = str(path)
    return hashlib.sha1(key.encode("utf-8", errors="ignore")).hexdigest()[:20]


def clean(s: str) -> str:
    return re.sub(r"\s+", " ", (s or "").replace("\xa0", " ")).strip()


def normalize_date(s: str) -> str:
    s = clean(s).lower().replace("г.", "").strip()

    m = re.search(r"(\d{1,2})[./-](\d{1,2})[./-](\d{4})", s)
    if m:
        d, mo, y = map(int, m.groups())
        try:
            return datetime(y, mo, d).strftime("%d.%m.%Y")
        except ValueError:
            return s

    m = re.search(
        r"(\d{1,2})\s+(" + "|".join(MONTHS) + r")\s+(\d{4})",
        s,
        flags=re.I,
    )
    if m:
        d = int(m.group(1))
        mo = MONTHS[m.group(2)]
        y = int(m.group(3))
        return datetime(y, mo, d).strftime("%d.%m.%Y")

    return s


def company_name(s: str) -> str:
    """Нормализует название организации/ИП без ИНН, КПП и адреса."""
    s = clean(s).replace("«", '"').replace("»", '"')

    s = re.sub(
        r"\bОБЩЕСТВО\s+С\s+ОГРАНИЧЕННОЙ\s+ОТВЕТСТВЕННОСТЬЮ\b",
        "ООО", s, flags=re.I
    )
    s = re.sub(
        r"\bОбщество\s+с\s+ограниченной\s+ответственностью\b",
        "ООО", s, flags=re.I
    )
    s = re.sub(
        r"\bИндивидуальный\s+предприниматель\b",
        "ИП", s, flags=re.I
    )

    # Реквизиты до названия.
    s = re.sub(r"^ИНН[: ]*\d+[,\s]*", "", s, flags=re.I)
    s = re.sub(r"^КПП[: ]*\d+[,\s]*", "", s, flags=re.I)
    s = re.sub(
        r"^ИНН\s+\d+[,\s]+КПП\s+\d+[,\s]+",
        "", s, flags=re.I
    )

    patterns = [
        r'(ИП\s+[А-ЯЁA-Z][^,;\n]+)',
        r'(ООО\s+(?:ТД\s+)?\"[^\"]+\")',
        r'(ООО\s+[А-ЯЁA-Z0-9][^,;\n]+)',
        r'(АО\s+\"[^\"]+\")',
        r'(АО\s+[А-ЯЁA-Z0-9][^,;\n]+)',
        r'(Интернет Решения,\s*ООО)',
        r'(П10\s+РУ\s+ООО)',
    ]
    for p in patterns:
        m = re.search(p, s, flags=re.I)
        if m:
            return clean(m.group(1)).strip(" ,;:")

    s = re.split(
        r",?\s+(?:ИНН|КПП|\d{6},|г\.|ул\.|пр-кт|дом\s|тел\.)",
        s, maxsplit=1, flags=re.I
    )[0]
    return clean(s).strip(" ,;:")

def extract_meta(text: str) -> dict:
    """Извлекает покупателя, поставщика, дату и номер счета."""
    flat = clean(text)
    lines = [clean(x) for x in text.splitlines() if clean(x)]

    invoice = ""
    date = ""

    invoice_patterns = [
        r'(?:Счет|Счёт|СЧЕТ)(?:-Оферта)?(?:\s+на\s+оплату)?\s*№\s*'
        r'([A-Za-zА-Яа-яЁё0-9._/-]+)\s+от\s+'
        r'([0-9]{1,2}(?:[./-][0-9]{1,2}[./-][0-9]{4}|\s+[А-Яа-яЁё]+\s+[0-9]{4})(?:\s*г\.?)?)',
        r'Оплата\s+по\s+заказу\s+([A-Za-zА-Яа-яЁё0-9._/-]+)\s+от\s+'
        r'([0-9]{1,2}[./-][0-9]{1,2}[./-][0-9]{4})',
    ]
    for p in invoice_patterns:
        m = re.search(p, flat, flags=re.I)
        if m:
            invoice = clean(m.group(1))
            date = normalize_date(m.group(2))
            break

    def after_label(labels, reject=""):
        for i, line in enumerate(lines):
            low = line.lower()
            if any(low.startswith(lbl) for lbl in labels):
                # Значение может быть на той же строке.
                raw = re.sub(
                    r"^(?:Поставщик|Покупатель|Плательщик|Получатель)"
                    r"(?:\s*\([^)]*\))?\s*:?\s*",
                    "", line, flags=re.I
                )
                candidates = []
                if raw and raw.lower() not in {"поставщик", "покупатель", "плательщик", "получатель"}:
                    candidates.append(raw)
                candidates.extend(lines[i + 1:i + 7])

                # Склеиваем соседние строки, если юр. название разорвано переносом.
                # Для строки с незакрытой кавычкой сначала пробуем склеенный вариант.
                joined = []
                for j, c in enumerate(candidates):
                    if j + 1 < len(candidates) and c.count('"') % 2 == 1:
                        joined.append(c + " " + candidates[j + 1])
                    joined.append(c)
                    if j + 1 < len(candidates) and c.count('"') % 2 == 0:
                        joined.append(c + " " + candidates[j + 1])

                for c in joined:
                    if reject and reject.lower() in c.lower():
                        continue
                    if (
                        re.search(r"\b(?:ООО|АО|ИП)\b", c, flags=re.I)
                        or re.search(r"Общество\s+с\s+ограниченной\s+ответственностью", c, flags=re.I)
                        or re.search(r"Индивидуальный\s+предприниматель", c, flags=re.I)
                        or "Интернет Решения" in c
                        or re.search(r"\bП10\s+РУ\s+ООО\b", c, flags=re.I)
                    ):
                        name = company_name(c)
                        if name and "банк" not in name.lower():
                            return name
        return ""

    supplier = after_label(["поставщик"])

    # Если поставщика нет, ищем получателя в банковском блоке.
    if not supplier:
        for i, line in enumerate(lines):
            if line.lower() == "получатель":
                for c in lines[max(0, i - 4):i + 5]:
                    if (
                        re.search(r"\b(?:ООО|АО|ИП)\b", c, flags=re.I)
                        or re.search(r"Общество\s+с\s+ограниченной\s+ответственностью", c, flags=re.I)
                        or re.search(r"Индивидуальный\s+предприниматель", c, flags=re.I)
                    ):
                        name = company_name(c)
                        if name and "банк" not in name.lower():
                            supplier = name
                            break
                if supplier:
                    break

    buyer = after_label(["покупатель", "плательщик"], reject=supplier)

    # Универсальные fallback'и.
    if not supplier and "Интернет Решения" in flat:
        supplier = "Интернет Решения, ООО"

    if not buyer:
        orgs = []
        for line in lines:
            if (
                re.search(r"\bИНН\b", line, flags=re.I)
                and (
                    re.search(r"\b(?:ООО|АО|ИП)\b", line, flags=re.I)
                    or re.search(r"Общество\s+с\s+ограниченной\s+ответственностью", line, flags=re.I)
                    or re.search(r"Индивидуальный\s+предприниматель", line, flags=re.I)
                )
            ):
                name = company_name(line)
                if name and "банк" not in name.lower():
                    orgs.append(name)
        for name in orgs:
            if clean(name).lower() != clean(supplier).lower():
                buyer = name
                break

    return {
        "buyer": buyer,
        "supplier": supplier,
        "date": date,
        "invoice": invoice,
    }

def extract_pdf_text(path: Path) -> str:
    try:
        import fitz
    except ImportError:
        raise RuntimeError("Установите PyMuPDF: pip install pymupdf")

    doc = fitz.open(path)
    try:
        return "\n".join(page.get_text("text") for page in doc)
    finally:
        doc.close()


def extract_pdf_text_with_ocr(path: Path, force: bool = False) -> str:
    text = extract_pdf_text(path)

    # Если в PDF есть нормальный текстовый слой — OCR не нужен, кроме force=True.
    if not force and len(re.findall(r"[A-Za-zА-Яа-яЁё]", text)) > 100:
        return text

    try:
        import fitz
        import numpy as np
        from PIL import Image
        from paddleocr import PaddleOCR
    except ImportError:
        raise RuntimeError(
            "PDF является сканом. Для OCR установите:\n"
            "pip install paddleocr paddlepaddle pillow numpy"
        )

    ocr = _get_paddle_ocr()

    doc = fitz.open(path)
    result_lines = []
    try:
        for page in doc:
            pix = page.get_pixmap(matrix=fitz.Matrix(2, 2), alpha=False)
            img = Image.frombytes("RGB", [pix.width, pix.height], pix.samples)
            arr = np.array(img)

            try:
                result = ocr.ocr(arr)
                for group in result or []:
                    for line in group or []:
                        if len(line) >= 2:
                            result_lines.append(str(line[1][0]))
            except Exception:
                pass
    finally:
        doc.close()

    return "\n".join(result_lines)


def extract_items_generic(text: str) -> list[tuple[str, str]]:
    """Обычный случай: вся товарная строка находится в одной строке текста."""
    rows = []
    lines = [clean(x) for x in text.splitlines() if clean(x)]

    for line in lines:
        m = re.match(
            r"^\d+\s+(.+?)\s+(\d+(?:[.,]\d+)?)\s*(?:шт\.?|pcs\.?)\b",
            line,
            flags=re.I,
        )
        if m:
            rows.append((clean(m.group(1)), m.group(2).replace(",", ".")))

    return rows


def extract_items_vertical_table(text: str) -> list[tuple[str, str]]:
    """
    Макет №1: PDF-таблица читается PyMuPDF по колонкам.
    Пример: счет крепежа №9303.
    """
    pattern = re.compile(
        r"(?:^|\n)\s*(\d+(?:[.,]\d+)?)\s*\n"
        r"\s*(?:шт\.?|pcs\.?|уп\.?|упак\.?)\s*\n"
        r"\s*(.+?)\s*\n"
        r"\s*(\d{1,4})\s*\n"
        r"\s*([A-Za-zА-Яа-яЁё0-9._/-]{3,})\s*(?=\n|$)",
        flags=re.I | re.S,
    )

    rows = []
    for m in pattern.finditer(text):
        qty = m.group(1).replace(",", ".")
        name = clean(m.group(2))
        if name and not name.lower().startswith(("итого", "в том числе", "расчетный вес")):
            rows.append((name, qty))
    return rows


def extract_items_ledcapital(text: str) -> list[tuple[str, str]]:
    """
    Макет №2: LED Capital / ИП Мухамеджанов.
    Наименование начинается с номера позиции, количество находится на следующей строке.
    """
    lines = [clean(x) for x in text.splitlines() if clean(x)]
    rows = []

    for i, line in enumerate(lines):
        m = re.match(r"^(\d+)\s+(.+)$", line)
        if not m:
            continue

        # Отсекаем пункты текста вне товарной таблицы.
        if not re.search(r"[A-Za-zА-Яа-яЁё]", m.group(2)):
            continue

        if i + 1 < len(lines) and re.fullmatch(r"\d+(?:[.,]\d+)?", lines[i + 1]):
            # После количества должна быть единица "шт".
            if i + 2 < len(lines) and re.fullmatch(r"шт\.?", lines[i + 2], flags=re.I):
                rows.append((clean(m.group(2)), lines[i + 1].replace(",", ".")))

    return rows


def extract_items_tayle(text: str) -> list[tuple[str, str]]:
    """
    Макет №3: Тайле Рус.
    Позиция занимает много строк:
    № -> артикул (1-2 строки) -> описание (несколько строк) -> '4 шт'.
    """
    lines = [clean(x) for x in text.splitlines() if clean(x)]
    rows = []

    try:
        start = next(i for i, x in enumerate(lines) if x.lower() == "сумма") + 1
    except StopIteration:
        return rows

    # Ограничиваем товарный блок до "Итого".
    end = next(
        (i for i in range(start, len(lines)) if lines[i].lower().startswith("итого")),
        len(lines),
    )
    block = lines[start:end]

    # Индексы отдельных строк "1", "2", ...
    position_starts = [
        i for i, x in enumerate(block)
        if re.fullmatch(r"\d{1,3}", x)
    ]

    for k, pos in enumerate(position_starts):
        next_pos = position_starts[k + 1] if k + 1 < len(position_starts) else len(block)
        part = block[pos + 1:next_pos]

        qty_idx = -1
        qty = ""
        for j, x in enumerate(part):
            m = re.fullmatch(r"(\d+(?:[.,]\d+)?)\s*шт\.?", x, flags=re.I)
            if m:
                qty_idx = j
                qty = m.group(1).replace(",", ".")
                break

        if qty_idx < 0:
            continue

        before_qty = part[:qty_idx]
        if not before_qty:
            continue

        # Артикул идет первым и часто разбит переносом.
        # Описание ищем с первой строки, явно похожей на русское товарное описание.
        desc_start = None
        for j, x in enumerate(before_qty):
            if re.search(r"[А-Яа-яЁё]{3,}", x):
                desc_start = j
                break

        if desc_start is None:
            continue

        name = clean(" ".join(before_qty[desc_start:]))
        if name:
            rows.append((name, qty))

    return rows


def extract_items_ozon(text: str) -> list[tuple[str, str]]:
    """
    Макет №4: Ozon.
    Наименование многострочное, далее категория, цена, количество, единица.
    """
    lines = [clean(x) for x in text.splitlines() if clean(x)]
    rows = []

    try:
        start = next(i for i, x in enumerate(lines) if x.lower() == "сумма") + 1
    except StopIteration:
        return rows

    end = next(
        (i for i in range(start, len(lines)) if lines[i].lower().startswith("итого")),
        len(lines),
    )
    block = lines[start:end]

    # Сейчас счет Ozon может содержать несколько позиций.
    # Начало позиции: "1 <название>" либо отдельный "1".
    i = 0
    while i < len(block):
        m_inline = re.match(r"^(\d+)\s+(.+)$", block[i])
        m_only = re.fullmatch(r"\d+", block[i])

        if not (m_inline or m_only):
            i += 1
            continue

        if m_inline:
            name_parts = [m_inline.group(2)]
            i += 1
        else:
            name_parts = []
            i += 1

        # Идем до количества+шт. Цена может быть отдельной строкой перед количеством.
        qty = ""
        while i < len(block):
            if re.fullmatch(r"\d+(?:[.,]\d+)?", block[i]):
                # Если следующая строка "шт.", это количество.
                if i + 1 < len(block) and re.fullmatch(r"шт\.?", block[i + 1], flags=re.I):
                    qty = block[i].replace(",", ".")
                    i += 2
                    break

                # Число с двумя десятичными часто цена — не включаем в имя.
                if re.fullmatch(r"\d[\d ]*[,.]\d{2}", block[i]):
                    i += 1
                    continue

            # Категорию Ozon стараемся не включать в название.
            low = block[i].lower()
            if low in {"электроника и", "электротовары", "электроника и электротовары"}:
                i += 1
                continue

            name_parts.append(block[i])
            i += 1

        name = clean(" ".join(name_parts))
        if name and qty:
            rows.append((name, qty))

    return rows


TABLE_UNITS_RE = (
    r"(?:шт\.?|pcs\.?|м2|м²|м|пог\.?\s*м|куб\.?\s*м|рул\.?|"
    r"упак\.?|уп\.?|компл\.?|кг|л|пач\.?)"
)

def _is_probable_code_line(s: str) -> bool:
    s = clean(s)
    if not s or len(s) > 45:
        return False
    if re.search(r"[А-Яа-яЁё]{4,}", s):
        return False
    return bool(re.fullmatch(r"[A-Za-zА-Яа-яЁё0-9._/-]+", s))


def extract_items_sequential_table(text: str) -> list[tuple[str, str]]:
    """
    Универсальный парсер типовых российских счетов.
    Работает с PDF, где PyMuPDF читает таблицу последовательностью:
    № -> наименование -> количество/единица -> цена -> сумма.
    Поддерживает многострочные наименования, артикулы и колонки НДС.
    """
    lines = [clean(x) for x in text.splitlines() if clean(x)]
    if not lines:
        return []

    header_keys = (
        "товары (работы, услуги)",
        "наименование товара",
        "название товара или услуги",
        "товар (услуга)",
    )
    header_positions = [
        i for i, x in enumerate(lines)
        if any(k in x.lower() for k in header_keys)
    ]
    start = header_positions[0] + 1 if header_positions else 0

    end = next(
        (
            i for i in range(start, len(lines))
            if re.match(
                r"^(?:Итого|Всего\s+к\s+оплате|Всего\s+наименований)",
                lines[i], flags=re.I
            )
        ),
        len(lines),
    )
    block = lines[start:end]

    qty_num = r"\d[\d ]*(?:[.,]\d+)?"
    rows = []
    expected = 1
    i = 0

    while i < len(block):
        line = block[i]
        item_first = ""

        if line == str(expected):
            pass
        else:
            m_inline = re.match(r"^(\d{1,3})\s+(.+)$", line)
            if not (m_inline and int(m_inline.group(1)) == expected):
                i += 1
                continue
            item_first = clean(m_inline.group(2))

        name_parts = [item_first] if item_first else []
        qty = ""
        qty_idx = -1

        j = i + 1
        while j < len(block) and j <= i + 24:
            x = block[j]

            m_same = re.fullmatch(
                rf"({qty_num})\s+({TABLE_UNITS_RE})",
                x, flags=re.I
            )
            if m_same:
                qty = clean(m_same.group(1)).replace(" ", "").replace(",", ".")
                qty_idx = j
                break

            if re.fullmatch(qty_num, x):
                if j + 1 < len(block) and re.fullmatch(TABLE_UNITS_RE, block[j + 1], flags=re.I):
                    qty = x.replace(" ", "").replace(",", ".")
                    qty_idx = j
                    break

            # Только после проверки количества проверяем начало следующей позиции.
            next_inline = re.match(r"^(\d{1,3})\s+(.+)$", x)
            if qty_idx < 0 and (
                x == str(expected + 1)
                or (next_inline and int(next_inline.group(1)) == expected + 1)
            ):
                break

            name_parts.append(x)
            j += 1

        if not qty:
            i += 1
            continue

        cleaned = []
        for x in name_parts:
            if not x:
                continue
            low = x.lower()
            if low in {
                "№", "артикул", "товар", "товары (работы, услуги)",
                "кол-во", "количество", "ед.", "ед", "ед.изм", "ед. изм.",
                "цена", "сумма", "код", "ставка", "ндс", "сумма ндс",
                "без ндс"
            }:
                continue
            if re.fullmatch(r"\d{1,3}", x):
                continue
            if re.fullmatch(r"\d[\d ]*[,.]\d{2}\s*₽?", x):
                continue
            if re.fullmatch(r"(?:Без\s+НДС|\d{1,2}%?)", x, flags=re.I):
                continue
            # Отдельный артикул/код не добавляем к наименованию.
            if _is_probable_code_line(x) and len(name_parts) > 1:
                continue
            cleaned.append(x)

        name = clean(" ".join(cleaned))
        if name:
            rows.append((name, qty))
            expected += 1
            i = qty_idx + 1
        else:
            i += 1

    return rows


def _num_value(value):
    """Преобразует число российского формата в float; None если это не число."""
    if value is None:
        return None
    s = clean(str(value)).replace("₽", "").replace("руб.", "").replace("руб", "")
    s = s.replace(" ", "").replace("\u202f", "").replace(",", ".")
    s = re.sub(r"[^0-9.\-]", "", s)
    if not s or s in {"-", "."}:
        return None
    try:
        return float(s)
    except Exception:
        return None


def _norm_unit(value):
    s = clean(str(value or "")).lower().replace("²", "2")
    s = s.replace(".", "")
    aliases = {
        "шт": "шт", "pcs": "шт", "м": "м", "м2": "м²", "пог м": "пог. м",
        "погм": "пог. м", "кг": "кг", "л": "л", "уп": "уп.", "упак": "упак.",
        "упаковка": "упак.", "компл": "компл.", "комплект": "компл.", "пач": "пач.",
        "рул": "рул.", "куб м": "куб. м",
    }
    return aliases.get(s, clean(str(value or "")))


def _bbox_union(boxes):
    boxes = [b for b in boxes if isinstance(b, (list, tuple)) and len(b) == 4]
    if not boxes:
        return None
    return [min(b[0] for b in boxes), min(b[1] for b in boxes),
            max(b[2] for b in boxes), max(b[3] for b in boxes)]


def _group_pdf_words_by_visual_row(words, y_tol=3.5):
    """Группирует PyMuPDF words в визуальные строки по Y, не полагаясь на text order."""
    items=[]
    for w in words or []:
        if len(w) < 5:
            continue
        x0,y0,x1,y1,text = w[:5]
        text=clean(str(text))
        if not text:
            continue
        items.append({"x0":float(x0),"y0":float(y0),"x1":float(x1),"y1":float(y1),
                      "yc":(float(y0)+float(y1))/2.0,"text":text})
    items.sort(key=lambda z:(z["yc"], z["x0"]))
    rows=[]
    for item in items:
        if not rows or abs(item["yc"] - rows[-1]["yc"]) > y_tol:
            rows.append({"yc":item["yc"],"words":[item]})
        else:
            r=rows[-1]
            r["words"].append(item)
            r["yc"] = sum(x["yc"] for x in r["words"])/len(r["words"])
    for r in rows:
        r["words"].sort(key=lambda z:z["x0"])
        r["text"] = clean(" ".join(x["text"] for x in r["words"]))
        r["bbox"] = _bbox_union([[x["x0"],x["y0"],x["x1"],x["y1"]] for x in r["words"]])
    return rows


def _header_column_centers(row):
    """Находит X центры ключевых колонок в строке заголовков таблицы."""
    found={}
    for w in row.get("words", []):
        t=w["text"].lower().strip(" :")
        xc=(w["x0"]+w["x1"])/2.0
        if t in {"№", "n", "no", "#"}:
            found.setdefault("position", xc)
        elif "наимен" in t or "товар" in t or "работ" in t or "услуг" in t:
            found.setdefault("item", xc)
        elif "кол-во" in t or "количество" in t or t in {"кол", "кол."}:
            found.setdefault("qty", xc)
        elif t.startswith("ед") or "изм" in t:
            found.setdefault("unit", xc)
        elif t.startswith("цена"):
            found.setdefault("price", xc)
        elif t.startswith("сумма"):
            # Если есть несколько "Сумма", для amount полезнее крайняя правая.
            found["amount"] = max(found.get("amount", xc), xc)
    return found


def _header_context_forbidden(text):
    """Строки, которые нельзя захватывать в состав объединённого header."""
    low=clean(str(text or "")).lower()
    return bool(re.match(
        r"^(?:основание\b|поставщик\b|покупатель\b|плательщик\b|получатель\b|"
        r"итого\b|всего\b|в\s+том\s+числе\b|ндс\b|банк\b|бик\b|инн\b|кпп\b|сч\.?\s*№)",
        low, flags=re.I
    ))


def _header_candidate_score(row):
    cols=_header_column_centers(row)
    score=sum(k in cols for k in ("item","qty","unit","price","amount"))
    valid=bool("item" in cols and "qty" in cols and score >= 3)
    return valid, score, cols


def _find_coordinate_table_header(rows):
    """Ищет визуальный заголовок товарной таблицы.

    V20.47: полноценная ОДИНОЧНАЯ строка всегда имеет приоритет. Только если ни
    одна одиночная строка не подходит, пробуем объединять соседние строки.
    Это предотвращает захват строки вроде «Основание: Без договора» перед header.
    """
    # Проход 1: только одиночные строки.
    best=None
    for i,row in enumerate(rows):
        valid,score,cols=_header_candidate_score(row)
        if valid and (best is None or score > best[0]):
            best=(score,i,cols,1)
    if best is not None:
        return best

    # Проход 2: объединение допускается лишь если одиночного header нет.
    for i in range(len(rows)-1):
        a,b=rows[i],rows[i+1]
        if abs(b["yc"]-a["yc"]) >= 24:
            continue
        if _header_context_forbidden(a.get("text","")) or _header_context_forbidden(b.get("text","")):
            continue
        merged={"words":a["words"]+b["words"], "text":clean(a.get("text","")+" "+b.get("text",""))}
        valid,score,cols=_header_candidate_score(merged)
        if valid and (best is None or score > best[0]):
            best=(score,i,cols,2)
    return best


def _looks_like_table_header_value(value, field=""):
    low=clean(str(value or "")).lower().replace("ё","е")
    low=re.sub(r"[.:]+$", "", low)
    if not low:
        return False
    exact={
        "товары (работы, услуги)", "товары", "товар", "товар (услуга)",
        "наименование", "наименование товара", "наименование товара или услуги",
        "кол-во", "количество", "ед", "ед изм", "ед. изм", "единица",
        "цена", "сумма", "№", "n", "no", "#"
    }
    if low in exact:
        return True
    if field == "item" and (("товар" in low and ("услуг" in low or "работ" in low)) or low.startswith("наименование ")):
        return True
    return False


def _is_numeric_token(value):
    s=clean(str(value or ""))
    if not s or re.search(r"[A-Za-zА-Яа-яЁё]", s):
        return False
    return _num_value(s) is not None


def _is_known_unit(value):
    raw=clean(str(value or ""))
    if not raw:
        return False
    norm=_norm_unit(raw)
    return norm in {"шт","м","м²","пог. м","кг","л","уп.","упак.","компл.","пач.","рул.","куб. м"}


def _coordinate_item_validation(item):
    """Базовая типовая валидация одной координатной позиции.

    Структурные ошибки (header вместо data, нечисловой qty/price/amount,
    неизвестная явно указанная единица) являются hard. Арифметическое
    расхождение — soft: оно понижает confidence, но само по себе не уничтожает
    координатный результат.
    """
    hard=[]; soft=[]
    name=clean(item.get("item", "")); qty=clean(item.get("qty", ""))
    unit=clean(item.get("unit", "")); price=clean(item.get("price", "")); amount=clean(item.get("amount", ""))
    if not name:
        hard.append("item is empty")
    if _looks_like_table_header_value(name, "item"):
        hard.append("item is table header")
    if _looks_like_table_header_value(qty, "qty") or not _is_numeric_token(qty):
        hard.append("qty is not numeric")
    if unit and (_looks_like_table_header_value(unit, "unit") or not _is_known_unit(unit)):
        hard.append("unit is not recognized")
    if price and (_looks_like_table_header_value(price, "price") or not _is_numeric_token(price)):
        hard.append("price is not numeric")
    if amount and (_looks_like_table_header_value(amount, "amount") or not _is_numeric_token(amount)):
        hard.append("amount is not numeric")
    q,p,a=_num_value(qty),_num_value(price),_num_value(amount)
    arithmetic=None
    if q is not None and p is not None and a is not None:
        arithmetic=abs(q*p-a) <= max(0.05,abs(a)*0.003)
        if not arithmetic:
            soft.append("qty × price != amount")
    return (not hard), hard+soft, arithmetic

def _validate_coordinate_result(items, text=""):
    """Валидация всего coordinate-result перед тем, как он станет финальным."""
    if not items:
        return False, ["no coordinate positions"], 0
    reasons=[]; valid_rows=0; arith=[]
    for idx,item in enumerate(items, start=1):
        ok,errs,aok=_coordinate_item_validation(item)
        if ok: valid_rows += 1
        else: reasons.append(f"row {idx}: " + "; ".join(errs))
        if aok is not None: arith.append(aok)
    declared=_extract_declared_item_count(text)
    if declared is not None and declared != len(items):
        reasons.append(f"declared positions {declared}, coordinate found {len(items)}")
    score=0
    if valid_rows == len(items): score += 60
    else: score += int(60 * valid_rows / max(1,len(items)))
    if declared is not None:
        score += 25 if declared == len(items) else 0
    else:
        score += 10
    if arith:
        score += 15 if all(arith) else 0
    else:
        score += 10
    # declared-count mismatch is suspicious, but not a structural corruption by itself.
    # If the V20.44 fallback finds the same count, keeping coordinate preserves unit/price/amount/bbox.
    hard_invalid=valid_rows != len(items)
    return (not hard_invalid), reasons, min(100,score)

def _assign_words_to_columns(words, centers):
    order=[k for k in ("position","item","qty","unit","price","amount") if k in centers]
    if not order:
        return {}
    order.sort(key=lambda k:centers[k])
    boundaries=[]
    for a,b in zip(order,order[1:]):
        boundaries.append((centers[a]+centers[b])/2.0)
    out={k:[] for k in order}
    for w in words:
        # Для длинных наименований используем начало слова, а не его центр:
        # последнее слово названия может визуально заходить в соседнюю колонку,
        # но его x0 всё ещё принадлежит колонке Наименование.
        probe=float(w["x0"])
        idx=0
        while idx < len(boundaries) and probe > boundaries[idx]:
            idx+=1
        out[order[idx]].append(w)

    # Узкая колонка № и широкая колонка Наименование часто дают границу,
    # которая режет первое длинное слово названия. В колонке position оставляем
    # только фактический номер строки, а текст переносим обратно в item.
    if "position" in out and "item" in out:
        keep=[]; move=[]
        for w in out["position"]:
            if re.fullmatch(r"\d{1,3}", clean(w.get("text", ""))):
                keep.append(w)
            else:
                move.append(w)
        if move:
            out["position"]=keep
            out["item"] = sorted(move + out["item"], key=lambda z:z["x0"])

    return {k: clean(" ".join(x["text"] for x in vals)) for k,vals in out.items()}


def _extract_coordinate_items_from_pages(page_words):
    """Общий координатный парсер для PyMuPDF words и OCR bbox."""
    result=[]
    for page_index, words in enumerate(page_words):
        visual_rows=_group_pdf_words_by_visual_row(words)
        header=_find_coordinate_table_header(visual_rows)
        if not header:
            continue
        _, header_idx, centers, header_span=header
        current=None; expected=1
        for vr in visual_rows[header_idx+header_span:]:
            low=vr["text"].lower()
            if re.match(r"^(итого|всего\s+к\s+оплате|всего\s+наименований|в\s+том\s+числе\s+ндс)", low):
                break
            # Повторный header (например, на новой странице) никогда не является товаром.
            hdr_ok,_,_=_header_candidate_score(vr)
            if hdr_ok:
                continue
            fields=_assign_words_to_columns(vr["words"], centers)
            pos=clean(fields.get("position", "")); item=clean(fields.get("item", "")); qty=clean(fields.get("qty", ""))
            unit=_norm_unit(fields.get("unit", "")); price=clean(fields.get("price", "")); amount=clean(fields.get("amount", ""))
            if (_looks_like_table_header_value(item,"item") or _looks_like_table_header_value(qty,"qty") or
                _looks_like_table_header_value(unit,"unit") or _looks_like_table_header_value(price,"price") or
                _looks_like_table_header_value(amount,"amount")):
                continue
            if qty and not re.fullmatch(r"[\d\s]+(?:[.,]\d+)?", qty):
                mq=re.match(r"^(.*?)(\d+(?:[.,]\d+)?)$", qty)
                if mq and re.search(r"[A-Za-zА-Яа-яЁё]", mq.group(1)):
                    item=clean(item+" "+mq.group(1)); qty=mq.group(2)
            mpos=re.search(r"\b(\d{1,3})\b", pos)
            starts_new=bool(mpos and (int(mpos.group(1))==expected or current is None))
            if not starts_new and current is None and item and qty:
                starts_new=True; mpos=None
            if starts_new:
                if current and current.get("item"): result.append(current)
                current={"position":str(int(mpos.group(1))) if mpos else str(expected),
                         "item":item,"qty":qty.replace(" ","").replace(",","."),"unit":unit,
                         "price":price,"amount":amount,"page_number":page_index,"bbox":vr["bbox"]}
                expected=(int(current["position"])+1) if current["position"].isdigit() else expected+1
            elif current is not None:
                if item and not qty and not price and not amount:
                    current["item"]=clean(current.get("item","")+" "+item)
                    current["bbox"]=_bbox_union([current.get("bbox"),vr.get("bbox")])
                else:
                    for key,val in (("qty",qty),("unit",unit),("price",price),("amount",amount)):
                        if val and not current.get(key):
                            current[key]=val; current["bbox"]=_bbox_union([current.get("bbox"),vr.get("bbox")])
        if current and current.get("item"): result.append(current)
    return result

def extract_items_coordinate_table(path: Path):
    """Координатный парсер текстового слоя PDF."""
    try:
        import fitz
    except ImportError:
        return []
    doc=fitz.open(path)
    try:
        return _extract_coordinate_items_from_pages([page.get_text("words") for page in doc])
    finally:
        doc.close()


def extract_pdf_ocr_bundle(path: Path):
    """OCR скана с сохранением bbox. Возвращает (text, page_words).

    Координаты PaddleOCR переводятся обратно из 2x raster в координаты PDF.
    При несовместимой версии PaddleOCR вызывающий код может использовать старый текстовый fallback.
    """
    import fitz
    import numpy as np
    from PIL import Image
    from paddleocr import PaddleOCR
    ocr=_get_paddle_ocr()
    doc=fitz.open(path); all_text=[]; pages=[]; zoom=2.0
    try:
        for page in doc:
            pix=page.get_pixmap(matrix=fitz.Matrix(zoom,zoom),alpha=False)
            img=Image.frombytes("RGB",[pix.width,pix.height],pix.samples); arr=np.array(img)
            result=ocr.ocr(arr)
            words=[]
            for group in result or []:
                for line in group or []:
                    try:
                        box=line[0]; payload=line[1]
                        txt=str(payload[0] if isinstance(payload,(list,tuple)) else payload)
                        if not txt: continue
                        xs=[float(pt[0]) for pt in box]; ys=[float(pt[1]) for pt in box]
                        x0,y0,x1,y1=min(xs)/zoom,min(ys)/zoom,max(xs)/zoom,max(ys)/zoom
                        words.append((x0,y0,x1,y1,txt,0,0,0)); all_text.append(txt)
                    except Exception:
                        continue
            pages.append(words)
    finally:
        doc.close()
    return "\n".join(all_text), pages


def _extract_declared_item_count(text):
    patterns=[
        r"Всего\s+наименований\s*[:\-]?\s*(\d+)",
        r"Всего\s+(\d+)\s+наименован",
    ]
    for pat in patterns:
        m=re.search(pat, text or "", flags=re.I)
        if m:
            try: return int(m.group(1))
            except Exception: pass
    return None


def _extract_document_total(text):
    lines=[clean(x) for x in (text or "").splitlines() if clean(x)]
    for line in reversed(lines):
        m=re.search(r"^(?:Итого|Всего\s+к\s+оплате)\s*:?\s*([\d\s]+[,.]\d{2})", line, flags=re.I)
        if m:
            return _num_value(m.group(1))
    return None


def _row_has_hard_validation_error(row):
    for e in list(getattr(row, "validation_errors", []) or []):
        low=str(e).lower()
        if "количество × цена" in low or "единица измерения" in low or "конфликт" in low:
            return True
    return False


def validate_invoice_rows(rows, text="", meta=None):
    """Валидация строк + confidence 0..100. Не удаляет сомнительные позиции."""
    meta=meta or {}
    declared=_extract_declared_item_count(text)
    doc_total=_extract_document_total(text)
    all_arith=[]
    amounts=[]
    units_ok=[]
    for row in rows:
        errors=[]
        q=_num_value(row.qty); p=_num_value(row.price); a=_num_value(row.amount)
        arith=None
        if q is not None and p is not None and a is not None:
            tol=max(0.05, abs(a)*0.003)
            arith=abs(q*p-a) <= tol
            if not arith:
                errors.append("Количество × Цена ≠ Сумма")
            all_arith.append(arith)
        if a is not None: amounts.append(a)
        norm_u=_norm_unit(row.unit)
        if norm_u:
            row.unit=norm_u; units_ok.append(True)
        elif row.unit:
            units_ok.append(False); errors.append("Неизвестная единица измерения")
        elif row.qty:
            units_ok.append(False); errors.append("Единица измерения не определена")
        score=40
        if arith is True: score += 30
        elif arith is None: score += 10
        if norm_u: score += 10
        if meta.get("invoice") or row.invoice: score += 10
        if meta.get("date") or row.date: score += 10
        row.validation_errors=errors
        row.confidence=max(0,min(100,score))

    file_score=0
    file_errors=[]
    if declared is not None:
        if declared == len(rows): file_score += 30
        else: file_errors.append(f"Всего наименований: {declared}, найдено: {len(rows)}")
    else:
        file_score += 15
    if all_arith:
        if all(all_arith): file_score += 30
        else: file_errors.append("Есть строки с ошибкой Количество × Цена")
    else:
        file_score += 15
    if doc_total is not None and amounts:
        if abs(sum(amounts)-doc_total) <= max(0.1, abs(doc_total)*0.003): file_score += 20
        else: file_errors.append("Сумма позиций не совпадает с Итого")
    else:
        file_score += 10
    if rows and all(bool(_norm_unit(r.unit)) for r in rows): file_score += 10
    elif any(r.unit for r in rows): file_score += 5
    if meta.get("invoice") and meta.get("date"): file_score += 10
    elif meta.get("invoice") or meta.get("date"): file_score += 5
    file_score=max(0,min(100,file_score))
    for row in rows:
        # Файловая уверенность ограничивает строковую: неполный документ не должен выглядеть "зелёным".
        row.confidence=min(row.confidence or 100, file_score)
        for e in file_errors:
            if e not in row.validation_errors:
                row.validation_errors.append(e)
    return file_score, file_errors, declared, doc_total


_LAST_PARSER_LOG=[]

def _parser_log_reset():
    global _LAST_PARSER_LOG
    _LAST_PARSER_LOG=[]

def _parser_log(message):
    global _LAST_PARSER_LOG
    _LAST_PARSER_LOG.append(str(message))

def get_last_parser_log():
    return list(_LAST_PARSER_LOG)


def _build_text_fallback_rows(text, meta):
    """Старая проверенная цепочка V20.44, сохранённая без vendor-specific новых правил."""
    low=(text or "").lower(); items=[]; parser_name=""
    if "мухамеджанов" in low or "ledcapital" in low:
        items=extract_items_ledcapital(text); parser_name="ledcapital"
    elif "тайле рус" in low:
        items=extract_items_tayle(text); parser_name="tayle"
    elif "ozon" in low or "интернет решения" in low or "счет-оферта" in low:
        items=extract_items_ozon(text); parser_name="ozon"
    elif "инструменты на горской" in low:
        items=extract_items_vertical_table(text); parser_name="vertical-special"
    if not items:
        items=extract_items_sequential_table(text); parser_name="sequential" if items else parser_name
    if not items:
        items=extract_items_generic(text); parser_name="generic" if items else parser_name
    if not items:
        items=extract_items_vertical_table(text); parser_name="vertical" if items else parser_name
    rows=[RowData(position=str(n), buyer=meta.get("buyer", ""), supplier=meta.get("supplier", ""),
                  date=meta.get("date", ""), invoice=meta.get("invoice", ""), item=name, qty=qty)
          for n,(name,qty) in enumerate(items,start=1)]
    return rows, (parser_name or "none")


def _basic_text_rows_valid(rows):
    if not rows: return False
    for r in rows:
        if not clean(r.item) or _looks_like_table_header_value(r.item,"item"):
            return False
        if not _is_numeric_token(r.qty):
            return False
    return True


def _choose_parser_result(coordinate_rows, coordinate_ok, coordinate_score, text_rows, text_name, text, coord_reasons):
    """Выбирает coordinate или V20.44 fallback на основании структуры и declared count."""
    declared=_extract_declared_item_count(text)
    text_ok=_basic_text_rows_valid(text_rows)
    if not coordinate_ok:
        return text_rows if text_ok else coordinate_rows, (text_name if text_ok else "coordinate")
    if not text_ok:
        return coordinate_rows, "coordinate"
    c_count=len(coordinate_rows); t_count=len(text_rows)
    if declared is not None:
        c_match=(c_count==declared); t_match=(t_count==declared)
        if c_match and not t_match: return coordinate_rows,"coordinate"
        if t_match and not c_match: return text_rows,text_name
    if c_count == t_count:
        return coordinate_rows,"coordinate"
    # Если coordinate нашёл меньше строк, а старый parser больше и нет подтверждения declared,
    # безопаснее сохранить полноту старой логики. Если coordinate нашёл больше — оставляем его,
    # но итоговая validation/confidence отметит расхождение при наличии контрольных сумм.
    if c_count < t_count:
        return text_rows,text_name
    return coordinate_rows,"coordinate"


def parse_pdf(path: Path) -> list[RowData]:
    _parser_log_reset()
    text=extract_pdf_text(path)
    meta=extract_meta(text)
    letters=len(re.findall(r"[A-Za-zА-Яа-яЁё]", text))
    coordinate_items=[]

    if letters >= 100:
        _parser_log("[OCR] PDF text layer OK")
        try:
            coordinate_items=extract_items_coordinate_table(path)
            _parser_log(f"[OCR] Coordinate parser: {len(coordinate_items)} candidate(s)")
        except Exception as exc:
            coordinate_items=[]
            _parser_log(f"[OCR] Coordinate parser error: {type(exc).__name__}: {exc}")
    else:
        _parser_log("[OCR] PDF text layer insufficient — OCR required")
        try:
            text,ocr_pages=extract_pdf_ocr_bundle(path)
            coordinate_items=_extract_coordinate_items_from_pages(ocr_pages)
            _parser_log(f"[OCR] OCR coordinate parser: {len(coordinate_items)} candidate(s)")
        except Exception as exc:
            _parser_log(f"[OCR] OCR coordinate parser error: {type(exc).__name__}: {exc}")
            text=extract_pdf_text_with_ocr(path, force=True)
            coordinate_items=[]
        meta=extract_meta(text)

    if letters >= 100 and (not meta.get("buyer") or not meta.get("supplier")):
        try:
            ocr_text=extract_pdf_text_with_ocr(path, force=True)
            combined=text+"\n"+ocr_text
            ocr_meta=extract_meta(combined)
            if ocr_meta.get("buyer"): meta["buyer"]=ocr_meta["buyer"]
            if ocr_meta.get("supplier"): meta["supplier"]=ocr_meta["supplier"]
        except Exception:
            pass

    coordinate_rows=[]
    for n,item in enumerate(coordinate_items,start=1):
        coordinate_rows.append(RowData(
            position=str(item.get("position") or n), buyer=meta.get("buyer",""), supplier=meta.get("supplier",""),
            date=meta.get("date",""), invoice=meta.get("invoice",""), item=clean(item.get("item","")),
            qty=clean(item.get("qty","")), unit=_norm_unit(item.get("unit","")),
            price=clean(item.get("price","")), amount=clean(item.get("amount","")),
            page_number=int(item.get("page_number",0) or 0), bbox=item.get("bbox")
        ))

    coord_ok,coord_reasons,coord_score=_validate_coordinate_result(coordinate_items,text=text)
    if coordinate_items:
        if coord_ok:
            if coord_reasons:
                _parser_log(f"[OCR] Coordinate validation: SUSPICIOUS (score {coord_score})")
                for reason in coord_reasons[:8]: _parser_log(f"[OCR] Reason: {reason}")
            else:
                _parser_log(f"[OCR] Coordinate validation: OK (score {coord_score})")
        else:
            _parser_log("[OCR] Coordinate validation: FAILED")
            for reason in coord_reasons[:8]: _parser_log(f"[OCR] Reason: {reason}")
    else:
        _parser_log("[OCR] Coordinate validation: FAILED")
        _parser_log("[OCR] Reason: no coordinate positions")

    # V20.44 fallback вычисляем всегда: это позволяет сравнить стратегии и ловить регрессии.
    text_rows,text_name=_build_text_fallback_rows(text,meta)
    _parser_log(f"[OCR] V20.44 fallback {text_name}: {len(text_rows)} position(s)")

    rows,final_parser=_choose_parser_result(
        coordinate_rows,coord_ok,coord_score,text_rows,text_name,text,coord_reasons
    )
    if final_parser != "coordinate":
        _parser_log(f"[OCR] Fallback: {final_parser} parser")
    _parser_log(f"[OCR] Final parser: {final_parser}")

    source_id=source_file_id_for_path(path)
    for row in rows:
        row.source_path=str(path); row.source_file_id=source_id
        row.original_item=row.item; row.original_qty=row.qty; row.original_unit=row.unit
        row.original_price=row.price; row.original_amount=row.amount

    score,errors,declared,doc_total=validate_invoice_rows(rows,text=text,meta=meta)
    for row in rows:
        row.confidence=min(row.confidence or score,score)
    return rows

def parse_xlsx(path: Path) -> list[RowData]:
    try:
        from openpyxl import load_workbook
    except ImportError:
        raise RuntimeError("Установите openpyxl: pip install openpyxl")

    wb = load_workbook(path, data_only=True, read_only=True)
    ws = wb[wb.sheetnames[0]]

    matrix = [
        ["" if v is None else str(v) for v in row]
        for row in ws.iter_rows(values_only=True)
    ]

    return parse_matrix(matrix)


def parse_xls(path: Path) -> list[RowData]:
    try:
        import xlrd
    except ImportError:
        raise RuntimeError("Установите xlrd: pip install xlrd")

    wb = xlrd.open_workbook(str(path))
    ws = wb.sheet_by_index(0)

    matrix = []
    for r in range(ws.nrows):
        row = []
        for c in range(ws.ncols):
            v = ws.cell_value(r, c)
            if isinstance(v, float) and v.is_integer():
                v = int(v)
            row.append("" if v is None else str(v))
        matrix.append(row)

    return parse_matrix(matrix)


def parse_matrix(matrix: list[list[str]]) -> list[RowData]:
    """
    Макет №5: XLS/XLSX.
    Не используем OCR — читаем реальные ячейки.

    Поддерживаем:
    - 1С-подобные счета с объединенными ячейками;
    - заголовки "Товар", "Товар (Услуга)", "Наименование";
    - "Кол-во" / "Количество".
    """
    normalized = [
        [clean("" if v is None else str(v)) for v in row]
        for row in matrix
    ]

    text = "\n".join(
        " | ".join(v for v in row if v)
        for row in normalized
    )

    meta = extract_meta(text)

    # В Excel надежнее отдельно искать реквизиты по строкам.
    for ri, row in enumerate(normalized):
        joined = " | ".join(v for v in row if v)
        low = joined.lower()

        # Счет.
        if "счет на оплату" in low or "счёт на оплату" in low:
            m = re.search(
                r"(?:Счет|Счёт)\s+на\s+оплату\s*№\s*([^\s|]+)\s+от\s+(.+?)(?:\||$)",
                joined,
                flags=re.I,
            )
            if m:
                meta["invoice"] = clean(m.group(1))
                meta["date"] = normalize_date(m.group(2))

        # Поставщик/покупатель могут находиться в другой ячейке той же строки.
        if any(v.lower().rstrip(":") == "поставщик" for v in row):
            candidates = [
                v for v in row
                if v and v.lower().rstrip(":") not in {"поставщик", "(исполнитель)"}
            ]
            if candidates:
                meta["supplier"] = company_name(max(candidates, key=len))

        if any(v.lower().rstrip(":") == "покупатель" for v in row):
            candidates = [
                v for v in row
                if v and v.lower().rstrip(":") not in {"покупатель", "(заказчик)"}
            ]
            if candidates:
                meta["buyer"] = company_name(max(candidates, key=len))

    # Ищем строку заголовка таблицы.
    header_row = -1
    name_col = -1
    qty_col = -1

    for ri, row in enumerate(normalized):
        local_name = -1
        local_qty = -1

        for ci, value in enumerate(row):
            low = value.lower()

            if (
                "наименование" in low
                or low == "товар"
                or low.startswith("товар ")
                or low.startswith("товар(")
                or "товар (услуга)" in low
                or "товары (работы, услуги)" in low
                or low == "продукт"
            ):
                local_name = ci

            if "кол-во" in low or "количество" in low or low == "кол.":
                local_qty = ci

        if local_name >= 0 and local_qty >= 0:
            header_row = ri
            name_col = local_name
            qty_col = local_qty
            break

    rows = []

    if header_row >= 0:
        for row in normalized[header_row + 1:]:
            if max(name_col, qty_col) >= len(row):
                continue

            name = clean(row[name_col])
            qty_cell = clean(row[qty_col])

            # Техническая строка 1|2|3|4... в печатной форме 1С.
            if name.isdigit() and qty_cell.isdigit():
                continue

            if not name:
                continue

            if name.lower().startswith(("итого", "всего", "ндс")):
                break

            q = re.search(r"\d+(?:[.,]\d+)?", qty_cell)
            if not q:
                continue

            rows.append(
                RowData(
                    position=str(len(rows) + 1),
                    buyer=meta["buyer"],
                    supplier=meta["supplier"],
                    date=meta["date"],
                    invoice=meta["invoice"],
                    item=name,
                    qty=q.group(0).replace(",", "."),
                )
            )

    return rows

def parse_file(path: Path) -> list[RowData]:
    ext = path.suffix.lower()

    if ext == ".pdf":
        return parse_pdf(path)

    if ext == ".xlsx":
        return parse_xlsx(path)

    if ext == ".xls":
        return parse_xls(path)

    raise RuntimeError(f"Формат {ext} не поддерживается")


# V20.50: таймаут одного файла 10 секунд; пакетный таймер и дедупликация по Поставщик + № счета.
# V20.41: распознавание одного счёта запускается отдельным обычным subprocess.
# Это устойчивее multiprocessing/spawn на Windows и в PyInstaller.
INVOICE_FILE_TIMEOUT_SECONDS = 10

def _invoice_subprocess_worker(path_str: str, result_path_str: str):
    """Режим дочернего процесса: распознать один файл и записать JSON-результат."""
    result_path = Path(result_path_str)
    try:
        rows = parse_file(Path(path_str))
        payload = {"status":"ok", "rows":[r.__dict__.copy() for r in rows], "parser_log": get_last_parser_log()}
    except BaseException as exc:
        try:
            err = f"{type(exc).__name__}: {exc}" if str(exc) else type(exc).__name__
        except BaseException:
            err = "Неизвестная ошибка распознавания"
        payload = {"status":"error", "error":err, "rows":[]}
    try:
        result_path.write_text(json.dumps(payload, ensure_ascii=False), encoding="utf-8")
    except BaseException:
        pass

def _parse_invoice_file_with_hard_timeout(path: Path, timeout_seconds: int = INVOICE_FILE_TIMEOUT_SECONDS):
    """Возвращает (rows, error, parser_log); зависший дочерний процесс завершается по тайм-ауту."""
    fd, result_name = tempfile.mkstemp(prefix="led_invoice_", suffix=".json")
    os.close(fd)
    result_path = Path(result_name)
    try:
        if getattr(sys, "frozen", False):
            cmd = [sys.executable, "--invoice-worker", str(path), str(result_path)]
        else:
            cmd = [sys.executable, str(Path(__file__).resolve()), "--invoice-worker", str(path), str(result_path)]
        kwargs = {"stdout": subprocess.DEVNULL, "stderr": subprocess.DEVNULL}
        if os.name == "nt":
            kwargs["creationflags"] = getattr(subprocess, "CREATE_NO_WINDOW", 0)
        try:
            completed = subprocess.run(cmd, timeout=max(1, int(timeout_seconds)), **kwargs)
        except subprocess.TimeoutExpired:
            return [], f"Превышено время распознавания ({int(timeout_seconds)} с)", []
        if completed.returncode != 0 and not result_path.exists():
            return [], f"Процесс распознавания завершился с кодом {completed.returncode}", []
        try:
            raw = result_path.read_text(encoding="utf-8").strip()
            result = json.loads(raw) if raw else {}
        except Exception as exc:
            return [], f"Не удалось получить результат распознавания: {exc}", []
        if result.get("status") != "ok":
            return [], result.get("error") or "Ошибка распознавания", result.get("parser_log", []) or []
        rows=[]
        for item in result.get("rows", []):
            allowed={k:item.get(k, "") for k in RowData.__dataclass_fields__}
            rows.append(RowData(**allowed))
        return rows, "", result.get("parser_log", []) or []
    finally:
        try:
            result_path.unlink(missing_ok=True)
        except Exception:
            pass



# Базовые размеры и режимы координатного поля
MODULE_W = 320
MODULE_H = 160
MCD_MODULE_W = 320
MCD_MODULE_H = 160
MCD_MARGIN = 50
MCD_RADIUS = 200
MCD_PRINT_RADIUS = 100

# V30.68: норма фронтальных LED для односторонней статики МЦД с подсветкой.
MCD_STATIC_1SIDE_LED_PER_SQM = 60

# V30.69: торцевые LED двусторонней прямоугольной статики МЦД.
MCD_STATIC_2SIDE_LED_PITCH_MM = 90
MCD_STATIC_2SIDE_SHORT_LIMIT_MM = 400

# V30.74: уголок 30×20×2 прямоугольной статики МЦД считается одинаково
# для одностороннего и двустороннего изделия: два контура по сторонам,
# уменьшенным на 180 мм. Квадрат со стороной менее 551 мм — по полным габаритам.
# V30.78: у круглых изделий МЦД контур гнётся из уголка 40×20×2 мм.
ROUND_MCD_ANGLE_NAME = "Уголок алюминиевый 40×20×2 мм"
ROUND_MCD_ANGLE_KEY = "angle40"
ROUND_MCD_ANGLE_WEIGHT_GPM = 313.0

MCD_STATIC_ANGLE_INSET_MM = 180.0
MCD_STATIC_ANGLE_SQUARE_LIMIT_MM = 551.0


def _mcd_static_angle_sides(w, h):
    """Длины сторон контура уголка для прямоугольной статики МЦД."""
    w = float(w); h = float(h)
    if abs(w - h) < 1e-9 and w < MCD_STATIC_ANGLE_SQUARE_LIMIT_MM:
        return w, h
    return max(0.0, w - MCD_STATIC_ANGLE_INSET_MM), max(0.0, h - MCD_STATIC_ANGLE_INSET_MM)


def _mcd_static_angle_length_m(w, h):
    aw, ah = _mcd_static_angle_sides(w, h)
    return 4.0 * (aw + ah) / 1000.0


def _v3069_mcd_2side_edge_leds(w, h):
    long_side, short_side = max(float(w), float(h)), min(float(w), float(h))
    if long_side <= 0:
        return 0
    n = math.ceil(long_side / MCD_STATIC_2SIDE_LED_PITCH_MM - 1e-9) * 2
    if short_side > MCD_STATIC_2SIDE_SHORT_LIMIT_MM:
        n += math.ceil(short_side / MCD_STATIC_2SIDE_LED_PITCH_MM - 1e-9) * 2
    return n

