COMPONENT_ORDER = list(COMPONENT_RATES[(960, 960)].keys())
for _name in COMPONENT_RATES[(640, 640)]:
    if _name not in COMPONENT_ORDER:
        COMPONENT_ORDER.append(_name)


def mm_to_px(mm):
    return mm * PX_PER_MM


def px_to_mm(px):
    return px / PX_PER_MM


def all_1d_decompositions(total_mm):
    """
    Возвращает все уникальные последовательности из 960 и 640 мм,
    которые точно дают total_mm.
    Порядок учитывается: [960, 640] и [640, 960] — разные раскладки.
    """
    result = set()

    max_parts = total_mm // 640 + 1

    for count in range(1, max_parts + 1):
        for combo in itertools.product((960, 640), repeat=count):
            if sum(combo) == total_mm:
                result.add(combo)

    # Более крупные кабинеты и меньшее число частей показываем раньше.
    return sorted(
        result,
        key=lambda seq: (len(seq), -seq.count(960), seq)
    )


def all_layouts(width_mm, height_mm):
    """
    Все варианты раскладки по X и Y.
    Каждый вариант содержит последовательность ширин колонок и высот рядов.
    """
    x_variants = all_1d_decompositions(width_mm)
    y_variants = all_1d_decompositions(height_mm)

    layouts = []
    for xs in x_variants:
        for ys in y_variants:
            layouts.append((xs, ys))

    return layouts


def representable_cabinet_sizes(limit_mm):
    """Все габариты <= limit_mm, которые точно собираются из 640/960 мм."""
    return [
        value for value in range(320, limit_mm + 1, 320)
        if all_1d_decompositions(value)
    ]


RZD_VALID_WIDTHS = representable_cabinet_sizes(MAX_W_MM)
RZD_VALID_HEIGHTS = representable_cabinet_sizes(MAX_H_MM)


def nearest_value(raw, values):
    if not values:
        return 0
    if raw <= 0:
        return 0
    return min(values, key=lambda v: (abs(v - raw), v))




def _raspberry_reference_companions(sections):
    """Place dependent accessories immediately after mini-PC, preserving all existing rows."""
    for section, rows in sections.items():
        if not isinstance(rows, list):
            continue
        new=[]
        for row in rows:
            if not isinstance(row,(list,tuple)) or not row:
                new.append(row); continue
            name=str(row[0]).strip().casefold()
            if name in {"sd-карта 64gb класса a2", "радиатор мини-пк"}:
                continue  # reinsert only in sections where mini-PC really exists
            new.append(row)
            if "мини-пк" in name and ("raspberry" in name or "rassberry" in name):
                rule="Количество равно фактически рассчитанному количеству мини-пк Raspberry pi."
                new.extend((["SD-карта 64Gb класса A2",rule,"По расчёту","шт.",""],
                            ["Радиатор мини-ПК",rule,"По расчёту","шт.",""]))
        sections[section]=new
    return sections


def _raspberry_bom_companions(rows):
    """Insert accessories from calculated Raspberry quantities, no per-product rule."""
    result=[]
    for name,unit,qty in rows:
        if name in {"SD-карта 64Gb класса A2", "Радиатор мини-ПК"}:
            continue
        result.append((name,unit,qty))
        lowered=str(name).casefold()
        if "мини-пк" in lowered and ("raspberry" in lowered or "rassberry" in lowered):
            if qty is not None and float(qty)>0:
                result.append(("SD-карта 64Gb класса A2","шт.",qty))
                result.append(("Радиатор мини-ПК","шт.",qty))
    return result

# V30.25: add backlit acrylic only to MCD static sections containing 8 mm glass.
def _v3025_mcd_backlit_reference(data):
    name="Молочный акрил 4 мм для бэклита"
    for section, rows in data.items():
        if not (str(section).startswith("МЦД /") and "с подсветкой" in str(section)):
            continue
        round_shape="круглый" in str(section).casefold()
        cleaned=[list(row) for row in rows if isinstance(row,(list,tuple)) and row
                 and str(row[0]).strip()!=name]
        glass_index=next((i for i,row in enumerate(cleaned)
                          if str(row[0]).strip()=="Оргстекло 8 мм"),None)
        if glass_index is None:
            data[section]=cleaned
            continue
        glass=cleaned[glass_index]
        qty=glass[2] if len(glass)>2 else "По расчёту"
        rule=("Количество равно количеству оргстёкол. Диаметр = рассчитанный диаметр оргстекла − 42 мм: Ø(оргстекло − 42). "
              "Для круглого акрила радиус скругления R45,5 не применяется." if round_shape else
              "Количество равно количеству оргстёкол. Размер = (ширина оргстекла − 41 мм) × "
              "(высота оргстекла − 41 мм). Скругление углов R45,5 мм.")
        cleaned.insert(glass_index+1,[name,rule,qty,"шт.",""])
        data[section]=cleaned
    return data


class ScreenDesigner(BaseTk):
    def __init__(self):
        super().__init__()

        # V30.02: авторизация отключена; стартуем со стандартного окна выбора проекта.
        self.withdraw()
        self.current_user = None

        # V20.22: сначала показываем выбор контекста проекта, основное окно не мигает на экране.
        self.project_brand_context = None
        self._last_notebook_tab = None

        self.title(APP_TITLE)
        self.geometry("1240x680")
        self.minsize(1160, 640)

        self.width_mm = 0
        self.height_mm = 0
        self.layouts = []
        self.layout_index = 0
        self.side2_layout_index = 0
        self.saved_screens = []
        self.procurement_records = []
        # V20.76: поставщики хранятся внутри конкретного .ledproj.
        # Отдельного локального suppliers.json нет.
        self.project_supplier_catalog = {}
        self.project_supplier_assignments = {}
        self.project_component_supplier_history = {}
        # V20.77: последний выбранный поставщик используется как предложение
        # для следующей комплектующей без назначенного поставщика.
        self.project_last_supplier_id = ""
        self.invoices = []
        self.invoice_files = []
        self.invoice_rows = []
        self.invoice_parse_log_entries = []
        # V20.38: сообщения фонового распознавания идут через Queue; Tkinter обновляется только из main thread.
        self._invoice_worker_queue = queue.Queue()
        self._invoice_parse_running = False
        self.project_name = "Новый проект"
        self.current_project_path = None
        now_iso = datetime.now().isoformat(timespec="seconds")
        self.project_metadata = {
            "created_at": now_iso,
            "modified_at": now_iso,
            "supplier_learning_id": uuid.uuid4().hex,
        }
        self._project_dirty = False
        self._loading_project_data = False
        self._loading_saved_product = False
        self._active_screen_index = None
        self._active_static_index = None
        # V20.28: отдельное состояние черновика. Сохранённое изделие никогда не
        # становится "новым" автоматически; новый объект начинается только
        # после явного нажатия кнопки «Новое изделие».
        self._dynamic_draft_mode = True
        self._static_draft_mode = True
        self._project_refresh_after_id = None
        self._tooltip_window = None
        self.screen_mode = MODE_RZD

        # V20.78: общая база поставщиков принадлежит приложению и автоматически
        # доступна всем новым проектам на этом компьютере.
        self._supplier_db_error = ""
        self._supplier_db_init()

        self._build_ui()
        self._install_project_autosave_traces()
        self._install_global_clipboard_bindings()
        self._install_global_combobox_click_behavior()
        self._install_global_selection_clear()
        self._configure_train_columns()
        self.notebook.bind("<<NotebookTabChanged>>", self._on_main_notebook_tab_changed, add="+")
        self.protocol("WM_DELETE_WINDOW", self._on_app_close)
        self._draw_grid()
        self._update_results()
        # V30.02: показываем root перед стандартным выбором РЖД / МЦД / проекта.
        try:
            self.deiconify()
        except Exception:
            pass
        # V30.92.1: стартовое окно РЖД / МЦД открываем только после входа Tk в mainloop
        # (как в v20.27). Модальный Toplevel, созданный прямо в __init__, на Windows
        # мог остаться невидимым, а главное окно — заблокированным grab'ом.
        self.after(150, self._run_startup_choice)

    def _log_startup_dialog_error(self, exc):
        """V30.92.1: ошибка стартового окна не скрывается — пишем лог и показываем сообщение."""
        import traceback
        text = traceback.format_exc()
        log_paths = []
        candidates = []
        try:
            base = Path(sys.executable if getattr(sys, "frozen", False) else __file__).resolve().parent
            candidates.append(base / "startup_dialog_error.log")
        except Exception:
            pass
        try:
            root = Path(os.environ.get("APPDATA") or (Path.home() / "AppData" / "Roaming"))
            folder = root / "LED Screen Designer"
            folder.mkdir(parents=True, exist_ok=True)
            candidates.append(folder / "startup_dialog_error.log")
        except Exception:
            pass
        for p in candidates:
            try:
                p.write_text(text, encoding="utf-8")
                log_paths.append(str(p))
            except Exception:
                pass
        try:
            print(f"[STARTUP] Main project chooser failed: {exc!r}", file=sys.stderr)
        except Exception:
            pass
        try:
            extra = ("\n\nЛог: " + log_paths[0]) if log_paths else ""
            messagebox.showerror(
                "Ошибка окна выбора проекта",
                f"Не удалось открыть графическое окно выбора РЖД/МЦД.\n{exc}{extra}",
                parent=self,
            )
        except Exception:
            pass

    def _run_startup_choice(self):
        """V30.92.1: стартовый выбор РЖД / МЦД / проекта / журнала после старта mainloop."""
        try:
            self.update_idletasks()
        except Exception:
            pass
        try:
            startup_action = self._show_startup_choice()
        except Exception as exc:
            # V20.53: не выбираем МЦД молча при сбое стартового окна —
            # показываем ошибку и простой резервный диалог с теми же вариантами.
            self._log_startup_dialog_error(exc)
            startup_action = self._show_startup_choice_fallback()
        # V30.63: «Журнал проектов» из стартового окна; без выбора — снова стартовое окно.
        log_path = None
        while startup_action == "LOG":
            log_path = self._open_project_log(modal=True)
            if log_path:
                break
            try:
                startup_action = self._show_startup_choice()
            except Exception:
                startup_action = self._show_startup_choice_fallback()
        if log_path:
            self.after(80, lambda p=log_path: self._open_project_path(p))
            return
        if startup_action not in ("РЖД", "МЦД", "OPEN"):
            startup_action = self._show_startup_choice_fallback()
        if startup_action == "OPEN":
            self.after(80, self._open_project)
        else:
            self._apply_project_brand_context()

    def _install_global_clipboard_bindings(self):
        """V20.33: layout-independent clipboard shortcuts for Windows/macOS/Linux.

        We install a custom bindtag *before* the widget class binding.  That makes
        the shortcuts depend on the physical key rather than the character emitted
        by the active keyboard layout, and also prevents the old double-paste bug.
        Windows/Linux use Ctrl, macOS uses Command (Meta).  Standard English-layout
        shortcuts therefore work exactly once, and the same physical keys continue
        to work in Russian or another layout.
        """
        import sys
        tag = "LEDLayoutIndependentClipboard"
        self._clipboard_bindtag = tag

        # Physical-key codes used by Tk on the main desktop platforms.
        # Windows virtual-key codes / macOS ANSI hardware codes / X11 keycodes.
        keycodes = {
            "copy":      {67, 8, 54},   # C
            "paste":     {86, 9, 55},   # V
            "cut":       {88, 7, 53},   # X
            "select_all":{65, 0, 38},   # A
        }

        def _editable(w):
            return isinstance(w, (tk.Entry, ttk.Entry, ttk.Combobox, tk.Spinbox, tk.Text))

        def _state_blocks_edit(w):
            try:
                state = str(w.cget("state"))
                return state in ("disabled", "readonly")
            except Exception:
                return False

        def _select_all(w):
            if isinstance(w, (tk.Entry, ttk.Entry, ttk.Combobox, tk.Spinbox)):
                w.selection_range(0, "end")
                try: w.icursor("end")
                except Exception: pass
                return
            if isinstance(w, tk.Text):
                w.tag_remove("sel", "1.0", "end")
                w.tag_add("sel", "1.0", "end-1c")
                w.mark_set("insert", "end-1c")

        def _handler(event):
            w = event.widget
            if not _editable(w):
                return None

            # Detect modifier independently of keyboard layout.
            # Tk state: Control=0x0004, macOS Command/Meta is normally 0x0008/0x0080.
            state = int(getattr(event, "state", 0) or 0)
            if sys.platform == "darwin":
                modifier = bool(state & 0x0008 or state & 0x0080 or state & 0x0010)
            else:
                modifier = bool(state & 0x0004)
            if not modifier:
                return None

            code = int(getattr(event, "keycode", -1) or -1)
            action = None
            for name, codes in keycodes.items():
                if code in codes:
                    action = name
                    break
            if action is None:
                return None

            try:
                if action == "select_all":
                    _select_all(w)
                    return "break"
                if action in ("paste", "cut") and _state_blocks_edit(w):
                    return "break"
                if action == "copy":
                    w.event_generate("<<Copy>>")
                elif action == "cut":
                    w.event_generate("<<Cut>>")
                elif action == "paste":
                    w.event_generate("<<Paste>>")
                return "break"
            except Exception:
                return "break"

        self.bind_class(tag, "<KeyPress>", _handler)

        def _install_tag(widget):
            try:
                tags = list(widget.bindtags())
                if tag not in tags:
                    # widget-specific handlers stay first; our shortcut handler comes
                    # before the Tk/ttk class binding that would otherwise depend on keysym.
                    tags.insert(1, tag)
                    widget.bindtags(tuple(tags))
            except Exception:
                pass
            try:
                for child in widget.winfo_children():
                    _install_tag(child)
            except Exception:
                pass

        _install_tag(self)
        # Dialogs/widgets created later are covered automatically when they are mapped.
        self.bind_all("<Map>", lambda e: _install_tag(e.widget), add="+")

    def _install_global_combobox_click_behavior(self):
        """V20.33: clicking anywhere on a ttk.Combobox opens its drop-down list."""
        def _enable(widget):
            try:
                if isinstance(widget, ttk.Combobox) and not getattr(widget, "_full_click_dropdown_bound", False):
                    widget._full_click_dropdown_bound = True

                    def _open(event):
                        w = event.widget
                        try:
                            state = str(w.cget("state"))
                            if state == "disabled":
                                return "break"
                            # The arrow already has native posting behavior.  For every
                            # other part of the field, explicitly post the list.
                            element = str(w.identify(event.x, event.y) or "")
                            if "downarrow" in element or "arrow" in element:
                                return None
                            w.focus_set()
                            w.tk.call("ttk::combobox::Post", str(w))
                            return "break"
                        except Exception:
                            try:
                                w.event_generate("<Down>")
                                return "break"
                            except Exception:
                                return None

                    widget.bind("<Button-1>", _open, add="+")
            except Exception:
                pass
            try:
                for child in widget.winfo_children():
                    _enable(child)
            except Exception:
                pass

        _enable(self)
        self.bind_all("<Map>", lambda e: _enable(e.widget), add="+")

    def _configure_train_columns(self):
        """Колонки двигаются последовательно: ширина соседних не растягивается автоматически."""
        for attr in ("components_tree","reference_tree","project_journal_tree"):
            tree=getattr(self,attr,None)
            if tree is None: continue
            try:
                for c in ("#0",)+tuple(tree["columns"]):
                    tree.column(c, stretch=False)
            except Exception:
                pass

    def _commit_active_product_edits(self, refresh_views=True):
        """V20.81: принудительно переносит текущую форму в сохранённое изделие.

        Используется перед сменой вкладки и перед сериализацией проекта, чтобы
        изменения существующего изделия не оставались только в UI.
        """
        # Если редактировался экземпляр многотиражного LED-экрана,
        # сначала переносим его серийные поля обратно в instances.
        try:
            active_inst=getattr(self,"_active_led_instance",None)
            if active_inst is not None:
                gi,ii=active_inst
                if 0 <= gi < len(getattr(self,"saved_screens",[])):
                    screen=self.saved_screens[gi]
                    instances=self._ensure_screen_instances(screen)
                    if 0 <= ii < len(instances):
                        instances[ii]["part_number"]=self.part_number_var.get()
                        instances[ii]["led_series"]=self.led_series_var.get()
        except Exception:
            pass

        try:
            self._sync_active_screen_from_form()
        except Exception:
            pass
        try:
            self._sync_active_static_from_form()
        except Exception:
            pass

        if refresh_views:
            # Отложенное обновление могло ещё не выполниться. Здесь нужен
            # немедленный пересчёт BOM перед уходом со вкладки/печатью.
            try:
                pending=getattr(self,"_project_refresh_after_id",None)
                if pending is not None:
                    self.after_cancel(pending)
                    self._project_refresh_after_id=None
            except Exception:
                pass
            try:self._refresh_project_journal()
            except Exception:pass
            try:self._refresh_components_screen_selector()
            except Exception:pass
            try:self._refresh_components_table()
            except Exception:pass
            try:self._refresh_cut_map()
            except Exception:pass
            try:self._refresh_stock_screen_selector()
            except Exception:pass
            try:self._refresh_procurement_table()
            except Exception:pass

    def _on_main_notebook_tab_changed(self, event=None):
        try:
            current=self.notebook.select()
        except Exception:
            return
        previous=getattr(self,"_last_notebook_tab",None)

        # V20.82: переход на другую вкладку больше НЕ отвязывает загруженное
        # сохранённое изделие. Пока пользователь явно не нажал «Новое изделие»
        # или не загрузил другое, форма продолжает редактировать тот же объект.
        if previous and previous != current:
            if previous == str(self.designer_tab):
                self._commit_active_product_edits(refresh_views=True)
            elif previous == str(self.static_tab):
                self._commit_active_product_edits(refresh_views=True)

        # При входе в «Комплектующие» строим BOM непосредственно из уже
        # обновлённой модели проекта.
        try:
            if current == str(self.components_tab):
                self._commit_active_product_edits(refresh_views=False)
                self._refresh_components_screen_selector()
                self._refresh_components_table()
                self._refresh_cut_map()
        except Exception:
            pass

        self._last_notebook_tab=current


    def _update_led_type_options(self):
        env=self.screen_environment_var.get() if hasattr(self,"screen_environment_var") else "Улица"
        if not hasattr(self,"led_type_combo"): return
        if env == "Улица":
            self.led_type_combo.configure(values=("OD",))
            if self.led_type_var.get() != "OD": self.led_type_var.set("OD")
        else:
            self.led_type_combo.configure(values=("OD","ID"))
            if self.led_type_var.get() not in ("OD","ID"): self.led_type_var.set("OD")
        try:self._dynamic_apply_autofill()
        except Exception:pass

    def _show_startup_choice(self):
        """Надёжный стартовый выбор проекта без отложенных callback'ов Toplevel.

        На Windows прежний dlg.after(... topmost ...) мог сработать уже после
        уничтожения окна и давать TclError/нестабильный старт.
        """
        result={"value":None}
        dlg=tk.Toplevel(self)
        dlg.title("Выбор проекта")
        dlg.transient(self)
        dlg.resizable(False,False)

        box=tk.Frame(dlg,padx=24,pady=22,bg="#f3f3f3")
        box.pack(fill="both",expand=True)
        tk.Label(box,text="С каким проектом работаем?",font=("Arial",18,"bold"),bg="#f3f3f3").pack(pady=(0,18))
        row=tk.Frame(box,bg="#f3f3f3")
        row.pack()

        def choose(value):
            result["value"]=value
            try:
                dlg.grab_release()
            except Exception:
                pass
            try:
                if dlg.winfo_exists():
                    dlg.destroy()
            except Exception:
                pass

        def _make_logo_button(parent, *, logo_b64, fallback_text, value):
            target_w, target_h = 250, 105
            img_obj=None
            try:
                from PIL import Image, ImageTk, ImageOps
                raw=base64.b64decode(logo_b64)
                img=Image.open(io.BytesIO(raw)).convert("RGB")
                img=ImageOps.fit(img,(target_w,target_h),method=Image.Resampling.LANCZOS,centering=(0.5,0.5))
                img_obj=ImageTk.PhotoImage(img)
            except Exception:
                img_obj=None

            if not hasattr(self,"_startup_logo_refs"):
                self._startup_logo_refs=[]
            if img_obj is not None:
                self._startup_logo_refs.append(img_obj)
                btn=tk.Button(parent,image=img_obj,command=lambda:choose(value),
                              width=target_w,height=target_h,relief="flat",bd=0,
                              highlightthickness=1,highlightbackground="#c9c9c9",
                              activebackground="white",cursor="hand2",takefocus=1)
            else:
                btn=tk.Button(parent,text=fallback_text,command=lambda:choose(value),
                              width=16,height=4,bg="#D52B1E" if value=="РЖД" else "#CC2037",
                              fg="white",activebackground="#B52319",
                              font=("Arial",16,"bold"),relief="flat",bd=0,cursor="hand2",takefocus=1)
            btn.pack(side="left",padx=10)
            return btn

        _make_logo_button(row,logo_b64=STARTUP_LOGO_RZD_B64,fallback_text="РЖД",value="РЖД")
        _make_logo_button(row,logo_b64=STARTUP_LOGO_MCD_B64,fallback_text="МЦД",value="МЦД")
        tk.Button(box,text="Открыть сохранённый проект",command=lambda:choose("OPEN"),
                  width=38,height=2,font=("Arial",11,"bold")).pack(pady=(18,0))
        tk.Button(box,text="Журнал проектов",command=lambda:choose("LOG"),
                  width=38,height=2,font=("Arial",11,"bold")).pack(pady=(8,0))
        dlg.protocol("WM_DELETE_WINDOW", lambda: choose("МЦД"))

        # Полностью создаём и показываем окно до grab_set/focus_force.
        # Это заметно надёжнее на Windows, особенно при запуске из .py/.exe.
        dlg.update_idletasks()
        req_w=max(1,dlg.winfo_reqwidth())
        req_h=max(1,dlg.winfo_reqheight())
        x=max(0,(dlg.winfo_screenwidth()-req_w)//2)
        y=max(0,(dlg.winfo_screenheight()-req_h)//2)
        dlg.geometry(f"{req_w}x{req_h}+{x}+{y}")
        try:
            dlg.deiconify()
            dlg.lift()
            dlg.attributes("-topmost", True)
            dlg.update_idletasks()
            dlg.update()
            dlg.attributes("-topmost", False)
            dlg.focus_force()
            dlg.grab_set()
        except Exception:
            try:
                dlg.grab_set()
            except Exception:
                pass

        self.wait_window(dlg)
        if result["value"] in ("РЖД","МЦД"):
            self.project_brand_context=result["value"]
        return result["value"]

    def _show_startup_choice_fallback(self):
        """V20.53: резервный стартовый выбор без изображений/Pillow.

        Используется только если основной диалог с логотипами не смог
        корректно открыться. Никогда не выбирает тип проекта автоматически.
        """
        result = {"value": None}
        dlg = tk.Toplevel(self)
        dlg.title("Выбор проекта")
        dlg.resizable(False, False)
        try:
            dlg.transient(self)
        except Exception:
            pass

        box = tk.Frame(dlg, padx=30, pady=26, bg="#f3f3f3")
        box.pack(fill="both", expand=True)
        tk.Label(
            box, text="С каким проектом работаем?",
            font=("Arial", 18, "bold"), bg="#f3f3f3"
        ).pack(pady=(0, 20))

        row = tk.Frame(box, bg="#f3f3f3")
        row.pack()

        def choose(value):
            result["value"] = value
            try:
                dlg.grab_release()
            except Exception:
                pass
            try:
                dlg.destroy()
            except Exception:
                pass

        tk.Button(
            row, text="РЖД", command=lambda: choose("РЖД"),
            width=16, height=4, bg="#D52B1E", fg="white",
            font=("Arial", 16, "bold"), relief="flat", cursor="hand2"
        ).pack(side="left", padx=10)
        tk.Button(
            row, text="МЦД", command=lambda: choose("МЦД"),
            width=16, height=4, bg="#CC2037", fg="white",
            font=("Arial", 16, "bold"), relief="flat", cursor="hand2"
        ).pack(side="left", padx=10)
        tk.Button(
            box, text="Открыть сохранённый проект",
            command=lambda: choose("OPEN"), width=38, height=2,
            font=("Arial", 11, "bold")
        ).pack(pady=(18, 0))

        # Закрытие крестиком не должно молча выбирать бренд.
        # Оставляем окно открытым, пока пользователь явно не выберет действие.
        dlg.protocol("WM_DELETE_WINDOW", lambda: None)
        dlg.update_idletasks()
        req_w = max(1, dlg.winfo_reqwidth())
        req_h = max(1, dlg.winfo_reqheight())
        x = max(0, (dlg.winfo_screenwidth() - req_w) // 2)
        y = max(0, (dlg.winfo_screenheight() - req_h) // 2)
        dlg.geometry(f"{req_w}x{req_h}+{x}+{y}")
        try:
            dlg.deiconify()
            dlg.lift()
            dlg.attributes("-topmost", True)
            dlg.update_idletasks()
            dlg.attributes("-topmost", False)
            dlg.focus_force()
            dlg.grab_set()
        except Exception:
            try:
                dlg.grab_set()
            except Exception:
                pass

        self.wait_window(dlg)
        if result["value"] in ("РЖД", "МЦД"):
            self.project_brand_context = result["value"]
        return result["value"]

    def _apply_project_brand_context(self):
        brand=getattr(self,"project_brand_context",None)
        if brand not in ("РЖД","МЦД"): return
        # Сначала возвращаем все кнопки, затем оставляем нужные.
        for b in getattr(self,"screen_mode_buttons",{}).values():
            try:b.pack_forget()
            except Exception:pass
        for b in getattr(self,"static_mode_buttons",{}).values():
            try:b.pack_forget()
            except Exception:pass
        if brand == "РЖД":
            rb=getattr(self,"screen_mode_buttons",{}).get(MODE_RZD)
            if rb: rb.configure(text="РЖД"); rb.pack(side="left",padx=(0,22))
            srb=getattr(self,"static_mode_buttons",{}).get(MODE_RZD)
            if srb:
                srb.configure(text="РЖД")
                srb.pack(side="left",padx=(0,22))
            self.screen_mode_var.set(MODE_RZD); self.static_mode_var.set(MODE_RZD)
        else:
            rb_m=getattr(self,"screen_mode_buttons",{}).get(MODE_MCD)
            rb_c=getattr(self,"screen_mode_buttons",{}).get(MODE_RZD)
            if rb_m: rb_m.configure(text="МЦД"); rb_m.pack(side="left",padx=(0,22))
            if rb_c: rb_c.configure(text="Кабинетный тип"); rb_c.pack(side="left",padx=(0,22))
            srb=getattr(self,"static_mode_buttons",{}).get(MODE_MCD)
            if srb:srb.pack(side="left",padx=(0,22))
            # Для нового МЦД-проекта стартуем с МЦД; загруженный кабинетный экран сам переключит режим при явной загрузке.
            if not getattr(self,"saved_screens",None): self.screen_mode_var.set(MODE_MCD)
            elif self.screen_mode_var.get() not in (MODE_MCD,MODE_RZD): self.screen_mode_var.set(MODE_MCD)
            self.static_mode_var.set(MODE_MCD)
        try:self._on_screen_mode_changed()
        except Exception:pass
        try:self._static_mode_changed()
        except Exception:pass

    def _safe_filename_part(self, value):
        s=str(value or "").strip() or "без_названия"
        s=re.sub(r'[<>:"/\\|?*]+','_',s)
        s=re.sub(r'\s+',' ',s).strip().rstrip('.')
        return s[:90] or "без_названия"

    def _make_print_pdf_path(self, product, copies=1, is_static=False):
        import tempfile
        project=self._safe_filename_part(self.project_name_var.get().strip() or self.project_name)
        prefix=self._safe_filename_part(getattr(self,"project_brand_context",None) or ("РЖД" if product.get("mode")==MODE_RZD else "МЦД"))
        article=self._safe_filename_part(product.get("article","") if is_static else product.get("module_article","") or product.get("screen_article",""))
        qty_suffix=f"_{int(copies)}шт" if int(copies)>1 else ""
        base=f"{project}_{prefix}_{article}{qty_suffix}"
        folder=Path(tempfile.gettempdir())/"LED_Screen_Designer"; folder.mkdir(parents=True,exist_ok=True)
        path=folder/f"{base}.pdf"
        n=2
        while path.exists():
            path=folder/f"{base}_{n}.pdf"; n+=1
        return path

    def _build_ui(self):
        root = ttk.Frame(self, padding=6)
        root.pack(fill="both", expand=True)

        project_bar = ttk.Frame(root)
