        self.project_name_var = tk.StringVar(value=self.project_name)
        self.project_name_entry = ttk.Entry(project_bar, textvariable=self.project_name_var)
        self.project_name_entry.pack(side="left", fill="x", expand=True, padx=(7, 10))
        self.project_name_var.trace_add("write", self._on_project_name_changed)
        ttk.Button(project_bar, text="Открыть проект", command=self._open_project).pack(side="left", padx=(0,5))
        ttk.Button(project_bar, text="Сохранить проект", command=self._save_project).pack(side="left")
        ttk.Button(project_bar, text="Сохранить проект как", command=self._save_project_as).pack(side="left", padx=(5,0))
        # V30.63: дата планируемой поставки и журнал проектов.
        ttk.Label(project_bar, text="Поставка:", font=("Arial", 10, "bold")).pack(side="left", padx=(14, 4))
        self.planned_delivery_var = tk.StringVar(value="")
        ttk.Entry(project_bar, textvariable=self.planned_delivery_var, width=12).pack(side="left")
        self.planned_delivery_var.trace_add("write", self._v3063_on_delivery_changed)
        ttk.Button(project_bar, text="Журнал проектов", command=self._open_project_log).pack(side="left", padx=(8,0))

        self.notebook = ttk.Notebook(root)
        self.notebook.pack(fill="both", expand=True)

        designer_tab = ttk.Frame(self.notebook, padding=4)
        static_tab = ttk.Frame(self.notebook, padding=4)
