        components_tab = ttk.Frame(self.notebook, padding=8)
        reference_tab = ttk.Frame(self.notebook, padding=8)
        procurement_tab = ttk.Frame(self.notebook, padding=8)
        invoices_tab = ttk.Frame(self.notebook, padding=8)
