        self.notebook.add(designer_tab, text="LED-экраны")
        self.notebook.add(static_tab, text="Статические указатели")
        self.notebook.add(journal_tab, text="Журнал проекта")
        self.notebook.add(components_tab, text="Комплектующие")
        self.notebook.add(reference_tab, text="Справочник")
        self.notebook.add(procurement_tab, text="Закупки и склад")
        self.notebook.add(invoices_tab, text="Счета")

        self.designer_tab=designer_tab
        self.static_tab=static_tab
        self.journal_tab=journal_tab
        self.components_tab=components_tab
        self._build_project_journal_tab(journal_tab)

        title_row = ttk.Frame(designer_tab)
        title_row.pack(fill="x", pady=(0, 5))

        ttk.Label(
            title_row,
            text="Конструктор LED-экрана",
            font=("Arial", 20, "bold")
        ).pack(side="left")


        mode_bar = ttk.LabelFrame(designer_tab, text="Тип исполнения", padding=(10, 6))
        mode_bar.pack(fill="x", pady=(0, 6))

