        def _part_number_changed(*_):
            value = self.part_number_var.get()
            clean = "".join(ch for ch in value if ch.isdigit())
            if value != clean:
                self.part_number_var.set(clean)
                return
            self._save_active_instance_overrides()
        self.part_number_var.trace_add("write", _part_number_changed)

        # Типоразмер МЦД — отдельный постоянный контейнер сразу под артикулом.
