        ttk.Label(self.mcd_manual_frame, text="Высота, мм").grid(row=0,column=1,sticky="w",padx=(8,0))
        self.mcd_manual_width_entry = ttk.Entry(self.mcd_manual_frame,textvariable=self.mcd_manual_width_var,width=10)
        self.mcd_manual_height_entry = ttk.Entry(self.mcd_manual_frame,textvariable=self.mcd_manual_height_var,width=10)
        self.mcd_manual_width_entry.grid(row=1,column=0,sticky="ew")
        self.mcd_manual_height_entry.grid(row=1,column=1,sticky="ew",padx=(8,0))
        self.mcd_manual_frame.columnconfigure(0,weight=1); self.mcd_manual_frame.columnconfigure(1,weight=1)
        self.mcd_manual_width_entry.bind("<KeyRelease>", self._on_mcd_manual_dimensions)
        self.mcd_manual_height_entry.bind("<KeyRelease>", self._on_mcd_manual_dimensions)
        # Начальный режим РЖД: содержимое контейнера скрыто.

