        # Двойной щелчок сразу загружает сохранённый экран на координатное поле.
        self.saved_tree.bind("<Double-1>", lambda event: self._load_saved_screen())

        saved_actions = ttk.Frame(saved_box)
        saved_actions.pack(fill="x", pady=(7, 0))

