    def _mcd_is_custom_size(self):
        return (
            hasattr(self, "mcd_size_var")
            and self.screen_mode_var.get() == MODE_MCD
            and self.mcd_size_var.get() == "Нестандарт"
        )

    def _set_mcd_standard_size(self, value=None):
        value = value or self.mcd_size_var.get()
        sizes = {
            "1780×580": (1780, 580),
            "1380×740": (1380, 740),
            "1700×1220": (1700, 1220),
            "2340×1220": (2340, 1220),
        }
        if value in sizes:
            self.width_mm, self.height_mm = sizes[value]
            self.mcd_manual_width_var.set(str(self.width_mm))
            self.mcd_manual_height_var.set(str(self.height_mm))
            self.layout_index = 0
            self.side2_layout_index = 0
            self._redraw_selection()
            if not getattr(self,"_loading_saved_product",False):
                self._sync_active_screen_from_form()

    def _on_mcd_size_changed(self, event=None):
        if self.screen_mode_var.get() != MODE_MCD:
            return
        if self.mcd_size_var.get() == "Нестандарт":
            self.mcd_manual_frame.pack(fill="x", pady=(0, 8))
            # Tk pack "before" не требуется: блок уже расположен после combobox.
            self.mcd_manual_width_var.set(str(self.width_mm) if self.width_mm else "")
            self.mcd_manual_height_var.set(str(self.height_mm) if self.height_mm else "")
            self.map_help_var.set("МЦД Нестандарт: габариты можно задать на координатном поле или вручную.")
        else:
            if self.mcd_manual_frame.winfo_manager():
                self.mcd_manual_frame.pack_forget()
            self._set_mcd_standard_size()
            self.map_help_var.set("МЦД: выбран стандартный типоразмер; координатное поле зафиксировано.")
        self._update_mode_ui()

    def _on_mcd_manual_dimensions(self, event=None):
        if not self._mcd_is_custom_size():
            return
        try:
            w = int(self.mcd_manual_width_var.get() or 0)
        except ValueError:
            w = 0
        try:
            h = int(self.mcd_manual_height_var.get() or 0)
        except ValueError:
            h = 0
        self.width_mm = max(0, min(MAX_W_MM, w))
        self.height_mm = max(0, min(MAX_H_MM, h))
        self.layout_index = 0
        self.side2_layout_index = 0
        self._redraw_selection()
        if not getattr(self,"_loading_saved_product",False):
            self._sync_active_screen_from_form()

    def _sync_mcd_size_controls_visibility(self):
        """V20.74: синхронизирует видимость блока «Типоразмер МЦД» с текущим режимом."""
        if not hasattr(self, "mcd_size_host"):
            return
        try:
            self.mcd_size_label.pack_forget()
            self.mcd_size_combo.pack_forget()
            self.mcd_manual_frame.pack_forget()
        except Exception:
            return

        mode = self.screen_mode_var.get() if hasattr(self, "screen_mode_var") else getattr(self, "screen_mode", MODE_RZD)
        if mode != MODE_MCD:
            return

        self.mcd_size_label.pack(anchor="w")
        self.mcd_size_combo.pack(fill="x", pady=(3, 6))
        if hasattr(self, "mcd_size_var") and self.mcd_size_var.get() == "Нестандарт":
            self.mcd_manual_frame.pack(fill="x", pady=(0, 8))

    def _on_screen_mode_changed(self):
        self.screen_mode = self.screen_mode_var.get()
        self.width_mm = 0
        self.height_mm = 0
        self.layouts = []
        self.layout_index = 0

        if hasattr(self, "mcd_size_host"):
            self._sync_mcd_size_controls_visibility()
            if self.screen_mode == MODE_MCD and self.mcd_size_var.get() != "Нестандарт":
                self._set_mcd_standard_size()

        if hasattr(self, "rzd_map_tabs"):
            if self.screen_mode == MODE_RZD:
                try: self.rzd_map_tabs.tab(self.rzd_nonstandard_page, state="normal")
                except tk.TclError: pass
            else:
                self.rzd_map_tabs.select(self.rzd_standard_page)
                try: self.rzd_map_tabs.tab(self.rzd_nonstandard_page, state="disabled")
                except tk.TclError: pass
        self._update_mode_ui()
        self._draw_grid()
        self._redraw_selection()
        self._on_side2_option_changed()
        try:self._dynamic_apply_autofill()
        except Exception:pass
        if not getattr(self,"_loading_saved_product",False):
            self._sync_active_screen_from_form()

    def _update_mode_ui(self):
        mode = self.screen_mode_var.get() if hasattr(self, "screen_mode_var") else self.screen_mode
        self.screen_mode = mode
        if mode == MODE_RZD:
            desc = "Кабинеты 640/960 мм; перебор всех допустимых последовательностей по X и Y."
            help_text = "РЖД/Кабинет: габарит привязывается к размерам, точно собираемым из 640/960 мм."
        elif mode == MODE_MCD:
            desc = "Модуль 320×160 мм; припуск 50 мм по периметру; R200."
            help_text = "МЦД: модульная зона 320×160 мм + по 50 мм с каждой стороны; углы R200."
        else:
            desc = "Свободный модульный габарит, кратный 320×160 мм."
            help_text = "Нестандарт: шаг выбора X = 320 мм, Y = 160 мм."
        if hasattr(self, "mode_description_var"):
            self.mode_description_var.set(desc)
        if hasattr(self, "map_help_var"):
            self.map_help_var.set(help_text)

    def _show_field_info(self, event):
        self._hide_field_info()

        tip = tk.Toplevel(self)
        tip.wm_overrideredirect(True)
        tip.attributes("-topmost", True)

        mode = self.screen_mode_var.get() if hasattr(self, "screen_mode_var") else MODE_RZD
        if mode == MODE_RZD:
            mode_info = (
                "РЖД / Кабинет\n"
                "Кабинеты: 960×960, 960×640, 640×960, 640×640 мм\n"
                "Допустимы все точные суммы 640/960 мм по X и Y."
            )
        elif mode == MODE_MCD:
            mode_info = (
                "МЦД\n"
                "Модуль: 320×160 мм\n"
                "Припуск: 50 мм с каждой стороны\n"
                "Скругление внешнего контура: R200 мм"
            )
        else:
            mode_info = (
                "Нестандарт\n"
                "Модуль: 320×160 мм\n"
                "Габариты кратны 320 мм по X и 160 мм по Y."
            )

        info_text = (
            f"Параметры координатного поля\n"
            f"Максимум X: {MAX_W_MM} мм\n"
            f"Максимум Y: {MAX_H_MM} мм\n\n"
            f"{mode_info}"
        )

        label = tk.Label(
            tip,
            text=info_text,
            justify="left",
            bg="#fffde8",
            fg="#333333",
            relief="solid",
            borderwidth=1,
            padx=9,
            pady=7,
            font=("Arial", 9)
        )
        label.pack()

        x = event.widget.winfo_rootx() + 18
        y = event.widget.winfo_rooty() + event.widget.winfo_height() + 5
        tip.wm_geometry(f"+{x}+{y}")
        self._tooltip_window = tip

    def _hide_field_info(self, event=None):
        if self._tooltip_window is not None:
            try:
                self._tooltip_window.destroy()
            except tk.TclError:
                pass
            self._tooltip_window = None

    def _build_project_journal_tab(self,parent):
        top=ttk.Frame(parent); top.pack(fill="x",pady=(0,8))
        ttk.Label(top,text="Журнал проекта",font=("Arial",18,"bold")).pack(side="left")
        self.project_journal_edit_var = tk.BooleanVar(value=False)
        self.project_journal_hint_var = tk.StringVar(value="Редактирование выключено")
        ttk.Checkbutton(
            top, text="Редактирование", variable=self.project_journal_edit_var,
            command=self._update_project_journal_edit_state
        ).pack(side="right", padx=(12, 0))
        ttk.Button(top, text="Удалить изделие", command=self._v3012_delete_journal_product).pack(side="right", padx=(12, 0))
        ttk.Button(top, text="Просмотр спецификации", command=self._open_specification_viewer).pack(side="right", padx=(12, 0))
        ttk.Button(
            top, text="Поз. спецификации",
            command=self._edit_selected_spec_position
        ).pack(side="right", padx=(12, 0))
        ttk.Label(top,textvariable=self.project_journal_hint_var,foreground="#666666").pack(side="right")

        # V20.75: подсказка быстрого просмотра комплектующих.
        ctrl_hint=ttk.Label(
            parent,
            text="Двойной клик — открыть изделие; F2 — изменить «Поз.» спецификации; Ctrl + клик — предпросмотр комплектующих.",
            foreground="#666666",
            justify="left"
        )
        ctrl_hint.pack(fill="x", pady=(0,6))

        # V20.34: внутри «Журнал проекта» два представления.
        # 1) прежний журнал изделий для открытия/редактирования;
        # 2) Excel-подобная калькуляционная матрица по счетам и изделиям.
        self.project_journal_views = ttk.Notebook(parent)
        self.project_journal_views.pack(fill="both", expand=True)
        items_page = ttk.Frame(self.project_journal_views, padding=2)
        matrix_page = ttk.Frame(self.project_journal_views, padding=2)
        self.project_journal_views.add(items_page, text="Изделия")
        self.project_journal_views.add(matrix_page, text="Калькуляция")

        # V20.36: после габарита отдельная колонка количества изделий.
        # V30.55: «calc» добавлен в конец данных (индексы прежних значений не меняются),
        # а на экране показывается первым через displaycolumns.
        cols=("spec_pos","num","fill_mode","type","name","article","serial","mark","series","size","qty","weight","sides","execution","calc")
        self.project_journal_tree=ttk.Treeview(items_page,columns=cols,show="tree headings",selectmode="browse")
        self.project_journal_tree.configure(displaycolumns=("calc",)+cols[:-1])
        self.project_journal_tree.heading("#0",text="")
        self.project_journal_tree.column("#0",width=26,stretch=False)
        headers={"spec_pos":"Поз.","num":"№","fill_mode":"Заполнение","type":"Тип изделия","name":"Наименование","article":"Артикул / код",
                 "serial":"Серийный номер","mark":"Маркировка","series":"Серия",
                 "size":"Габарит, мм","qty":"Кол-во изделий","weight":"Вес, кг","sides":"Ст.","execution":"Исполнение","calc":"Расчёт"}
        widths={"spec_pos":60,"num":45,"fill_mode":92,"type":145,"name":175,"article":125,"serial":120,"mark":80,"series":60,
                "size":110,"qty":105,"weight":80,"sides":48,"execution":155,"calc":62}
        self._project_journal_headers=dict(headers)
        self._project_journal_sort_column=None
        self._project_journal_sort_reverse=False
        for c in cols:
            self.project_journal_tree.heading(
                c,
                text=headers[c],
                command=lambda col=c:self._sort_project_journal_by_column(col)
            )
            self.project_journal_tree.column(c,width=widths[c],
                anchor=("center" if c in ("spec_pos","num","fill_mode","size","qty","weight","sides","calc") else "w"),
                stretch=(c not in ("spec_pos","num","fill_mode","weight","sides","calc")))
        sb=ttk.Scrollbar(items_page,orient="vertical",command=self.project_journal_tree.yview)
        xsb=ttk.Scrollbar(items_page,orient="horizontal",command=self.project_journal_tree.xview)
        self.project_journal_tree.configure(yscrollcommand=sb.set,xscrollcommand=xsb.set)
        xsb.pack(side="bottom",fill="x")
        self.project_journal_tree.pack(side="left",fill="both",expand=True); sb.pack(side="right",fill="y")
        self.project_journal_tree.bind("<Double-1>",self._project_journal_double_click)
        self.project_journal_tree.bind("<F2>",lambda e:(self._edit_selected_spec_position(),"break")[1])
        # V20.75: физический Ctrl + клик по любой ячейке строки открывает
        # предпросмотр комплектующих конкретного изделия.
        self.project_journal_tree.bind("<Control-Button-1>", self._project_journal_ctrl_click, add="+")
        # V20.63: в режиме редактирования верхнеуровневые изделия можно
        # перетаскивать мышью. Вложенные экземпляры перемещаются вместе с родителем.
        self.project_journal_tree.bind("<ButtonPress-1>", self._project_journal_drag_start, add="+")
        self.project_journal_tree.bind("<B1-Motion>", self._project_journal_drag_motion, add="+")
        self.project_journal_tree.bind("<ButtonRelease-1>", self._project_journal_drag_end, add="+")
        # V30.55: клик по столбцу «Расчёт» включает/выключает расчёт комплектующих изделия.
        self.project_journal_tree.bind("<ButtonRelease-1>", self._project_journal_calc_click, add="+")

        self._build_project_matrix_view(matrix_page)

        # V30.52: «Расход по изделиям» — обратная связь материал → изделия.
        usage_page = ttk.Frame(self.project_journal_views, padding=2)
        self.project_journal_views.add(usage_page, text="Расход по изделиям")
        self._build_material_usage_view(usage_page)

    def _build_project_matrix_view(self, parent):
        toolbar=ttk.Frame(parent)
        toolbar.pack(fill="x",pady=(0,5))
        ttk.Label(toolbar,text="Калькуляция по счетам и изделиям",font=("Arial",11,"bold")).pack(side="left")
        ttk.Label(toolbar,text="Данные слева — из вкладки «Счета», серые колонки — изделия проекта",
                  foreground="#666666").pack(side="left",padx=(12,0))
        ttk.Button(toolbar,text="Экспорт калькуляции",command=self._invoice_export_calculation_xlsx).pack(side="right",padx=(6,0))
        if CALC_ITEM_ASSIGNMENT_ENABLED:
            ttk.Button(toolbar,text="Назначить позиции",command=self._open_calc_assignment_dialog).pack(side="right",padx=(6,0))
        ttk.Button(toolbar,text="Обновить",command=self._refresh_project_matrix).pack(side="right")

        holder=ttk.Frame(parent)
        holder.pack(fill="both",expand=True)
        self.project_matrix_canvas=tk.Canvas(holder,bg="white",highlightthickness=0)
        vs=ttk.Scrollbar(holder,orient="vertical",command=self.project_matrix_canvas.yview)
        hs=ttk.Scrollbar(holder,orient="horizontal",command=self.project_matrix_canvas.xview)
        self.project_matrix_canvas.configure(yscrollcommand=vs.set,xscrollcommand=hs.set)
        hs.pack(side="bottom",fill="x")
        vs.pack(side="right",fill="y")
        self.project_matrix_canvas.pack(side="left",fill="both",expand=True)

        def wheel(event):
            if not getattr(self,"project_matrix_canvas",None): return
            delta=getattr(event,"delta",0)
            if delta:
                self.project_matrix_canvas.yview_scroll(-1 if delta>0 else 1,"units")
            elif getattr(event,"num",None)==4:
                self.project_matrix_canvas.yview_scroll(-1,"units")
            elif getattr(event,"num",None)==5:
                self.project_matrix_canvas.yview_scroll(1,"units")
            return "break"
        def shift_wheel(event):
            delta=getattr(event,"delta",0)
            if delta:
                self.project_matrix_canvas.xview_scroll(-1 if delta>0 else 1,"units")
            return "break"
        self.project_matrix_canvas.bind("<MouseWheel>",wheel)
        self.project_matrix_canvas.bind("<Shift-MouseWheel>",shift_wheel)
        self.project_matrix_canvas.bind("<Button-4>",wheel)
        self.project_matrix_canvas.bind("<Button-5>",wheel)

    def _project_matrix_products(self):
        """Колонки калькуляции по порядку спецификации.

        Только СОСЕДНИЕ изделия объединяются, и только если:
        1) у обоих непустая одинаковая «Поз.»;
        2) одинаковое наименование.
        Количество объединённых записей суммируется.

        V30.60 — динамика (табло МЦД и РЖД): изделия с одинаковыми «Поз.» и
        артикулом объединяются в одну колонку независимо от места в журнале и
        наименования; колонка стоит на месте первого из них. Разная «Поз.» —
        разные колонки. Без «Поз.» или без артикула — не объединяются.
        МЦД и РЖД между собой не объединяются.
        """
        raw=[]
        for _order,_ins,kind,i,rec in self._journal_product_records_in_order():
            spec=self._journal_spec_position(rec)
            if kind=="dynamic":
                name=str(
                    rec.get("screen_article","")
                    or rec.get("module_article","")
                    or f"Динамическое изделие {i+1}"
                ).strip()
                try:qty=max(1,int(rec.get("quantity",1) or 1))
                except Exception:qty=1
                key=f"dynamic:{i}"
                article=str(rec.get("module_article","") or "").strip()
                mode=rec.get("mode",MODE_RZD)
            else:
                name=str(
                    rec.get("name","")
                    or rec.get("article","")
                    or f"Статический указатель {i+1}"
                ).strip()
                raw_qty=str(rec.get("quantity","") or "").strip()
                try:qty=max(1,int(raw_qty)) if raw_qty.isdigit() else 1
                except Exception:qty=1
                key=f"static:{i}"
                article=""; mode=rec.get("mode",MODE_MCD)
            raw.append({"keys":[key],"spec":spec,"name":name,"qty":qty,
                        "kind":kind,"article":article,"mode":mode})

        grouped=[]
        dyn_index={}
        def _norm(v):
            return re.sub(r"\s+"," ",str(v or "")).strip().casefold()
        for item in raw:
            if item["kind"]=="dynamic" and item["spec"] and item["article"]:
                dkey=(item["mode"],_norm(item["spec"]),_norm(item["article"]))
                if dkey in dyn_index:
                    target=grouped[dyn_index[dkey]]
                    target["qty"]+=item["qty"]
                    target["keys"].extend(item["keys"])
                else:
                    dyn_index[dkey]=len(grouped)
                    grouped.append(dict(item,keys=list(item["keys"])))
                continue
            if (
                grouped
                and grouped[-1].get("kind")==item["kind"]
                and item["spec"]
                and grouped[-1]["spec"]==item["spec"]
                and grouped[-1]["name"]==item["name"]
            ):
                grouped[-1]["qty"]+=item["qty"]
                grouped[-1]["keys"].extend(item["keys"])
            else:
                grouped.append(dict(item))

        return [
            ("+".join(item["keys"]),item["name"],item["qty"])
            for item in grouped
        ]


    def _refresh_project_matrix(self):
        c=getattr(self,"project_matrix_canvas",None)
        if c is None:return
        c.delete("all")

        # Точные цвета из присланного образца «Калькуляция Примыкание».
        COLOR_PALE_YELLOW="#FFFFCC"
        COLOR_DARK_GRAY="#C9C9C9"
        COLOR_BLUE="#00B0F0"
        COLOR_ORANGE="#F4B183"
        COLOR_GRID="#333333"
        COLOR_PROJECT="#7030A0"

        left_headers=["Покупатель","Поставщик","Дата","№ Счета","Наименование товара","Кол-во"]
        left_widths=[130,230,95,155,380,75]
        product_w=195
        total_w_col=95
        balance_w_col=95
        title_h=30
        header_h=150
        qty_h=30
        start_x=0
        products=self._project_matrix_products()
        invoices=list(getattr(self,"invoice_rows",[]) or [])

        def rect(x1,y1,x2,y2,fill,outline=COLOR_GRID,width=1):
            c.create_rectangle(x1,y1,x2,y2,fill=fill,outline=outline,width=width)
        def cell_text(x1,y1,x2,y2,text,*,font=("Arial",9),anchor="center",bold=False,color="black"):
            f=(font[0],font[1],"bold") if bold else font
            if anchor=="center":
                c.create_text((x1+x2)/2,(y1+y2)/2,text=str(text or ""),font=f,fill=color,
                              width=max(10,x2-x1-8),justify="center")
            else:
                c.create_text(x1+5,(y1+y2)/2,text=str(text or ""),font=f,fill=color,
                              width=max(10,x2-x1-10),anchor="w",justify="left")

        total_left=sum(left_widths)
        # Верхняя строка с названием проекта над колонками изделий — как в образце.
        if products:
            px1=total_left; px2=px1+product_w*len(products)
            rect(px1,0,px2,title_h,"white",outline=COLOR_GRID)
            cell_text(px1,0,px2,title_h,self.project_name_var.get().strip() if hasattr(self,"project_name_var") else self.project_name,
                      font=("Arial",10),bold=True,color=COLOR_PROJECT)

        # Основная шапка слева.
        x=start_x
        for title,w in zip(left_headers,left_widths):
            rect(x,title_h,x+w,title_h+header_h,COLOR_PALE_YELLOW)
            cell_text(x,title_h,x+w,title_h+header_h,title,font=("Arial",10),bold=True)
            x+=w

        # Серые ячейки — наименования изделий.
        for _key,name,qty in products:
            rect(x,title_h,x+product_w,title_h+header_h,COLOR_DARK_GRAY)
            cell_text(x,title_h,x+product_w,title_h+header_h,name,font=("Arial",9))
            x+=product_w

        # В образце после серых колонок изделий всегда идут «ИТОГО» и «Остаток».
        rect(x,title_h,x+total_w_col,title_h+header_h,COLOR_PALE_YELLOW)
        cell_text(x,title_h,x+total_w_col,title_h+header_h,"ИТОГО",font=("Arial",10),bold=True)
        x+=total_w_col
        rect(x,title_h,x+balance_w_col,title_h+header_h,COLOR_PALE_YELLOW)
        cell_text(x,title_h,x+balance_w_col,title_h+header_h,"Остаток",font=("Arial",10),bold=True)
        x+=balance_w_col

        # Строка «Количество изделий» и оранжевые количества.
        x=0
        rect(x,title_h+header_h,total_left,title_h+header_h+qty_h,COLOR_BLUE)
        cell_text(x,title_h+header_h,total_left,title_h+header_h+qty_h,"Количество изделий",font=("Arial",10),bold=True)
        x=total_left
        for _key,_name,qty in products:
            rect(x,title_h+header_h,x+product_w,title_h+header_h+qty_h,COLOR_ORANGE)
            cell_text(x,title_h+header_h,x+product_w,title_h+header_h+qty_h,qty,font=("Arial",10),bold=True)
            x+=product_w
        # Как в Excel-образце: под «ИТОГО» — жёлтая ячейка, под «Остаток» — голубая.
        rect(x,title_h+header_h,x+total_w_col,title_h+header_h+qty_h,"#FFFF00")
        x+=total_w_col
        rect(x,title_h+header_h,x+balance_w_col,title_h+header_h+qty_h,COLOR_BLUE)
        x+=balance_w_col

        # V30.40: ячейки распределения заполняются автоматически по норме BOM.
        # Назначения — из памяти проекта (metadata) + словаря PROCUREMENT_TO_BOM.
        try:
            _ap,alloc_entries=self._calc_allocation_rows()
        except Exception:
            alloc_entries=[None]*len(invoices)
        def fmt_qty(v):
            if v is None:return ""
            return str(int(round(v))) if abs(v-round(v))<1e-6 else f"{v:.2f}".replace(".",",")
        y=title_h+header_h+qty_h
        for ridx,row in enumerate(invoices):
            item=str(getattr(row,"item","") or "")
            L=len(item)
            row_h=28 if L<=55 else 44 if L<=120 else 62
            values=[getattr(row,"buyer",""),getattr(row,"supplier",""),getattr(row,"date",""),
                    getattr(row,"invoice",""),item,getattr(row,"qty","")]
            x=0
            for idx,(val,w) in enumerate(zip(values,left_widths)):
                rect(x,y,x+w,y+row_h,"white")
                cell_text(x,y,x+w,y+row_h,val,font=("Arial",8 if idx==4 else 9),anchor=("left" if idx in (0,1,4) else "center"))
                x+=w
            entry=alloc_entries[ridx] if ridx<len(alloc_entries) else None
            cells=(entry or {}).get("cells") if entry else None
            for pidx,(_key,_name,_qty) in enumerate(products):
                rect(x,y,x+product_w,y+row_h,"white")
                if cells and pidx<len(cells) and cells[pidx]:
                    cell_text(x,y,x+product_w,y+row_h,fmt_qty(cells[pidx]),font=("Arial",9))
                x+=product_w
            # ИТОГО / Остаток из расчёта распределения.
            rect(x,y,x+total_w_col,y+row_h,"white")
            if entry and entry.get("itogo") is not None:
                cell_text(x,y,x+total_w_col,y+row_h,fmt_qty(entry["itogo"]),font=("Arial",9),bold=True)
            x+=total_w_col
            rect(x,y,x+balance_w_col,y+row_h,"white")
            if entry and entry.get("ostatok") is not None:
                ost=entry["ostatok"]
                cell_text(x,y,x+balance_w_col,y+row_h,fmt_qty(ost),font=("Arial",9),
                          color=("#B00000" if ost<-1e-6 else "black"))
            x+=balance_w_col
            y+=row_h

        if not invoices:
            y0=title_h+header_h+qty_h
            empty_w=max(total_left,total_left+product_w*max(1,len(products))+total_w_col+balance_w_col)
            rect(0,y0,empty_w,y0+45,"white")
            cell_text(0,y0,empty_w,y0+45,
                      "Нет распознанных позиций. Добавьте документы во вкладке «Счета».",font=("Arial",10),color="#666666")
            y=y0+45

        total_w=max(total_left,total_left+product_w*len(products)+total_w_col+balance_w_col)
        c.configure(scrollregion=(0,0,total_w+2,y+2))
        c.xview_moveto(0); c.yview_moveto(0)

    def _update_project_journal_edit_state(self):
        enabled = bool(getattr(self, "project_journal_edit_var", tk.BooleanVar(value=False)).get())
        if hasattr(self, "project_journal_hint_var"):
            self.project_journal_hint_var.set(
                "Двойной щелчок — редактировать; перетаскивание — изменить порядок"
                if enabled else "Редактирование выключено"
            )

    def _project_journal_product_iid(self, iid):
        """Вложенный экземпляр LED относится к родительскому изделию."""
        value=str(iid or "")
        if value.startswith("ledinst:"):
            parts=value.split(":")
            if len(parts)>=2:
                return f"led:{parts[1]}"
        return value

    def _component_scope_for_journal_iid(self, iid):
        """Возвращает точное значение выпадающего списка «Комплектующие» для изделия журнала."""
        iid=self._project_journal_product_iid(iid)
        self._refresh_components_screen_selector()
        values=list(self.component_scope_combo["values"]) if hasattr(self,"component_scope_combo") else []

        if iid.startswith("led:"):
            try:index=int(iid.split(":",1)[1])+1
            except Exception:return None
            prefix=f"LED {index} —"
        elif iid.startswith("static:"):
            try:
                idx=int(iid.split(":",1)[1])
                signs=getattr(self,"saved_static_signs",[]) or []
                if not (0 <= idx < len(signs)): return None
                prefix=("МЦД" if signs[idx].get("mode",MODE_MCD)==MODE_MCD else "РЖД") + f" {idx+1} —"
            except Exception:
                return None
        else:
            return None

        for value in values:
            if str(value).startswith(prefix):
                return value
        return None

    def _component_rows_for_scope(self, scope_value):
        """Получает рассчитанные строки BOM для одного scope, не меняя состояние вкладки."""
        if not scope_value or not hasattr(self,"components_tree"):
            return []

        old_scope=self.component_scope_var.get()
        old_search=(self.component_search_var.get() if hasattr(self,"component_search_var") else "")
        try:
            if hasattr(self,"component_search_var"):
                self.component_search_var.set("")
            self.component_scope_var.set(scope_value)
            self._refresh_components_table()
            rows=self._components_print_rows()
            return [dict(r) for r in rows]
        finally:
            self.component_scope_var.set(old_scope)
            if hasattr(self,"component_search_var"):
                self.component_search_var.set(old_search)
            self._refresh_components_table()

    def _journal_component_preview_title(self, iid):
        iid=self._project_journal_product_iid(iid)
        try:
            vals=list(self.project_journal_tree.item(iid,"values"))
        except Exception:
            vals=[]
        name=str(vals[2] if len(vals)>2 else "").strip()
        article_legacy=str(vals[3] if len(vals)>3 else "").strip()
        size=str(vals[7] if len(vals)>7 else "").strip()
        bits=[x for x in (name,article_legacy,size) if x]
        base=" — ".join(bits) or "Комплектующие изделия"
        # V30.42: добавляем артикул изделия и количество изделий в заголовок превью.
        article=str(vals[5] if len(vals)>5 else "").strip()
        qty_products=str(vals[10] if len(vals)>10 else "").strip()
        if article:
            base+=" — "+article
        if qty_products:
            base+=f" · {qty_products} шт"
        return base

    def _open_components_scope_from_preview(self, scope_value, preview=None):
        """Переход из предпросмотра во вкладку Комплектующие к конкретному изделию."""
        if not scope_value:return "break"
        try:
            if preview is not None and preview.winfo_exists():
                preview.destroy()
        except Exception:
            pass
        self._refresh_components_screen_selector()
        values=list(self.component_scope_combo["values"])
        if scope_value in values:
            self.component_scope_var.set(scope_value)
        if hasattr(self,"component_search_var"):
            self.component_search_var.set("")
        self._refresh_components_table()
        try:
            self.notebook.select(self.components_tab)
        except Exception:
            # components_tab не был сохранён как атрибут в старых версиях:
            try:
                for tab_id in self.notebook.tabs():
                    if self.notebook.tab(tab_id,"text")=="Комплектующие":
                        self.notebook.select(tab_id)
                        break
            except Exception:
                pass
        return "break"

    def _show_journal_components_preview(self, iid):
        """Окно предпросмотра фактического BOM одного изделия."""
        iid=self._project_journal_product_iid(iid)
        scope=self._component_scope_for_journal_iid(iid)
        if not scope:
            return

        rows=self._component_rows_for_scope(scope)
        title=self._journal_component_preview_title(iid)

        # V30.42: расход на одно изделие считаем прямым пересчётом BOM этого же
        # изделия с количеством = 1. Так корректно и для функций, масштабирующих
        # норму по количеству (МЦД-статика, экраны), и для не масштабирующих
        # (РЖД-статика): значение всегда соответствует одному физическому изделию.
        per_unit_map={}
        _seq=None
        if iid.startswith("led:"):
            _seq=getattr(self,"saved_screens",[]) or []
        elif iid.startswith("static:"):
            _seq=getattr(self,"saved_static_signs",[]) or []
        _idx=None
        if _seq is not None:
            try:_idx=int(iid.split(":",1)[1])
            except Exception:_idx=None
        if _seq is not None and _idx is not None and 0<=_idx<len(_seq):
            _rec=_seq[_idx]
            _saved_q=_rec.get("quantity")
            try:
                _rec["quantity"]="1" if isinstance(_saved_q,str) else 1
                for _r in self._component_rows_for_scope(scope):
                    per_unit_map[(str(_r.get("name","")),str(_r.get("unit","")))]=_r.get("qty","")
            except Exception:
                per_unit_map={}
            finally:
                _rec["quantity"]=_saved_q
        def _per_unit_for(rec):
            return per_unit_map.get((str(rec.get("name","")),str(rec.get("unit",""))),"")

        win=tk.Toplevel(self)
        win.title("Комплектующие — "+title)
        win.geometry("900x570")
        win.minsize(680,420)
        try:win.transient(self)
        except Exception:pass

        head=ttk.Frame(win,padding=(10,9))
        head.pack(fill="x")
        ttk.Label(head,text=title,font=("Arial",14,"bold")).pack(side="left")
        ttk.Label(
            head,
            text="Ctrl + клик по списку → открыть изделие во вкладке «Комплектующие»",
            foreground="#666666"
        ).pack(side="right")

        holder=ttk.Frame(win,padding=(10,0,10,10))
        holder.pack(fill="both",expand=True)
        holder.columnconfigure(0,weight=1); holder.rowconfigure(0,weight=1)

        # V30.42: колонка расхода на одно изделие — слева от «Количество».
        cols=("name","unit","per_unit","qty","weight","supplier")
        tree=ttk.Treeview(holder,columns=cols,show="tree headings")
        tree.heading("#0",text="Подгруппа")
        tree.column("#0",width=185,stretch=False,anchor="w")
        tree.heading("name",text="Комплектующая")
        tree.heading("unit",text="Ед.")
        tree.heading("per_unit",text="На 1 изделие")
        tree.heading("qty",text="Количество")
        tree.heading("weight",text="Вес, кг")
        tree.heading("supplier",text="Поставщик")
        tree.column("name",width=430,anchor="w")
        tree.column("unit",width=70,anchor="center",stretch=False)
        tree.column("per_unit",width=100,anchor="center",stretch=False)
        tree.column("qty",width=100,anchor="center",stretch=False)
        tree.column("weight",width=100,anchor="center",stretch=False)
        tree.column("supplier",width=180,anchor="w")

        ybar=ttk.Scrollbar(holder,orient="vertical",command=tree.yview)
        xbar=ttk.Scrollbar(holder,orient="horizontal",command=tree.xview)
        tree.configure(yscrollcommand=ybar.set,xscrollcommand=xbar.set)
        tree.grid(row=0,column=0,sticky="nsew")
        ybar.grid(row=0,column=1,sticky="ns")
        xbar.grid(row=1,column=0,sticky="ew")

        by_group={}
        order=[]
        for rec in rows:
            group=str(rec.get("group","") or "Прочее")
            if group not in by_group:
                by_group[group]=[]
                order.append(group)
            by_group[group].append(rec)

        for gi,group in enumerate(order):
            parent=f"preview_group_{gi}"
            tree.insert("","end",iid=parent,text=group,values=("","","","","",""),open=True)
            for ri,rec in enumerate(by_group[group]):
                tree.insert(
                    parent,"end",iid=f"preview_{gi}_{ri}",text="",
                    values=(rec.get("name",""),rec.get("unit",""),_per_unit_for(rec),rec.get("qty",""),rec.get("weight",""),rec.get("supplier",""))
                )

        if not rows:
            tree.insert("","end",text="",values=("Комплектующие для изделия не рассчитаны.","","","","",""))

        def open_components(event=None):
            return self._open_components_scope_from_preview(scope,win)

        # Layout-independent physical Ctrl. Mouse binding is independent of keyboard language.
        tree.bind("<Control-Button-1>",open_components,add="+")
        win.bind("<Control-Button-1>",open_components,add="+")
        head.bind("<Control-Button-1>",open_components,add="+")
        holder.bind("<Control-Button-1>",open_components,add="+")
        return win

    def _project_journal_ctrl_click(self, event):
        """Ctrl + клик по любой ячейке строки журнала → BOM предпросмотр."""
        try:
            iid=self.project_journal_tree.identify_row(event.y)
        except Exception:
            iid=""
        if not iid:
            return None
        iid=self._project_journal_product_iid(iid)
        if not (iid.startswith("led:") or iid.startswith("static:")):
            return None
        self._show_journal_components_preview(iid)
        return "break"

    def _project_journal_sort_value(self, iid, col):
        """Нормализованное значение строки журнала для сортировки."""
        tree=self.project_journal_tree
        columns=list(tree["columns"])
        try:
            ci=columns.index(col)
        except ValueError:
            return (2,"")
        vals=list(tree.item(iid,"values"))
        value=vals[ci] if ci < len(vals) else ""

        if col in {"num","qty","weight","sides"}:
            raw=str(value or "").strip().replace(" ","").replace(",",".")
            m=re.search(r"-?\d+(?:\.\d+)?",raw)
            if m:
                try:return (0,float(m.group(0)))
                except Exception:pass
            return (1,0.0)

        if col=="size":
            raw=str(value or "").strip().lower().replace("×","x").replace("х","x")
            nums=re.findall(r"\d+(?:[.,]\d+)?",raw)
            if nums:
                try:
                    parsed=tuple(float(x.replace(",",".")) for x in nums)
                    return (0,parsed)
                except Exception:
                    pass

        s=str(value or "").strip().casefold().replace("ё","е")
        parts=re.split(r"(\d+(?:[.,]\d+)?)",s)
        natural=[]
        for part in parts:
            if re.fullmatch(r"\d+(?:[.,]\d+)?",part or ""):
                try:natural.append((0,float(part.replace(",","."))))
                except Exception:natural.append((1,part))
            else:
                natural.append((1,part))
        return (0,tuple(natural))

    def _project_journal_update_sort_headers(self):
        """Показывает направление сортировки стрелкой в заголовке."""
        tree=getattr(self,"project_journal_tree",None)
        headers=getattr(self,"_project_journal_headers",{}) or {}
        if tree is None:return
        active=getattr(self,"_project_journal_sort_column",None)
        reverse=bool(getattr(self,"_project_journal_sort_reverse",False))
        for col,title in headers.items():
            suffix=""
            if col==active:
                suffix=" ▼" if reverse else " ▲"
            try:
                tree.heading(
                    col,
                    text=title+suffix,
                    command=lambda c=col:self._sort_project_journal_by_column(c)
                )
            except Exception:
                pass

    def _project_journal_commit_current_order(self):
        """Сохраняет текущий порядок строк и пересчитывает №."""
        tree=getattr(self,"project_journal_tree",None)
        if tree is None:return
        roots=list(tree.get_children(""))
        for index,row_iid in enumerate(roots):
            rec=self._project_journal_record_for_iid(row_iid)
            if isinstance(rec,dict):
                rec["journal_order"]=index
            vals=list(tree.item(row_iid,"values"))
            if vals:
                vals[1]=index+1
                tree.item(row_iid,values=vals)

    def _sort_project_journal_by_column(self, col):
        """Сортировка верхнеуровневых изделий по выбранному столбцу."""
        tree=getattr(self,"project_journal_tree",None)
        if tree is None:return

        if getattr(self,"_project_journal_sort_column",None)==col:
            self._project_journal_sort_reverse=not bool(
                getattr(self,"_project_journal_sort_reverse",False)
            )
        else:
            self._project_journal_sort_column=col
            self._project_journal_sort_reverse=False

        roots=list(tree.get_children(""))
        reverse=bool(self._project_journal_sort_reverse)
        decorated=[]
        for original_index,iid in enumerate(roots):
            decorated.append((
                self._project_journal_sort_value(iid,col),
                original_index,
                iid
            ))

        decorated.sort(key=lambda x:(x[0],x[1]), reverse=reverse)

        for new_index,(_,_,iid) in enumerate(decorated):
            tree.move(iid,"",new_index)

        self._project_journal_commit_current_order()
        self._project_journal_update_sort_headers()
        self._mark_project_dirty()
        try:self._refresh_project_matrix()
        except Exception:pass

    def _project_journal_record_for_iid(self, iid):
        """Возвращает словарь сохранённого изделия для верхнеуровневой строки журнала."""
        try:
            if str(iid).startswith("led:"):
                idx=int(str(iid).split(":",1)[1])
                if 0 <= idx < len(getattr(self,"saved_screens",[]) or []):
                    return self.saved_screens[idx]
            if str(iid).startswith("static:"):
                idx=int(str(iid).split(":",1)[1])
                signs=getattr(self,"saved_static_signs",[]) or []
                if 0 <= idx < len(signs):
                    return signs[idx]
        except Exception:
            pass
        return None

    def _project_journal_apply_saved_order(self):
        """Восстанавливает сохранённый порядок изделий и пересчитывает колонку №."""
        tree=getattr(self,"project_journal_tree",None)
        if tree is None:
            return
        roots=list(tree.get_children(""))
        decorated=[]
        for insertion_index,iid in enumerate(roots):
            rec=self._project_journal_record_for_iid(iid)
            raw=rec.get("journal_order") if isinstance(rec,dict) else None
            try:
                order=float(raw)
            except Exception:
                order=10**9 + insertion_index
            decorated.append((order, insertion_index, iid, rec))

        decorated.sort(key=lambda x:(x[0],x[1]))
        for new_index,(_,_,iid,rec) in enumerate(decorated):
            tree.move(iid,"",new_index)
            if isinstance(rec,dict):
                rec["journal_order"]=new_index
            vals=list(tree.item(iid,"values"))
            if vals:
                vals[1]=new_index+1
                tree.item(iid,values=vals)

    def _project_journal_drag_start(self, event):
        self._project_journal_drag_iid=None
        self._project_journal_drag_changed=False
        try:
            if not bool(self.project_journal_edit_var.get()):
                return
            region=str(self.project_journal_tree.identify_region(event.x,event.y) or "")
            if region not in ("cell","tree"):
                return
            iid=self.project_journal_tree.identify_row(event.y)
            if not iid:
                return
            if self.project_journal_tree.parent(iid):
                return
            if not (str(iid).startswith("led:") or str(iid).startswith("static:")):
                return
            self._project_journal_drag_iid=iid
            self._project_journal_drag_start_y=event.y
        except Exception:
            self._project_journal_drag_iid=None

    def _project_journal_drag_motion(self, event):
        iid=getattr(self,"_project_journal_drag_iid",None)
        if not iid:
            return
        try:
            tree=self.project_journal_tree
            if not tree.exists(iid):
                return
            target=tree.identify_row(event.y)
            if not target:
                return
            parent=tree.parent(target)
            if parent:
                target=parent
            if target==iid or not target:
                return
            roots=list(tree.get_children(""))
            if target not in roots or iid not in roots:
                return
            target_index=roots.index(target)
            bbox=tree.bbox(target)
            if bbox:
                _,ty,_,th=bbox
                insert_index=target_index + (1 if event.y > ty + th/2 else 0)
            else:
                insert_index=target_index
            current_index=roots.index(iid)
            if current_index < insert_index:
                insert_index-=1
            insert_index=max(0,min(insert_index,len(roots)-1))
            if insert_index != current_index:
                tree.move(iid,"",insert_index)
                self._project_journal_drag_changed=True
                tree.selection_set(iid)
                tree.focus(iid)
        except Exception:
            pass

    def _project_journal_drag_end(self, event=None):
        iid=getattr(self,"_project_journal_drag_iid",None)
        changed=bool(getattr(self,"_project_journal_drag_changed",False))
        self._project_journal_drag_iid=None
        self._project_journal_drag_changed=False
        if not iid or not changed:
            return
        try:
            self._project_journal_commit_current_order()
            self._project_journal_sort_column=None
            self._project_journal_sort_reverse=False
            self._project_journal_update_sort_headers()
            self._mark_project_dirty()
            try:self._refresh_project_matrix()
            except Exception:pass
        except Exception:
            pass

    def _project_journal_double_click(self, event=None):
        """V20.88: двойной клик по любой ячейке строки открывает конкретное изделие."""
        try:
            if event is not None:
                iid=self.project_journal_tree.identify_row(event.y)
                if iid:
                    self.project_journal_tree.selection_set(iid)
                    self.project_journal_tree.focus(iid)
        except Exception:
            pass
        return self._open_project_journal_item(event)


    def _start_project_journal_cell_edit(self, iid, col):
        """Редактируем напрямую только поля, которые однозначно соответствуют параметрам изделия."""
        if col not in {"spec_pos","name","article","serial","series","qty"}:
            return False
        if iid.startswith("static:") and col in {"serial","series"}:
            return False
        if iid.startswith("ledinst:") and col not in {"serial","series","spec_pos"}:
            return False
        try:
            columns=list(self.project_journal_tree["columns"])
            col_index=columns.index(col)+1
            bbox=self.project_journal_tree.bbox(iid,col)
            if not bbox:return False
            x,y,w,h=bbox
            values=list(self.project_journal_tree.item(iid,"values"))
            current=values[col_index-1] if col_index-1 < len(values) else ""
        except Exception:
            return False

        old=getattr(self,"_project_journal_editor",None)
        if old is not None:
            try: old.destroy()
            except Exception: pass
        editor=ttk.Entry(self.project_journal_tree)
        self._project_journal_editor=editor
        editor.insert(0,str(current or ""))
        editor.place(x=x,y=y,width=max(40,w),height=max(20,h))
        editor.focus_set(); editor.selection_range(0,"end")
        state={"done":False}
        def finish(save=True):
            if state["done"]:return
            state["done"]=True
            value=editor.get().strip()
            try:editor.destroy()
            except Exception:pass
            self._project_journal_editor=None
            if save:self._apply_project_journal_cell_edit(iid,col,value)
        editor.bind("<Return>",lambda e:(finish(True),"break")[1])
        editor.bind("<KP_Enter>",lambda e:(finish(True),"break")[1])
        editor.bind("<Escape>",lambda e:(finish(False),"break")[1])
        editor.bind("<FocusOut>",lambda e:finish(True))
        return True

    def _apply_project_journal_cell_edit(self, iid, col, value):
        """Записывает изменение ячейки одновременно в запись проекта и в форму параметров,
        если это изделие сейчас открыто для редактирования.
        """
        try:
            if iid.startswith("ledinst:"):
                _,si,ii=iid.split(":"); si=int(si); ii=int(ii)
                if not (0 <= si < len(self.saved_screens)):return
                screen=self.saved_screens[si]; instances=self._ensure_screen_instances(screen)
                if not (0 <= ii < len(instances)):return
                inst=instances[ii]
                if col=="serial": inst["part_number"]="".join(ch for ch in value if ch.isdigit())
                elif col=="series": inst["led_series"]="".join(ch for ch in value if ch.isdigit())[:3]
                elif col=="spec_pos": screen["spec_position"]=str(value).strip()
                else:return
                if ii==0:
                    screen["part_number"]=inst.get("part_number","")
                    screen["led_series"]=inst.get("led_series",screen.get("led_series",""))
                if getattr(self,"_active_led_instance",None)==(si,ii):
                    self._loading_saved_product=True
                    try:
                        if col=="serial": self.part_number_var.set(inst.get("part_number",""))
                        else:self.led_series_var.set(inst.get("led_series",""))
                    finally:self._loading_saved_product=False
            elif iid.startswith("led:"):
                si=int(iid.split(":",1)[1])
                if not (0 <= si < len(self.saved_screens)):return
                screen=self.saved_screens[si]
                if col=="spec_pos":
                    screen["spec_position"]=str(value).strip()
                elif col=="name":
                    screen["screen_article"]=value; screen["autofill"]=False
                elif col=="article":
                    screen["module_article"]=value.upper(); screen["autofill"]=False
                elif col=="qty":
                    try:q=max(1,int(value or 1))
                    except Exception:return
                    screen["quantity"]=q; self._ensure_screen_instances(screen)
                elif col=="serial":
                    instances=self._ensure_screen_instances(screen); clean="".join(ch for ch in value if ch.isdigit())
                    if instances:instances[0]["part_number"]=clean
                    screen["part_number"]=clean
                elif col=="series":
                    clean="".join(ch for ch in value if ch.isdigit())[:3]; screen["led_series"]=clean
                    instances=self._ensure_screen_instances(screen)
                    if instances:instances[0]["led_series"]=clean
                else:return
                if getattr(self,"_active_screen_index",None)==si:
                    self._loading_saved_product=True
                    try:
                        if col=="name":
                            if hasattr(self,"dynamic_autofill_var"):self.dynamic_autofill_var.set(False)
                            self.screen_article_var.set(screen["screen_article"])
                        elif col=="article":
                            if hasattr(self,"dynamic_autofill_var"):self.dynamic_autofill_var.set(False)
                            self.module_article_var.set(screen["module_article"])
                        elif col=="qty":self.screen_quantity_var.set(str(screen["quantity"]))
                        elif col=="serial":self.part_number_var.set(screen.get("part_number",""))
                        elif col=="series":self.led_series_var.set(screen.get("led_series",""))
                    finally:self._loading_saved_product=False
            elif iid.startswith("static:"):
                si=int(iid.split(":",1)[1]); signs=getattr(self,"saved_static_signs",[])
                if not (0 <= si < len(signs)):return
                sign=signs[si]
                if col=="spec_pos":sign["spec_position"]=str(value).strip()
                elif col=="name":sign["name"]=value; sign["autofill"]=False
                elif col=="article":sign["article"]=value.upper(); sign["autofill"]=False
                elif col=="qty":
                    try:q=max(1,int(value or 1))
                    except Exception:return
                    sign["quantity"]=str(q)
                else:return
                if getattr(self,"_active_static_index",None)==si:
                    self._loading_saved_product=True
                    try:
                        if col=="name":
                            if hasattr(self,"static_autofill_var"):self.static_autofill_var.set(False)
                            self.static_name_var.set(sign["name"])
                        elif col=="article":
                            if hasattr(self,"static_autofill_var"):self.static_autofill_var.set(False)
                            self.static_article_var.set(sign["article"])
                        elif col=="qty":self.static_quantity_var.set(str(sign["quantity"]))
                    finally:self._loading_saved_product=False
            else:return
        except Exception:
            return
        self._mark_project_dirty()
        try:self._rebuild_saved_screens_tree()
        except Exception:pass
        try:self._refresh_static_saved_tree()
        except Exception:pass
        try:self._refresh_project_journal()
        except Exception:pass
        try:self._refresh_components_screen_selector()
        except Exception:pass
        try:self._refresh_components_table()
        except Exception:pass

    def _party_letter(self, index):
        letters=list("АБВГДЕЖЗИЙКЛМНПРСТУФХЦЧШЩЪЫЬЭЮЯ")
        n=max(0,int(index)); out=""; base=len(letters)
        while True:
            out=letters[n%base]+out
            n=n//base-1
            if n<0: break
        return out

    def _ensure_screen_instances(self, screen):
        qty=max(1,int(screen.get("quantity",1) or 1))
        instances=screen.get("instances")
        if not isinstance(instances,list): instances=[]
        base_series=str(screen.get("led_series",screen.get("firmware","")) or "")[:3]
        base_part="".join(ch for ch in str(screen.get("part_number","") or "") if ch.isdigit())
        while len(instances)<qty:
            j=len(instances)
            instances.append({"part_number":base_part if (qty==1 or j==0) else "","led_series":base_series})
        instances=instances[:qty]
        for inst in instances:
            inst.setdefault("part_number",""); inst.setdefault("led_series",base_series)
        screen["instances"]=instances
        return instances

    def _instance_mark(self, group_index, instance_index):
        return f"{group_index+1}.{self._party_letter(instance_index)}"

    def _save_active_instance_overrides(self):
        active=getattr(self,"_active_led_instance",None)
        if not active:return
        try:
            gi,ii=active; screen=self.saved_screens[gi]; inst=self._ensure_screen_instances(screen)[ii]
            inst["part_number"]="".join(ch for ch in self.part_number_var.get() if ch.isdigit())
            inst["led_series"]="".join(ch for ch in self.led_series_var.get() if ch.isdigit())[:3]
            screen["part_number"] = inst["part_number"]
            if hasattr(self,"project_journal_tree"):
                parent_iid=f"led:{gi}"
                if self.project_journal_tree.exists(parent_iid):
                    vals=list(self.project_journal_tree.item(parent_iid,"values"))
                    if len(vals)>=7:
                        vals[4]=inst["part_number"]; vals[6]=inst["led_series"]
                        self.project_journal_tree.item(parent_iid,values=vals)
                iid=f"ledinst:{gi}:{ii}"
                if self.project_journal_tree.exists(iid):
                    vals=list(self.project_journal_tree.item(iid,"values"))
                    if len(vals)>=7:
                        vals[4]=inst["part_number"]; vals[6]=inst["led_series"]
                        self.project_journal_tree.item(iid,values=vals)
        except Exception: pass

    def _screen_weight_kg(self, screen):
        """Вес изделия без упаковки по актуальному справочнику."""
        if screen.get("mode", MODE_RZD) == MODE_MCD:
            one=dict(screen); one["quantity"]=1
            rows=self._dynamic_mcd_component_rows_v1972([one])
            unit_g=MCD_UNIT_WEIGHTS_G
            module_g={"LED-модуль P 2.5 IN":414,"LED-модуль P 2.5 ID":414,"LED-модуль P 2.5 OD":416,"LED-модуль P1.53 OD":433,
                      "LED-модуль P1.25 IN":433,"LED-модуль P1.25 ID":433,"LED-модуль P1.25 OD":433,
                      "LED-модуль P4.0 IN":340,"LED-модуль P4.0 ID":340,"LED-модуль P4.0 OD":430,
                      "LED-модуль P5.0 OD":429,"LED-модуль P3,07 OD":425}
            total=0.0; mod=self._selected_led_module_name(one)
            for name,unit,qty in rows:
                q=float(qty) if isinstance(qty,(int,float)) else 0.0
                if name==mod and mod in module_g: total+=q*module_g[mod]
                elif str(name).startswith("Профиль 175мм"):
                    total+=(2*(float(one.get("width",0))+float(one.get("height",0)))/1000.0)*3880
                elif str(name).startswith("Профиль Гефест"):
                    # V30.39: справочник — 400 гр/м.п; длина каждого профиля = высота изделия.
                    total+=q*(float(one.get("height",0))/1000.0)*400
                elif str(name).startswith("Оргстекло 8 мм"):
                    gw=max(0,float(one.get("width",0))-18)/1000; gh=max(0,float(one.get("height",0))-18)/1000; total+=gw*gh*9520*q
                elif str(name).startswith(("Алюкобонд 3 мм","Алюкобонд 4 мм")):
                    aw=max(0,float(one.get("width",0))-52)/1000; ah=max(0,float(one.get("height",0))-52)/1000; total+=aw*ah*7600*q
                elif name in unit_g: total+=q*unit_g[name]
            return total/1000.0 if total else None
        if screen.get("mode", MODE_RZD) != MODE_RZD:
            return None
        module_name = self._selected_led_module_name(screen)
        counts = screen.get("counts", {}) or {}
        sides = max(1, int(screen.get("sides", 1) or 1))
        total_grams = 0.0
        for size, count in counts.items():
            size_key = tuple(size) if isinstance(size, (tuple, list)) else size
            lookup_size = (960,640) if size_key == (640,960) else size_key
            data = CABINET_WEIGHT_DATA_V19_71.get(lookup_size)
            if not data or not count: continue
            module_weight = data["module_weights"].get(module_name)
            if module_weight is None: return None
            total_grams += (data["fixed_grams"] + data["module_qty"] * module_weight) * float(count) * sides
        # V20.22: +4 наконечника 0,75 × 3 г только на динамическое изделие РЖД.
        total_grams += 12.0
        return total_grams / 1000.0

    def _weight_coverage_issues(self):
        """V30.39: самопроверка покрытия весов.

        Ищет комплектующие, которые BOM динамического МЦД выдаёт, а расчёт веса
        изделия не учитывает — такая позиция молча весит 0. Именно так до V30.39
        терялись «Профиль Гефест» (400 гр/м.п) и «Уголок алюминиевый 30×20×2 мм»
        (259 гр/м.п). Возвращает список (имя, ед.изм., вес по справочнику).
        """
        issues=[]; seen=set()
        products=list(getattr(self,"saved_screens",[]) or [])
        for sc in products:
            if sc.get("mode")!=MODE_MCD: continue
            one=dict(sc); one["quantity"]=1
            try:
                rows=self._dynamic_mcd_component_rows_v1972([one])
                module_name=self._selected_led_module_name(one)
            except Exception:
                continue
            for name,unit,qty in rows:
                key=str(name).strip()
                if not key or key in seen: continue
                seen.add(key)
                if key==module_name: continue
                if key.startswith(MCD_WEIGHT_FORMULA_PREFIXES): continue
                if key in MCD_UNIT_WEIGHTS_G: continue
                if key in MCD_WEIGHT_EXCLUDED_PACKAGING: continue
                # Вес не учитывается. Сообщаем только если справочник его знает.
                ref=self._component_reference_weight(key)
                if ref not in (None,"",0):
                    issues.append((key,unit,ref))
        return issues

    def _show_weight_coverage_report(self):
        """V30.39: кнопка «Проверить веса» на вкладке «Справочник»."""
        if not [s for s in (getattr(self,"saved_screens",[]) or []) if s.get("mode")==MODE_MCD]:
            messagebox.showinfo("Проверка весов",
                "В проекте нет сохранённых изделий МЦД — проверять нечего.")
            return
        issues=self._weight_coverage_issues()
        if not issues:
            messagebox.showinfo("Проверка весов",
                "Все комплектующие МЦД, у которых справочник задаёт вес, учтены в расчёте веса изделия.")
            return
        lines="\n".join(f"  • {n} ({u or 'без ед.'}) — справочник: {w}" for n,u,w in issues)
        messagebox.showwarning("Проверка весов",
            "Эти позиции BOM не учитываются в весе изделия (вклад = 0), "
            f"хотя вес задан в справочнике:\n\n{lines}\n\n"
            "Нужно добавить их в MCD_UNIT_WEIGHTS_G или формульную ветку _screen_weight_kg.")

    def _static_sign_weight_kg(self, sign):
        """Вес статического МЦД/РЖД по фактическому BOM и весам справочника."""
        mode=sign.get("mode")
        face=sign.get("face_type")
        if mode==MODE_MCD:
            if face!="С подсветкой":
                return None
            rows=self._static_mcd_component_rows([sign])
        elif mode==MODE_RZD:
            rows=self._static_rzd_component_rows([sign])
        else:
            return None
        total=0.0; found=False
        for name,unit,qty in rows:
            w=self._component_weight_kg(name,unit,qty)
            if w is not None:
                total+=w; found=True
        return total if found else None

    def _format_static_sign_weight(self, sign):
        value=self._static_sign_weight_kg(sign)
        return "—" if value is None else f"{value:.2f}".replace(".",",")

    def _format_screen_weight(self, screen):
        value = self._screen_weight_kg(screen)
        return "—" if value is None else f"{value:.2f}".replace(".", ",")

    def _journal_fill_mode_text(self, record):
        return "Авто" if bool((record or {}).get("autofill", True)) else "Вручную"

    def _journal_spec_position(self, record):
        return str((record or {}).get("spec_position","") or "").strip()

    def _edit_selected_spec_position(self):
        """Назначает/редактирует позицию спецификации для выбранного изделия."""
        tree=getattr(self,"project_journal_tree",None)
        if tree is None:
            return
        sel=tree.selection()
        if not sel:
            messagebox.showinfo("Позиция спецификации","Выберите изделие в журнале.")
            return
        iid=self._project_journal_product_iid(sel[0])
        rec=self._project_journal_record_for_iid(iid)
        if not isinstance(rec,dict):
            return
        current=self._journal_spec_position(rec)
        value=simpledialog.askstring(
            "Позиция спецификации",
            "Введите номер/обозначение позиции спецификации.\n"
            "Одинаковое значение можно назначить нескольким изделиям.\n"
            "Пустое значение удаляет позицию.",
            initialvalue=current,
            parent=self
        )
        if value is None:
            return
        rec["spec_position"]=str(value).strip()
        self._mark_project_dirty()
        self._refresh_project_journal()

    def _journal_product_records_in_order(self):
        """Возвращает изделия в сохранённом порядке журнала."""
        records=[]
        insertion=0
        for i,s in enumerate(getattr(self,"saved_screens",[]) or []):
            try:order=float(s.get("journal_order"))
            except Exception:order=10**9+insertion
            records.append((order,insertion,"dynamic",i,s))
            insertion+=1
        for i,s in enumerate(getattr(self,"saved_static_signs",[]) or []):
            try:order=float(s.get("journal_order"))
            except Exception:order=10**9+insertion
            records.append((order,insertion,"static",i,s))
            insertion+=1
        records.sort(key=lambda x:(x[0],x[1]))
        return records

    def _refresh_project_journal(self):
        if not hasattr(self,"project_journal_tree"):return
        opened={iid for iid in self.project_journal_tree.get_children()
                if iid.startswith("led:") and self.project_journal_tree.item(iid,"open")}
        for iid in self.project_journal_tree.get_children():self.project_journal_tree.delete(iid)
        n=1
        for i,s in enumerate(self.saved_screens):
            mode=s.get("mode",MODE_RZD)
            brand=getattr(self,"project_brand_context",None)
            screen_article=str(s.get("screen_article","") or "").strip()
            if mode==MODE_RZD:
                execution=("МЦД кабинетный тип" if brand=="МЦД" else "РЖД кабинет")
            else:
                execution="МЦД динамика"
            if screen_article:
                execution=f"{execution} {screen_article}"
            instances=self._ensure_screen_instances(s); parent=f"led:{i}"
            serial = instances[0].get("part_number","") if instances else s.get("part_number","")
            try: product_qty=max(1,int(s.get("quantity",1) or 1))
            except Exception: product_qty=1
            self.project_journal_tree.insert("","end",iid=parent,open=(parent in opened),values=(
                self._journal_spec_position(s),n,self._journal_fill_mode_text(s),"LED-экран",
                s.get("screen_article",""),s.get("module_article",""),serial,"","",
                f"{s.get('width',0)} × {s.get('height',0)}",product_qty,self._format_screen_weight(s),s.get("sides",1),execution))
            if len(instances)>1:
                for j,inst in enumerate(instances):
                    self.project_journal_tree.insert(parent,"end",iid=f"ledinst:{i}:{j}",values=(
                        self._journal_spec_position(s),"",self._journal_fill_mode_text(s),"Экземпляр",
                        s.get("screen_article",""),s.get("module_article",""),
                        inst.get("part_number",""),self._instance_mark(i,j),inst.get("led_series",""),
                        f"{s.get('width',0)} × {s.get('height',0)}",1,self._format_screen_weight(s),s.get("sides",1),execution))
            n+=1
        for i,s in enumerate(getattr(self,"saved_static_signs",[])):
            size=f"Ø {s.get('width',0)}" if s.get("round",False) else f"{s.get('width',0)} × {s.get('height',0)}"
            article=str(s.get("article","") or "").strip()
            static_prefix="РЖД статика" if s.get("mode",MODE_MCD)==MODE_RZD else "МЦД статика"
            execution=f"{static_prefix} {article}".strip()
            raw_qty=str(s.get("quantity","") or "").strip()
            try: product_qty=max(1,int(raw_qty)) if raw_qty else 1
            except Exception: product_qty=1
            self.project_journal_tree.insert("","end",iid=f"static:{i}",values=(
                self._journal_spec_position(s),n,self._journal_fill_mode_text(s),"Статический указатель",
                s.get("name",""),s.get("article",""),"","","",size,product_qty,self._format_static_sign_weight(s),
                s.get("sides",1),execution)); n+=1

        # V20.63: восстанавливаем пользовательский порядок и пересчитываем №.
        self._project_journal_apply_saved_order()
        self._project_journal_update_sort_headers()

        try: self._refresh_project_matrix()
        except Exception: pass

    def _open_project_journal_item(self,event=None):
        sel=self.project_journal_tree.selection()
        if not sel:return
        iid=sel[0]

        if iid.startswith("ledinst:"):
            _,gi,ii=iid.split(":"); gi=int(gi); ii=int(ii)
            if gi>=len(self.saved_screens):return
            screen=self.saved_screens[gi]; instances=self._ensure_screen_instances(screen)
            if ii>=len(instances):return
            self._active_led_instance=None
            self.notebook.select(self.designer_tab)
            self.saved_tree.selection_set(str(gi)); self.saved_tree.focus(str(gi)); self._load_saved_screen()
            self._active_led_instance=(gi,ii)
            self.part_number_var.set(instances[ii].get("part_number",""))
            self.led_series_var.set(instances[ii].get("led_series",screen.get("led_series","")))
            return

        if iid.startswith("led:"):
            idx=int(iid.split(":",1)[1])
            if idx>=len(self.saved_screens):return
            self._active_led_instance=None
            self.notebook.select(self.designer_tab)
            self.saved_tree.selection_set(str(idx)); self.saved_tree.focus(str(idx)); self._load_saved_screen()
            return

        if iid.startswith("static:"):
            self._active_led_instance=None
            idx=int(iid.split(":",1)[1])
            if idx>=len(getattr(self,"saved_static_signs",[])):return
            self.notebook.select(self.static_tab)
            self.static_saved_tree.selection_set(str(idx)); self.static_saved_tree.focus(str(idx))
            self._load_selected_static_sign()
            return


    def _on_project_name_changed(self, *args):
        if hasattr(self, "project_name_var"):
            new_name = self.project_name_var.get().strip() or "Новый проект"
            changed = (new_name != getattr(self, "project_name", "Новый проект"))
            self.project_name = new_name
            if changed and not getattr(self, "_loading_project_data", False):
                self._mark_project_dirty()

    def _mark_project_dirty(self):
        if getattr(self, "_loading_project_data", False):
            return
        self._project_dirty = True
        if not isinstance(getattr(self, "project_metadata", None), dict):
            self.project_metadata = {}
        self.project_metadata.setdefault("created_at", datetime.now().isoformat(timespec="seconds"))
        self.project_metadata["modified_at"] = datetime.now().isoformat(timespec="seconds")

    def _install_project_autosave_traces(self):
        # Изменения загруженного изделия сразу записываются в его словарь в памяти проекта.
        screen_vars = (
            "screen_mode_var","screen_article_var","module_article_var","part_number_var","dynamic_autofill_var",
            "screen_environment_var","pixel_pitch_var","led_type_var","led_series_var",
            "control_type_var","media_converter_var","optical_cross_var","chip_var",
            "card_model_var","support_var","screen_quantity_var","screen_sides_var",
            "mcd_size_var","side2_different_layout_var"
        )
        static_vars = (
            "static_mode_var","static_name_var","static_article_var","static_layout_no_var",
            "static_round_var","static_sides_var","static_face_type_var","static_profile_var",
            "static_frame_profile_var","static_mount_type_var","static_quantity_var","static_autofill_var"
        )
        for attr in screen_vars:
            var=getattr(self,attr,None)
            if var is not None:
                try: var.trace_add("write", self._on_active_screen_field_changed)
                except Exception: pass
        for attr in static_vars:
            var=getattr(self,attr,None)
            if var is not None:
                try: var.trace_add("write", self._on_active_static_field_changed)
                except Exception: pass

    def _on_active_screen_field_changed(self, *args):
        if not getattr(self, "_loading_saved_product", False):
            self._sync_active_screen_from_form()

    def _on_active_static_field_changed(self, *args):
        if not getattr(self, "_loading_saved_product", False):
            self._sync_active_static_from_form()

    def _schedule_project_views_refresh(self):
        try:
            if self._project_refresh_after_id is not None:
                self.after_cancel(self._project_refresh_after_id)
        except Exception:
            pass
        try:
            self._project_refresh_after_id = self.after(180, self._refresh_views_after_autosave)
        except Exception:
            self._project_refresh_after_id = None

    def _refresh_views_after_autosave(self):
        self._project_refresh_after_id = None
        try: self._refresh_project_journal()
        except Exception: pass
        try: self._refresh_components_screen_selector()
        except Exception: pass
        try: self._refresh_components_table()
        except Exception: pass

    def _sync_active_static_from_form(self):
        idx=getattr(self,"_active_static_index",None)
        signs=getattr(self,"saved_static_signs",[])
        if idx is None or not (0 <= idx < len(signs)) or getattr(self,"_loading_saved_product",False):
            return
        s=signs[idx]
        try: sides=int(self.static_sides_var.get() or 1)
        except Exception: sides=1
        mode=self.static_mode_var.get()
        updated={
            "name":self.static_name_var.get().strip(),
            "article":self.static_article_var.get().strip(),
            "layout_no":self.static_layout_no_var.get().strip(),
            "mode":mode,"width":int(self.static_width_mm or 0),"height":int(self.static_height_mm or 0),
            "sides":max(1,min(2,sides)),"profile":self.static_profile_var.get(),
            "frame_profile":self.static_frame_profile_var.get(),
            "mount_type":self.static_mount_type_var.get() if mode==MODE_RZD else "",
            "quantity":self.static_quantity_var.get().strip() if mode in (MODE_MCD,MODE_RZD) else "",
            "autofill":bool(self.static_autofill_var.get()) if mode in (MODE_MCD, MODE_RZD) else False,
            "face_type":self.static_face_type_var.get(),
            "round":bool(self.static_round_var.get()) if mode==MODE_MCD else False,
            "diameter":(int(self.static_width_mm or 0) if mode==MODE_MCD and self.static_round_var.get() else "")
        }
        changed=any(s.get(k)!=v for k,v in updated.items())
        if not changed:
            return
        s.update(updated)
        self._mark_project_dirty()
        try:
            if self.static_saved_tree.exists(str(idx)):
                self.static_saved_tree.item(str(idx),values=(idx+1,s.get("article") or f"Указатель {idx+1}",s.get("sides",1),s.get("face_type",""),s.get("quantity",1)))
        except Exception: pass
        self._schedule_project_views_refresh()

    def _sync_active_screen_from_form(self):
        idx=getattr(self,"_active_screen_index",None)
        screens=getattr(self,"saved_screens",[])
        if idx is None or not (0 <= idx < len(screens)) or getattr(self,"_loading_saved_product",False):
            return
        sc=screens[idx]
        mode=self.screen_mode_var.get()
        try: quantity=max(1,int(self.screen_quantity_var.get() or 1))
        except Exception: quantity=1
        try: sides=max(1,min(2,int(self.screen_sides_var.get() or 1)))
        except Exception: sides=1
        w=int(self.width_mm or 0); h=int(self.height_mm or 0)
        counts={(960,960):0,(960,640):0,(640,960):0,(640,640):0}
        width_parts=(); height_parts=(); cabinet_total=0; module_total=0
        module_field_w=w; module_field_h=h
        layout_index=int(getattr(self,"layout_index",0) or 0)
        if mode==MODE_RZD and sc.get("pro_screen"):
            if self._pro_is_selected() and getattr(self,"_pro_locked",False):
                w,h,xs,ys,counts=self._pro_screen_geometry()
            else:
                w=int(sc.get("width",0));h=int(sc.get("height",0))
                xs=sc.get("pro_x_edges",[]);ys=sc.get("pro_y_edges",[])
                counts=self._pro_counts_from_edges(xs,ys) if len(xs)>1 and len(ys)>1 else {}
            width_parts=tuple(b-a for a,b in zip(xs,xs[1:]))
            height_parts=tuple(b-a for a,b in zip(ys,ys[1:]))
            cabinet_total=sum(counts.values())
            module_total=(w//MODULE_W)*(h//MODULE_H)
        elif mode==MODE_RZD and w and h:
            layouts=all_layouts(w,h)
            if layouts:
                layout_index=min(layout_index,len(layouts)-1)
                width_parts,height_parts=layouts[layout_index]
                nw960,nw640=width_parts.count(960),width_parts.count(640)
                nh960,nh640=height_parts.count(960),height_parts.count(640)
                counts={(960,960):nw960*nh960,(960,640):nw960*nh640,(640,960):nw640*nh960,(640,640):nw640*nh640}
                cabinet_total=sum(counts.values())
            module_total=(w//MODULE_W)*(h//MODULE_H) if w and h else 0
        elif mode==MODE_MCD and w and h:
            if self._mcd_is_custom_size():
                mc=max(0,w//MCD_MODULE_W); mr=max(0,h//MCD_MODULE_H)
                module_field_w=mc*MCD_MODULE_W; module_field_h=mr*MCD_MODULE_H; module_total=mc*mr
            else:
                module_field_w=w-2*MCD_MARGIN; module_field_h=h-2*MCD_MARGIN
                module_total=max(0,module_field_w//MCD_MODULE_W)*max(0,module_field_h//MCD_MODULE_H)
        updated={
            "screen_article":self.screen_article_var.get().strip(),"module_article":self.module_article_var.get().strip(),
            "autofill":bool(self.dynamic_autofill_var.get()) if hasattr(self,"dynamic_autofill_var") else True,
            "part_number":self.part_number_var.get(),"environment":self.screen_environment_var.get(),
            "pixel_pitch":self.pixel_pitch_var.get(),"led_type":self.led_type_var.get(),
            "led_series":self.led_series_var.get(),"control_type":self.control_type_var.get(),
            "media_converter":bool(self.media_converter_var.get()),"optical_cross":bool(self.optical_cross_var.get()),
            "chip":self.chip_var.get().strip(),"card_model":self.card_model_var.get().strip() or "MRV416-N",
            "firmware":self.firmware_var.get().strip(),"support":self.support_var.get().strip(),
            "mode":mode,"mcd_size":(self.mcd_size_var.get() if mode==MODE_MCD else ""),
            "quantity":quantity,"sides":sides,"width":w,"height":h,
            "module_field_width":module_field_w,"module_field_height":module_field_h,
            "layout_index":layout_index,"side2_layout_index":int(getattr(self,"side2_layout_index",0) or 0),
            "side2_different_layout":bool(self.side2_different_layout_var.get()),
            "cabinet_total":cabinet_total,"module_total":module_total,"counts":counts,
            "width_parts":tuple(width_parts),"height_parts":tuple(height_parts),
            "pro_screen":bool(sc.get("pro_screen",False)),
            "pro_x_edges":list(xs) if mode==MODE_RZD and sc.get("pro_screen") else sc.get("pro_x_edges",[]),
            "pro_y_edges":list(ys) if mode==MODE_RZD and sc.get("pro_screen") else sc.get("pro_y_edges",[])
        }
        changed=any(sc.get(k)!=v for k,v in updated.items())
        if not changed:
            return
        sc.update(updated)
        old_instances=[dict(x) for x in (sc.get("instances",[]) or []) if isinstance(x,dict)]
        while len(old_instances)<quantity:
            old_instances.append({"part_number":"","led_series":self.led_series_var.get()})
        sc["instances"]=old_instances[:quantity]

        active_inst=getattr(self,"_active_led_instance",None)
        if active_inst is not None:
            gi,ii=active_inst
            if gi==idx and 0 <= ii < len(sc["instances"]):
                sc["instances"][ii]["part_number"]=self.part_number_var.get()
                sc["instances"][ii]["led_series"]=self.led_series_var.get()
        elif sc["instances"]:
            # При редактировании самого изделия первая карточка соответствует
            # видимым полям формы.
            sc["instances"][0]["part_number"]=self.part_number_var.get()
            sc["instances"][0]["led_series"]=self.led_series_var.get()
        self._mark_project_dirty()
        try:
            if self.saved_tree.exists(str(idx)):
                factor=quantity*sides
                cab_disp=cabinet_total*factor if mode==MODE_RZD else "—"
                self.saved_tree.item(str(idx),values=(idx+1,sc.get("module_article",""),sides,cab_disp,quantity))
        except Exception: pass
        self._schedule_project_views_refresh()

    def _confirm_unsaved_project(self):
        if not getattr(self,"_project_dirty",False):
            return True
        answer=messagebox.askyesnocancel(
            "Несохранённые изменения",
            "Проект был изменён.\n\nСохранить изменения перед выходом?"
        )
        if answer is None:
            return False
        if answer:
            return bool(self._save_project(quiet=True))
        return True

    def _on_app_close(self):
        phrases = [
            "Ты устал или действительно решил на сегодня всё?",
            "Уже домой? Проверим, точно закрываем?",
            "Крестик нажат уверенно. Закрываем программу?",
            "Рабочий день официально закончен или это случайный клик?",
            "Проект отпускаем отдыхать?",
            "Точно закрыть, а не просто потянуться к правому верхнему углу?",
            "Все экраны посчитаны и можно расходиться?",
            "Закрываем цех калькуляций на сегодня?",
            "Оператор покидает пост? Подтвердить закрытие?",
            "Пора выключать свет? Закрываем программу?",
            "Это осознанное закрытие или мышь решила сама?",
            "Финальный аккорд? Закрыть приложение?",
            "Все проверено дважды? Тогда закрываем?",
            "Программа спрашивает: ты точно закончил?",
            "Последний шанс перед выходом — закрыть программу?",
        ]
        if not messagebox.askyesno("Закрытие программы", random.choice(phrases) + "\n\nЗакрыть программу?"):
            return
        if not self._confirm_unsaved_project():
            return
        self.destroy()

    def _dynamic_autofill_values(self):
        """Возвращает автоматически сформированные Наименование ДИТ и Артикул."""
        try:
            sides = 2 if int(self.screen_sides_var.get() or 1) == 2 else 1
        except Exception:
            sides = 1
        environment = str(self.screen_environment_var.get() or "Улица").strip()
        execution = "Внутреннее" if environment == "Помещение" else "Уличное"
        side_text = "Двустороннее" if sides == 2 else "Одностороннее"

        # Префикс определяется контекстом проекта, а не внутренним режимом вкладки:
        # РЖД -> AS-TAB; МЦД (включая «Кабинетный тип») -> ASD-TAB.
        prefix = "AS-TAB" if getattr(self, "project_brand_context", None) == "РЖД" else "ASD-TAB"
        roman = " II" if sides == 2 else ""
        pitch = str(self.pixel_pitch_var.get() or "").strip()
        led_type = str(self.led_type_var.get() or "OD").strip().upper()
        if led_type in ("I", "IN"):
            led_type = "ID"
        if led_type not in ("OD", "ID"):
            led_type = "OD"
        w = int(getattr(self, "width_mm", 0) or 0)
        h = int(getattr(self, "height_mm", 0) or 0)
        dims = f"{w}x{h}" if w > 0 and h > 0 else ""

        technical = " ".join(x for x in (f"{prefix}{roman}", pitch, dims, led_type) if x).strip()
        name = f"Динамическое информационное табло. {side_text}. {execution}."
        if technical:
            name = f"{name} {technical}"
        return name, technical

    def _dynamic_apply_autofill(self, *args):
        if getattr(self, "_loading_saved_product", False):
            return
        if not hasattr(self, "dynamic_autofill_var") or not self.dynamic_autofill_var.get():
            return
        if not hasattr(self, "screen_article_var") or not hasattr(self, "module_article_var"):
            return
        name, article = self._dynamic_autofill_values()
        if self.screen_article_var.get() != name:
            self.screen_article_var.set(name)
        if self.module_article_var.get() != article:
            self.module_article_var.set(article)

    def _dynamic_autofill_changed(self):
        if self.dynamic_autofill_var.get():
            self._dynamic_apply_autofill()

    def _force_module_article_upper(self, *args):
        if getattr(self, "_module_article_upper_guard", False):
            return
        value = self.module_article_var.get()
        upper = value.upper()
        # Размер в артикуле записываем через строчную латинскую x: 1920x640.
        upper = re.sub(r"(?<=\d)X(?=\d)", "x", upper)
        if value != upper:
            self._module_article_upper_guard = True
            self.module_article_var.set(upper)
            self._module_article_upper_guard = False

    def _update_dynamic_product_buttons(self):
        has_saved=bool(getattr(self,"saved_screens",[]))
        draft=bool(getattr(self,"_dynamic_draft_mode",True))
        if hasattr(self,"new_dynamic_product_button"):
            self.new_dynamic_product_button.configure(
                state=("normal" if has_saved else "disabled"),
                cursor=("hand2" if has_saved else "arrow")
            )
        if hasattr(self,"add_project_button"):
            self.add_project_button.configure(
                state=("normal" if draft else "disabled"),
                cursor=("hand2" if draft else "arrow")
            )

    def _reset_dynamic_form(self, *, draft=False):
        self._loading_saved_product=True
        self._active_screen_index=None
        self._active_led_instance=None
        self._dynamic_draft_mode=bool(draft)
        try:
            self.saved_tree.selection_remove(self.saved_tree.selection()); self.saved_tree.focus("")
        except Exception:
            pass
        default_mode=MODE_RZD if getattr(self,"project_brand_context",None)=="РЖД" else MODE_MCD
        self.screen_mode_var.set(default_mode)
        self.screen_mode=default_mode
        self.width_mm=0; self.height_mm=0; self.layouts=[]; self.layout_index=0; self.side2_layout_index=0
        if hasattr(self,"dynamic_autofill_var"):
            self.dynamic_autofill_var.set(True)
        for var,val in ((self.screen_article_var,""),(self.module_article_var,""),(self.part_number_var,""),
                        (self.screen_environment_var,"Улица"),(self.pixel_pitch_var,"P2,5"),(self.led_type_var,"OD"),
                        (self.led_series_var,""),(self.control_type_var,"Встроенный Мини-ПК"),
                        (self.chip_var,""),(self.card_model_var,"MRV416-N"),(self.support_var,""),
                        (self.screen_quantity_var,"1"),(self.screen_sides_var,"1")):
            try: var.set(val)
            except Exception: pass
        try:self.media_converter_var.set(False)
        except Exception:pass
        try:self.optical_cross_var.set(False)
        except Exception:pass
        try:self.side2_different_layout_var.set(False)
        except Exception:pass
        try:
            if default_mode==MODE_MCD:
                self.mcd_size_var.set("Нестандарт")
                self.mcd_manual_width_var.set(""); self.mcd_manual_height_var.set("")
            self._sync_mcd_size_controls_visibility()
        except Exception:pass
        self._loading_saved_product=False
        try:self._update_mode_ui(); self._draw_grid(); self._redraw_selection(); self._on_side2_option_changed(); self._dynamic_apply_autofill()
        except Exception:pass
        self._update_dynamic_product_buttons()

    def _start_new_dynamic_product(self):
        self._reset_dynamic_form(draft=True)
        try:self.screen_article_entry.focus_set()
        except Exception:pass

    def _update_static_product_buttons(self):
        has_saved=bool(getattr(self,"saved_static_signs",[]))
        draft=bool(getattr(self,"_static_draft_mode",True))
        if hasattr(self,"new_static_product_button"):
            self.new_static_product_button.configure(
                state=("normal" if has_saved else "disabled"),
                cursor=("hand2" if has_saved else "arrow")
            )
        self._update_static_add_button_state()

    def _reset_static_form(self, *, draft=False):
        self._loading_saved_product=True
        self._active_static_index=None
        self._static_draft_mode=bool(draft)
        try:
            self.static_saved_tree.selection_remove(self.static_saved_tree.selection()); self.static_saved_tree.focus("")
        except Exception:pass
        default_mode=MODE_RZD if getattr(self,"project_brand_context",None)=="РЖД" else MODE_MCD
        self.static_mode_var.set(default_mode)
        self.static_width_mm=0; self.static_height_mm=0
        self.static_name_var.set(""); self.static_article_var.set(""); self.static_layout_no_var.set("")
        self.static_width_input_var.set(""); self.static_height_input_var.set("")
        try:self.static_diameter_input_var.set("")
        except Exception:pass
        self.static_sides_var.set(1); self.static_face_type_var.set("С подсветкой")
        self.static_mount_type_var.set(""); self.static_quantity_var.set("")
        self.static_round_var.set(False); self.static_autofill_var.set(default_mode in (MODE_MCD, MODE_RZD))
        self._loading_saved_product=False
        try:self._update_static_params_visibility(); self._update_static_mcd_params(); self._toggle_static_round_mode(); self._static_apply_autofill(); self._draw_static_grid()
        except Exception:pass
        self._update_static_product_buttons()

    def _start_new_static_product(self):
        self._reset_static_form(draft=True)
        try:self.static_name_entry.focus_set()
        except Exception:pass

    def _add_to_project(self):
        if not bool(getattr(self,"_dynamic_draft_mode",True)):
            self._flash_project_button("Сначала нажмите «Новое изделие»")
            return
        w = self.width_mm
        h = self.height_mm
        mode = self.screen_mode_var.get()

        screen_article = self.screen_article_var.get().strip()
        module_article = self.module_article_var.get().strip()

        try:
            quantity = max(1, int(self.screen_quantity_var.get()))
            sides = max(1, min(2, int(self.screen_sides_var.get())))
        except ValueError:
            self._flash_project_button("Проверьте количество и стороны")
            return

        if mode == MODE_RZD and self._pro_is_selected() and getattr(self,"_pro_locked",False):
            w,h=self._pro_size
        if not (w and h):
            self._flash_project_button("Сначала выберите экран")
            return
        if not screen_article:
            self._flash_project_button("Укажите артикул LED-экрана")
            self.screen_article_entry.focus_set()
            return
        if not module_article:
            self._flash_project_button("Укажите артикул LED-модуля")
            self.module_article_entry.focus_set()
            return

        counts = {(960, 960): 0, (960, 640): 0, (640, 960): 0, (640, 640): 0}
        width_parts = ()
        height_parts = ()
        cabinet_total = 0
        layout_index = 0

        if mode == MODE_RZD and self._pro_is_selected():
            try:
                w,h,xs,ys,counts=self._pro_screen_geometry()
            except ValueError as exc:
                self._flash_project_button(str(exc));return
            width_parts=tuple(b-a for a,b in zip(xs,xs[1:]))
            height_parts=tuple(b-a for a,b in zip(ys,ys[1:]))
            cabinet_total=sum(counts.values())
            module_total=(w//MODULE_W)*(h//MODULE_H)
            module_field_w,module_field_h=w,h
            layout_index=0
        elif mode == MODE_RZD:
            layouts = self._rzd_filtered_layouts(w, h)
            if not layouts:
                self._flash_project_button("Нет допустимой раскладки с выбранными размерами и остатками")
                return
            layout_index = min(self.layout_index, len(layouts) - 1)
            width_parts, height_parts = layouts[layout_index]
            nw960, nw640 = width_parts.count(960), width_parts.count(640)
            nh960, nh640 = height_parts.count(960), height_parts.count(640)
            counts = {
                (960, 960): nw960 * nh960,
                (960, 640): nw960 * nh640,
                (640, 960): nw640 * nh960,
                (640, 640): nw640 * nh640,
            }
            cabinet_total = sum(counts.values())
            # Existing reports/BOM resolve saved layout_index against all_layouts().
            # Therefore persist the ORIGINAL index, not the filtered UI index.
            full_layouts=all_layouts(w,h)
            layout_index=full_layouts.index((width_parts,height_parts))
            side2_full_index=layout_index
            if sides == 2 and self.side2_different_layout_var.get():
                side2_layout=layouts[self.side2_layout_index % len(layouts)]
                side2_full_index=full_layouts.index(side2_layout)
                counts2=self._layout_cabinet_counts(side2_layout)
                selected={size for size,var in self.cab_allowed_vars.items() if var.get()}
                if selected:
                    for size in selected:
                        stock=self.cab_stock_vars[size].get().strip()
                        if stock and (counts[size]+counts2[size])*quantity>int(stock):
                            self._flash_project_button("Недостаточно кабинетов на складе для двух сторон")
                            return
            else:
                selected={size for size,var in self.cab_allowed_vars.items() if var.get()}
                if selected:
                    for size in selected:
                        stock=self.cab_stock_vars[size].get().strip()
                        if stock and counts[size]*sides*quantity>int(stock):
                            self._flash_project_button("Недостаточно кабинетов на складе для количества изделий")
                            return
            module_total = (w // MODULE_W) * (h // MODULE_H)
            module_field_w, module_field_h = w, h
        elif mode == MODE_MCD:
            if self._mcd_is_custom_size():
                module_cols=max(0,int(w)//MCD_MODULE_W)
                module_rows=max(0,int(h)//MCD_MODULE_H)
                module_field_w=module_cols*MCD_MODULE_W
                module_field_h=module_rows*MCD_MODULE_H
                module_total=module_cols*module_rows
            else:
                module_field_w = w - 2 * MCD_MARGIN
                module_field_h = h - 2 * MCD_MARGIN
                module_total = (module_field_w // MCD_MODULE_W) * (module_field_h // MCD_MODULE_H)
        else:
            module_field_w, module_field_h = w, h
            module_total = (w // MODULE_W) * (h // MODULE_H)

        screen = {
            "screen_article": screen_article,
            "module_article": module_article,
            "autofill": bool(self.dynamic_autofill_var.get()) if hasattr(self,"dynamic_autofill_var") else True,
            "part_number": self.part_number_var.get(),
            "environment": self.screen_environment_var.get(),
            "pixel_pitch": self.pixel_pitch_var.get(),
            "led_type": self.led_type_var.get(),
            "led_series": self.led_series_var.get(),
            "control_type": self.control_type_var.get(),
            "media_converter": bool(self.media_converter_var.get()),
            "optical_cross": bool(self.optical_cross_var.get()),
            "chip": self.chip_var.get().strip(),
            "card_model": self.card_model_var.get().strip() or "MRV416-N",
            "firmware": self.firmware_var.get().strip(),
            "support": self.support_var.get().strip(),
            "mode": mode,
            "mcd_size": (self.mcd_size_var.get() if mode == MODE_MCD else ""),
            "quantity": quantity,
            "sides": sides,
            "width": w,
            "height": h,
            "module_field_width": module_field_w,
            "module_field_height": module_field_h,
            "layout_index": layout_index,
            "side2_layout_index": side2_full_index if mode == MODE_RZD else self.side2_layout_index,
            "side2_different_layout": bool(self.side2_different_layout_var.get()),
            "cabinet_total": cabinet_total,
            "module_total": module_total,
            "counts": counts,
            "width_parts": tuple(width_parts),
            "height_parts": tuple(height_parts),
            "pro_screen": bool(mode == MODE_RZD and self._pro_is_selected()),
            "pro_x_edges": list(self._pro_x_edges) if mode == MODE_RZD and self._pro_is_selected() else [],
            "pro_y_edges": list(self._pro_y_edges) if mode == MODE_RZD and self._pro_is_selected() else [],
        }
        screen["instances"]=[{"part_number":(self.part_number_var.get() if (quantity==1 or j==0) else ""),
                              "led_series":self.led_series_var.get()} for j in range(quantity)]
        self.saved_screens.append(screen)
        self._active_led_instance=None
        self._active_screen_index=None
        self._dynamic_draft_mode=False
        self._mark_project_dirty()

        number = len(self.saved_screens)
        factor = quantity * sides
        cabinet_display = cabinet_total * factor if mode == MODE_RZD else "—"
        self.saved_tree.insert(
            "", "end", iid=str(number - 1),
            values=(number, module_article, sides, cabinet_display, quantity)
        )

        self._refresh_project_journal()
        self._refresh_components_screen_selector()
        self._refresh_components_table()
        self._refresh_stock_screen_selector()
        self._refresh_procurement_table()

        # После добавления изделия координатное поле сразу переходит
        # к префиксу следующего по порядку изделия.
        # Снимаем выделение с только что добавленной строки: тогда
        # _current_product_prefix() возвращает len(saved_screens) + 1.
        try:
            self.saved_tree.selection_remove(self.saved_tree.selection())
            self.saved_tree.focus("")
        except Exception:
            pass
        # Кабинетные номера рисуются в _redraw_selection(), поэтому
        # после добавления изделия перерисовываем именно выбор/раскладку.
        # К этому моменту выделение сохранённой строки снято, и префикс
        # становится номером следующего изделия: len(saved_screens) + 1.
        self._redraw_selection()

        self._flash_project_button("✓ Добавлено в проект")
        self._update_dynamic_product_buttons()

    def _flash_project_button(self, message):
        original = "＋  Добавить в проект"
        self.add_project_button.configure(text=message)
        self.after(1200, lambda: self.add_project_button.configure(text=original))

    def _load_saved_screen(self):
        selected = self.saved_tree.selection()
        if not selected:
            return
        index = int(selected[0])
        if index >= len(self.saved_screens):
            return

        self._sync_active_screen_from_form()
        screen = self.saved_screens[index]
        self._loading_saved_product=True
        self._active_screen_index=index
        mode = screen.get("mode", MODE_RZD)
        self.screen_mode_var.set(mode)
        self.screen_mode = mode
        if hasattr(self, "mcd_size_var"):
            if mode == MODE_MCD:
                self.mcd_size_var.set(screen.get("mcd_size", "Нестандарт"))
            self._sync_mcd_size_controls_visibility()
        self._update_mode_ui()
        self._draw_grid()

        if hasattr(self,"dynamic_autofill_var"):
            self.dynamic_autofill_var.set(bool(screen.get("autofill", True)))
        self.screen_article_var.set(screen.get("screen_article", ""))
        self.module_article_var.set(screen.get("module_article", ""))
        self.part_number_var.set(screen.get("part_number", ""))
        self.screen_environment_var.set(screen.get("environment", "Улица"))
        self._update_led_type_options()
        self.pixel_pitch_var.set(screen.get("pixel_pitch", "P2,5"))
        _lt=str(screen.get("led_type", "OD") or "OD").upper()
        self.led_type_var.set("ID" if _lt in ("I","IN","ID") else "OD")
        self._update_led_type_options()
        self.led_series_var.set(str(screen.get("led_series", screen.get("firmware", "")) or "")[:3])
        self.control_type_var.set(screen.get("control_type", "Встроенный Мини-ПК"))
        self.media_converter_var.set(bool(screen.get("media_converter", False)))
        self.optical_cross_var.set(bool(screen.get("optical_cross", False)))
        self.chip_var.set(screen.get("chip", ""))
        self.card_model_var.set(screen.get("card_model", "MRV416-N"))
        self.firmware_var.set(screen.get("firmware", ""))
        self.support_var.set(screen.get("support", ""))
        self.screen_quantity_var.set(str(screen.get("quantity", 1)))
        self.screen_sides_var.set(str(screen.get("sides", 1)))
        self.width_mm = screen.get("width", 0)
        self.height_mm = screen.get("height", 0)
        if mode == MODE_MCD and hasattr(self, "mcd_manual_width_var"):
            self.mcd_manual_width_var.set(str(self.width_mm))
            self.mcd_manual_height_var.set(str(self.height_mm))

        self.layout_index = 0
        self.side2_layout_index = int(screen.get("side2_layout_index", 0) or 0)
        self.side2_different_layout_var.set(bool(screen.get("side2_different_layout", False)))
        if mode == MODE_RZD:
            layouts = all_layouts(self.width_mm, self.height_mm)
            target_x = tuple(screen.get("width_parts", ()))
            target_y = tuple(screen.get("height_parts", ()))
            for i, (xs, ys) in enumerate(layouts):
                if tuple(xs) == target_x and tuple(ys) == target_y:
                    self.layout_index = i
                    break
        if screen.get("pro_screen"):
            xs=list(screen.get("pro_x_edges",[]));ys=list(screen.get("pro_y_edges",[]))
            if len(xs)>1 and len(ys)>1:
                self._pro_size=(int(self.width_mm),int(self.height_mm))
                self._pro_requested=self._pro_size
                self._pro_x_edges=xs;self._pro_y_edges=ys
                self._pro_locked=True
                self.pro_w_var.set(str(self.width_mm));self.pro_h_var.set(str(self.height_mm))
                self.rzd_map_tabs.select(self.rzd_pro_page)
                self._pro_redraw()
        self._on_side2_option_changed()
        self._redraw_selection()
        self._loading_saved_product=False
        try:self._dynamic_apply_autofill()
        except Exception:pass
        self._dynamic_draft_mode=False
        self._update_dynamic_product_buttons()

    def _delete_saved_screen(self):
        selected = self.saved_tree.selection()
        if not selected:
            return

        old_index = int(selected[0])
        if old_index >= len(self.saved_screens):
            return

        del self.saved_screens[old_index]
        self._active_screen_index=None
        self._mark_project_dirty()

        self._rebuild_saved_screens_tree()
        self._refresh_project_journal()

        self._refresh_components_screen_selector()
        self._refresh_components_table()
        self._refresh_stock_screen_selector()
        self._refresh_procurement_table()
        if not self.saved_screens:
            self._dynamic_draft_mode=True
        self._update_dynamic_product_buttons()

    def _refresh_components_screen_selector(self):
        if not hasattr(self, "component_scope_combo"):
            return
        # V20.69: агрегированные фильтры по типу изделия идут сразу после
        # «Весь проект», затем — отдельные изделия.
        values=["Весь проект", "Динамика", "Статика"]
        for i,screen in enumerate(self.saved_screens,start=1):
            mode=screen.get("mode",MODE_RZD)
            product_type=("МЦД динамика" if mode==MODE_MCD else "РЖД динамика")
            sides=f"{int(screen.get('sides',1) or 1)} сторона" if int(screen.get('sides',1) or 1)==1 else f"{int(screen.get('sides',1) or 1)} стороны"
            size=f"{screen.get('width',0)}×{screen.get('height',0)}"
            pitch=str(screen.get("pixel_pitch","") or "").replace(",",".")
            values.append(f"LED {i} — {product_type}, {sides}, {size}, {pitch}")
        for i,sign in enumerate(getattr(self,"saved_static_signs",[]),start=1):
            mode=sign.get("mode",MODE_MCD)
            product_type=("МЦД статика" if mode==MODE_MCD else "РЖД статика")
            side_count=int(sign.get("sides",1) or 1)
            sides=f"{side_count} сторона" if side_count==1 else f"{side_count} стороны"
            size=(f"Ø{sign.get('width',0)}" if sign.get("round",False) else f"{sign.get('width',0)}×{sign.get('height',0)}")
            face=str(sign.get("face_type","") or "").lower()
            static_prefix=("МЦД" if mode==MODE_MCD else "РЖД")
            values.append(f"{static_prefix} {i} — {product_type}, {sides}, {size}, {face}")
        self.component_scope_combo["values"]=values
        if self.component_scope_var.get() not in values:self.component_scope_var.set("Весь проект")

    def _selected_component_items(self):
        selected=self.component_scope_var.get()
        if selected=="Весь проект":
            return list(self.saved_screens), list(getattr(self,"saved_static_signs",[]))
        if selected=="Динамика":
            return list(self.saved_screens), []
        if selected=="Статика":
            return [], list(getattr(self,"saved_static_signs",[]))
        if selected.startswith("LED "):
            try:i=int(selected.split(" ",2)[1])-1
            except Exception:return list(self.saved_screens),[]
            return ([self.saved_screens[i]] if 0<=i<len(self.saved_screens) else []),[]
        if selected.startswith("МЦД ") or selected.startswith("РЖД "):
            signs=getattr(self,"saved_static_signs",[])
            try:i=int(selected.split(" ",2)[1])-1
            except Exception:return [],signs
            return [],([signs[i]] if 0<=i<len(signs) else [])
        return list(self.saved_screens),list(getattr(self,"saved_static_signs",[]))

    def _selected_component_screens(self):
        return self._selected_component_items()[0]

    def _format_component_qty(self, value):
        if isinstance(value,str):return value
        if abs(value-round(value))<1e-9:return str(int(round(value)))
        return f"{value:.2f}".rstrip("0").rstrip(".")

    def _mcd_case_elements(self, width_mm, height_mm):
        """Расчёт составных элементов корпуса МЦД из профиля 75/120/175 мм.

        Обе стороны <= 2999 мм: 2 П-элемента.
        П-элемент всегда формируется делением изделия ПО ВЕРТИКАЛИ:
        ширина элемента = полная ширина изделия,
        высота элемента = 1/2 высоты изделия.
        Если хотя бы одна сторона > 2999 мм: 4 Г-элемента; прежняя логика
        деления обеих сторон пополам для четырёх угловых элементов сохраняется.
        """
        w=max(0.0,float(width_mm)); h=max(0.0,float(height_mm))
        if w<=0 or h<=0:
            return None
        short=min(w,h); long=max(w,h)
        if w>2999 or h>2999:
            return ("Г-элемент",4,long/2.0,short/2.0)
        return ("П-элемент",2,w,h/2.0)

    def _mcd_case_component_row(self, width_mm, height_mm, profile_mm=None):
        data=self._mcd_case_elements(width_mm,height_mm)
        if not data:return None
        kind,qty,long_part,shelf=data
        def fmt(v):
            return str(int(round(v))) if abs(v-round(v))<1e-9 else f"{v:.1f}".rstrip("0").rstrip(".")
        prefix=f"Профиль {profile_mm}мм — " if profile_mm else ""
        if kind == "П-элемент":
            size=f"{fmt(long_part)}×{fmt(shelf)} мм"
        else:
            size=f"{fmt(long_part)}×{fmt(shelf)} мм"
        return (f"{prefix}{kind} — {size}", "шт.", qty)

    def _draw_mcd_case_split(self, canvas, x1, y1, x2, y2, width_mm, height_mm, tags="cabinet"):
        """Пунктирная визуализация стыков П-/Г-элементов."""
        if width_mm>2999 or height_mm>2999:
            canvas.create_line((x1+x2)/2,y1,(x1+x2)/2,y2,fill="#725b00",dash=(7,5),width=2,tags=tags)
            canvas.create_line(x1,(y1+y2)/2,x2,(y1+y2)/2,fill="#725b00",dash=(7,5),width=2,tags=tags)
            canvas.create_text((x1+x2)/2,(y1+y2)/2,text="  4 × Г-элемент",anchor="nw",
                               fill="#725b00",font=("Arial",8,"bold"),tags=tags)
        else:
            # Для двух П-элементов корпус всегда делится ПО ВЕРТИКАЛИ:
            # полная ширина изделия сохраняется, высота делится пополам.
            ym=(y1+y2)/2
            canvas.create_line(x1,ym,x2,ym,fill="#725b00",dash=(7,5),width=2,tags=tags)
            canvas.create_text((x1+x2)/2,ym,text="2 × П-элемент  ",anchor="s",
                               fill="#725b00",font=("Arial",8,"bold"),tags=tags)

    def _static_mcd_power_supplies(self, clean_power):
        """Подбор БП по суммарной мощности LED без дополнительного запаса.

        Номиналы из справочника: 40/60/100/150 Вт (V30.67: 25 Вт не применяется). Сначала выбирается
        минимальное количество блоков, достаточное по мощности; среди вариантов
        с тем же количеством — минимальная суммарная установленная мощность.
        """
        import itertools
        allowed=(40,60,100,150)   # V30.67: БП 25 Вт исключён, минимальный — 40 Вт
        required=max(0.0,float(clean_power))
        result={p:0 for p in allowed}
        if required<=1e-9:
            return result
        min_count=max(1,int(math.ceil(required/max(allowed))))
        best=None
        for count in range(min_count, min_count+len(allowed)+1):
            candidates=[]
            for combo in itertools.combinations_with_replacement(allowed,count):
                capacity=sum(combo)
                if capacity+1e-9>=required:
                    candidates.append((capacity,combo))
            if candidates:
                best=min(candidates,key=lambda x:(x[0],tuple(-v for v in sorted(x[1],reverse=True))))[1]
                break
        if best is None:
            return result
        for nominal in best:
            result[nominal]+=1
        return result

    def _round_mcd_dimension_text(self, value):
        value=float(value or 0)
        if abs(value-round(value))<1e-9:
            return str(int(round(value)))
        return f"{value:.3f}".rstrip("0").rstrip(".").replace(".",",")

    def _round_mcd_angle_name(self, diameter_mm):
        # This helper accepts the actual diameter of the supported panel.
        # V30.78: круглые изделия гнутся из уголка 40×20×2 мм.
        radius=max(0.0,float(diameter_mm)/2.0)
        return (
            f"{ROUND_MCD_ANGLE_NAME} — "
            f"РАДИУС гиба R{self._round_mcd_dimension_text(radius)} мм"
        )

    def _round_mcd_profile_name(self, diameter_mm):
        radius=max(0.0,float(diameter_mm)/2.0)
        return (
            "Профиль алюминиевый 75 мм — круглый — "
            f"РАДИУС гиба R{self._round_mcd_dimension_text(radius)} мм"
        )

    def _static_mcd_component_rows(self, signs):
        """Комплектующие МЦД с подсветкой по актуальному справочнику.

        Поддерживаются 1- и 2-сторонние изделия.
        Электрический расчёт выполняется отдельно для ОДНОГО физического изделия:
        суммарная мощность LED × 1,20, затем подбор БП 40/60/100/150 Вт.
        После расчёта одного изделия все позиции BOM умножаются на сохранённое
        значение "Кол-во изделий". Это не объединяет несколько изделий в один
        общий электрический расчёт.
        """
        rows={}
        current_product_qty=1
        def add(name,unit,qty):
            if qty is None:return
            # V20.58: для статики МЦД сначала рассчитываем полный комплект
            # ОДНОГО изделия, затем масштабируем каждую итоговую позицию на
            # сохранённое поле "Кол-во изделий".
            scaled_qty=qty*current_product_qty
            key=(name,unit); rows[key]=rows.get(key,0)+scaled_qty

        def m4_per_two_horizontal_sides(width_mm):
            # Справочник: на сторону 1 м→2; 2 м→3; 3 м→4, минимум 2.
            per_side=max(2,math.ceil(max(0.0,width_mm)/1000.0)+1)
            return per_side*2

        for s in signs:
            if s.get("mode")!=MODE_MCD or s.get("face_type")!="С подсветкой":
                continue
            raw_product_qty=str(s.get("quantity","") or "").strip()
            try:
                current_product_qty=max(1,int(raw_product_qty)) if raw_product_qty else 1
            except Exception:
                current_product_qty=1
            w=float(s.get("width",0)); h=float(s.get("height",0))
            sides=int(s.get("sides",1))
            if w<=0 or h<=0:continue
            perimeter=2.0*(w+h)/1000.0

            is_round=bool(s.get("round",False))
            diameter=float(s.get("diameter",0) or w)
            if is_round:
                # V20.86: круглый корпус — одно кольцо профиля 75 мм
                # по наружной окружности изделия. Никаких П-/Г-элементов.
                profile_len=math.pi*diameter/1000.0
                add(self._round_mcd_profile_name(diameter),"м.п.",profile_len)
            else:
                profile_mm = 120 if sides == 2 else 75
                case_row=self._mcd_case_component_row(w,h,profile_mm)
                if case_row:add(*case_row)

            if sides==2:
                if is_round:
                    # V20.94: круглый двухсторонний МЦД.
                    # LED считаются один раз по наружной окружности, без ×2 на стороны.
                    led_buy=math.ceil(math.pi*diameter/65.0)
                    # Для мощности берём фактическое количество этих же LED.
                    led_installed=led_buy
                else:
                    # V30.69: прямоугольный двухсторонний МЦД — шаг торцевых LED 90 мм.
                    # Короткая сторона ≤ 400 мм: ceil(длинная / 90) × 2;
                    # короткая сторона > 400 мм: ceil(длинная / 90) × 2 + ceil(короткая / 90) × 2.
                    led_buy=_v3069_mcd_2side_edge_leds(w,h)
                    # Для мощности — то же фактическое количество LED.
                    led_installed=led_buy
                clean_power=led_installed*1.5
                design_power=clean_power*1.20
                psus=self._static_mcd_power_supplies(design_power)
                psu_count=sum(psus.values())

                add("Торцевой светодиод 50×25 мм, 1,5 Вт","шт.",led_buy)
                add("Саморез острый (клоп) 3,5×9,5 мм","шт.",led_buy*2)
                add("Соединитель проводов WAGO 2-полюсный","шт.",psu_count)
                add("Соединитель проводов WAGO 3-полюсный","шт.",1)
                for nominal,count in psus.items():
                    if count:add(f"Блок питания {nominal} Вт","шт.",count)

                # ШВВП: по справочнику v2 отдельный 2-метровый провод для остаточной
                # группы 1–19 LED после формирования полных групп по 20.
                remainder=led_installed%20
                add("Кабель ШВВП 2×0,75 мм²","м",2 if remainder else 0)

                if is_round:
                    # V20.86: два кольца по окружности двух оргстёкол.
                    glass_d=max(0.0,diameter-18.0)
                    # Норма одного изделия фиксируется до 0,001 м.п.,
                    # после чего масштабируется на количество изделий.
                    angle_len=round(2.0*math.pi*glass_d/1000.0,3)
                    angle_name=self._round_mcd_angle_name(glass_d)
                else:
                    # V30.74: правило двустороннего прямоугольного МЦД приведено
                    # к одностороннему: два контура по сторонам минус 180 мм
                    # (квадрат со стороной менее 551 мм — по полным габаритам).
                    # Раньше контуры считались по сторонам минус 50 мм.
                    angle_w,angle_h=_mcd_static_angle_sides(w,h)
                    angle_len=_mcd_static_angle_length_m(w,h)
                    angle_name="Уголок алюминиевый 30×20×2 мм"
                add(angle_name,"м.п.",angle_len)
                add("Уплотнитель 9х7,4мм","м.п.",perimeter*2)
                # Для двухстороннего изделия 3M равен полной длине уголка.
                add("Скотч двухсторонний 3M","м.п.",angle_len)
                # Праймер: 2,5 г на 1 м.п. скотча.
                add("Праймер","г",2.5*angle_len)

                m4=m4_per_two_horizontal_sides(w)
                add("Саморез оконный 3,9×25 мм","шт.",m4)
                add("Заклёпка резьбовая М4","шт.",m4)
                add("Заглушка пластиковая декоративная 12","шт.",m4)

                add("Заклёпка вытяжная алюминиевая 4,8×12 мм","шт.",36)
                add("Монтажная пластина металлическая 80×13×2 мм","шт.",4)
                add("Герметик силиконовый бесцветный прозрачный","г",30)
                add("Термоусадочная трубка ТТУ 3/1.5 + ТТУ 2/1","м",0.30)
                add("Клей космофен","г",3)
                glass_w=max(0,w-18); glass_h=max(0,h-18)
                # V30.57: у круглого изделия размер листа — диаметр, без радиуса скругления.
                if is_round:
                    add(f"Оргстекло 8 мм Ø{self._format_component_qty(max(0.0,diameter-18.0))} мм","шт.",2)
                else:
                    add(f"Оргстекло 8 мм {self._format_component_qty(glass_w)}×{self._format_component_qty(glass_h)} мм, R66","шт.",2)
                # V30.25: бэклит строго по рассчитанному размеру соответствующего оргстекла.
                if is_round:
                    glass_d=max(0.0,diameter-18.0)
                    backlit_size=f"Ø{self._format_component_qty(max(0.0,glass_d-42.0))} мм"  # V30.58: круг — Ø(оргстекло − 42)
                else:
                    backlit_size=(f"{self._format_component_qty(max(0.0,glass_w-41.0))}×"
                                  f"{self._format_component_qty(max(0.0,glass_h-41.0))} мм, R45,5")
                add(f"Молочный акрил 4 мм для бэклита {backlit_size}","шт.",2)

                # Для двухстороннего изделия шириной от 1999 мм:
                # одна перемычка-шпилька М10 длиной в высоту изделия.
                if w>=1999 and not is_round:
                    add("Перемычка — шпилька М10","м",h/1000.0)
                    add("Резьбовая заклёпка для шпильки М10","шт.",2)
                    add("Площадка для шпильки 80×40×5 мм","шт.",2)
                    add("Заклёпка вытяжная алюминиевая 4,8×12 мм для шпильки","шт.",8)

                add("LED фактически установлено (для расчёта мощности)","шт.",led_installed)
                add("Расчётная мощность LED (+20%)","Вт",design_power)

            elif sides==1:
                # V30.68: 60 фронтальных LED на 1 м² площади изделия
                # (прямоугольник W × H, круглое — π·D²/4), округление вверх.
                face_area=(math.pi*diameter*diameter/4.0 if is_round else w*h)/1_000_000.0
                led_count=max(1,math.ceil(face_area*MCD_STATIC_1SIDE_LED_PER_SQM-1e-9))
                clean_power=led_count*1.5
                design_power=clean_power*1.20
                psus=self._static_mcd_power_supplies(design_power)
                psu_count=sum(psus.values())
                add("Фронтальный светодиод 70×15 мм, 1,5 Вт","шт.",led_count)
                add("Саморез универсальный 3×10 мм","шт.",led_count*2)
                add("Соединитель проводов WAGO 2-полюсный","шт.",psu_count)
                add("Соединитель проводов WAGO 3-полюсный","шт.",1)
                for nominal,count in psus.items():
                    if count:add(f"Блок питания {nominal} Вт","шт.",count)
                if led_count%20:
                    add("Кабель ШВВП 2×0,75 мм²","м",2)
                if is_round:
                    # V20.86: одно кольцо по окружности оргстекла Ø(D−18).
                    glass_d=max(0.0,diameter-18.0)
                    # Норма одного изделия фиксируется до 0,001 м.п.,
                    # после чего масштабируется на количество изделий.
                    angle_len=round(math.pi*glass_d/1000.0,3)
                    angle_name=self._round_mcd_angle_name(glass_d)
                    aw=ah=0.0
                else:
                    # V30.74: то же правило, что и у двустороннего изделия.
                    # Два контура (переднее оргстекло + задняя стенка) по сторонам
                    # минус 180 мм; квадрат со стороной менее 551 мм — по габаритам.
                    aw,ah=_mcd_static_angle_sides(w,h)
                    angle_len=_mcd_static_angle_length_m(w,h)
                    angle_name="Уголок алюминиевый 30×20×2 мм"
                add(angle_name,"м.п.",angle_len)
                add("Уплотнитель 9х7,4мм","м.п.",perimeter)
                # М4 по всем четырём сторонам: ceil(L м)+1, минимум 2 на сторону.
                per_w=max(2,math.ceil(w/1000.0)+1); per_h=max(2,math.ceil(h/1000.0)+1)
                m4=2*per_w+2*per_h
                add("Саморез оконный 3,9×25 мм","шт.",m4)
                add("Заклёпка резьбовая М4","шт.",m4)
                add("Заглушка пластиковая декоративная 12","шт.",m4)
                is_g=(w>2999 or h>2999)
                add("Заклёпка вытяжная алюминиевая 4,8×12 мм","шт.",72 if is_g else 36)
                add("Монтажная пластина металлическая 80×13×2 мм","шт.",4 if is_g else 2)
                # На стенку: 1 клёпка на 150 мм уголка, минимум 2 на каждую сторону.
                wall=2*max(2,math.ceil(aw/150.0))+2*max(2,math.ceil(ah/150.0))
                add("Заклёпка вытяжная алюминиевая 4,8×10 мм на стенку","шт.",wall)
                add("Герметик силиконовый бесцветный прозрачный","г",30)
                add("Термоусадочная трубка ТТУ 3/1.5 + ТТУ 2/1","м",0.30)
                add("Фольгированный скотч","м",0.4*psu_count)
                if is_round:
                    # V20.65: круглый МЦД — 3M равен полной длине уголка по окружности стекла.
                    tape=angle_len
                else:
                    tape=angle_len/2.0+0.4  # V19.88: прямоугольный МЦД — прежнее правило
                add("Скотч двухсторонний 3M","м",tape)
                add("Праймер","г",2.5*tape)
                add("Наконечник 0,75 мм²","шт.",4)
                add("Клей космофен","г",3)
                # V19.87 — оргстекло для любого МЦД: (W−18) × (H−18).
                glass_w=max(0,w-18); glass_h=max(0,h-18)
                # V30.57: у круглого изделия размер листа — диаметр, без радиуса скругления.
                if is_round:
                    add(f"Оргстекло 8 мм Ø{self._format_component_qty(max(0.0,diameter-18.0))} мм","шт.",1)
                else:
                    add(f"Оргстекло 8 мм {self._format_component_qty(glass_w)}×{self._format_component_qty(glass_h)} мм, R66","шт.",1)
                # V30.25: бэклит строго по рассчитанному размеру соответствующего оргстекла.
                if is_round:
                    glass_d=max(0.0,diameter-18.0)
                    backlit_size=f"Ø{self._format_component_qty(max(0.0,glass_d-42.0))} мм"  # V30.58: круг — Ø(оргстекло − 42)
                else:
                    backlit_size=(f"{self._format_component_qty(max(0.0,glass_w-41.0))}×"
                                  f"{self._format_component_qty(max(0.0,glass_h-41.0))} мм, R45,5")
                add(f"Молочный акрил 4 мм для бэклита {backlit_size}","шт.",1)
                # Односторонняя статика МЦД: задняя крышка из алюкобонда остаётся (W−52) × (H−52), R49.
                back_w=max(0,w-52); back_h=max(0,h-52)
                if is_round:
                    # V30.57: круглая задняя крышка — Ø(D − 52), радиус R49 не применяется.
                    add(f"Алюкобонд 3 мм Ø{self._format_component_qty(max(0.0,diameter-52.0))} мм","шт.",1)
                else:
                    add(f"Алюкобонд 3 мм {self._format_component_qty(back_w)}×{self._format_component_qty(back_h)} мм, R49","шт.",1)
                add("LED фактически установлено (для расчёта мощности)","шт.",led_count)
                add("Расчётная мощность LED (+20%)","Вт",design_power)

        return [(name,unit,qty) for (name,unit),qty in rows.items()]

    def _reference_group_for_component(self, name):
        n=str(name).lower()

        # Расходные материалы проверяем первыми, чтобы скотч/герметик/клей
        # не попадали в соседние группы по случайным словам.
        if any(k in n for k in ("герметик","космофен","клей","скотч","праймер","уплотнитель","термоусад")):
            return "Герметики, клеи и прочее"

        # 1. Электроника
        if any(k in n for k in (
            "модули", "модуль", "led", "светодиод", "бп", "блок питания",
            "мрв", "приёмная карта", "приемная карта", "novastar", "msd", "карта msd",
            "мини-пк", "rassberry", "raspberry", "sd-карта 64gb класса a2", "вентилятор", "термодатчик", "медиаконвертер", "кросс"
        )):
            return "Электроника"

        # 2. Металлические комплектующие
        if any(k in n for k in (
            "профиль", "профильная труба", "уголок перфор", "алюкобонд",
            "площадк", "пластина", "уголок алюминиев", "решетки на кабинеты", "решётки на кабинеты",
            "din-рейка", "din рейка", "шпилька"
        )):
            return "Металлические комплектующие"

        # 3. Электрика
        if any(k in n for k in (
            "кабель", "провод", "wago", "наконечник", "utp", "rj-45", "rj45",
            "вилка+розетка", "powercon", "пвс", "кгхл", "шввп", "ввг", "клеммная колодка",
            "dvi-hdmi", "hdmi", "bls1"
        )):
            return "Электрика"

        # 4. Крепёж и метизы
        if any(k in n for k in (
            "саморез", "винт", "болт", "гайка", "шайба", "закл",
            "заглушка", "замок"
        )):
            return "Крепёж и метизы"

        # 5. Герметики, клеи и прочее
        return "Герметики, клеи и прочее"

    def _reference_led_cabinet_rows(self, cabinet_size):
        """Полный справочник одного LED-кабинета из тех же норм,
        которые реально используются калькулятором COMPONENT_RATES."""
        rates = COMPONENT_RATES[cabinet_size]
        rows=[]
        size_label=f"{cabinet_size[0]}×{cabinet_size[1]}"

        pretty = {
            "Кабинеты": "Кабинет",
            "Модули": "LED-модуль",
            "БП": "Блок питания",
            "МРВ": "Приёмная карта NovaStar MRV416-N",
        }
        special_logic = {
            "Кабинеты": f"Один кабинет типоразмера {size_label}.",
            "Модули": f"Фиксированная норма LED-модулей на один кабинет {size_label}.",
            "БП": f"Фиксированная норма блоков питания на один кабинет {size_label}.",
            "МРВ": "Одна приёмная карта на кабинет.",
            "DIN-рейка": "Одна DIN-рейка длиной 10 см на каждый кабинет.",
        }

        for key, qty in rates.items():
            name=pretty.get(key,key)
            logic=special_logic.get(key, f"Фиксированная норма на один кабинет {size_label}.")
            unit=COMPONENT_UNITS.get(key,"шт.")
            if isinstance(qty,float):
                qtext=(f"{qty:.2f}".rstrip("0").rstrip(".")).replace(".",",")
            else:
                qtext=str(qty)
            rows.append([name,logic,qtext,unit])
        return rows

