    def _force_static_article_upper(self,*_):
        v=self.static_article_var.get()
        u=v.upper()
        u=re.sub(r"(?<=\d)X(?=\d)","x",u)
        if v!=u:self.static_article_var.set(u)

    def _validate_static_quantity_input(self, proposed):
        """Для РЖД поле количества может быть пустым либо содержать только цифры."""
        return proposed == "" or proposed.isdigit()

    def _static_dimensions_typed(self,event=None):
        mode=self.static_mode_var.get()
        if mode not in (MODE_MCD,MODE_RZD):return
        max_w,max_h=(3100,1600) if mode==MODE_MCD else (MAX_W_MM,MAX_H_MM)

        # Круглое исполнение МЦД — исключение из прямоугольного ограничения
        # по высоте 1600 мм. Для круга допускаем диаметр до 2400 мм.
        if mode==MODE_MCD and hasattr(self,"static_round_var") and self.static_round_var.get():
            round_max_d=2400
            try:d=max(0,min(round_max_d,int(self.static_width_input_var.get() or 0)))
            except ValueError:d=0
            self.static_width_mm=self.static_height_mm=d
            self.static_height_input_var.set(str(d) if d else "")
            if hasattr(self,"static_diameter_input_var"):
                self.static_diameter_input_var.set(str(d) if d else "")
        else:
            try:w=max(0,min(max_w,int(self.static_width_input_var.get() or 0)))
            except ValueError:w=0
            try:h=max(0,min(max_h,int(self.static_height_input_var.get() or 0)))
            except ValueError:h=0
            self.static_width_mm,self.static_height_mm=w,h
        self._update_static_mcd_params()
        self._static_apply_autofill()
        self._draw_static_grid()

    def _static_autofill_values(self):
        """Сформировать стандартные наименование и артикул статического указателя.

        РЖД:
          обычный / с подсветкой -> AS-L / AS-L II
          светоотражающий        -> AS-LS / AS-LS II

        МЦД:
          все исполнения         -> ASD-L / ASD-L II

        Даже без введённых габаритов возвращается стандартная базовая часть,
        чтобы при создании нового изделия поля уже были заполнены.
        """
        mode=self.static_mode_var.get() if hasattr(self,"static_mode_var") else MODE_RZD
        try:
            sides=2 if int(self.static_sides_var.get() or 1)==2 else 1
        except Exception:
            sides=1
        face_raw=str(self.static_face_type_var.get() or "").strip()
        face_key=face_raw.casefold().replace("ё","е")
        is_reflective=face_key.startswith("светоотраж")
        is_lit=face_key == "с подсветкой"
        w=int(getattr(self,"static_width_mm",0) or 0)
        h=int(getattr(self,"static_height_mm",0) or 0)

        is_round_mcd=(
            mode==MODE_MCD
            and hasattr(self,"static_round_var")
            and bool(self.static_round_var.get())
        )

        if mode==MODE_MCD:
            if is_round_mcd:
                # V20.62: для круглых МЦД отдельная система артикулов.
                # 1 сторона  -> ASD-L
                # 2 стороны -> ASD-ST
                base_family="ASD-ST" if sides==2 else "ASD-L"
                family=base_family
            else:
                base_family="ASD-L"
                family=f"{base_family} II" if sides==2 else base_family
        else:
            base_family="AS-LS" if is_reflective else "AS-L"
            family=f"{base_family} II" if sides==2 else base_family

        side_word="Двусторонний" if sides==2 else "Односторонний"

        parts=["Статический навигационный указатель."]
        if is_lit:
            parts.append("Световой.")
        elif is_reflective:
            parts.extend(["Несветовой.","Световозвращающий материал."])

        tail=f"{side_word} {family}"
        if is_round_mcd:
            diameter=w if w>0 else h
            dims=f"D={diameter}" if diameter>0 else ""
        else:
            dims=f"{w}x{h}" if w>0 and h>0 else ""

        if dims:
            tail+=f" {dims}"
        parts.append(tail)
        return " ".join(parts), family + (f" {dims}" if dims else "")

    def _static_rzd_autofill_values(self):
        """Совместимый alias для старых вызовов."""
        return self._static_autofill_values()

    def _static_apply_autofill(self, *args):
        if getattr(self,"_loading_saved_product",False):
            return
        if not hasattr(self,"static_mode_var") or self.static_mode_var.get() not in (MODE_MCD, MODE_RZD):
            return
        if not hasattr(self,"static_autofill_var") or not self.static_autofill_var.get():
            return
        name,article=self._static_autofill_values()
        if self.static_name_var.get()!=name:
            self.static_name_var.set(name)
        if self.static_article_var.get()!=article:
            self.static_article_var.set(article)

    def _static_autofill_changed(self):
        if self.static_autofill_var.get():
            self._static_apply_autofill()
        self._sync_active_static_from_form()

    def _update_static_mcd_params(self):
        if hasattr(self,"static_dimensions_var"):
            self.static_dimensions_var.set(f"{self.static_width_mm} × {self.static_height_mm} мм" if self.static_width_mm and self.static_height_mm else "—")
        mode = self.static_mode_var.get() if hasattr(self,"static_mode_var") else MODE_MCD
        if hasattr(self,"static_profile_var"):
            if mode == MODE_RZD:
                self.static_profile_var.set("60×20×2 мм")
                if hasattr(self,"static_frame_profile_var"):
                    self.static_frame_profile_var.set("40×20×2 мм")
                if hasattr(self,"static_profile_label_var"):
                    self.static_profile_label_var.set("П-профиль:")
            else:
                self.static_profile_var.set("120 мм" if int(self.static_sides_var.get())==2 else "75 мм")
                if hasattr(self,"static_profile_label_var"):
                    self.static_profile_label_var.set("Алюминиевый профиль:")
        if hasattr(self,"static_frame_label") and hasattr(self,"static_frame_value"):
            if mode == MODE_RZD:
                self.static_frame_label.grid()
                self.static_frame_value.grid()
            else:
                self.static_frame_label.grid_remove()
                self.static_frame_value.grid_remove()
        if hasattr(self,"static_mount_type_frame"):
            # V20.20: блок количества нужен и РЖД, и МЦД. Для МЦД скрываем только выбор вида крепления.
            self.static_mount_type_frame.pack(side="left",anchor="n",padx=(38,0))
            if mode == MODE_RZD:
                self.static_mount_type_label.pack(anchor="w")
                self.static_mount_type_combo.pack(anchor="w",pady=(2,0))
                self.static_quantity_label.pack(anchor="w",pady=(7,0))
            else:
                self.static_mount_type_label.pack_forget()
                self.static_mount_type_combo.pack_forget()
                self.static_quantity_label.pack(anchor="w",pady=(0,0))
            self.static_quantity_entry.pack(anchor="w",pady=(2,0))
        if hasattr(self,"static_autofill_check"):
            if mode in (MODE_MCD, MODE_RZD):
                self.static_autofill_check.grid()
            else:
                self.static_autofill_check.grid_remove()
        self._update_static_add_button_state()

    def _update_static_add_button_state(self):
        if not hasattr(self,"static_add_project_button"):
            return
        ready=(bool(getattr(self,"_static_draft_mode",True)) and self.static_mode_var.get() in (MODE_MCD,MODE_RZD) and self.static_width_mm>0 and self.static_height_mm>0)
        if ready:
            self.static_add_project_button.configure(
                state="normal", bg="#9fd8aa", activebackground="#86c995",
                fg="#174f24", activeforeground="#103919", cursor="hand2"
            )
        else:
            self.static_add_project_button.configure(
                state="disabled", bg="#d2d2d2", activebackground="#d2d2d2",
                fg="#777777", activeforeground="#777777", cursor="arrow"
            )

    def _update_static_params_visibility(self):
        if hasattr(self,"static_params_frame"):
            if self.static_mode_var.get() in (MODE_MCD,MODE_RZD):self.static_params_frame.grid()
            else:self.static_params_frame.grid_remove()
            self.static_params_frame.configure(text=("Параметры указателя РЖД" if self.static_mode_var.get()==MODE_RZD else "Параметры указателя МЦД"))

    def _add_static_sign_to_project(self):
        if not bool(getattr(self,"_static_draft_mode",True)):
            messagebox.showinfo("Статический указатель","Для нового указателя нажмите «Новое изделие».")
            return
        mode=self.static_mode_var.get()
        if mode not in (MODE_MCD,MODE_RZD):return
        if not self.static_width_mm or not self.static_height_mm:
            messagebox.showwarning("Статический указатель","Укажите диаметр изделия." if self.static_round_var.get() else "Укажите ширину и высоту изделия."); return
        self.saved_static_signs.append({"name":self.static_name_var.get().strip(),"article":self.static_article_var.get().strip(),
            "layout_no":self.static_layout_no_var.get().strip(),"mode":mode,"width":self.static_width_mm,"height":self.static_height_mm,
            "sides":int(self.static_sides_var.get()),"profile":self.static_profile_var.get(),"frame_profile":self.static_frame_profile_var.get(),"mount_type":self.static_mount_type_var.get(),"quantity":(self.static_quantity_var.get().strip() if mode in (MODE_MCD,MODE_RZD) else ""),"autofill":(bool(self.static_autofill_var.get()) if mode in (MODE_MCD, MODE_RZD) else False),"face_type":self.static_face_type_var.get(),"round":bool(self.static_round_var.get()),"diameter":(self.static_width_mm if self.static_round_var.get() else "")})
        self._active_static_index=None
        self._static_draft_mode=False
        self._mark_project_dirty()
        self._refresh_static_saved_tree(); self._refresh_project_journal(); self._refresh_components_screen_selector(); self._refresh_components_table()
        self._update_static_product_buttons()

    def _refresh_static_saved_tree(self):
        if not hasattr(self,"static_saved_tree"):return
        for iid in self.static_saved_tree.get_children():self.static_saved_tree.delete(iid)
        for i,s in enumerate(self.saved_static_signs):
            if bool(s.get("round",False)):
                diameter=float(s.get("diameter",0) or s.get("width",0) or 0)
                size_text=f"Ø {self._format_component_qty(diameter)} мм"
            else:
                size_text=f"{s.get('width',0)} × {s.get('height',0)}"
            self.static_saved_tree.insert(
                "","end",iid=str(i),
                values=(
                    i+1,
                    s.get("article") or f"Указатель {i+1}",
                    s.get("sides",1),
                    s.get("face_type",""),
                    s.get("quantity",1)
                )
            )
        if hasattr(self,"new_static_product_button"):
            has_saved=bool(self.saved_static_signs)
            self.new_static_product_button.configure(state=("normal" if has_saved else "disabled"),cursor=("hand2" if has_saved else "arrow"))

    def _delete_selected_static_sign(self):
        sel=self.static_saved_tree.selection()
        if not sel:return
        idx=int(sel[0])
        if idx<0 or idx>=len(self.saved_static_signs):return
        del self.saved_static_signs[idx]
        self._active_static_index=None
        self._mark_project_dirty()
        self._refresh_static_saved_tree(); self._refresh_project_journal(); self._refresh_components_screen_selector(); self._refresh_components_table()
        if not self.saved_static_signs:
            self._static_draft_mode=True
        self._update_static_product_buttons()

    def _load_selected_static_sign(self,event=None):
        sel=self.static_saved_tree.selection()
        if not sel:return
        self._sync_active_static_from_form()
        idx=int(sel[0])
        self._loading_saved_product=True
        self._active_static_index=idx
        s=self.saved_static_signs[idx]
        self.static_mode_var.set(s.get("mode",MODE_MCD)); self._update_static_params_visibility()
        self.static_autofill_var.set(bool(s.get("autofill",True)) if self.static_mode_var.get() in (MODE_MCD, MODE_RZD) else False)
        self.static_name_var.set(s.get("name","")); self.static_article_var.set(s.get("article","")); self.static_layout_no_var.set(s.get("layout_no",""))
        self.static_width_mm=int(s.get("width",0)); self.static_height_mm=int(s.get("height",0))
        self.static_round_var.set(bool(s.get("round",False)) and self.static_mode_var.get()==MODE_MCD)
        if self.static_round_var.get():
            d=int(float(s.get("diameter") or self.static_width_mm or 0))
            self.static_width_mm=self.static_height_mm=d
            self.static_width_input_var.set(str(d) if d else "")
            self.static_height_input_var.set(str(d) if d else "")
            self.static_diameter_input_var.set(str(d) if d else "")
        else:
            self.static_width_input_var.set(str(self.static_width_mm)); self.static_height_input_var.set(str(self.static_height_mm))
        self.static_sides_var.set(int(s.get("sides",1)))
        _loaded_face=str(s.get("face_type","С подсветкой") or "С подсветкой").strip()
        if _loaded_face.casefold().replace("ё","е").startswith("светоотраж"):
            _loaded_face="Светоотражающее"
        self.static_face_type_var.set(_loaded_face)
        self.static_mount_type_var.set(s.get("mount_type","") if self.static_mode_var.get()==MODE_RZD else "")
        self.static_quantity_var.set(str(s.get("quantity","") or "") if self.static_mode_var.get() in (MODE_MCD,MODE_RZD) else "")
        self._toggle_static_round_mode()
        self._update_static_mcd_params(); self._draw_static_grid()
        self._loading_saved_product=False
        # После загрузки старого изделия пересчитываем автополя по текущим правилам.
        self._static_apply_autofill()
        self._static_draft_mode=False
        self._update_static_product_buttons()

    def _static_mode_changed(self):
        self.static_width_mm=self.static_height_mm=0
        if hasattr(self,"static_mount_type_var"):
            self.static_mount_type_var.set("")
        if hasattr(self,"static_quantity_var"):
            self.static_quantity_var.set("")
        if hasattr(self,"static_autofill_var"):
            self.static_autofill_var.set(self.static_mode_var.get() in (MODE_MCD, MODE_RZD))
        if hasattr(self,"static_width_input_var"):
            self.static_width_input_var.set(""); self.static_height_input_var.set("")
        if hasattr(self,"static_round_check"):
            if self.static_mode_var.get()==MODE_MCD:
                self.static_round_check.configure(state="normal")
            else:
                self.static_round_var.set(False)
                self.static_round_check.configure(state="disabled")
        self._toggle_static_round_mode()
        self._update_static_params_visibility(); self._update_static_mcd_params(); self._static_apply_autofill(); self._draw_static_grid()

    def _static_mouse_mm(self, event):
        cw=max(1,self.static_canvas.winfo_width()-100); ch=max(1,self.static_canvas.winfo_height()-90)
        scale=min(cw/MAX_W_MM,ch/MAX_H_MM)
        raw_w=max(0,min(MAX_W_MM,(event.x-70)/scale)); raw_h=max(0,min(MAX_H_MM,(event.y-50)/scale))
        mode=self.static_mode_var.get()
        if mode==MODE_RZD:
            return nearest_value(raw_w,RZD_VALID_WIDTHS), nearest_value(raw_h,RZD_VALID_HEIGHTS)
        if mode==MODE_MCD:
            vw=[2*MCD_MARGIN+n*MCD_MODULE_W for n in range(1,100) if 2*MCD_MARGIN+n*MCD_MODULE_W<=MAX_W_MM]
            vh=[2*MCD_MARGIN+n*MCD_MODULE_H for n in range(1,100) if 2*MCD_MARGIN+n*MCD_MODULE_H<=MAX_H_MM]
            return nearest_value(raw_w,vw), nearest_value(raw_h,vh)
        return min(round(raw_w/CUSTOM_STEP_X)*CUSTOM_STEP_X,(MAX_W_MM//CUSTOM_STEP_X)*CUSTOM_STEP_X), min(round(raw_h/CUSTOM_STEP_Y)*CUSTOM_STEP_Y,(MAX_H_MM//CUSTOM_STEP_Y)*CUSTOM_STEP_Y)

    def _static_drag(self,event):
        if self.static_mode_var.get()==MODE_MCD:return
        self.static_width_mm,self.static_height_mm=map(int,self._static_mouse_mm(event))
        self._update_static_mcd_params()
        self._static_apply_autofill()
        self._draw_static_grid()

    def _static_reset(self):
        self.static_width_mm=self.static_height_mm=0
        self._update_static_mcd_params()
        self._static_apply_autofill()
        self._draw_static_grid()


    def _toggle_static_round_mode(self):
        """Круглое исполнение: ширина становится диаметром, высота блокируется."""
        # Круг разрешён только для МЦД.
        if self.static_mode_var.get()!=MODE_MCD:
            self.static_round_var.set(False)

        is_round=bool(self.static_round_var.get())
        if hasattr(self,"static_width_label_var"):
            self.static_width_label_var.set("Диаметр:" if is_round else "Ширина:")
        if hasattr(self,"static_height_entry"):
            self.static_height_entry.configure(state="disabled" if is_round else "normal")

        if is_round:
            # Текущее значение ширины используем как диаметр.
            # Для круглого МЦД допускаем Ø до 2400 мм.
            try:d=max(0,min(2400,int(self.static_width_input_var.get() or 0)))
            except ValueError:d=0
            self.static_width_mm=self.static_height_mm=d
            self.static_height_input_var.set(str(d) if d else "")
            self.static_diameter_input_var.set(str(d) if d else "")
        else:
            self.static_diameter_input_var.set("")
            try:self.static_width_mm=max(0,int(self.static_width_input_var.get() or 0))
            except ValueError:self.static_width_mm=0
            try:self.static_height_mm=max(0,int(self.static_height_input_var.get() or 0))
            except ValueError:self.static_height_mm=0

        self._update_static_mcd_params()
        self._draw_static_grid()

    def _draw_static_grid(self):
        """Координатное поле статического указателя.

        Для двухстороннего МЦД/РЖД используется та же логика представления,
        что у динамического РЖД: сторона 1 слева, сторона 2 справа через
        480 мм и помечена как зеркальный вид.
        """
        c=self.static_canvas; c.delete("all")
        W=max(400,c.winfo_width()); H=max(300,c.winfo_height())
        ox,oy=70,50; mode=self.static_mode_var.get()
        is_round_mcd=(
            mode==MODE_MCD
            and hasattr(self,"static_round_var")
            and bool(self.static_round_var.get())
        )
        grid_w,grid_h=(3100,2400 if is_round_mcd else 1600) if mode==MODE_MCD else (MAX_W_MM,MAX_H_MM)
        w,h=self.static_width_mm,self.static_height_mm
        try:sides=max(1,min(2,int(self.static_sides_var.get() or 1)))
        except Exception:sides=1
        side_gap_mm=int(MODULE_W*1.5)  # 480 мм — как на динамическом РЖД.
        display_w=grid_w
        if sides==2 and w>0:
            display_w=max(grid_w,2*w+side_gap_mm)
        scale=min((W-100)/max(1,display_w),(H-90)/max(1,grid_h))
        mx=ox+display_w*scale; my=oy+grid_h*scale
        c.create_rectangle(ox,oy,mx,my,outline="#777",width=2)
        sx,sy=(MCD_MODULE_W,MCD_MODULE_H) if mode==MODE_MCD else ((CUSTOM_STEP_X,CUSTOM_STEP_Y) if mode==MODE_CUSTOM else (RZD_GRID_X,RZD_GRID_Y))
        # Координатная сетка растягивается на всю область, включая вторую сторону.
        for mm in range(0,int(display_w)+1,sx):
            x=ox+mm*scale; c.create_line(x,oy,x,my,fill="#ddd",dash=(4,4)); c.create_text(x,oy-8,text=str(mm),anchor="s",font=("Arial",7))
        if display_w % sx:
            c.create_text(mx,oy-8,text=str(int(display_w)),anchor="s",font=("Arial",7))
        for mm in range(0,grid_h+1,sy):
            y=oy+mm*scale; c.create_line(ox,y,mx,y,fill="#ddd",dash=(4,4)); c.create_text(ox-8,y,text=str(mm),anchor="e",font=("Arial",7))

        def draw_mcd_rounded(x1,y1,x2,y2,mirrored=False):
            r=min(90*scale,(x2-x1)/2,(y2-y1)/2)
            c.create_rectangle(x1+r,y1,x2-r,y2,fill="#a9dfb3",outline="")
            c.create_rectangle(x1,y1+r,x2,y2-r,fill="#a9dfb3",outline="")
            c.create_arc(x1,y1,x1+2*r,y1+2*r,start=90,extent=90,style="pieslice",fill="#a9dfb3",outline="")
            c.create_arc(x2-2*r,y1,x2,y1+2*r,start=0,extent=90,style="pieslice",fill="#a9dfb3",outline="")
            c.create_arc(x2-2*r,y2-2*r,x2,y2,start=270,extent=90,style="pieslice",fill="#a9dfb3",outline="")
            c.create_arc(x1,y2-2*r,x1+2*r,y2,start=180,extent=90,style="pieslice",fill="#a9dfb3",outline="")
            c.create_line(x1+r,y1,x2-r,y1,fill="#145d25",width=5)
            c.create_line(x2,y1+r,x2,y2-r,fill="#145d25",width=5)
            c.create_line(x2-r,y2,x1+r,y2,fill="#145d25",width=5)
            c.create_line(x1,y2-r,x1,y1+r,fill="#145d25",width=5)
            for box_,start_ in (((x1,y1,x1+2*r,y1+2*r),90),((x2-2*r,y1,x2,y1+2*r),0),
                                ((x2-2*r,y2-2*r,x2,y2),270),((x1,y2-2*r,x1+2*r,y2),180)):
                c.create_arc(*box_,start=start_,extent=90,style="arc",outline="#145d25",width=5)
            # Радиус также зеркалим визуально: сторона 2 подписана слева снизу.
            c.create_text(x1+6 if mirrored else x2-6,y2-6,text="R90",anchor="sw" if mirrored else "se",fill="#8a3b3b",font=("Arial",8,"bold"))
            self._draw_mcd_case_split(c,x1,y1,x2,y2,w,h,tags="selection")

        def draw_side(x1,side_no,mirrored=False):
            if not (w and h):return
            x2=x1+w*scale; y2=oy+h*scale
            if mode==MODE_MCD and hasattr(self,"static_round_var") and self.static_round_var.get():
                d=min(w,h); x2=x1+d*scale; y2=oy+d*scale
                c.create_oval(x1,oy,x2,y2,fill="#a9dfb3",outline="#145d25",width=5)
                # V20.61: круглое изделие МЦД всегда визуально делится
                # на две равные половины вертикальной пунктирной линией.
                xm=(x1+x2)/2
                c.create_line(
                    xm, oy, xm, y2,
                    fill="#725b00", dash=(7,5), width=2,
                    tags="selection"
                )
                c.create_text((x1+x2)/2,oy-4,text=f"Ø {d} мм",anchor="s",fill="#145d25",font=("Arial",9,"bold"))
            elif mode==MODE_MCD:
                draw_mcd_rounded(x1,oy,x2,y2,mirrored)
            else:
                c.create_rectangle(x1,oy,x2,y2,fill="#a9dfb3",outline="#218838",width=2)
            if not (mode==MODE_MCD and hasattr(self,"static_round_var") and self.static_round_var.get()):
                c.create_text((x1+x2)/2,oy-4,text=f"{w} мм",anchor="s",fill="#145d25",font=("Arial",9,"bold"))
                c.create_text(x1-4 if not mirrored else x2+4,y2,text=f"{h} мм",anchor="se" if not mirrored else "sw",fill="#145d25",font=("Arial",9,"bold"))
            if sides==2:
                label="СТОРОНА 2 — зеркальный вид" if side_no==2 else "СТОРОНА 1"
                c.create_text((x1+x2)/2,y2+14,text=label,anchor="n",fill="#333333",font=("Arial",9,"bold"))

        if w and h:
            draw_side(ox,1,False)
            if sides==2:
                side2_x1=ox+(w+side_gap_mm)*scale
                c.create_text(ox+(w+side_gap_mm/2)*scale,oy+18,text="480 мм",anchor="n",fill="#777777",font=("Arial",8))
                draw_side(side2_x1,2,True)

        if w and h and mode==MODE_MCD and hasattr(self,"static_round_var") and self.static_round_var.get():
            self.static_size_var.set(f"Габарит: Ø {w} мм")
        else:
            self.static_size_var.set(f"Габарит: {w} × {h} мм" if w and h else "Габарит: —")
        self._sync_active_static_from_form()

    def _current_product_prefix(self):
        """Префикс кабинета = порядковый номер экрана в списке сохранённых."""
        try:
            sel = self.saved_tree.selection()
            if sel:
                iid = sel[0]
                if str(iid).isdigit():
                    idx = int(iid)
                    if 0 <= idx < len(self.saved_screens):
                        return idx + 1
        except Exception:
            pass
        return len(self.saved_screens) + 1

    # V30.29. Standalone, module-aligned manual cabinet designer.
