def _trial_collect(self):
    rows = []
    for entry in self._cut_map_project_entries():
        key = entry["key"]
        if key not in {m[0] for m in TRIAL_MATERIALS}:
            continue
        title = entry["title"]
        rec = {
            "key": key,
            "title": title,
            "article": str(entry.get("article", "") or ""),
            "cuts": list(entry["cuts"]),
            "display": entry["display"],
            "products": entry["qty_products"],
            "stock": self._trial_get_stock_length(key),
            "bend_radius_mm": entry.get("bend_radius_mm"),
            "cut_details": list(entry.get("cut_details", [])),
        }
        rows.append(rec)
    if not rows:
        self.trial_demo = True
        rows = [{
            "key": "angle30",
            "title": "МЦД статика 2 стороны 2000×800",
            "article": "МЦД19",
            "cuts": [1950]*4 + [750]*4,
            "display": "1950 × 750 мм × (2 изд.)",
            "products": 2,
            "stock": self._trial_get_stock_length("angle30"),
        }]
    else:
        self.trial_demo = False
    return rows


def _trial_refresh(self, keep_stock_value=False):
    material = {m[1]: m[0] for m in TRIAL_MATERIALS}.get(self.trial_material_var.get())
    self.trial_rows_all = self._trial_collect()
    products = list(dict.fromkeys(r["title"] for r in self.trial_rows_all))
    self.trial_product_combo["values"] = ["Все изделия"] + products
    if self.trial_product_var.get() not in self.trial_product_combo["values"]:
        self.trial_product_var.set("Все изделия")
    chosen = self.trial_product_var.get()
    self.trial_rows = [
        r for r in self.trial_rows_all
        if (material is None or r["key"] == material) and (chosen == "Все изделия" or r["title"] == chosen)
    ]
    self.trial_tree.delete(*self.trial_tree.get_children())
    self.trial_row_colors = {}
    self.trial_full_cell_values = {}
    for i, r in enumerate(self.trial_rows, 1):
        n = len(r["cuts"])
        total = sum(r["cuts"])
        iid = f"part{i}"
        self.trial_row_colors[iid] = TRIAL_PALETTE[(i-1) % len(TRIAL_PALETTE)]
        values = (
            i, r["title"], r["article"], next(m[2] for m in TRIAL_MATERIALS if m[0] == r["key"]),
            r["display"], n, r["products"], f"{total} мм", f"{r['stock']} мм"
        )
        self.trial_full_cell_values[iid] = values
        self.trial_tree.insert("", "end", iid=iid, values=values)
    mat = next((m for m in TRIAL_MATERIALS if m[0] == material), None)
    if mat:
        value = self._trial_get_stock_length(mat[0])
        self.trial_stock_var.set(f"{value} мм")
        if not keep_stock_value:
            self.trial_stock_edit_var.set(str(value))
    else:
        self.trial_stock_var.set("По материалам")
        if not keep_stock_value:
            self.trial_stock_edit_var.set("")
    self._trial_sync_stock_controls()
    self._trial_show_sketch(mat)
    self._trial_draw_map()



def _trial_fit_journal_columns(self):
    """Keep journal strings within their current visible column width.

    This is display-only. Full texts remain in trial_full_cell_values and the
    underlying project records are never truncated.
    """
    tree = getattr(self, "trial_tree", None)
    if tree is None or not tree.winfo_exists():
        return
    try:
        from tkinter import font as tkfont
        style = ttk.Style(tree)
        font_name = style.lookup("Treeview", "font") or "TkDefaultFont"
        measure_font = tkfont.nametofont(font_name) if isinstance(font_name, str) else tkfont.Font(font=font_name)
    except Exception:
        from tkinter import font as tkfont
        measure_font = tkfont.nametofont("TkDefaultFont")
    cols = tuple(tree["columns"])
    text_cols = {"product", "article", "material", "dimension"}
    for iid, full in getattr(self, "trial_full_cell_values", {}).items():
        if not tree.exists(iid):
            continue
        displayed = list(full)
        for index, col in enumerate(cols):
            if col not in text_cols:
                continue
            raw = str(full[index])
            available = max(0, int(tree.column(col, "width")) - 14)
            if measure_font.measure(raw) <= available:
                continue
            suffix = "…"
            max_width = max(0, available - measure_font.measure(suffix))
            lo, hi = 0, len(raw)
            while lo < hi:
                mid = (lo + hi + 1) // 2
                if measure_font.measure(raw[:mid]) <= max_width:
                    lo = mid
                else:
                    hi = mid - 1
            displayed[index] = raw[:lo] + suffix if available >= measure_font.measure(suffix) else ""
        if tuple(str(v) for v in tree.item(iid, "values")) != tuple(str(v) for v in displayed):
            tree.item(iid, values=displayed)


