ScreenDesigner._trial_build_cut_tab = _trial_build_cut_tab


def _trial_schedule_redraw(self, delay_ms=80):
    """V30.38: при изменении размера окна карта раскроя перерисовывается один раз
    после паузы, а не на каждое событие <Configure> (раньше — полный пересчёт раскроя на каждый пиксель)."""
    job = getattr(self, "_trial_redraw_job", None)
    if job is not None:
        try:
            self.after_cancel(job)
        except Exception:
            pass

    def _run():
        self._trial_redraw_job = None
        self._trial_draw_map()

    self._trial_redraw_job = self.after(delay_ms, _run)


ScreenDesigner._trial_schedule_redraw = _trial_schedule_redraw
ScreenDesigner._trial_collect = _trial_collect
ScreenDesigner._trial_refresh = _trial_refresh


