def _trial_show_sketch_embedded(self, material):
    c = self.trial_sketch
    c.delete("all")
    self.trial_sketch_image = None
    if material is None:
        c.create_text(127, 110, text="Выберите материал для просмотра эскиза",
                      fill="#64748B", width=220)
        self.trial_image_label.configure(text="Все материалы")
        return
    key, short, name, section, metal, default_stock = material
    stock = self._trial_get_stock_length(key)
    raw = EMBEDDED_CUT_SKETCHES.get(key)
    if raw:
        try:
            from PIL import Image, ImageTk
            image = Image.open(io.BytesIO(base64.b64decode(raw)))
            cw = max(1, int(c.winfo_width()))
            ch = max(1, int(c.winfo_height()))
            target_w = min(245, cw-10) if cw > 20 else 245
            target_h = min(225, ch-10) if ch > 20 else 225
            image.thumbnail((target_w, target_h), Image.Resampling.LANCZOS)
            self.trial_sketch_image = ImageTk.PhotoImage(image)
            c.create_image(cw//2 if cw > 20 else 127,
                           ch//2 if ch > 20 else 112,
                           image=self.trial_sketch_image)
        except Exception:
            c.create_text(127, 112, text="Не удалось открыть эскиз", fill="#64748B")
    else:
        c.create_text(127, 112, text="Эскиз отсутствует", fill="#64748B")
    self.trial_image_label.configure(text=f"{name}\nСечение: {section}\nМатериал: {metal}\nХлыст: {stock} мм")

ScreenDesigner._trial_show_sketch = _trial_show_sketch_embedded










# V30.12 — deletion from product journal; supplier card edit/delete.
def _v3012_delete_journal_product(self):
    sel=self.project_journal_tree.selection()
    if not sel:
        messagebox.showwarning("Журнал изделий", "Выберите изделие для удаления.",parent=self)
        return
    iid=sel[0]
    if iid.startswith("ledinst:"):
        # A child row represents an individual instance; remove its parent product explicitly.
        iid="led:"+iid.split(":")[1]
    try:
        kind,index=iid.split(":",1)
        index=int(index)
    except (ValueError,IndexError):
        return
    if kind=="led":
        source=self.saved_screens
    elif kind=="static":
        source=self.saved_static_signs
    else:
        return
    if index<0 or index>=len(source):
        return
    item=source[index]
    name=str(item.get("name") or item.get("screen_article") or item.get("article") or "Изделие")
    if not messagebox.askyesno("Удаление изделия",
            f"Удалить изделие «{name}» из проекта и всех связанных журналов?\nЭто действие нельзя отменить.",parent=self):
        return
    # Unlink editing state before deleting a saved product.
    if kind=="led":
        self._active_screen_index=None
    else:
        self._active_static_index=None
    del source[index]
    self._mark_project_dirty()
    self._rebuild_saved_screens_tree()
    self._refresh_static_saved_tree()
    self._refresh_project_journal()
    self._refresh_components_screen_selector()
    self._refresh_components_table()
    self._refresh_stock_screen_selector()
    self._refresh_procurement_table()
    try:self._refresh_cut_map()
    except Exception:pass
    try:self._trial_refresh()
    except Exception:pass
    try:self._refresh_project_matrix()
    except Exception:pass
    try:self._update_dynamic_product_buttons()
    except Exception:pass
    try:self._update_static_product_buttons()
    except Exception:pass


def _v3012_supplier_card(self, sid, on_change=None, picker=None):
    catalog=self._supplier_catalog_union()
    record=catalog.get(str(sid))
    if not record:return
    win=tk.Toplevel(self)
    win.title("Карточка поставщика")
    win.resizable(False,False)
    try:win.transient(picker or self);win.grab_set()
    except Exception:pass
    frame=ttk.Frame(win,padding=14);frame.pack(fill="both",expand=True)
    fields=(("Название *","name"),("ИНН","inn"),("Контактное лицо","contact"),
            ("Телефон","phone"),("E-mail","email"),("Примечание","note"))
    values={}
    for row,(title,key) in enumerate(fields):
        ttk.Label(frame,text=title).grid(row=row,column=0,sticky="w",padx=(0,10),pady=5)
        var=tk.StringVar(value=str(record.get(key,"") or ""));values[key]=var
        ttk.Entry(frame,textvariable=var,width=48).grid(row=row,column=1,sticky="ew",pady=5)

    def after_change(deleted=False):
        self._refresh_components_table()
        self._mark_project_dirty()
        if picker is not None:
            # Reopen picker to refresh labels without changing assignments.
            try:picker.destroy()
            except Exception:pass
        if callable(on_change):on_change()

    def save():
        data={key:var.get().strip() for key,var in values.items()}
        if not data["name"]:
            messagebox.showwarning("Поставщик","Укажите название поставщика.",parent=win);return
        try:
            other=self._supplier_db_find_by_name(data["name"])
            if other and str(other.get("id"))!=str(sid):
                raise ValueError("Поставщик с таким названием уже существует.")
            now=datetime.now().isoformat(timespec="seconds")
            with self._supplier_db_connect() as conn:
                exists=conn.execute("SELECT id FROM suppliers WHERE id=?",(sid,)).fetchone()
                if exists:
                    conn.execute("UPDATE suppliers SET name=?,name_key=?,inn=?,contact=?,phone=?,email=?,note=?,updated_at=? WHERE id=?",
                        (data["name"],self._supplier_normalized_name(data["name"]),data["inn"],data["contact"],data["phone"],data["email"],data["note"],now,sid))
                else:
                    conn.execute("INSERT INTO suppliers(id,name,name_key,inn,contact,phone,email,note,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?)",
                        (sid,data["name"],self._supplier_normalized_name(data["name"]),data["inn"],data["contact"],data["phone"],data["email"],data["note"],now,now))
            if sid in self.project_supplier_catalog:
                self.project_supplier_catalog[sid].update(data)
        except Exception as exc:
            messagebox.showerror("Поставщик",f"Не удалось сохранить карточку:\n{exc}",parent=win);return
        win.destroy();after_change()

    def delete():
        if not messagebox.askyesno("Удаление поставщика",
                f"Удалить поставщика «{record.get('name','')}» из общей базы и текущего проекта?\nНазначения поставщика в проекте будут сняты.",parent=win):
            return
        try:
            with self._supplier_db_connect() as conn:
                conn.execute("DELETE FROM component_supplier_stats WHERE supplier_id=?",(sid,))
                conn.execute("DELETE FROM learned_project_assignments WHERE supplier_id=?",(sid,))
                conn.execute("DELETE FROM suppliers WHERE id=?",(sid,))
            self.project_supplier_catalog.pop(sid,None)
            self.project_supplier_assignments={k:v for k,v in self.project_supplier_assignments.items() if v!=sid}
            history=getattr(self,"project_component_supplier_history",{})
            for key,items in list(history.items()):
                history[key]=[x for x in items if x!=sid]
            if getattr(self,"project_last_supplier_id","")==sid:
                self.project_last_supplier_id=""
        except Exception as exc:
            messagebox.showerror("Поставщик",f"Не удалось удалить поставщика:\n{exc}",parent=win);return
        win.destroy();after_change(deleted=True)

    buttons=ttk.Frame(frame);buttons.grid(row=len(fields),column=0,columnspan=2,sticky="ew",pady=(14,0))
    ttk.Button(buttons,text="Удалить поставщика",command=delete).pack(side="left")
    ttk.Button(buttons,text="Отмена",command=win.destroy).pack(side="right")
    ttk.Button(buttons,text="Сохранить",command=save).pack(side="right",padx=(0,8))
    return win

ScreenDesigner._v3012_delete_journal_product=_v3012_delete_journal_product
ScreenDesigner._v3012_supplier_card=_v3012_supplier_card



# V30.14 - presentation-only 3D cut pack enhancements.
def _v3014_ranges(numbers):
    seq=sorted(set(int(n) for n in numbers))
    if not seq:return ''
    chunks=[];start=prev=seq[0]
    for n in seq[1:]:
        if n==prev+1:prev=n
        else:
            chunks.append(f'{start}–{prev}' if start!=prev else str(start))
            start=prev=n
    chunks.append(f'{start}–{prev}' if start!=prev else str(start))
    return ', '.join(chunks)


def _v3014_groups(bins, kerf, grouped=True):
    result=[];index={}
    for i,(material,stock,bar) in enumerate(bins,1):
        left=int(stock)-sum(int(x[0]) for x in bar)-int(kerf)*max(0,len(bar)-1)
        signature=(material[0],int(stock),int(kerf),tuple(int(x[0]) for x in bar),left)
        if not grouped or signature not in index:
            if grouped:index[signature]=len(result)
            result.append({'material':material,'stock':stock,'bar':bar,'numbers':[i], 'left':left})
        else:result[index[signature]]['numbers'].append(i)
    return result




def _pack3d_draw_stack_canvas(self,canvas,x,y,width_px,row_h,depth_x,depth_y,stock,bins,kerf):
    """V30.16: single-pixel continuous row grid; grouped physical bars unchanged."""
    if not bins:return y
    material=next((m for m in TRIAL_MATERIALS if m[5]==stock),('unknown','','','','',stock))
    groups=_v3014_groups([(material,stock,b) for b in bins],kerf,
                         getattr(self,'trial_group_mode_var',None) is None or self.trial_group_mode_var.get()=='С группировкой')
    n=len(groups);x=float(x);y=float(y);right=x+float(width_px)
    heights=[y+i*float(row_h) for i in range(n+1)]
    # Faces first.  One shared front rectangle, no per-segment outlines.
    canvas.create_rectangle(x,heights[0],right,heights[-1],fill='#F5EA00',outline='')
    canvas.create_polygon(x,y,right,y,right+depth_x,y-depth_y,x+depth_x,y-depth_y,
                          fill='#FFF36A',outline='')
    canvas.create_polygon(right,y,right+depth_x,y-depth_y,
                          right+depth_x,heights[-1]-depth_y,right,heights[-1],
                          fill='#D5B100',outline='')
    import tkinter.font as tkfont
    label_font=tkfont.Font(root=self,family='Arial',size=9,weight='bold')
    row_text=[]
    for j,g in enumerate(groups):
        yy=heights[j];row_bottom=heights[j+1];pos=x;unfit=[]
        bar=g['bar']
        for k,(length,iid,title) in enumerate(bar):
            segw=float(length)*width_px/stock;last=pos+segw
            # Hit areas are invisible: no duplicate horizontal outlines.
            rid=canvas.create_rectangle(pos,yy,last,row_bottom,fill='',outline='',tags=('segment',iid))
            self.trial_segment_items.setdefault(iid,[]).append(rid)
            caption=str(length)
            if label_font.measure(caption)+12<=segw:
                row_text.append(( (pos+last)/2,(yy+row_bottom)/2,caption,iid))
            else:unfit.append(caption)
            canvas.tag_bind(rid,'<Button-1>',lambda event,row_id=iid:self._trial_select_segment(row_id))
            pos=last
            if k<len(bar)-1:
                if kerf:
                    advance=float(kerf)*width_px/stock
                    # Draw cut inside the row only, behind the shared grid.
                    canvas.create_rectangle(pos,yy,pos+advance,row_bottom,fill='white',outline='')
                    pos+=advance
                canvas.create_line(pos,yy,pos,row_bottom,fill='black',width=1)
        nums=g['numbers'];leftlabel=(_v3014_ranges(nums)+f' ({len(nums)} шт.)') if len(nums)>1 else str(nums[0])+'.'
        rightlabel=(f"({', '.join(unfit)}) " if unfit else '')+f"— {g['left']} мм"
        row_text.append((x-14,(yy+row_bottom)/2,leftlabel,'_left'))
        row_text.append((right+depth_x+12,(yy+row_bottom)/2,rightlabel,'_right'))
    # Exactly one full-width line per shared boundary, including outer limits.
    for yy in heights:
        canvas.create_line(x,yy,right,yy,fill='black',width=1)
        canvas.create_line(right,yy,right+depth_x,yy-depth_y,fill='black',width=1)
    canvas.create_line(x,heights[0],x,heights[-1],fill='black',width=1)
    canvas.create_line(right,heights[0],right,heights[-1],fill='black',width=1)
    canvas.create_line(right+depth_x,heights[0]-depth_y,right+depth_x,heights[-1]-depth_y,fill='black',width=1)
    canvas.create_line(x+depth_x,y-depth_y,right+depth_x,y-depth_y,fill='black',width=1)
    canvas.create_line(x,y,x+depth_x,y-depth_y,fill='black',width=1)
    for tx,ty,caption,iid in row_text:
        if iid=='_left':canvas.create_text(tx,ty,text=caption,anchor='e',font=('Arial',9),fill='black')
        elif iid=='_right':canvas.create_text(tx,ty,text=caption,anchor='w',font=('Arial',9),fill='black')
        else:canvas.create_text(tx,ty,text=caption,font=label_font,fill='black',tags=(iid,))
    return heights[-1]


_v3014_original_build_cut_tab=ScreenDesigner._trial_build_cut_tab
def _v3014_build_cut_tab(self,parent):
    _v3014_original_build_cut_tab(self,parent)
    self.trial_group_mode_var=tk.StringVar(value='С группировкой')
    mapframe=self.trial_canvas.master
    # Preserve original geometry; insert a bar above canvas and shift it down.
    self.trial_canvas.grid_configure(row=1)
    mapframe.rowconfigure(0,weight=0)
    mapframe.rowconfigure(1,weight=1)
    for child in mapframe.winfo_children():
        if isinstance(child,ttk.Scrollbar):child.grid_configure(row=1)
    modebar=ttk.Frame(mapframe)
    modebar.grid(row=0,column=0,columnspan=2,sticky='w',pady=(0,3))
    ttk.Label(modebar,text='Отображение:').pack(side='left',padx=(0,8))
    for value in ('С группировкой','Без группировки'):
        ttk.Radiobutton(modebar,text=value,variable=self.trial_group_mode_var,value=value,
                        command=self._trial_redraw_presentation).pack(side='left',padx=(0,14))
    self._trial_redraw_presentation()


def _v3014_redraw_presentation(self):
    # The established draw function does run BFD for display. To avoid re-optimising
    # on mode toggle, cache per-material physical bars and reuse them instead.
    if hasattr(self,'_v3014_cached_canvas_rows'):
        self._v3014_paint_cached()
    else:
        self._trial_draw_map()


_v3014_prior_draw=ScreenDesigner._trial_draw_map
def _v3014_draw_map(self):
    _v3014_prior_draw(self)
    # Snapshot is physical bars, never the presentation groups.
    self._v3014_cached_canvas_rows=list(getattr(self,'wizard_bins',[]))
    self._v3014_paint_cached()


def _v3014_paint_cached(self):
    c=self.trial_canvas
    bins=list(getattr(self,'_v3014_cached_canvas_rows',[]))
    if not bins:return
    try:kerf=max(0,int(self.trial_kerf_var.get()))
    except Exception:kerf=3
    c.delete('all');self.trial_segment_items={}
    width=max(900,c.winfo_width()-20)
    x=190;barw=min(980,max(560,width-x-260));y=18
    by_material={}
    for m,stock,b in bins:by_material.setdefault((m[0],stock),[m,stock,[]])[2].append(b)
    total_physical=0
    for m,stock,bars in by_material.values():
        c.create_text(25,y,text=m[2],anchor='nw',font=('Arial',11,'bold'),fill='#172A44')
        c.create_text(375,y,text=f'Хлыст {stock} мм · Пропил {kerf} мм',anchor='nw',font=('Arial',9),fill='#172A44')
        y+=55
        maximum=max(stock-sum(int(z[0]) for z in b)-kerf*max(0,len(b)-1) for b in bars)
        if maximum>0:
            bx=x+150;bw=max(140,maximum*barw/stock)
            c.create_polygon(bx,y,bx+bw,y,bx+bw+23,y-13,bx+23,y-13,fill='#FFF36A',outline='black')
            c.create_polygon(bx+bw,y,bx+bw+23,y-13,bx+bw+23,y+11,bx+bw,y+24,fill='#D5B100',outline='black')
            c.create_rectangle(bx,y,bx+bw,y+24,fill='#F5EA00',outline='black')
            c.create_text(bx+bw/2,y+12,text=str(maximum),font=('Arial',9,'bold'))
            c.create_text(bx+bw+43,y+11,text='Максимальный остаток',anchor='w',font=('Arial',9))
            y+=65
        y=_pack3d_draw_stack_canvas(self,c,x,y,barw,25,28,17,stock,bars,kerf)+38
        total_physical+=len(bars)
    c.create_text(25,y,text=f'Требуется (хлыстов) заготовок: {total_physical} шт.',anchor='nw',font=('Arial',12))
    c.configure(bg='#A9C9EE',scrollregion=(0,0,max(1400,x+barw+720),max(c.winfo_height(),y+45)))
    self._trial_highlight()


# PDF renderer is self-contained and never changes GUI grouping state.
def _v3014_print_pdf(self):
    try:
        from PIL import Image,ImageDraw,ImageFont
    except ImportError:
        messagebox.showerror('Печать','Требуется Pillow');return
    bins=list(getattr(self,'wizard_bins',[]))
    if not bins:
        messagebox.showwarning('Раскрой','Нет деталей');return
    try:kerf=max(0,int(self.trial_kerf_var.get()))
    except Exception:kerf=3
    groups=_v3014_groups(bins,kerf,True)
    fontpath=next((v for v in ('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf',
                       'C:/Windows/Fonts/arial.ttf','/System/Library/Fonts/Supplemental/Arial.ttf') if Path(v).exists()),None)
    def font(size):return ImageFont.truetype(fontpath,size) if fontpath else ImageFont.load_default()
    pages=[]
    for materialkey in dict.fromkeys(g['material'][0] for g in groups):
        materialgroups=[g for g in groups if g['material'][0]==materialkey]
        for pstart in range(0,len(materialgroups),22):
            chunk=materialgroups[pstart:pstart+22]
            W=2100;M=65;right=720;barx=290;barw=W-barx-right
            rowh=48;headerh=370
            H=max(1220,headerh+rowh*len(chunk)*3+260)
            im=Image.new('RGB',(W,H),'#E2EEFF');d=ImageDraw.Draw(im)
            m=chunk[0]['material'];stock=chunk[0]['stock']
            d.text((M,38),'КАРТА РАСКРОЯ',font=font(37),fill='#183047')
            d.text((M,102),m[2],font=font(26),fill='#183047')
            d.text((M,150),f'Стандартный хлыст: {stock} мм    Пропил: {kerf} мм',font=font(23),fill='#183047')
            # Right-top embedded sketch; same source as interactive sketch.
            try:
                blob=EMBEDDED_CUT_SKETCHES.get(materialkey)
                if blob:
                    picture=Image.open(io.BytesIO(base64.b64decode(blob))).convert('RGB')
                    picture.thumbnail((380,285),Image.Resampling.LANCZOS)
                    im.paste(picture,(W-440+(380-picture.width)//2,38+(285-picture.height)//2))
            except Exception:pass
            # Compact grouped matrix by segment size.
            lengths=sorted(set(a[0] for g in chunk for a in g['bar']),reverse=True)
            mat_x=M;mat_y=215;cellw=95;cellh=25
            d.text((mat_x,mat_y-27),'Деталь, мм',font=font(16),fill='#183047')
            for j,g in enumerate(chunk[:12]):
                px=mat_x+170+j*cellw
                d.rectangle((px,mat_y,px+cellw,mat_y+cellh),fill='#C1D8F4',outline='#617895')
                d.text((px+4,mat_y+3),str(g['numbers'][0]),font=font(14),fill='black')
            for i,length in enumerate(lengths[:4]):
                yy=mat_y+(i+1)*cellh
                d.text((mat_x+4,yy+3),str(length),font=font(15),fill='#183047')
                for j,g in enumerate(chunk[:12]):
                    xx=mat_x+170+j*cellw
                    d.rectangle((xx,yy,xx+cellw,yy+cellh),fill='#DEEAFA',outline='#8597AD')
                    count=sum(z[0]==length for z in g['bar'])
                    if count:d.text((xx+40,yy+3),str(count),font=font(14),fill='black')
            starty=headerh
            d.text((M,starty-38),'№ хлыстов',font=font(18),fill='#172A44')
            d.text((barx,starty-38),'3D-пачка — идентичные схемы объединены',font=font(18),fill='#172A44')
            yy=starty
            pdf_bar_geometries=[]
            for index,g in enumerate(chunk):
                stock=g['stock'];bar=g['bar'];r=g['left']
                dx=25;dy=14
                row_top=yy
                d.rectangle((barx,yy,barx+barw,yy+rowh),fill='#F5EA00')
                d.polygon([(barx+barw,yy),(barx+barw+dx,yy-dy),(barx+barw+dx,yy+rowh-dy),(barx+barw,yy+rowh)],fill='#D5B100')
                if index==0:
                    d.polygon([(barx,yy),(barx+barw,yy),(barx+barw+dx,yy-dy),(barx+dx,yy-dy)],fill='#FFF36A')
                pos=float(barx);out=[]
                ff=font(18)
                for j,(length,iid,title) in enumerate(bar):
                    sw=float(length)*barw/stock
                    # No segment perimeter: only interior vertical separators.
                    if j:d.line([(round(pos),yy),(round(pos),yy+rowh)],fill='black',width=1)
                    name=str(length);box=d.textbbox((0,0),name,font=ff)
                    if box[2]-box[0]+18<=sw:
                        d.text((pos+(sw-(box[2]-box[0]))/2,yy+12),name,font=ff,fill='black')
                    else:out.append(name)
                    pos+=sw
                    if j<len(bar)-1:pos+=kerf*barw/stock
                # Keep geometry; draw the outlines only AFTER all yellow fills.
                pdf_bar_geometries.append((row_top, row_top+rowh, dx, dy))
                if False:
                    d.line([(barx,yy),(barx+barw,yy)],fill='black',width=1)
                    d.line([(barx+barw,yy),(barx+barw+dx,yy-dy)],fill='black',width=1)
                # Deferred separator: the next row's fill must not cover it.




                nums=g['numbers']
                label=_v3014_ranges(nums)+(f' ({len(nums)} шт.)' if len(nums)>1 else '')
                d.text((M,yy+11),label,font=font(18),fill='black')
                side=(f"({', '.join(out)}) " if out else '')+f'— {r} мм'
                # Wrapped on a second line when long, no missing dimensions.
                sx=barx+barw+dx+15
                maxpixels=W-sx-M
                next_y=yy+rowh
                if d.textbbox((0,0),side,font=font(18))[2]>maxpixels:
                    import textwrap
                    a=f"({', '.join(out)})" if out else ''
                    parts=[];current=''
                    for value in out:
                        token=value if not current else ', '+value
                        if d.textbbox((0,0),'('+current+token+')',font=font(18))[2]>maxpixels and current:
                            parts.append('('+current+')');current=value
                        else:current+=token
                    if current:parts.append('('+current+')')
                    parts.append(f'— {r} мм')
                    for k,part in enumerate(parts):d.text((sx,yy+3+20*k),part,font=font(17),fill='black')
                    next_y=max(next_y,yy+8+20*len(parts))
                else:d.text((sx,yy+12),side,font=font(18),fill='black')
                yy=next_y
            # Draw each horizontal boundary once, after all rows have been painted.
            # Also connect it to the right 3D end face.
            seen_edges=set()
            for top,bottom,dx,dy in pdf_bar_geometries:
                for edge in (top,bottom):
                    if edge not in seen_edges:
                        d.line([(barx,edge),(barx+barw,edge)],fill='black',width=2)
                        d.line([(barx+barw,edge),(barx+barw+dx,edge-dy)],fill='black',width=2)
                        seen_edges.add(edge)
            for top,bottom,dx,dy in pdf_bar_geometries:
                d.line([(barx,top),(barx,bottom)],fill='black',width=2)
                d.line([(barx+barw,top),(barx+barw,bottom)],fill='black',width=2)
                d.line([(barx+barw+dx,top-dy),(barx+barw+dx,bottom-dy)],fill='black',width=2)
            count=sum(len(g['numbers']) for g in materialgroups)
            useful=sum(sum(z[0] for z in g['bar'])*len(g['numbers']) for g in materialgroups)
            purchase=count*stock
            prop=sum(kerf*max(0,len(g['bar'])-1)*len(g['numbers']) for g in materialgroups)
            yy=yy+32
            d.text((M,yy),f'Закупка: {count} шт. × {stock} мм = {purchase} мм',font=font(21),fill='#172A44')
            d.text((M,yy+36),f'Полезная длина: {useful} мм  ·  Пропил: {prop} мм  ·  Остаток: {purchase-useful-prop} мм  ·  Использование: {useful/purchase*100:.1f}%',font=font(19),fill='#172A44')
            pages.append(im)
    self._v3020_preview_pdf_pages(pages)


# V30.20: preview the exact Pillow pages produced by the existing PDF renderer.
# PDF is written only after explicit confirmation in the preview window.
def _v3020_preview_pdf_pages(self, pages):
    from PIL import Image, ImageTk
    if not pages:
        messagebox.showwarning('Предпросмотр раскроя', 'Нет страниц для просмотра.')
        return
    win=tk.Toplevel(self)
    win.title('Предпросмотр раскроя — перед сохранением PDF')
    win.geometry('1120x780')
    win.minsize(550,400)
    win.transient(self)
    state={'page':0,'zoom':None,'photo':None}

    toolbar=ttk.Frame(win,padding=(9,7))
    toolbar.pack(side='top',fill='x')
    viewport=ttk.Frame(win)
    viewport.pack(fill='both',expand=True)
    viewport.columnconfigure(0,weight=1)
    viewport.rowconfigure(0,weight=1)
    canvas=tk.Canvas(viewport,bg='#777777',highlightthickness=0)
    canvas.grid(row=0,column=0,sticky='nsew')
    vbar=ttk.Scrollbar(viewport,orient='vertical',command=canvas.yview)
    hbar=ttk.Scrollbar(viewport,orient='horizontal',command=canvas.xview)
    vbar.grid(row=0,column=1,sticky='ns')
    hbar.grid(row=1,column=0,sticky='ew')
    canvas.configure(xscrollcommand=hbar.set,yscrollcommand=vbar.set)
    info=tk.StringVar()

    def draw():
        source=pages[state['page']]
        zoom=state['zoom'] or 1
        w=max(1,round(source.width*zoom))
        h=max(1,round(source.height*zoom))
        # Protect Tk against accidentally allocating extremely large photos.
        if w*h>35000000:
            zoom=(35000000/(source.width*source.height))**0.5
            state['zoom']=zoom
            w=max(1,round(source.width*zoom));h=max(1,round(source.height*zoom))
        method=Image.Resampling.LANCZOS if zoom<1 else Image.Resampling.BICUBIC
        resized=source.resize((w,h),method)
        photo=ImageTk.PhotoImage(resized)
        state['photo']=photo
        canvas.delete('all')
        canvas.create_image(12,12,image=photo,anchor='nw')
        canvas.configure(scrollregion=(0,0,w+24,h+24))
        info.set(f"Страница {state['page']+1} из {len(pages)}    Масштаб: {zoom*100:.0f}%")

    def fit():
        source=pages[state['page']]
        cw=max(450,canvas.winfo_width()-36)
        ch=max(280,canvas.winfo_height()-36)
        state['zoom']=min(cw/source.width,ch/source.height,2.0)
        draw()

    def change_zoom(multiplier):
        if state['zoom'] is None:fit()
        old=state['zoom']
        state['zoom']=max(.1,min(4.0,old*multiplier))
        draw()

    def change_page(delta):
        next_page=max(0,min(len(pages)-1,state['page']+delta))
        if next_page!=state['page']:
            state['page']=next_page
            draw()
            canvas.xview_moveto(0);canvas.yview_moveto(0)

    def save_pdf():
        path=filedialog.asksaveasfilename(parent=win,title='Сохранить раскрой в PDF',
              defaultextension='.pdf',initialfile='Раскрой_V30_20.pdf',
              filetypes=[('PDF','*.pdf')])
        if not path:return
        try:
            pages[0].save(path,format='PDF',resolution=150,
                          save_all=True,append_images=pages[1:])
        except Exception as exc:
            messagebox.showerror('Сохранение PDF',str(exc),parent=win)
            return
        win.destroy()
        messagebox.showinfo('Печать раскроя',f'PDF сохранён:\n{path}',parent=self)

    ttk.Button(toolbar,text='◀',width=4,command=lambda:change_page(-1)).pack(side='left')
    ttk.Button(toolbar,text='▶',width=4,command=lambda:change_page(1)).pack(side='left',padx=(3,14))
    ttk.Button(toolbar,text='−',width=4,command=lambda:change_zoom(1/1.2)).pack(side='left')
    ttk.Button(toolbar,text='+',width=4,command=lambda:change_zoom(1.2)).pack(side='left',padx=3)
    ttk.Button(toolbar,text='По размеру окна',command=fit).pack(side='left',padx=(7,12))
    ttk.Label(toolbar,textvariable=info).pack(side='left',padx=6)
    def print_pdf():
        """Submit exactly the PDF shown in preview to the OS default printer."""
        if not messagebox.askyesno(
            'Печать раскроя',
            f'Отправить все {len(pages)} стр. раскроя на принтер по умолчанию?',
            parent=win,
        ):
            return
        import atexit
        import tempfile
        import shutil
        fd, path = tempfile.mkstemp(prefix='led_cut_print_', suffix='.pdf')
        os.close(fd)
        try:
            pages[0].save(path, format='PDF', resolution=150,
                          save_all=True, append_images=pages[1:])
            # Keep the temporary file until the application exits: some PDF
            # viewers spool asynchronously, particularly on Windows.
            atexit.register(lambda p=path: os.path.exists(p) and os.remove(p))
            if sys.platform == 'darwin':
                command = shutil.which('lp') or '/usr/bin/lp'
                result = subprocess.run([command, path], capture_output=True,
                                        text=True, timeout=45)
                if result.returncode != 0:
                    raise RuntimeError(result.stderr.strip() or result.stdout.strip()
                                       or 'Очередь печати отклонила документ.')
            elif sys.platform.startswith('win'):
                os.startfile(path, 'print')
            else:
                command = shutil.which('lp') or shutil.which('lpr')
                if not command:
                    raise RuntimeError('Не найдена системная команда lp или lpr.')
                result = subprocess.run([command, path], capture_output=True,
                                        text=True, timeout=45)
                if result.returncode != 0:
                    raise RuntimeError(result.stderr.strip() or 'Ошибка системной печати.')
        except Exception as exc:
            messagebox.showerror('Печать раскроя',
                                 f'Не удалось отправить документ на печать:\n{exc}',
                                 parent=win)
            return
        messagebox.showinfo('Печать раскроя',
                            'PDF передан в системную очередь печати.\n'
                            'Проверьте состояние задания в очереди принтера.',
                            parent=win)

    ttk.Button(toolbar,text='Отмена',command=win.destroy).pack(side='right',padx=(8,0))
    ttk.Button(toolbar,text='Сохранить PDF',command=save_pdf).pack(side='right')
    ttk.Button(toolbar,text='Печать',command=print_pdf).pack(side='right',padx=(0,8))

    # Windows: Ctrl+wheel zoom; macOS: Command+wheel zoom; regular wheel scrolls.
    # Tk on Linux also emits Button-4/5 for wheel scroll.
    def wheel(event):
        delta=getattr(event,'delta',0)
        if not delta:return
        modifier=(event.state & 0x0004) or (event.state & 0x0008)
        if modifier:
            change_zoom(1.15 if delta>0 else 1/1.15)
        elif event.state & 0x0001:
            canvas.xview_scroll(-1 if delta>0 else 1,'units')
        else:
            canvas.yview_scroll(-1 if delta>0 else 1,'units')
        return 'break'
    canvas.bind('<MouseWheel>',wheel)
    canvas.bind('<Button-4>',lambda e:(canvas.yview_scroll(-3,'units'),'break')[1])
    canvas.bind('<Button-5>',lambda e:(canvas.yview_scroll(3,'units'),'break')[1])
    for key in ('<Control-plus>','<Control-equal>','<Command-plus>','<Command-equal>'):
        win.bind(key,lambda e:(change_zoom(1.2),'break')[1])
    for key in ('<Control-minus>','<Command-minus>'):
        win.bind(key,lambda e:(change_zoom(1/1.2),'break')[1])
    win.bind('<Escape>',lambda e:win.destroy())
    win.bind('<Prior>',lambda e:change_page(-1))
    win.bind('<Next>',lambda e:change_page(1))
    win.after(100,fit)

ScreenDesigner._v3020_preview_pdf_pages=_v3020_preview_pdf_pages

ScreenDesigner._trial_build_cut_tab=_v3014_build_cut_tab
ScreenDesigner._trial_draw_map=_v3014_draw_map
ScreenDesigner._trial_redraw_presentation=_v3014_redraw_presentation
ScreenDesigner._v3014_paint_cached=_v3014_paint_cached
ScreenDesigner._wizard_print_pdf=_v3014_print_pdf


# =====================================================================
# V30.40 — Автоматическое распределение калькуляции по изделиям.
# Движок: позиция счёта -> норма BOM изделия -> раскладка по колонкам,
# ИТОГО и Остаток. Назначения («закупочное имя -> норма BOM» или
# «накладные») запоминаются в metadata проекта (calc_item_assignments)
# и засеваются из PROCUREMENT_TO_BOM. Логика по выбору пользователя:
# раскладка по технической норме изделия, норма заполняется один раз
# (повторные строки той же позиции целиком уходят в Остаток), позиции
# без нормы в изделиях — накладные (по изделиям не распределяются).
# =====================================================================

def _calc_to_number(value):
    """Безопасный разбор количества из счёта ('1 200,50' -> 1200.5)."""
    try:
        s=str(value or "").replace("\xa0"," ").replace(" ","").replace(",",".")
        s=re.sub(r"[^0-9.\-]","",s)
        return float(s) if s not in ("","-",".") else None
    except Exception:
        return None


def _calc_norm_item_name(self, name):
    """Нормализация закупочного наименования для ключа назначения."""
    s=str(name or "").lower().replace("ё","е")
    s=s.replace("×","x").replace("х","x").replace("*","x")
    s=re.sub(r"\s+"," ",s).strip()
    return s


def _calc_assignments(self):
    """Словарь назначений проекта: norm(имя из счёта) -> {'mode','bom'}."""
    if not isinstance(getattr(self,"project_metadata",None),dict):
        self.project_metadata={}
    a=self.project_metadata.get("calc_item_assignments")
    if not isinstance(a,dict):
        a={}
        self.project_metadata["calc_item_assignments"]=a
    return a


def _calc_assignment_for_item(self, item):
    """Возвращает ('bom', имя_нормы) | ('overhead', None) | ('unassigned', None).

    Приоритет: сохранённое назначение пользователя > встроенный словарь
    PROCUREMENT_TO_BOM > не назначено.
    """
    key=self._calc_norm_item_name(item)
    stored=self._calc_assignments().get(key)
    if isinstance(stored,dict):
        mode=stored.get("mode")
        if mode=="overhead":
            return "overhead",None
        if mode=="bom" and stored.get("bom"):
            return "bom",str(stored.get("bom"))
    seeded=self._bom_name_for_procurement_item(str(item or ""))
    if seeded:
        return "bom",str(seeded)
    return "unassigned",None


def _calc_target_matches_demand(self, target, demand_name):
    """Сопоставление имени назначения с именем позиции расчётной нормы.

    Отдельно обрабатывается «Модули»: у РЖД-экранов норма перечисляет
    конкретное имя модуля (LED-модуль P…), а словарь закупок указывает «Модули».
    """
    if not target:
        return False
    if target==demand_name:
        return True
    dn=str(demand_name or "")
    if target=="Модули" and dn.lower().startswith("led-модуль"):
        return True
    return False


def _calc_demand_for_record(self, kind, rec):
    """Норма BOM одного изделия-записи (с учётом его количества/сторон).

    Повторяет диспетчинг вкладки «Комплектующие», чтобы имена и количества
    совпадали с тем, что видит пользователь.
    """
    out={}
    def add(name,qty):
        name=str(name).strip()
        try:qty=float(qty or 0)
        except Exception:qty=0.0
        if name and qty:
            out[name]=out.get(name,0.0)+qty
    try:
        if kind=="static":
            fn=(self._static_mcd_component_rows if rec.get("mode",MODE_MCD)==MODE_MCD
                else self._static_rzd_component_rows)
            for n,u,q in fn([dict(rec)]):
                add(n,q)
            return out
        # dynamic
        if rec.get("mode")==MODE_MCD:
            for n,u,q in self._dynamic_mcd_component_rows_v1972([dict(rec)]):
                add(n,q)
            return out
        if rec.get("pro_screen"):
            computed,_unknown=self._pro_bom_one(rec)
            factor=self._screen_factor(rec)
            for n,v in computed.items():
                add(n,float(v or 0)*factor)
            add("Наконечник 0,75 мм²",4*max(1,int(rec.get("quantity",1) or 1)))
            return out
        # РЖД кабинетный
        factor=self._screen_factor(rec)
        counts=rec.get("counts",{}) or {}
        module_name=self._selected_led_module_name(rec) or (
            f"LED-модуль {rec.get('pixel_pitch','')} {rec.get('led_type','OD')}")
        for size in ((960,960),(960,640),(640,960),(640,640)):
            cnt=counts.get(size,0)
            if cnt:
                add(module_name,COMPONENT_RATES.get(size,{}).get("Модули",0)*cnt*factor)
        for name in COMPONENT_ORDER:
            if name=="Модули":
                continue
            tot=sum(COMPONENT_RATES.get(size,{}).get(name,0)*counts.get(size,0)
                    for size in ((960,960),(960,640),(640,960),(640,640)))*factor
            if name=="Наконечник 0,75 мм²":
                tot+=4*max(1,int(rec.get("quantity",1) or 1))
            add(name,tot)
    except Exception:
        pass
    return out


def _calc_column_demand(self, column_key):
    """Суммарная норма для колонки калькуляции (ключ вида 'dynamic:0+static:1')."""
    demand={}
    for part in str(column_key or "").split("+"):
        part=part.strip()
        if not part or ":" not in part:
            continue
        kind,_,idx=part.partition(":")
        try:
            idx=int(idx)
        except Exception:
            continue
        if kind=="dynamic":
            seq=getattr(self,"saved_screens",[]) or []
            if 0<=idx<len(seq):
                sub=self._calc_demand_for_record("dynamic",seq[idx])
        elif kind=="static":
            seq=getattr(self,"saved_static_signs",[]) or []
            if 0<=idx<len(seq):
                sub=self._calc_demand_for_record("static",seq[idx])
            else:
                sub={}
        else:
            sub={}
        for n,v in (sub or {}).items():
            demand[n]=demand.get(n,0.0)+v
    return demand


def _calc_allocation_rows(self):
    """Расчёт содержимого матрицы калькуляции.

    Возвращает (products, entries): products — список (key, name, qty),
    entries — выровнен по self.invoice_rows; каждый элемент:
      {'status','target','cells'(список по products),'itogo','ostatok'}.
    status: 'bom' (норма разложена), 'bom_dup' (повтор позиции — всё в Остаток),
    'bom_nodemand' (позиция есть в словаре, но нормы в изделиях нет),
    'overhead' (накладные), 'unassigned' (не назначено).
    """
    products=self._project_matrix_products()
    rows=list(getattr(self,"invoice_rows",[]) or [])
    if not CALC_ITEM_ASSIGNMENT_ENABLED:
        # V30.50: распределение отключено — все ячейки распределения пустые.
        return products,[None]*len(rows)
    demand_by_col=[self._calc_column_demand(key) for key,_name,_qty in products]
    filled=set()
    entries=[]
    for row in rows:
        item=str(getattr(row,"item","") or "")
        bought=_calc_to_number(getattr(row,"qty",""))
        mode,target=self._calc_assignment_for_item(item)
        entry={"status":mode,"target":target,"cells":[None]*len(products),
               "itogo":None,"ostatok":None}
        if mode=="bom" and target:
            cells=[sum(v for nm,v in demand_by_col[j].items()
                       if self._calc_target_matches_demand(target,nm))
                   for j in range(len(products))]
            tot=sum(cells)
            if tot<=0:
                entry["status"]="bom_nodemand"
            elif target in filled:
                entry["status"]="bom_dup"
                entry["ostatok"]=bought
            else:
                filled.add(target)
                entry["cells"]=cells
                entry["itogo"]=tot
                entry["ostatok"]=(bought-tot) if bought is not None else None
        entries.append(entry)
    return products,entries


ScreenDesigner._calc_norm_item_name=_calc_norm_item_name
ScreenDesigner._calc_assignments=_calc_assignments
ScreenDesigner._calc_assignment_for_item=_calc_assignment_for_item
ScreenDesigner._calc_target_matches_demand=_calc_target_matches_demand
ScreenDesigner._calc_demand_for_record=_calc_demand_for_record
ScreenDesigner._calc_column_demand=_calc_column_demand
ScreenDesigner._calc_allocation_rows=_calc_allocation_rows



# =====================================================================
# V30.41 — Диалог «Назначить позиции» для калькуляции.
# Пользователь один раз сопоставляет закупочное имя из счёта с нормой BOM
# изделия (из подсказок-кандидатов) либо помечает его «накладные».
# Решения запоминаются в metadata проекта (calc_item_assignments) и
# переживают сохранение/открытие .ledproj.
# =====================================================================

def _calc_all_demand_names(self):
    """Отсортированный список всех имён BOM-нормы по колонкам проекта."""
    names=set()
    for key,_name,_qty in self._project_matrix_products():
        names.update(self._calc_column_demand(key).keys())
    return sorted(names, key=lambda s: s.lower())


def _calc_unique_invoice_items(self):
    """Уникальные наименования из счетов в порядке появления: [(текст, norm_key, кол-во строк)]."""
    order=[]; index={}
    for row in (getattr(self,"invoice_rows",[]) or []):
        item=str(getattr(row,"item","") or "").strip()
        if not item:
            continue
        key=self._calc_norm_item_name(item)
        if key in index:
            order[index[key]][2]+=1
        else:
            index[key]=len(order); order.append([item,key,1])
    return [tuple(x) for x in order]


def _calc_suggest_bom(self, item, names, k=6):
    """Ранжированные кандидаты имён нормы для закупочного наименования."""
    from difflib import SequenceMatcher
    ni=self._calc_norm_item_name(item)
    ti=set(t for t in re.split(r"[\s,]+",ni) if len(t)>=2)
    scored=[]
    for bn in names:
        nb=self._calc_norm_item_name(bn)
        tb=set(t for t in re.split(r"[\s,]+",nb) if len(t)>=2)
        seq=SequenceMatcher(None,ni,nb).ratio()
        jac=(len(ti&tb)/len(ti|tb)) if (ti|tb) else 0.0
        scored.append((0.45*seq+0.55*jac,bn))
    scored.sort(reverse=True)
    return [bn for _s,bn in scored[:k]]


def _calc_item_status_text(self, item):
    """Человекочитаемый текущий статус назначения для позиции."""
    mode,target=self._calc_assignment_for_item(item)
    key=self._calc_norm_item_name(item)
    stored=self._calc_assignments().get(key)
    if isinstance(stored,dict) and stored.get("mode")=="overhead":
        return "накладные"
    if isinstance(stored,dict) and stored.get("mode")=="bom":
        return f"норма: {target}"
    if mode=="bom":
        return f"авто: {target}"
    return "— не назначено"


def _calc_set_assignment(self, norm_key, mode, bom=None):
    """Записывает/удаляет назначение в памяти проекта."""
    a=self._calc_assignments()
    if mode=="clear":
        a.pop(norm_key,None)
    elif mode=="overhead":
        a[norm_key]={"mode":"overhead"}
    elif mode=="bom" and bom:
        a[norm_key]={"mode":"bom","bom":str(bom)}
    try:
        self._mark_project_dirty()
    except Exception:
        pass


def _open_calc_assignment_dialog(self):
    if not CALC_ITEM_ASSIGNMENT_ENABLED:
        messagebox.showinfo("Калькуляция","Назначение позиций по изделиям временно отключено.")
        return
    items=self._calc_unique_invoice_items()
    if not items:
        messagebox.showinfo("Назначение позиций",
            "Нет распознанных позиций счетов. Добавьте документы во вкладке «Счета».")
        return
    all_names=self._calc_all_demand_names()
    if not all_names:
        messagebox.showinfo("Назначение позиций",
            "В проекте нет изделий с рассчитанной нормой. Добавьте изделия.")
        return

    win=tk.Toplevel(self); win.title("Назначение позиций калькуляции")
    win.transient(self); win.grab_set(); win.geometry("1040x560"); win.minsize(900,460)

    root=ttk.Frame(win,padding=10); root.pack(fill="both",expand=True)
    root.columnconfigure(0,weight=3); root.columnconfigure(1,weight=2); root.rowconfigure(0,weight=1)

    # --- слева: таблица позиций счетов ---
    left=ttk.Frame(root); left.grid(row=0,column=0,sticky="nsew",padx=(0,10))
    left.rowconfigure(1,weight=1); left.columnconfigure(0,weight=1)
    ttk.Label(left,text="Позиции из счетов",font=("Arial",11,"bold")).grid(row=0,column=0,sticky="w",pady=(0,4))
    cols=("item","status","lines")
    tree=ttk.Treeview(left,columns=cols,show="headings",selectmode="browse")
    tree.heading("item",text="Наименование из счёта  ⇅",command=lambda:sort_by("item"))
    tree.heading("status",text="Назначение  ⇅",command=lambda:sort_by("status"))
    tree.heading("lines",text="Строк  ⇅",command=lambda:sort_by("lines"))
    tree.column("item",width=360,anchor="w")
    tree.column("status",width=190,anchor="w")
    tree.column("lines",width=55,anchor="center",stretch=False)
    tree.grid(row=1,column=0,sticky="nsew")
    sb=ttk.Scrollbar(left,orient="vertical",command=tree.yview); sb.grid(row=1,column=1,sticky="ns")
    tree.configure(yscrollcommand=sb.set)

    key_by_iid={}
    sort_state={"col":None,"desc":False}
    def status_tag(text):
        if text.startswith("норма"): return ("assigned",)
        if text=="накладные": return ("overhead",)
        if text.startswith("авто"): return ("seed",)
        return ("none",)
    tree.tag_configure("assigned",foreground="#1F7A1F")
    tree.tag_configure("overhead",foreground="#7030A0")
    tree.tag_configure("seed",foreground="#555555")
    tree.tag_configure("none",foreground="#B00000")

    def reload_tree(select_key=None):
        tree.delete(*tree.get_children(""))
        key_by_iid.clear()
        rows=[(t,k,n,self._calc_item_status_text(t)) for t,k,n in items]
        col=sort_state["col"]
        if col=="item":
            rows.sort(key=lambda r:r[0].lower(),reverse=sort_state["desc"])
        elif col=="status":
            rows.sort(key=lambda r:r[3].lower(),reverse=sort_state["desc"])
        elif col=="lines":
            rows.sort(key=lambda r:r[2],reverse=sort_state["desc"])
        sel_iid=None
        for t,k,n,st in rows:
            iid=tree.insert("","end",values=(t,st,n),tags=status_tag(st))
            key_by_iid[iid]=(t,k)
            if select_key is not None and k==select_key:
                sel_iid=iid
        if sel_iid:
            tree.selection_set(sel_iid); tree.see(sel_iid)

    def sort_by(col):
        if sort_state["col"]==col:
            sort_state["desc"]=not sort_state["desc"]
        else:
            sort_state["col"]=col; sort_state["desc"]=False
        cur=tree.selection()
        selkey=key_by_iid.get(cur[0],(None,None))[1] if cur else None
        reload_tree(select_key=selkey)

    # --- справа: панель назначения ---
    right=ttk.Frame(root); right.grid(row=0,column=1,sticky="nsew")
    right.columnconfigure(0,weight=1); right.rowconfigure(3,weight=1)
    sel_label=ttk.Label(right,text="Выберите позицию слева",font=("Arial",10,"bold"),wraplength=360,justify="left")
    sel_label.grid(row=0,column=0,sticky="ew",pady=(22,6))

    search_row=ttk.Frame(right); search_row.grid(row=1,column=0,sticky="ew")
    ttk.Label(search_row,text="Поиск нормы:").pack(side="left")
    search_var=tk.StringVar()
    search_entry=ttk.Entry(search_row,textvariable=search_var); search_entry.pack(side="left",fill="x",expand=True,padx=(6,0))

    ttk.Label(right,text="Подходящая норма BOM (подсказки сверху):").grid(row=2,column=0,sticky="w",pady=(8,2))
    lb_frame=ttk.Frame(right); lb_frame.grid(row=3,column=0,sticky="nsew")
    lb_frame.rowconfigure(0,weight=1); lb_frame.columnconfigure(0,weight=1)
    lb=tk.Listbox(lb_frame,activestyle="dotbox"); lb.grid(row=0,column=0,sticky="nsew")
    lbsb=ttk.Scrollbar(lb_frame,orient="vertical",command=lb.yview); lbsb.grid(row=0,column=1,sticky="ns")
    lb.configure(yscrollcommand=lbsb.set)

    current={"text":None,"key":None}

    def fill_listbox():
        lb.delete(0,"end")
        q=self._calc_norm_item_name(search_var.get())
        if current["text"] is None:
            return
        suggestions=self._calc_suggest_bom(current["text"],all_names,6)
        rest=[n for n in all_names if n not in suggestions]
        shown=[]
        for n in suggestions:
            if not q or q in self._calc_norm_item_name(n): shown.append(n)
        for n in rest:
            if not q or q in self._calc_norm_item_name(n): shown.append(n)
        for n in shown:
            lb.insert("end",n)

    def on_select(_e=None):
        sel=tree.selection()
        if not sel:
            return
        text,key=key_by_iid.get(sel[0],(None,None))
        current["text"],current["key"]=text,key
        sel_label.configure(text=f"Позиция: {text}")
        search_var.set("")
        fill_listbox()
        # предвыбрать уже назначенную норму, если есть
        stored=self._calc_assignments().get(key)
        if isinstance(stored,dict) and stored.get("mode")=="bom":
            tgt=stored.get("bom")
            for i in range(lb.size()):
                if lb.get(i)==tgt:
                    lb.selection_clear(0,"end"); lb.selection_set(i); lb.see(i); break

    tree.bind("<<TreeviewSelect>>",on_select)
    search_var.trace_add("write",lambda *_:fill_listbox())

    def assign_bom():
        if current["key"] is None:
            return
        if not lb.curselection():
            messagebox.showinfo("Назначение","Выберите норму BOM в списке."); return
        name=lb.get(lb.curselection()[0])
        self._calc_set_assignment(current["key"],"bom",name)
        reload_tree(select_key=current["key"])

    def assign_overhead():
        if current["key"] is None: return
        self._calc_set_assignment(current["key"],"overhead")
        reload_tree(select_key=current["key"])

    def assign_clear():
        if current["key"] is None: return
        self._calc_set_assignment(current["key"],"clear")
        reload_tree(select_key=current["key"])

    btns=ttk.Frame(right); btns.grid(row=4,column=0,sticky="ew",pady=(8,0))
    ttk.Button(btns,text="Назначить норму BOM",command=assign_bom).pack(side="left")
    ttk.Button(btns,text="Накладные",command=assign_overhead).pack(side="left",padx=(6,0))
    ttk.Button(btns,text="Очистить",command=assign_clear).pack(side="left",padx=(6,0))

    # --- низ: закрытие ---
    bottom=ttk.Frame(root); bottom.grid(row=1,column=0,columnspan=2,sticky="ew",pady=(10,0))
    hint=ttk.Label(bottom,foreground="#666666",
        text="Двойной клик по норме = назначить. Решения сохраняются в проекте; матрица обновится при закрытии.")
    hint.pack(side="left")
    def done():
        try:
            self._refresh_project_matrix()
        except Exception:
            pass
        win.destroy()
    ttk.Button(bottom,text="Готово",command=done).pack(side="right")
    lb.bind("<Double-1>",lambda e:assign_bom())
    win.protocol("WM_DELETE_WINDOW",done)

    reload_tree()
    win.bind("<Escape>",lambda e:done())


ScreenDesigner._calc_all_demand_names=_calc_all_demand_names
ScreenDesigner._calc_unique_invoice_items=_calc_unique_invoice_items
ScreenDesigner._calc_suggest_bom=_calc_suggest_bom
ScreenDesigner._calc_item_status_text=_calc_item_status_text
ScreenDesigner._calc_set_assignment=_calc_set_assignment
ScreenDesigner._open_calc_assignment_dialog=_open_calc_assignment_dialog



def _components_update_sum(self, event=None):
    """V30.43: сумма столбца «Итого» по выделенным строкам таблицы комплектующих.
    Единица измерения назначается по большинству выделенных строк (строки с иной
    единицей всё равно входят в сумму, но не меняют выбранную единицу)."""
    label=getattr(self,"components_sum_label",None)
    tree=getattr(self,"components_tree",None)
    if label is None or tree is None:
        return
    from collections import Counter
    total=0.0; found=False; units=[]
    for iid in tree.selection():
        try:vals=list(tree.item(iid,"values"))
        except Exception:continue
        if len(vals)<7:continue
        raw=str(vals[6] or "").replace("\xa0","").replace(" ","")
        m=re.search(r"-?\d+(?:[.,]\d+)?",raw)
        if not m:continue
        try:total+=float(m.group(0).replace(",","."));found=True
        except Exception:continue
        u=str(vals[1] or "").strip()
        if u:units.append(u)
    if not found:
        label.configure(text="СУММА СТРОК : —");return
    unit=Counter(units).most_common(1)[0][0] if units else ""
    label.configure(text=("СУММА СТРОК : "+self._format_component_qty(total)+(" "+unit if unit else "")))

ScreenDesigner._components_update_sum=_components_update_sum


def _migrate_component_names_v3044(self):
    """V30.44: старые имена комплектующих -> новые (после унификации справочника)
    в назначениях поставщиков, истории поставщиков и назначениях калькуляции
    открытого проекта, чтобы связи не терялись."""
    def key(n):
        v=str(n or "").split("•",1)[-1].strip()
        return re.sub(r"\s+"," ",v).casefold().replace("ё","е")
    keymap={key(o):key(n) for o,n in COMPONENT_RENAME_V3044.items()}
    for attr in ("project_supplier_assignments","project_component_supplier_history"):
        d=getattr(self,attr,None)
        if isinstance(d,dict) and d:
            nd={}
            for k,v in d.items():
                nd[keymap.get(k,k)]=v
            setattr(self,attr,nd)
    meta=getattr(self,"project_metadata",None)
    if isinstance(meta,dict):
        a=meta.get("calc_item_assignments")
        if isinstance(a,dict):
            for rec in a.values():
                if isinstance(rec,dict) and rec.get("bom") in COMPONENT_RENAME_V3044:
                    rec["bom"]=COMPONENT_RENAME_V3044[rec["bom"]]

ScreenDesigner._migrate_component_names_v3044=_migrate_component_names_v3044


# =====================================================================
# V30.48 — Печатная «Карта раскроя»: A4 альбомная, один профиль = один лист.
# Рендер полностью самостоятельный: логика раскроя, экранный вывод и
# прежняя «Печать раскроя (PDF)» не затрагиваются.
# =====================================================================

_V3048_DPI = 200.0
_V3048_K = _V3048_DPI / 25.4          # мм -> пиксели
_V3048_PAGE_MM = (297.0, 210.0)       # A4 альбомная
_V3048_MARGIN_MM = 10.0

_V3048_INK = "#1f2a37"                # основной текст
_V3048_SUB = "#44505e"                # подписи колонок
_V3048_EDGE = "#222222"               # контуры
_V3048_FACE = "#F2E34C"               # деталь (фронт)
_V3048_TOP = "#F7EE8A"                # верхняя грань
_V3048_SIDE = "#CDB532"               # боковая грань
_V3048_SEP = "#333333"                # разделители деталей
_V3048_REST_BG = "#FBF6C8"            # фон остатка
_V3048_REST_LN = "#8f7f22"            # штриховка остатка
_V3048_SKETCH_LN = "#c9d2dc"          # рамка блока эскиза
_V3048_SECTION = "#cfd4da"            # заливка сечения


def _v3048_mm(value):
    """Миллиметры -> пиксели листа."""
    return float(value) * _V3048_K


def _v3048_font_paths():
    """Пара путей (обычный, жирный) с кириллицей."""
    pairs = (
        ("/System/Library/Fonts/Supplemental/Arial.ttf",
         "/System/Library/Fonts/Supplemental/Arial Bold.ttf"),
        ("C:/Windows/Fonts/arial.ttf", "C:/Windows/Fonts/arialbd.ttf"),
        ("/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
         "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf"),
        ("/usr/share/fonts/truetype/pt-sans/PTS55F.ttf",
         "/usr/share/fonts/truetype/pt-sans/PTS75F.ttf"),
    )
    for regular, bold in pairs:
        if Path(regular).exists():
            return regular, (bold if Path(bold).exists() else regular)
    return None, None


_V3048_FONT_CACHE = {}


def _v3048_font(size_pt, bold=False):
    """Шрифт по размеру в пунктах для текущего DPI листа."""
    key = (round(float(size_pt), 2), bool(bold))
    if key in _V3048_FONT_CACHE:
        return _V3048_FONT_CACHE[key]
    from PIL import ImageFont
    regular, boldpath = _v3048_font_paths()
    px = max(6, int(round(float(size_pt) * _V3048_DPI / 72.0)))
    try:
        font = ImageFont.truetype(boldpath if bold else regular, px)
    except Exception:
        font = ImageFont.load_default()
    _V3048_FONT_CACHE[key] = font
    return font


def _v3048_text_w(draw, text, font):
    box = draw.textbbox((0, 0), str(text), font=font)
    return box[2] - box[0]


def _v3048_text_h(draw, text, font):
    box = draw.textbbox((0, 0), str(text), font=font)
    return box[3] - box[1]


def _v3048_group_int(value):
    """1234567 -> «1 234 567» (разряды неразрывным пробелом не нужны — печать)."""
    try:
        n = int(round(float(value)))
    except Exception:
        return str(value)
    sign = "-" if n < 0 else ""
    digits = str(abs(n))
    parts = []
    while digits:
        parts.append(digits[-3:])
        digits = digits[:-3]
    return sign + " ".join(reversed(parts))


def _v3048_decimal(value, places=1):
    """Десятичная запятая, как на экране."""
    return f"{float(value):.{places}f}".replace(".", ",")


def _v3048_profile_names(material):
    """(полное имя для печати, короткое имя для блока эскиза)."""
    key = str(material[0])
    full = str(material[2])
    short = str(material[1])
    size = str(material[3]).split(",")[0].strip()
    compact = re.sub(r"[^0-9a-zа-я]", "", full.lower().replace("×", "x").replace("х", "x"))
    # П-профиль: в данных встречается и «60×20×2», и «20×60×20×2».
    if key == "u60" or "побразн" in compact or "20x60x20x2" in compact:
        return "П-профиль алюминиевый 60×20×2 мм", "П-профиль 60×20×2"
    bare = re.sub(r"\s*мм\.?$", "", size).strip()
    if short and bare and bare.lower() not in short.lower():
        short = f"{short} {bare}".strip()
    return full, short


def _v3048_dims(material):
    """Числа из описания типоразмера: «30×20×2 мм» -> [30.0, 20.0, 2.0]."""
    raw = str(material[3]).replace("×", "x").replace("х", "x").replace(",", ".")
    return [float(v) for v in re.findall(r"\d+(?:\.\d+)?", raw)]


def _v3048_hatch_polygon(image, polygon, step_px, width=1):
    """Штриховка 45° внутри произвольного многоугольника (через маску)."""
    from PIL import Image, ImageDraw
    xs = [p[0] for p in polygon]
    ys = [p[1] for p in polygon]
    x0, y0 = int(math.floor(min(xs))), int(math.floor(min(ys)))
    x1, y1 = int(math.ceil(max(xs))) + 1, int(math.ceil(max(ys))) + 1
    w, h = x1 - x0, y1 - y0
    if w <= 0 or h <= 0:
        return
    tile = Image.new("RGB", (w, h), _V3048_REST_BG)
    td = ImageDraw.Draw(tile)
    step = max(2, int(round(step_px)))
    offset = -h
    while offset < w + h:
        td.line([(offset, h), (offset + h, 0)], fill=_V3048_REST_LN, width=width)
        offset += step
    mask = Image.new("L", (w, h), 0)
    ImageDraw.Draw(mask).polygon([(p[0] - x0, p[1] - y0) for p in polygon], fill=255)
    image.paste(tile, (x0, y0), mask)


def _v3048_tick(draw, x, y, horizontal, size, color):
    """Засечка размерной линии."""
    if horizontal:
        draw.line([(x, y - size), (x, y + size)], fill=color, width=1)
    else:
        draw.line([(x - size, y), (x + size, y)], fill=color, width=1)


def _v3048_dim_h(draw, x0, x1, y, text, font, color):
    """Горизонтальный размер с засечками, подпись сверху по центру."""
    draw.line([(x0, y), (x1, y)], fill=color, width=1)
    tick = max(2, int(_v3048_mm(0.7)))
    _v3048_tick(draw, x0, y, True, tick, color)
    _v3048_tick(draw, x1, y, True, tick, color)
    w = _v3048_text_w(draw, text, font)
    draw.text(((x0 + x1) / 2 - w / 2, y - _v3048_mm(3.1)), text, font=font, fill=color)


def _v3048_dim_v(draw, x, y0, y1, text, font, color):
    """Вертикальный размер с засечками, подпись слева."""
    draw.line([(x, y0), (x, y1)], fill=color, width=1)
    tick = max(2, int(_v3048_mm(0.7)))
    _v3048_tick(draw, x, y0, False, tick, color)
    _v3048_tick(draw, x, y1, False, tick, color)
    w = _v3048_text_w(draw, text, font)
    draw.text((x - w - _v3048_mm(1.0), (y0 + y1) / 2 - _v3048_mm(1.4)), text, font=font, fill=color)


def _v3048_mm_label(value):
    """2.0 -> «2,0 мм»; 30.0 -> «30 мм»."""
    v = float(value)
    if abs(v - round(v)) < 1e-6 and abs(v) >= 10:
        return f"{int(round(v))} мм"
    return f"{_v3048_decimal(v, 1)} мм"


def _v3048_section_polygon(key, dims):
    """Контур сечения в миллиметрах профиля: (points, width_mm, height_mm).

    Универсально по фактическим размерам: уголок — L, П-профиль и Гефест — П,
    труба — замкнутый прямоугольник со стенкой, шпилька — круг.
    """
    d = list(dims) + [0.0, 0.0, 0.0]
    if key.startswith("angle"):
        a, b, t = (d[0] or 30.0), (d[1] or 20.0), (d[2] or 2.0)
        pts = [(0, 0), (a, 0), (a, t), (t, t), (t, b), (0, b)]
        return pts, a, b
    if key == "u60":
        a, b, t = (d[0] or 60.0), (d[1] or 20.0), (d[2] or 2.0)
        pts = [(0, 0), (a, 0), (a, b), (a - t, b), (a - t, t), (t, t), (t, b), (0, b)]
        return pts, a, b
    if key == "gefest":
        # «14×51×14» — полки 14, спинка 51, тонкая стенка.
        leg = d[0] or 14.0
        back = d[1] or 51.0
        t = 0.8
        pts = [(0, 0), (back, 0), (back, leg), (back - t, leg), (back - t, t),
               (t, t), (t, leg), (0, leg)]
        return pts, back, leg
    if key == "tube40":
        a, b, t = (d[0] or 40.0), (d[1] or 20.0), (d[2] or 2.0)
        pts = [(0, 0), (a, 0), (a, b), (0, b)]
        return pts, a, b
    if key.startswith("rod"):
        dia = d[0] or 10.0
        return "circle", dia, dia
    if key == "din":
        # DIN-рейка 35×7,5 — характерная «шляпа».
        a, b, t = 35.0, 7.5, 1.0
        pts = [(0, 0), (a, 0), (a, b), (a - 7, b), (a - 7, t), (7, t), (7, b), (0, b)]
        return pts, a, b
    a = d[0] or 20.0
    b = d[1] or 20.0
    return [(0, 0), (a, 0), (a, b), (0, b)], a, b


def _v3048_draw_section(image, draw, cx, top, scale, key, dims, font):
    """Сечение профиля с размерами. Возвращает нижнюю границу занятой области."""
    pts, w_mm, h_mm = _v3048_section_polygon(key, dims)
    d = list(dims) + [0.0, 0.0, 0.0]
    x0 = cx - w_mm * scale / 2.0
    if pts == "circle":
        r = w_mm * scale / 2.0
        draw.ellipse((cx - r, top, cx + r, top + 2 * r), fill=_V3048_SECTION, outline=_V3048_EDGE, width=2)
        _v3048_dim_h(draw, cx - r, cx + r, top + 2 * r + _v3048_mm(3.4), _v3048_mm_label(w_mm), font, _V3048_INK)
        return top + 2 * r + _v3048_mm(5.0)
    poly = [(x0 + px * scale, top + py * scale) for px, py in pts]
    draw.polygon(poly, fill=_V3048_SECTION, outline=_V3048_EDGE)
    draw.line(poly + [poly[0]], fill=_V3048_EDGE, width=2)
    if key == "tube40":
        t = d[2] or 2.0
        inner = [(x0 + t * scale, top + t * scale),
                 (x0 + (w_mm - t) * scale, top + t * scale),
                 (x0 + (w_mm - t) * scale, top + (h_mm - t) * scale),
                 (x0 + t * scale, top + (h_mm - t) * scale)]
        draw.polygon(inner, fill="#ffffff", outline=_V3048_EDGE)
        draw.line(inner + [inner[0]], fill=_V3048_EDGE, width=2)
    bottom = top + h_mm * scale
    # Размеры: ширина снизу, высота слева, толщина стенки справа.
    _v3048_dim_h(draw, x0, x0 + w_mm * scale, bottom + _v3048_mm(3.4), _v3048_mm_label(w_mm), font, _V3048_INK)
    _v3048_dim_v(draw, x0 - _v3048_mm(2.2), top, bottom, _v3048_mm_label(h_mm), font, _V3048_INK)
    thickness = d[2] if key.startswith("angle") or key in ("u60", "tube40") else (0.8 if key == "gefest" else 0.0)
    if thickness:
        tx = x0 + w_mm * scale + _v3048_mm(1.6)
        draw.text((tx, top + _v3048_mm(0.4)), _v3048_mm_label(thickness), font=font, fill=_V3048_INK)
    return bottom + _v3048_mm(5.2)


def _v3048_draw_u60_side(image, draw, left, top, scale, length_mm, height_mm, back_mm, font, bold_font):
    """Вид сбоку П-профиля: прямая левая кромка, рез 45° справа вниз-влево."""
    h = height_mm * scale
    length = length_mm * scale
    cut = h  # рез под 45°: горизонтальная проекция равна высоте
    top_right = left + length
    bottom_right = top_right - cut
    poly = [(left, top), (top_right, top), (bottom_right, top + h), (left, top + h)]
    draw.polygon(poly, fill=_V3048_SECTION, outline=_V3048_EDGE)
    draw.line([(left, top), (top_right, top)], fill=_V3048_EDGE, width=2)          # верхняя кромка
    draw.line([(left, top + h), (bottom_right, top + h)], fill=_V3048_EDGE, width=2)  # нижняя кромка
    draw.line([(left, top), (left, top + h)], fill=_V3048_EDGE, width=2)            # левая кромка, без обрыва
    draw.line([(top_right, top), (bottom_right, top + h)], fill=_V3048_EDGE, width=3)  # линия реза толще
    # Толщина спинки 2 мм — пунктиром вдоль верхней кромки.
    yb = top + back_mm * scale
    dash = max(3, int(_v3048_mm(1.0)))
    x = left
    while x < top_right - dash:
        draw.line([(x, yb), (min(x + dash, top_right), yb)], fill=_V3048_EDGE, width=1)
        x += dash * 2
    # Дуга угла между верхней кромкой и резом + подпись 45°.
    r = min(h * 0.55, _v3048_mm(5.0))
    draw.arc((top_right - r, top - r, top_right + r, top + r), start=90, end=135, fill=_V3048_EDGE, width=2)
    label = "45°"
    lw = _v3048_text_w(draw, label, bold_font)
    draw.text((top_right - r - lw - _v3048_mm(0.6), top + _v3048_mm(1.0)), label, font=bold_font, fill=_V3048_INK)
    return top + h


def _v3048_draw_sketch(image, draw, x, y, w, h, material):
    """Блок эскиза профиля: рамка, короткое имя, сечение (для П — и вид сбоку)."""
    key = str(material[0])
    dims = _v3048_dims(material)
    _, short = _v3048_profile_names(material)
    draw.rectangle((x, y, x + w, y + h), outline=_V3048_SKETCH_LN, width=max(1, int(_v3048_mm(0.25))))
    title_font = _v3048_font(8.5, True)
    dim_font = _v3048_font(6.2)
    tw = _v3048_text_w(draw, short, title_font)
    draw.text((x + w / 2 - tw / 2, y + _v3048_mm(1.2)), short, font=title_font, fill=_V3048_INK)
    content_top = y + _v3048_mm(6.2)
    pts, w_mm, h_mm = _v3048_section_polygon(key, dims)
    pad_l, pad_r = _v3048_mm(10.0), _v3048_mm(10.0)
    usable = max(_v3048_mm(8.0), w - pad_l - pad_r)
    cx = x + pad_l + usable / 2.0
    if key == "u60":
        # Два вида в одном масштабе: сечение сверху, вид сбоку снизу.
        avail_h = (y + h) - content_top - _v3048_mm(9.0)
        side_len_mm = w_mm
        scale = min(usable / max(side_len_mm, w_mm),
                    avail_h / (h_mm * 2 + 2.0))
        bottom = _v3048_draw_section(image, draw, cx, content_top, scale, key, dims, dim_font)
        side_left = cx - side_len_mm * scale / 2.0
        side_bottom = _v3048_draw_u60_side(image, draw, side_left, bottom + _v3048_mm(0.6), scale,
                                           side_len_mm, h_mm, (dims[2] if len(dims) > 2 else 2.0),
                                           dim_font, _v3048_font(7.2, True))
        caption = "вид сбоку · рез под 45°"
        cf = _v3048_font(5.6)
        cw = _v3048_text_w(draw, caption, cf)
        draw.text((cx - cw / 2, side_bottom + _v3048_mm(1.0)), caption, font=cf, fill=_V3048_SUB)
        return
    avail_h = (y + h) - content_top - _v3048_mm(6.0)
    scale = min(usable / max(w_mm, 1.0), avail_h / max(h_mm, 1.0))
    _v3048_draw_section(image, draw, cx, content_top + _v3048_mm(1.5), scale, key, dims, dim_font)


def _v3048_draw_angle_badge(draw, right_x, top_y, height):
    """Блок «угол / под 45°» слева от эскиза, вплотную, по верхней кромке."""
    font_px = height / 3.0
    size_pt = max(6.0, font_px * 72.0 / _V3048_DPI)
    font = _v3048_font(size_pt, True)
    w1 = _v3048_text_w(draw, "угол", font)
    w2 = _v3048_text_w(draw, "под 45°", font)
    width = max(w1, w2) + _v3048_mm(4.0)
    x0 = right_x - width
    draw.rectangle((x0, top_y, right_x, top_y + height), outline=_V3048_EDGE,
                   width=max(2, int(_v3048_mm(0.35))))
    gap = (height - 2 * font_px) / 3.0
    draw.text((x0 + width / 2 - w1 / 2, top_y + gap), "угол", font=font, fill=_V3048_INK)
    draw.text((x0 + width / 2 - w2 / 2, top_y + gap * 2 + font_px), "под 45°", font=font, fill=_V3048_INK)
    return x0


# V30.49: отрезки длинее этого значения подписываются ВНУТРИ полосы хлыста,
# более короткие уходят в правую колонку «(детали) — обрезок».
_V3048_INSIDE_MIN_MM = 200.0


def _v3048_fit_font(draw, text, max_w, max_h, start_pt, min_pt=4.5):
    """Наибольший шрифт, при котором подпись влезает в сегмент; иначе None."""
    pt = float(start_pt)
    while pt >= min_pt:
        font = _v3048_font(pt)
        if (_v3048_text_w(draw, text, font) <= max_w
                and _v3048_text_h(draw, text, font) <= max_h):
            return font
        pt -= 0.5
    return None


def _v3048_wrap(draw, text, font, maxw):
    """Перенос по словам в заданную ширину."""
    words = str(text).split(" ")
    lines = []
    cur = ""
    for word in words:
        probe = word if not cur else cur + " " + word
        if _v3048_text_w(draw, probe, font) <= maxw or not cur:
            cur = probe
        else:
            lines.append(cur)
            cur = word
    if cur:
        lines.append(cur)
    return lines


def _v3048_right_text(draw, unfit, left_mm, font, maxw):
    """«(120, 50) — 29 мм»; при нехватке 2 строк — сжатие повторов «120 × 12»."""
    tail = "— {}\u00a0мм".format(int(round(float(left_mm))))
    if not unfit:
        return [tail]
    lines = _v3048_wrap(draw, "(" + ", ".join(unfit) + ") " + tail, font, maxw)
    if len(lines) <= 2:
        return lines
    packed = []
    current = unfit[0]
    count = 1
    for value in unfit[1:]:
        if value == current:
            count += 1
        else:
            packed.append(f"{current} × {count}" if count > 1 else current)
            current = value
            count = 1
    packed.append(f"{current} × {count}" if count > 1 else current)
    return _v3048_wrap(draw, "(" + ", ".join(packed) + ") " + tail, font, maxw)[:2]


def _v3048_build_page(material, stock, groups, kerf, project_line):
    """Один лист A4 (альбомная) для одного типа профиля."""
    from PIL import Image, ImageDraw
    W = int(round(_v3048_mm(_V3048_PAGE_MM[0])))
    H = int(round(_v3048_mm(_V3048_PAGE_MM[1])))
    image = Image.new("RGB", (W, H), "white")
    d = ImageDraw.Draw(image)
    M = _v3048_mm(_V3048_MARGIN_MM)
    X0, X1 = M, W - M
    full_name, _short = _v3048_profile_names(material)
    stock = int(stock)

    # --- блок эскиза (справа сверху) и, для П-профиля, бейдж «угол под 45°» ---
    sk_w, sk_h = _v3048_mm(55.0), _v3048_mm(41.0)
    sk_x, sk_y = X1 - sk_w, M
    _v3048_draw_sketch(image, d, sk_x, sk_y, sk_w, sk_h, material)
    if str(material[0]) == "u60":
        # Бейдж «угол под 45°» рисуется слева от эскиза.
        _v3048_draw_angle_badge(d, sk_x, sk_y, sk_h / 2.0)

    # --- шапка ---
    # V30.79: название проекта — в левом верхнем углу, над заголовком;
    # вся свободная зона правее отдана под блок «Изделия в раскрое».
    head_font = _v3048_font(13.5, True)
    proj_font = _v3048_font(13.5, False)
    title = "КАРТА РАСКРОЯ"
    line_h = _v3048_text_h(d, "Ag", head_font) + _v3048_mm(1.2)
    proj_lines = _v3048_wrap(d, project_line, proj_font, _v3048_mm(85.0))[:2]
    y = M
    for line in proj_lines:
        d.text((X0, y), line, font=proj_font, fill=_V3048_INK)
        y += line_h
    y += _v3048_mm(4.5)
    d.text((X0, y), title, font=head_font, fill=_V3048_INK)
    y += line_h + _v3048_mm(1.0)
    name_font = _v3048_font(10.5)
    d.text((X0, y), full_name, font=name_font, fill=_V3048_INK)
    y += _v3048_text_h(d, "Ag", name_font) + _v3048_mm(2.0)
    info_font = _v3048_font(9.0)
    d.text((X0, y), f"Стандартный хлыст: {_v3048_group_int(stock)} мм", font=info_font, fill=_V3048_INK)
    d.text((X0 + _v3048_mm(62.0), y), f"Пропил: {_v3048_group_int(kerf)} мм", font=info_font, fill=_V3048_INK)
    y += _v3048_text_h(d, "Ag", info_font)

    # --- геометрия колонок ---
    content_top = max(y + _v3048_mm(4.0), sk_y + sk_h + _v3048_mm(3.0))
    bottom_block_h = _v3048_mm(17.0)
    bottom_top = H - M - bottom_block_h
    n = max(1, len(groups))
    X_CHK = X0 + _v3048_mm(28.0)
    X_BAR = X0 + _v3048_mm(36.0)
    X_RIGHT = X1 - _v3048_mm(45.0)

    hdr_font = _v3048_font(7.0)
    d.text((X0, content_top), "№ хлыстов (кол-во)", font=hdr_font, fill=_V3048_SUB)
    d.text((X_BAR, content_top), "3D-пачка — идентичные схемы объединены", font=hdr_font, fill=_V3048_SUB)
    d.text((X_RIGHT, content_top), "(изделие) — остаток", font=hdr_font, fill=_V3048_SUB)
    hdr_h = _v3048_text_h(d, "Ag", hdr_font) + _v3048_mm(2.0)

    # Автоподгонка: высота строки и зависящие от неё размеры.
    iso_full_dx, iso_full_dy = _v3048_mm(3.2), _v3048_mm(2.69)   # скос 40°
    rows_area_top = content_top + hdr_h + iso_full_dy
    avail_h = bottom_top - rows_area_top - _v3048_mm(2.0)
    rowh = min(_v3048_mm(12.0), avail_h / n)
    shrink = max(0.35, min(1.0, rowh / _v3048_mm(12.0)))
    iso_dx, iso_dy = iso_full_dx * shrink, iso_full_dy * shrink
    rows_top = content_top + hdr_h + iso_dy
    small = rowh < _v3048_mm(5.0)
    seg_pt = 7.0 if small else max(7.0, 9.0 * shrink)
    seg_font = _v3048_font(seg_pt)
    side_font = _v3048_font(7.0 if small else max(7.0, 8.5 * shrink))
    num_font = _v3048_font(7.0 if small else max(7.0, 8.5 * shrink))
    barw = X_RIGHT - _v3048_mm(2.0) - iso_dx - X_BAR

    lw_thin = max(1, int(_v3048_mm(0.18)))
    lw_edge = max(2, int(_v3048_mm(0.30)))
    hatch_step = max(2, int(_v3048_mm(1.3)))

    for index, g in enumerate(groups):
        y_top = rows_top + index * rowh
        y_bot = y_top + rowh
        bar = g["bar"]
        used = sum(float(z[0]) for z in bar)
        split = X_BAR + used * barw / stock          # граница «детали | остаток»
        # фронт: детали и заштрихованный остаток
        d.rectangle((X_BAR, y_top, split, y_bot), fill=_V3048_FACE)
        if split < X_BAR + barw - 1:
            _v3048_hatch_polygon(image, [(split, y_top), (X_BAR + barw, y_top),
                                         (X_BAR + barw, y_bot), (split, y_bot)], hatch_step, lw_thin)
        # боковая грань строки
        d.polygon([(X_BAR + barw, y_top), (X_BAR + barw + iso_dx, y_top - iso_dy),
                   (X_BAR + barw + iso_dx, y_bot - iso_dy), (X_BAR + barw, y_bot)],
                  fill=_V3048_SIDE, outline=_V3048_EDGE)
        # верхняя грань пачки — только над первой строкой
        if index == 0:
            top_poly = [(X_BAR, y_top), (X_BAR + barw, y_top),
                        (X_BAR + barw + iso_dx, y_top - iso_dy), (X_BAR + iso_dx, y_top - iso_dy)]
            d.polygon(top_poly, fill=_V3048_TOP, outline=_V3048_EDGE)
            if split < X_BAR + barw - 1:
                _v3048_hatch_polygon(image, [(split, y_top), (X_BAR + barw, y_top),
                                             (X_BAR + barw + iso_dx, y_top - iso_dy),
                                             (split + iso_dx, y_top - iso_dy)], hatch_step, lw_thin)
            d.line(top_poly + [top_poly[0]], fill=_V3048_EDGE, width=lw_thin)
        # сегменты деталей
        pos = float(X_BAR)
        unfit = []
        for j, item in enumerate(bar):
            length = float(item[0])
            segw = length * barw / stock
            if j:
                d.line([(pos, y_top), (pos, y_bot)], fill=_V3048_SEP, width=lw_thin)
                if index == 0:   # линия пропила по верхней грани — наискосок
                    d.line([(pos, y_top), (pos + iso_dx, y_top - iso_dy)], fill=_V3048_SEP, width=lw_thin)
            caption = str(int(length))
            inside = None
            if length > _V3048_INSIDE_MIN_MM:
                # Длинные отрезки подписываются внутри: кегль ужимается под сегмент.
                inside = _v3048_fit_font(d, caption, segw - _v3048_mm(0.8),
                                         rowh - _v3048_mm(0.8), seg_pt)
            if inside is not None:
                cw = _v3048_text_w(d, caption, inside)
                ch = _v3048_text_h(d, caption, inside)
                d.text((pos + (segw - cw) / 2, (y_top + y_bot) / 2 - ch / 2),
                       caption, font=inside, fill="#000000")
            else:
                unfit.append(caption)
            pos += segw
        # подпись остатка внутри широкой зоны
        rest_w = (X_BAR + barw) - split
        if rest_w >= _v3048_mm(18.0):
            label = f"ост. {int(round(float(g['left'])))}"
            lw = _v3048_text_w(d, label, side_font)
            lh = _v3048_text_h(d, label, side_font)
            cxp = split + rest_w / 2
            cyp = (y_top + y_bot) / 2
            d.rectangle((cxp - lw / 2 - _v3048_mm(0.8), cyp - lh / 2 - _v3048_mm(0.5),
                         cxp + lw / 2 + _v3048_mm(0.8), cyp + lh / 2 + _v3048_mm(0.5)),
                        fill=_V3048_REST_BG)
            d.text((cxp - lw / 2, cyp - lh / 2), label, font=side_font, fill=_V3048_INK)
        # внешний контур строки
        d.rectangle((X_BAR, y_top, X_BAR + barw, y_bot), outline=_V3048_EDGE, width=lw_edge)
        # № хлыстов
        nums = g["numbers"]
        label = (_v3014_ranges(nums) + f" ({len(nums)} шт.)") if len(nums) > 1 else str(nums[0])
        lw = _v3048_text_w(d, label, num_font)
        d.text((X_CHK - _v3048_mm(2.5) - lw, (y_top + y_bot) / 2 - _v3048_text_h(d, label, num_font) / 2),
               label, font=num_font, fill=_V3048_INK)
        # чекбокс для отметки при резке
        side = rowh * 0.7
        cy = (y_top + y_bot) / 2
        d.rectangle((X_CHK, cy - side / 2, X_CHK + side, cy + side / 2),
                    outline=_V3048_EDGE, width=max(2, int(_v3048_mm(0.30))))
        # правая колонка
        lines = _v3048_right_text(d, unfit, g["left"], side_font, X1 - X_RIGHT)
        lh = _v3048_text_h(d, "Ag", side_font) + _v3048_mm(0.6)
        start = (y_top + y_bot) / 2 - (len(lines) * lh) / 2
        for k, line in enumerate(lines):
            d.text((X_RIGHT, start + k * lh), line, font=side_font, fill=_V3048_INK)

    # --- низ листа ---
    count = sum(len(g["numbers"]) for g in groups)
    useful = sum(sum(float(z[0]) for z in g["bar"]) * len(g["numbers"]) for g in groups)
    purchase = count * stock
    prop = sum(kerf * max(0, len(g["bar"]) - 1) * len(g["numbers"]) for g in groups)
    rest = purchase - useful - prop
    util = (useful / purchase * 100.0) if purchase else 0.0
    f1 = _v3048_font(10.0, True)
    f2 = _v3048_font(8.5)
    by = bottom_top + _v3048_mm(2.0)
    d.text((X0, by), f"Закупка: {_v3048_group_int(count)} шт. × {_v3048_group_int(stock)} мм = "
                     f"{_v3048_group_int(purchase)} мм", font=f1, fill=_V3048_INK)
    by += _v3048_text_h(d, "Ag", f1) + _v3048_mm(1.6)
    d.text((X0, by), f"Полезная длина: {_v3048_group_int(useful)} мм · Пропил: {_v3048_group_int(prop)} мм · "
                     f"Остаток: {_v3048_group_int(rest)} мм · Использование: {_v3048_decimal(util, 1)} %",
           font=f2, fill=_V3048_INK)
    # легенда справа
    lg_w, lg_h = _v3048_mm(16.0), _v3048_mm(6.0)
    lg_x = X1 - lg_w
    lg_y = bottom_top + _v3048_mm(3.0)
    _v3048_hatch_polygon(image, [(lg_x, lg_y), (lg_x + lg_w, lg_y),
                                 (lg_x + lg_w, lg_y + lg_h), (lg_x, lg_y + lg_h)], hatch_step, lw_thin)
    d.rectangle((lg_x, lg_y, lg_x + lg_w, lg_y + lg_h), outline=_V3048_EDGE, width=lw_thin)
    legend = "остаток / обрезок хлыста (с учётом пропилов)"
    lf = _v3048_font(7.5)
    lines = _v3048_wrap(d, legend, lf, X1 - X0 - lg_w - _v3048_mm(100.0))
    ly = lg_y + lg_h / 2 - (len(lines) * (_v3048_text_h(d, "Ag", lf) + _v3048_mm(0.4))) / 2
    for k, line in enumerate(lines):
        tw = _v3048_text_w(d, line, lf)
        d.text((lg_x - _v3048_mm(2.0) - tw, ly + k * (_v3048_text_h(d, "Ag", lf) + _v3048_mm(0.4))),
               line, font=lf, fill=_V3048_INK)
    return image


def _v3048_project_line(self):
    """«<Имя проекта> — <Тип проекта>» для шапки листа."""
    name = ""
    try:
        name = str(self.project_name_var.get() or "").strip()
    except Exception:
        name = str(getattr(self, "project_name", "") or "").strip()
    if not name:
        path = getattr(self, "current_project_path", None)
        if path:
            try:
                name = Path(path).stem
            except Exception:
                name = ""
    if not name:
        name = "Без названия"
    brand = getattr(self, "project_brand_context", None)
    return f"{name} — {brand}" if brand in ("МЦД", "РЖД") else name


def _v3048_print_cutmap_pdf(self):
    """Кнопка «Печать карты раскроя»: A4 альбомная, один профиль — один лист."""
    try:
        from PIL import Image
    except ImportError:
        messagebox.showerror("Печать карты раскроя", "Требуется Pillow")
        return
    bins = list(getattr(self, "wizard_bins", []))
    if not bins:
        messagebox.showwarning("Печать карты раскроя", "Нет деталей для раскроя.")
        return
    try:
        kerf = max(0, int(self.trial_kerf_var.get()))
    except Exception:
        kerf = 3
    groups = _v3014_groups(bins, kerf, True)
    project_line = self._v3048_project_line()
    pages = []
    for key in dict.fromkeys(g["material"][0] for g in groups):
        chunk = [g for g in groups if g["material"][0] == key]
        pages.append(_v3048_build_page(chunk[0]["material"], chunk[0]["stock"], chunk, kerf, project_line))
    if not pages:
        messagebox.showwarning("Печать карты раскроя", "Нет данных для печати.")
        return
    safe = self._safe_filename_part(project_line.split(" — ")[0])
    # V30.77: в имя файла добавляются размеры исходного материала (30x20x2).
    sizes = []
    for key in dict.fromkeys(g["material"][0] for g in groups):
        size = _v3077_material_size(key)
        if size and size not in sizes:
            sizes.append(size)
    suffix = ("_" + "_".join(sizes)) if sizes else ""
    path = filedialog.asksaveasfilename(
        title="Печать карты раскроя",
        defaultextension=".pdf",
        initialfile=f"Карта_раскроя_{safe}{suffix}.pdf",
        filetypes=[("PDF", "*.pdf")],
    )
    if not path:
        return
    try:
        pages[0].save(path, format="PDF", resolution=_V3048_DPI, save_all=True, append_images=pages[1:])
    except Exception as exc:
        messagebox.showerror("Печать карты раскроя", f"Не удалось сохранить PDF:\n{exc}")
        return
    messagebox.showinfo("Печать карты раскроя", f"PDF сохранён ({len(pages)} лист(ов)):\n{path}")


ScreenDesigner._v3048_project_line = _v3048_project_line
ScreenDesigner._v3048_print_cutmap_pdf = _v3048_print_cutmap_pdf



# =====================================================================
# V30.52 — Журнал проекта → «Расход по изделиям».
# Обратная связь «материал → изделия»: для выбранного материала одна
# строка, у каждого изделия два столбца («на 1 изд.» и «на N изд.») под
# общей шапкой с артикулом. Числа берутся из того же расчёта, что и вкладка
# «Комплектующие» (по каждому изделию отдельно), поэтому сумма по изделиям
# совпадает с режимом «Весь проект». Сам расчёт BOM не меняется.
# =====================================================================

def _usage_num(value):
    t=str(value or "").replace("\xa0","").replace(" ","").replace(",",".")
    try:
        return float(t)
    except Exception:
        return None


def _usage_norm(text):
    return re.sub(r"\s+"," ",str(text or "")).casefold().replace("ё","е").strip()


def _usage_products(self):
    """Изделия в порядке журнала: iid, артикул, наименование, количество."""
    products=[]
    for _order,_ins,kind,i,rec in self._journal_product_records_in_order():
        if kind=="dynamic":
            iid=f"led:{i}"
            article=str(rec.get("module_article","") or rec.get("screen_article","") or f"LED {i+1}").strip()
            name=str(rec.get("screen_article","") or article).strip()
            try: qty=max(1,int(rec.get("quantity",1) or 1))
            except Exception: qty=1
        else:
            iid=f"static:{i}"
            article=str(rec.get("article","") or rec.get("name","") or f"Указатель {i+1}").strip()
            name=str(rec.get("name","") or article).strip()
            raw=str(rec.get("quantity","") or "").strip()
            try: qty=max(1,int(raw)) if raw else 1
            except Exception: qty=1
        spec=str(rec.get("spec_position","") or "").strip()
        products.append({"iid":iid,"article":article,"name":name,"qty":qty,"spec":spec})
    # V30.53: шапка всегда в порядке «Поз.» спецификации (естественная сортировка);
    # изделия без позиции — в конце, в порядке журнала.
    indexed=list(enumerate(products))
    indexed.sort(key=lambda t:((0,_usage_spec_sort_key(t[1]["spec"])) if t[1]["spec"] else (1,()),t[0]))
    return [p for _i,p in indexed]


def _usage_collect(self):
    """Строки BOM по каждому изделию. Вкладка «Комплектующие» восстанавливается."""
    products=self._usage_products()
    materials={}; order=[]; group_order=[]
    if not hasattr(self,"components_tree"):
        return {"products":products,"materials":[]}
    old_scope=self.component_scope_var.get()
    old_search=(self.component_search_var.get() if hasattr(self,"component_search_var") else "")
    # Таблица «Комплектующие» хранит количества уже округлёнными до сотых.
    # На время сбора выводим их без округления, чтобы «на 1 изд.» и суммы были точными.
    precise=lambda v: v if isinstance(v,str) else repr(float(v))
    try:
        self._format_component_qty=precise
        if hasattr(self,"component_search_var"):
            self.component_search_var.set("")
        # V30.61: колонка может объединять несколько изделий журнала (как в «Калькуляции»);
        # расход каждого изделия-участника считается отдельно и складывается в колонку.
        jobs=[]
        for p in products:
            for mem in (p.get("members") or [p]):
                if not mem.get("calc_off"):
                    jobs.append((p,mem["iid"]))
        for p,member_iid in jobs:
            scope=self._component_scope_for_journal_iid(member_iid)
            if not scope:
                continue
            self.component_scope_var.set(scope)
            self._refresh_components_table()
            for r in self._components_print_rows():
                qty=_usage_num(r.get("qty"))
                if qty is None or abs(qty)<1e-12:
                    continue
                raw=str(r.get("name","") or "")
                clean=raw.split("•",1)[-1].strip() if "•" in raw else raw.strip()
                unit=str(r.get("unit","") or "").strip()
                # V30.59: листы и погонаж объединяются без учёта габарита (только эта вкладка).
                clean,unit,qty=_usage_canonical(clean,unit,qty)
                key=(clean.casefold(),unit.casefold())
                group=str(r.get("group","") or "")
                if group not in group_order:
                    group_order.append(group)
                if key not in materials:
                    materials[key]={"key":key,"group":group,"name":clean,"unit":unit,"per_product":{}}
                    order.append(key)
                pp=materials[key]["per_product"]
                pp[p["iid"]]=pp.get(p["iid"],0.0)+qty
    finally:
        if self.__dict__.get("_format_component_qty") is precise:
            del self.__dict__["_format_component_qty"]
        self.component_scope_var.set(old_scope)
        if hasattr(self,"component_search_var"):
            self.component_search_var.set(old_search)
        try: self._refresh_components_table()
        except Exception: pass
    rows=[materials[k] for k in order]
    rows.sort(key=lambda m:(group_order.index(m["group"]) if m["group"] in group_order else 999,m["name"].casefold()))
    return {"products":products,"materials":rows}


def _build_material_usage_view(self, parent):
    self._usage_data={"products":[],"materials":[]}
    self._usage_stale=True
    pw=ttk.PanedWindow(parent,orient="vertical")
    pw.pack(fill="both",expand=True)

    # --- Верхняя часть: поиск и список материалов ---
    top=ttk.Frame(pw,padding=(0,0,0,4))
    bar=ttk.Frame(top); bar.pack(fill="x",pady=(0,5))
    ttk.Label(bar,text="Расход по изделиям",font=("Arial",11,"bold")).pack(side="left")
    ttk.Label(bar,text="Поиск материала:").pack(side="left",padx=(18,4))
    self.usage_search_var=tk.StringVar()
    ent=ttk.Entry(bar,textvariable=self.usage_search_var,width=40); ent.pack(side="left")
    ttk.Button(bar,text="×",width=2,command=lambda:self.usage_search_var.set("")).pack(side="left",padx=(2,0))
    ttk.Button(bar,text="Обновить",command=lambda:self._refresh_material_usage(force=True)).pack(side="right")
    # V30.59: в шапке всегда все изделия проекта — переключатель убран.
    self.usage_only_used_var=tk.BooleanVar(value=False)
    if False: ttk.Checkbutton(bar,text="Только изделия с расходом",variable=self.usage_only_used_var,
                    command=self._draw_material_usage_matrix).pack(side="right",padx=(0,12))
    self.usage_status_var=tk.StringVar(value="")
    ttk.Label(top,textvariable=self.usage_status_var,foreground="#666666").pack(fill="x",pady=(0,3))
    holder=ttk.Frame(top); holder.pack(fill="both",expand=True)
    cols=("group","name","unit","total","products")
    self.usage_tree=ttk.Treeview(holder,columns=cols,show="headings",selectmode="extended",height=10)
    for c,t,w,a,st in (("group","Подгруппа",210,"w",False),("name","Материал",420,"w",True),("unit","Ед.",60,"center",False),
                       ("total","Итого по проекту",120,"center",False),("products","Изделий",80,"center",False)):
        self.usage_tree.heading(c,text=t); self.usage_tree.column(c,width=w,anchor=a,stretch=st)
    vs=ttk.Scrollbar(holder,orient="vertical",command=self.usage_tree.yview)
    self.usage_tree.configure(yscrollcommand=vs.set)
    self.usage_tree.pack(side="left",fill="both",expand=True); vs.pack(side="right",fill="y")
    self.usage_tree.bind("<<TreeviewSelect>>",lambda e:self._draw_material_usage_matrix())
    self.usage_search_var.trace_add("write",lambda *a:self._fill_material_usage_list())
    ent.bind("<Down>",lambda e:(self.usage_tree.focus_set(),
                                self.usage_tree.selection_set(self.usage_tree.get_children()[:1]) if self.usage_tree.get_children() else None,"break")[-1])
    pw.add(top,weight=1)

    # --- Нижняя часть: расход выбранного материала по изделиям ---
    bottom=ttk.Frame(pw,padding=(0,4,0,0))
    self.usage_title_var=tk.StringVar(value="Выберите материал в списке выше")
    ttk.Label(bottom,textvariable=self.usage_title_var,font=("Arial",10,"bold")).pack(fill="x",pady=(0,4))
    h2=ttk.Frame(bottom); h2.pack(fill="both",expand=True)
    self.usage_canvas=tk.Canvas(h2,bg="white",highlightthickness=0,height=180)
    cvs=ttk.Scrollbar(h2,orient="vertical",command=self.usage_canvas.yview)
    chs=ttk.Scrollbar(h2,orient="horizontal",command=self.usage_canvas.xview)
    self.usage_canvas.configure(yscrollcommand=cvs.set,xscrollcommand=chs.set)
    chs.pack(side="bottom",fill="x"); cvs.pack(side="right",fill="y")
    self.usage_canvas.pack(side="left",fill="both",expand=True)
    def _wheel(event):
        d=getattr(event,"delta",0)
        if d: self.usage_canvas.yview_scroll(-1 if d>0 else 1,"units")
        return "break"
    def _shift_wheel(event):
        d=getattr(event,"delta",0)
        if d: self.usage_canvas.xview_scroll(-1 if d>0 else 1,"units")
        return "break"
    self.usage_canvas.bind("<MouseWheel>",_wheel)
    self.usage_canvas.bind("<Shift-MouseWheel>",_shift_wheel)
    # V30.53: выделение ячеек расхода и копирование значений.
    self.usage_canvas.configure(takefocus=1)
    self.usage_canvas.bind("<ButtonPress-1>",self._usage_on_press)
    self.usage_canvas.bind("<B1-Motion>",self._usage_on_drag)
    self.usage_canvas.bind("<Double-Button-1>",self._usage_on_double)
    for seq in ("<Control-c>","<Control-C>","<Command-c>","<Command-C>"):
        try: self.usage_canvas.bind(seq,self._usage_copy)
        except Exception: pass
    for seq in ("<Control-a>","<Control-A>","<Command-a>","<Command-A>"):
        try: self.usage_canvas.bind(seq,self._usage_select_all)
        except Exception: pass
    for seq in ("<Button-3>","<Button-2>","<Control-Button-1>"):
        try: self.usage_canvas.bind(seq,self._usage_context_menu)
        except Exception: pass
    pw.add(bottom,weight=1)

    nb=getattr(self,"project_journal_views",None)
    if nb is not None:
        def _on_tab(_e=None):
            try:
                if nb.select()==str(parent):
                    self._refresh_material_usage(force=self._usage_stale)
            except Exception:
                pass
        nb.bind("<<NotebookTabChanged>>",_on_tab,add="+")


def _refresh_material_usage(self, force=True):
    if not hasattr(self,"usage_tree"):
        return
    if force or not self._usage_data.get("materials"):
        try:
            self.configure(cursor="watch"); self.update_idletasks()
        except Exception:
            pass
        try:
            self._usage_data=self._usage_collect()
            self._usage_stale=False
        finally:
            try: self.configure(cursor="")
            except Exception: pass
    self._fill_material_usage_list()


def _fill_material_usage_list(self):
    tree=getattr(self,"usage_tree",None)
    if tree is None:
        return
    keep=set(tree.selection())
    tree.delete(*tree.get_children())
    tokens=[t for t in _usage_norm(self.usage_search_var.get()).split(" ") if t]
    mats=self._usage_data.get("materials",[])
    shown=0
    for idx,m in enumerate(mats):
        hay=_usage_norm(m["name"]+" "+m["group"])
        if tokens and not all(t in hay for t in tokens):
            continue
        total=sum(m["per_product"].values())
        iid=f"m{idx}"
        tree.insert("","end",iid=iid,values=(m["group"],m["name"],m["unit"],
                    self._format_component_qty(round(total,2)),len(m["per_product"])))
        shown+=1
    products=self._usage_data.get("products",[])
    self.usage_status_var.set(
        f"Материалов: {shown} из {len(mats)} • изделий в проекте: {len(products)} "
        f"(всего {sum(p['qty'] for p in products)} шт.) • данные — как во вкладке «Комплектующие»")
    still=[i for i in keep if tree.exists(i)]
    if still:
        tree.selection_set(still)
    elif len(tree.get_children())==1:
        tree.selection_set(tree.get_children())
    self._draw_material_usage_matrix()


def _usage_spec_sort_key(spec):
    """Естественная сортировка «Поз.»: 2 < 10, 1.2 < 1.10; буквы — по алфавиту."""
    parts=re.findall(r"\d+|[^\d]+",str(spec or "").strip().casefold())
    return tuple((0,int(p),"") if p.isdigit() else (1,0,p.strip(" .-_/")) for p in parts)


def _draw_material_usage_matrix(self):
    """V30.54: A — «Материал» (название материала), B — «Ед.», C… — изделия:
    строка 1 — артикул, 2 — кол-во изделий (оранжевая), 3 — расход на 1 изделие,
    4 — расход на все изделия, 5 — «+20%» (строка 4 × 1,2). Строки 3–5 копируются."""
    c=getattr(self,"usage_canvas",None)
    if c is None:
        return
    c.delete("all")
    self._usage_cells={}
    mats=self._usage_data.get("materials",[])
    selected=[]
    for iid in self.usage_tree.selection():
        try: selected.append(mats[int(iid[1:])])
        except Exception: pass
    products=self._usage_data.get("products",[])
    if not selected:
        self.usage_title_var.set("Выберите материал в списке выше (Ctrl/Shift — несколько)")
        self._usage_sel=None
        c.configure(scrollregion=(0,0,1,1)); return
    hint="выделение мышью, Ctrl+C / ⌘C — копировать значения"
    if len(selected)==1:
        self.usage_title_var.set(f"Расход: {selected[0]['name']}, {selected[0]['unit']}   •   {hint}")
    else:
        self.usage_title_var.set(f"Расход выбранных материалов: {len(selected)}   •   {hint}")
    # V30.59: все изделия, в порядке «Поз.» журнала, даже при нулевом расходе.
    cols=list(products)
    sig=(tuple(m["name"]+"|"+m["unit"] for m in selected),tuple(p["iid"] for p in cols))
    if getattr(self,"_usage_sig",None)!=sig:
        self._usage_sig=sig; self._usage_sel=None

    YELLOW="#FFFFCC"; GRAY="#C9C9C9"; ORANGE="#F4B183"; BLUE="#DDEBF7"; GREEN="#E2EFDA"; GRID="#333333"; SEL="#BFD7FF"
    name_w=300; unit_w=60; col_w=118; total_w=120
    h_art=48; h_qty=28; row_h=28
    RESERVE=1.20
    def rect(x1,y1,x2,y2,fill): c.create_rectangle(x1,y1,x2,y2,fill=fill,outline=GRID)
    def txt(x1,y1,x2,y2,t,bold=False,anchor="center",color="black",size=9):
        f=("Arial",size,"bold") if bold else ("Arial",size)
        if anchor=="center":
            c.create_text((x1+x2)/2,(y1+y2)/2,text=str(t),font=f,fill=color,width=max(10,x2-x1-8),justify="center")
        else:
            c.create_text(x1+6,(y1+y2)/2,text=str(t),font=f,fill=color,width=max(10,x2-x1-10),anchor="w")
    def fmt(v,digits=3):
        if v is None or abs(v)<1e-12: return ""
        return f"{round(v,digits):.{digits}f}".rstrip("0").rstrip(".")

    ncols=len(cols)+1
    x_first=name_w+unit_w
    def col_x(j): return x_first+j*col_w
    def col_w_of(j): return col_w if j<len(cols) else total_w
    right=x_first+len(cols)*col_w+total_w

    # Строки 1–2: шапка. A1:A2 — «Материал», B1:B2 — «Ед.».
    head_h=h_art+h_qty
    rect(0,0,name_w,head_h,YELLOW); txt(0,0,name_w,head_h,"Материал",bold=True)
    rect(name_w,0,x_first,head_h,YELLOW); txt(name_w,0,x_first,head_h,"Ед.",bold=True)
    for j,p in enumerate(cols):
        x=col_x(j)
        if p.get("calc_off"):
            rect(x,0,x+col_w,h_art,"#EDEDED"); txt(x,0,x+col_w,h_art,p["article"]+"\n(без расчёта)",bold=True,size=8,color="#808080")
        else:
            rect(x,0,x+col_w,h_art,GRAY); txt(x,0,x+col_w,h_art,p["article"],bold=True,size=8)
        rect(x,h_art,x+col_w,head_h,ORANGE); txt(x,h_art,x+col_w,head_h,p["qty"],bold=True,size=10)
    xt=col_x(len(cols))
    rect(xt,0,right,h_art,YELLOW); txt(xt,0,right,h_art,"ИТОГО",bold=True)
    rect(xt,h_art,right,head_h,ORANGE); txt(xt,h_art,right,head_h,sum(p["qty"] for p in cols),bold=True,size=10)
    y=head_h

    sel=getattr(self,"_usage_sel",None)
    def in_sel(r,j):
        if not sel: return False
        (r1,c1),(r2,c2)=sel
        return min(r1,r2)<=r<=max(r1,r2) and min(c1,c2)<=j<=max(c1,c2)
    vrow=0
    for m in selected:
        top=y
        # A3:A4 — название материала, A5 — «+20%»; B3:B5 — единица.
        rect(0,top,name_w,top+2*row_h,"white"); txt(0,top,name_w,top+2*row_h,m["name"],bold=True,anchor="w")
        rect(0,top+2*row_h,name_w,top+3*row_h,GREEN); txt(0,top+2*row_h,name_w,top+3*row_h,"+20%",bold=True,anchor="w")
        rect(name_w,top,x_first,top+3*row_h,"white"); txt(name_w,top,x_first,top+3*row_h,m["unit"])
        total=sum(m["per_product"].values())
        for kind in ("one","all","reserve"):
            base=(BLUE if kind=="all" else GREEN if kind=="reserve" else "white")
            for j in range(ncols):
                x=col_x(j); w=col_w_of(j)
                if j<len(cols):
                    p=cols[j]; v=m["per_product"].get(p["iid"])
                    if v is None: val=None
                    elif kind=="one": val=v/max(1,p.get("qty_calc") or p["qty"])
                    elif kind=="all": val=v
                    else: val=v*RESERVE
                else:
                    val=None if kind=="one" else (total if kind=="all" else total*RESERVE)
                text=fmt(val)
                rect(x,y,x+w,y+row_h,SEL if in_sel(vrow,j) else base)
                txt(x,y,x+w,y+row_h,text,bold=(kind!="one"),size=10)
                self._usage_cells[(vrow,j)]=(x,y,x+w,y+row_h,text)
            y+=row_h; vrow+=1
    self._usage_grid=(vrow,ncols)
    if not cols:
        rect(0,y,right,y+row_h,"white"); txt(0,y,right,y+row_h,"Выбранный материал не используется в изделиях проекта",color="#666666")
        y+=row_h
    c.configure(scrollregion=(0,0,right+2,y+2))


def _usage_cell_at(self, event):
    c=self.usage_canvas
    x=c.canvasx(event.x); y=c.canvasy(event.y)
    for key,(x1,y1,x2,y2,_t) in getattr(self,"_usage_cells",{}).items():
        if x1<=x<=x2 and y1<=y<=y2:
            return key
    return None


def _usage_on_press(self, event):
    self.usage_canvas.focus_set()
    cell=self._usage_cell_at(event)
    if cell is None:
        # V30.62: щелчок по пустому месту таблицы сбрасывает выделение.
        if getattr(self,"_usage_sel",None):
            self._usage_sel=None
            self._draw_material_usage_matrix()
        return
    if (event.state & 0x0001) and getattr(self,"_usage_sel",None):   # Shift — расширить
        self._usage_sel=(self._usage_sel[0],cell)
    else:
        self._usage_sel=(cell,cell)
    self._draw_material_usage_matrix()


def _usage_on_double(self, event):
    """V30.62: двойной щелчок по ячейке изделия (столбцы C…) выделяет всю строку
    по изделиям, без ячейки «ИТОГО»."""
    cell=self._usage_cell_at(event)
    rows,cols=getattr(self,"_usage_grid",(0,0))
    if cell is None or cols<2:
        return "break"
    r,j=cell
    last_product=cols-2              # последний столбец изделия; cols-1 — «ИТОГО»
    if j>last_product:
        return "break"
    self._usage_sel=((r,0),(r,last_product))
    self._draw_material_usage_matrix()
    return "break"


def _usage_on_drag(self, event):
    if not getattr(self,"_usage_sel",None):
        return
    cell=self._usage_cell_at(event)
    if cell is not None and cell!=self._usage_sel[1]:
        self._usage_sel=(self._usage_sel[0],cell)
        self._draw_material_usage_matrix()


def _usage_select_all(self, _event=None):
    rows,cols=getattr(self,"_usage_grid",(0,0))
    if rows and cols:
        self._usage_sel=((0,0),(rows-1,cols-1))
        self._draw_material_usage_matrix()
    return "break"


def _usage_copy(self, _event=None):
    """Копирует только значения строк расхода: табуляция между ячейками, перенос между строками,
    десятичная запятая — для прямой вставки в русский Excel."""
    sel=getattr(self,"_usage_sel",None)
    cells=getattr(self,"_usage_cells",{})
    if not sel or not cells:
        return "break"
    (r1,c1),(r2,c2)=sel
    lines=[]
    for r in range(min(r1,r2),max(r1,r2)+1):
        line=[]
        for j in range(min(c1,c2),max(c1,c2)+1):
            t=cells.get((r,j),(0,0,0,0,""))[4]
            line.append(str(t).replace(".",","))
        lines.append("\t".join(line))
    text="\n".join(lines)
    try:
        self.clipboard_clear(); self.clipboard_append(text)
        n=(abs(r2-r1)+1)*(abs(c2-c1)+1)
        if hasattr(self,"usage_status_var"):
            base=self.usage_status_var.get().split("   ✓",1)[0]
            self.usage_status_var.set(f"{base}   ✓ Скопировано ячеек: {n}")
    except Exception:
        pass
    return "break"


def _usage_context_menu(self, event):
    if self._usage_cell_at(event) is not None and not getattr(self,"_usage_sel",None):
        self._usage_on_press(event)
    menu=tk.Menu(self,tearoff=0)
    menu.add_command(label="Копировать",command=self._usage_copy)
    menu.add_command(label="Выделить все значения",command=self._usage_select_all)
    try: menu.tk_popup(event.x_root,event.y_root)
    finally: menu.grab_release()



# V30.59 — «Расход по изделиям»: объединение листовых и погонажных материалов
# без учёта габарита детали. Листы → м² (прямоугольник W×H без вычета радиусов,
# круг π·D²/4), погонаж → м.п. Вкладка «Комплектующие», печать и вес не меняются.
_USAGE_SHEET_RE = re.compile(r"^(оргстекло|алюкобонд|молочный акрил)\s+(\d+(?:[.,]\d+)?)\s*мм\b(.*)$", re.I)
_USAGE_SHEET_NAMES = {"оргстекло": "Оргстекло", "алюкобонд": "Алюкобонд", "молочный акрил": "Молочный акрил"}
_USAGE_LINEAR_UNITS = {"м", "м.", "м.п.", "м.п", "мп", "п.м.", "пог.м"}


def _usage_num_mm(text):
    return float(str(text).replace(",", "."))


def _usage_canonical(name, unit, qty):
    """(имя, ед., кол-во) → объединённая позиция для вкладки «Расход по изделиям»."""
    n = re.sub(r"\s+", " ", str(name or "")).strip()
    u = str(unit or "").strip()
    ul = u.casefold().replace(" ", "")
    is_linear_unit = ul in _USAGE_LINEAR_UNITS
    is_piece = ul in ("шт", "шт.")
    is_sqm = ul in ("м²", "м2", "мкв", "м.кв.", "кв.м")

    # --- Листы: оргстекло / алюкобонд / молочный акрил одной толщины.
    m = _USAGE_SHEET_RE.match(n)
    if m:
        kind = _USAGE_SHEET_NAMES[m.group(1).casefold()]
        thick = m.group(2).replace(".", ",")
        cname = f"{kind} {thick} мм"
        if is_sqm:
            return cname, "м²", qty
        if is_piece:
            rest = m.group(3)
            mr = re.search(r"(\d+(?:[.,]\d+)?)\s*[×xх]\s*(\d+(?:[.,]\d+)?)\s*мм", rest)
            if mr:
                return cname, "м²", _usage_num_mm(mr.group(1)) * _usage_num_mm(mr.group(2)) / 1e6 * qty
            md = re.search(r"Ø\s*(\d+(?:[.,]\d+)?)\s*мм", rest)
            if md:
                d = _usage_num_mm(md.group(1)) / 1000.0
                return cname, "м²", math.pi * d * d / 4.0 * qty
        return name, unit, qty    # размер не распознан — оставляем как есть

    nl = n.casefold().replace("ё", "е")
    # --- Профиль Гефест — L мм (шт.) → м.п.
    m = re.match(r"^профиль гефест\s*(?:—\s*(\d+(?:[.,]\d+)?)\s*мм)?", nl)
    if m:
        if is_linear_unit:
            return "Профиль Гефест", "м.п.", qty
        if is_piece and m.group(1):
            return "Профиль Гефест", "м.п.", _usage_num_mm(m.group(1)) / 1000.0 * qty
        return name, unit, qty
    # --- Уголок алюминиевый A×B×C (прямой и гнутый по радиусу).
    m = re.match(r"^уголок алюминиевый\s*(\d+)\s*[×xх]\s*(\d+)\s*[×xх]\s*(\d+)", nl)
    if m and is_linear_unit:
        return f"Уголок алюминиевый {m.group(1)}×{m.group(2)}×{m.group(3)} мм", "м.п.", qty
    # --- Профиль корпуса МЦД 75/120/175 мм: П-/Г-элементы и круглый гнутый.
    m = re.match(r"^профиль\s*(75|120|175)\s*мм\s*—\s*([пг])-элемент\s*—\s*([\d.,]+)\s*×\s*([\d.,]+)", nl)
    if m and is_piece:
        a, b = _usage_num_mm(m.group(3)), _usage_num_mm(m.group(4))
        length = (a + 2.0 * b) if m.group(2) == "п" else (a + b)      # как в расчёте веса
        return f"Профиль алюминиевый {m.group(1)} мм", "м.п.", length / 1000.0 * qty
    m = re.match(r"^профиль алюминиевый\s*(75|120|175)\s*мм", nl)
    if m and is_linear_unit:
        return f"Профиль алюминиевый {m.group(1)} мм", "м.п.", qty
    # --- Шпильки (в т.ч. «Перемычка — шпилька М10»).
    m = re.match(r"^(?:перемычка\s*—\s*)?шпилька\s*[мm]\s*(\d+)", nl)
    if m and is_linear_unit:
        return f"Шпилька М{m.group(1)}", "м.п.", qty
    # --- DIN-рейка.
    if re.match(r"^din[\s-]*рейка", nl) and is_linear_unit:
        return "DIN-рейка", "м.п.", qty
    # --- Профильная труба и П-профиль: единица м → м.п.
    if (nl.startswith("профильная труба") or nl.startswith("профиль алюминиевый п-образный")) and is_linear_unit:
        return n, "м.п.", qty
    return name, unit, qty     # прочие позиции — без изменений


