def _v3052_mark_usage_stale(func):
    def wrapper(self,*a,**k):
        result=func(self,*a,**k)
        self._usage_stale=True
        return result
    return wrapper

# Любое обновление журнала (добавление/изменение/удаление изделия, открытие проекта)
# помечает данные вкладки устаревшими — при следующем открытии они пересчитаются.
ScreenDesigner._refresh_project_journal=_v3052_mark_usage_stale(ScreenDesigner._refresh_project_journal)



# =====================================================================
# V30.55 — Журнал проекта: столбец «Расчёт» (чекбокс).
# ☑ — изделие участвует в расчёте комплектующих (по умолчанию);
# ☐ — изделие остаётся в проекте и в «Калькуляции», но НЕ входит в
#     «Комплектующие», «Карту раскроя» / «Раскрой», «Закупки и склад»
#     и «Расход по изделиям». Флаг хранится в изделии: calc_enabled.
# =====================================================================

CALC_ON_MARK = "☑"
CALC_OFF_MARK = "☐"


def _product_calc_enabled(rec):
    return not (isinstance(rec, dict) and rec.get("calc_enabled", True) is False)


def _v3055_calc_screens(self):
    return [s for s in (getattr(self, "saved_screens", []) or []) if _product_calc_enabled(s)]


def _v3055_calc_signs(self):
    return [s for s in (getattr(self, "saved_static_signs", []) or []) if _product_calc_enabled(s)]


# --- «Комплектующие»: агрегаты без отключённых изделий; отдельное отключённое изделие — пусто.
_v3055_orig_selected_component_items = ScreenDesigner._selected_component_items
def _v3055_selected_component_items(self):
    screens, signs = _v3055_orig_selected_component_items(self)
    return ([s for s in screens if _product_calc_enabled(s)],
            [s for s in signs if _product_calc_enabled(s)])
ScreenDesigner._selected_component_items = _v3055_selected_component_items


_v3055_orig_refresh_components_table = ScreenDesigner._refresh_components_table
def _v3055_refresh_components_table(self):
    _v3055_orig_refresh_components_table(self)
    try:
        off = [s for s in (getattr(self, "saved_screens", []) or []) + (getattr(self, "saved_static_signs", []) or [])
               if not _product_calc_enabled(s)]
        if not off or not hasattr(self, "component_summary_var"):
            return
        scope = str(self.component_scope_var.get() or "")
        if "без расчёта" in scope:
            self.component_summary_var.set(
                "Расчёт комплектующих для этого изделия отключён в журнале проекта (столбец «Расчёт»).")
        else:
            text = self.component_summary_var.get()
            self.component_summary_var.set(
                (text + "\n" if text else "") + f"Без расчёта комплектующих (отключено в журнале): {len(off)} изд.")
    except Exception:
        pass
ScreenDesigner._refresh_components_table = _v3055_refresh_components_table


_v3055_orig_scope_selector = ScreenDesigner._refresh_components_screen_selector
def _v3055_refresh_components_screen_selector(self):
    # Исходный селектор не знает о пометке «без расчёта» — временно снимаем её,
    # чтобы текущий выбор не сбрасывался на «Весь проект».
    suffix = " — без расчёта"
    try:
        cur = str(self.component_scope_var.get() or "")
        if cur.endswith(suffix):
            self.component_scope_var.set(cur[:-len(suffix)])
    except Exception:
        pass
    _v3055_orig_scope_selector(self)
    combo = getattr(self, "component_scope_combo", None)
    if combo is None:
        return
    try:
        values = list(combo["values"])
        screens = getattr(self, "saved_screens", []) or []
        signs = getattr(self, "saved_static_signs", []) or []
        out = []
        for v in values:
            rec = None
            m = re.match(r"^(LED|МЦД|РЖД) (\d+) —", str(v))
            if m:
                idx = int(m.group(2)) - 1
                pool = screens if m.group(1) == "LED" else signs
                rec = pool[idx] if 0 <= idx < len(pool) else None
            out.append(f"{v} — без расчёта" if rec is not None and not _product_calc_enabled(rec) else v)
        combo["values"] = out
        if self.component_scope_var.get() not in out:
            cur = self.component_scope_var.get()
            match = next((x for x in out if x.startswith(cur)), None)
            self.component_scope_var.set(match or "Весь проект")
    except Exception:
        pass
ScreenDesigner._refresh_components_screen_selector = _v3055_refresh_components_screen_selector


# --- Карта раскроя / Раскрой: только изделия с расчётом.
_v3055_orig_cut_entries = ScreenDesigner._cut_map_project_entries
def _v3055_cut_map_project_entries(self):
    entries = []
    for i, sc in enumerate(getattr(self, "saved_screens", []) or []):
        if not _product_calc_enabled(sc):
            continue
        rows = self._cut_map_entries_for_product("dynamic", i, sc)
        for row in rows:
            row["article"] = str(sc.get("module_article", "") or "").strip()
        entries.extend(rows)
    for i, sg in enumerate(getattr(self, "saved_static_signs", []) or []):
        if not _product_calc_enabled(sg):
            continue
        rows = self._cut_map_entries_for_product("static", i, sg)
        for row in rows:
            row["article"] = str(sg.get("article", "") or "").strip()
        entries.extend(rows)
    return entries
ScreenDesigner._cut_map_project_entries = _v3055_cut_map_project_entries


# --- Закупки и склад: «Весь проект» без отключённых изделий.
_v3055_orig_stock_screens = ScreenDesigner._selected_stock_screens
def _v3055_selected_stock_screens(self):
    return [s for s in _v3055_orig_stock_screens(self) if _product_calc_enabled(s)]
ScreenDesigner._selected_stock_screens = _v3055_selected_stock_screens


# --- Расход по изделиям: отключённые изделия не выводятся.
_v3055_orig_usage_products = ScreenDesigner._usage_products
def _v3055_usage_products(self):
    # V30.59: изделия без расчёта остаются в шапке (с пометкой), но не считаются.
    out = []
    for p in _v3055_orig_usage_products(self):
        rec = self._project_journal_record_for_iid(p["iid"])
        p = dict(p); p["calc_off"] = not _product_calc_enabled(rec)
        out.append(p)
    return out
ScreenDesigner._usage_products = _v3055_usage_products


# --- LED-экран: флаг переживает сохранение/открытие (сериализатор со списком полей).
_v3055_orig_serialize_screen = ScreenDesigner._serialize_screen
def _v3055_serialize_screen(self, screen):
    data = _v3055_orig_serialize_screen(self, screen)
    data["calc_enabled"] = _product_calc_enabled(screen)
    return data
ScreenDesigner._serialize_screen = _v3055_serialize_screen


# --- Журнал: значения чекбокса, серый текст для изделий без расчёта, переключение кликом.
_v3055_orig_refresh_journal = ScreenDesigner._refresh_project_journal
def _v3055_refresh_project_journal(self):
    _v3055_orig_refresh_journal(self)
    tree = getattr(self, "project_journal_tree", None)
    if tree is None:
        return
    try:
        tree.tag_configure("calc_off", foreground="#8A8A8A")
        for iid in tree.get_children(""):
            rec = self._project_journal_record_for_iid(iid)
            if rec is None:
                continue
            on = _product_calc_enabled(rec)
            tree.set(iid, "calc", CALC_ON_MARK if on else CALC_OFF_MARK)
            tags = [t for t in (tree.item(iid, "tags") or ()) if t != "calc_off"]
            if not on:
                tags.append("calc_off")
            tree.item(iid, tags=tags)
            for child in tree.get_children(iid):
                ctags = [t for t in (tree.item(child, "tags") or ()) if t != "calc_off"]
                if not on:
                    ctags.append("calc_off")
                tree.item(child, tags=ctags)
    except Exception:
        pass
ScreenDesigner._refresh_project_journal = _v3055_refresh_project_journal


def _project_journal_calc_click(self, event):
    tree = self.project_journal_tree
    try:
        if str(tree.identify_region(event.x, event.y) or "") != "cell":
            return None
        col_id = tree.identify_column(event.x)            # «#N» по отображаемым колонкам
        display = list(tree["displaycolumns"])
        if display and display != ["#all"]:
            col = display[int(col_id[1:]) - 1]
        else:
            col = list(tree["columns"])[int(col_id[1:]) - 1]
        if col != "calc":
            return None
        iid = tree.identify_row(event.y)
    except Exception:
        return None
    if not iid or tree.parent(iid):
        return "break"
    rec = self._project_journal_record_for_iid(iid)
    if not isinstance(rec, dict):
        return "break"
    if not bool(getattr(self, "project_journal_edit_var", None) and self.project_journal_edit_var.get()):
        messagebox.showinfo("Журнал проекта",
                            "Чтобы включить или выключить расчёт изделия, отметьте «Редактирование».")
        return "break"
    rec["calc_enabled"] = not _product_calc_enabled(rec)
    self._project_journal_drag_iid = None
    try: self._mark_project_dirty()
    except Exception: pass
    for fn in ("_refresh_project_journal", "_refresh_components_screen_selector", "_refresh_components_table"):
        try: getattr(self, fn)()
        except Exception: pass
    try: self._refresh_procurement_table()
    except Exception: pass
    try:
        if hasattr(self, "trial_canvas"): self._trial_refresh()
    except Exception: pass
    self._usage_stale = True
    try:
        tree.selection_set(iid); tree.focus(iid)
    except Exception:
        pass
    return "break"
ScreenDesigner._project_journal_calc_click = _project_journal_calc_click


_v3055_orig_journal_double_click = ScreenDesigner._project_journal_double_click
def _v3055_project_journal_double_click(self, event=None):
    # Двойной щелчок по чекбоксу «Расчёт» не открывает изделие.
    try:
        if event is not None:
            tree = self.project_journal_tree
            col_id = tree.identify_column(event.x)
            display = list(tree["displaycolumns"])
            if display and display != ["#all"] and display[int(col_id[1:]) - 1] == "calc":
                return "break"
    except Exception:
        pass
    return _v3055_orig_journal_double_click(self, event)
ScreenDesigner._project_journal_double_click = _v3055_project_journal_double_click


# V30.56: точечная миграция сохранённого справочника (файл overrides хранит разделы
# целиком). Обновляем только текст правила оргстекла/алюкобонда динамики МЦД,
# если там осталась старая формула (W − 18) × (H − 18), R66. Веса и прочие правки не трогаем.
_v3056_orig_reference_load = ScreenDesigner._reference_load
def _v3056_reference_load(self):
    data = _v3056_orig_reference_load(self)
