# =====================================================================
# V30.64 — (1) просмотр спецификации «как есть» (в духе быстрого просмотра macOS):
#              без разбора содержимого; Word/Excel и пр. один раз переводятся в PDF
#              средствами компьютера (LibreOffice / Microsoft Office / Quick Look),
#              вид хранится в проекте; (2) окно «Поставщики» — дерево
#              Поставщик → Проект/счёт → закупка, по всем проектам программы.
# =====================================================================

_SPEC_IMAGE_EXT = {".jpg", ".jpeg", ".png", ".gif", ".tif", ".tiff", ".bmp", ".webp"}


def _v3064_find_soffice():
    import shutil
    for name in ("soffice", "libreoffice"):
        p = shutil.which(name)
        if p:
            return p
    for p in (r"C:\Program Files\LibreOffice\program\soffice.exe",
              r"C:\Program Files (x86)\LibreOffice\program\soffice.exe",
              "/Applications/LibreOffice.app/Contents/MacOS/soffice"):
        if Path(p).exists():
            return p
    return None


def _v3064_convert_to_preview(src_path):
    """Файл → ('pdf', bytes) | ('png', bytes) | (None, причина). Содержимое не разбирается."""
    import tempfile, shutil
    src = Path(src_path)
    ext = src.suffix.lower()
    out_dir = Path(tempfile.mkdtemp(prefix="led_spec_"))
    try:
        soffice = _v3064_find_soffice()
        if soffice:
            try:
                kw = {"stdout": subprocess.DEVNULL, "stderr": subprocess.DEVNULL, "timeout": 120}
                if os.name == "nt":
                    kw["creationflags"] = getattr(subprocess, "CREATE_NO_WINDOW", 0)
                subprocess.run([soffice, "--headless", "--convert-to", "pdf", "--outdir", str(out_dir), str(src)], **kw)
                pdf = out_dir / (src.stem + ".pdf")
                if pdf.exists() and pdf.stat().st_size > 0:
                    return "pdf", pdf.read_bytes()
            except Exception:
                pass
        if sys.platform.startswith("win"):
            try:
                import win32com.client  # pywintypes / Microsoft Office
                pdf = out_dir / (src.stem + ".pdf")
                if ext in (".doc", ".docx", ".rtf", ".odt"):
                    app = win32com.client.DispatchEx("Word.Application"); app.Visible = False
                    try:
                        doc = app.Documents.Open(str(src), ReadOnly=True)
                        doc.ExportAsFixedFormat(str(pdf), 17); doc.Close(False)
                    finally:
                        app.Quit()
                elif ext in (".xls", ".xlsx", ".xlsm", ".csv", ".ods"):
                    app = win32com.client.DispatchEx("Excel.Application"); app.Visible = False
                    try:
                        wb = app.Workbooks.Open(str(src), ReadOnly=True)
                        wb.ExportAsFixedFormat(0, str(pdf)); wb.Close(False)
                    finally:
                        app.Quit()
                if pdf.exists() and pdf.stat().st_size > 0:
                    return "pdf", pdf.read_bytes()
            except Exception:
                pass
        if sys.platform == "darwin" and shutil.which("qlmanage"):
            try:
                subprocess.run(["qlmanage", "-t", "-s", "2000", "-o", str(out_dir), str(src)],
                               stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=60)
                pngs = sorted(out_dir.glob("*.png"))
                if pngs:
                    return "png", pngs[0].read_bytes()
            except Exception:
                pass
        return None, ("На этом компьютере не найдено средство для показа такого файла "
                      "(LibreOffice или Microsoft Office). Файл сохранён в проекте — откройте его "
                      "кнопкой «Открыть в системной программе».")
    finally:
        shutil.rmtree(out_dir, ignore_errors=True)


def _v3064_spec_temp_file(self, spec):
    import tempfile
    folder = Path(tempfile.gettempdir()) / "LED_Screen_Designer"
    folder.mkdir(parents=True, exist_ok=True)
    stem = self._safe_filename_part(Path(spec.get("file_name") or "Спецификация").stem) or "Спецификация"
    path = folder / (stem + (spec.get("ext") or ""))
    path.write_bytes(base64.b64decode(spec["b64"]))
    return path


def _v3064_ensure_preview(self, spec):
    """Для не-PDF/не-изображений один раз строит вид документа и кладёт его в проект."""
    ext = str(spec.get("ext", "")).lower()
    if ext == ".pdf" or ext in _SPEC_IMAGE_EXT:
        return True
    if spec.get("preview_pdf_b64") or spec.get("preview_png_b64"):
        return True
    try:
        self.configure(cursor="watch"); self.update_idletasks()
    except Exception:
        pass
    try:
        kind, data = _v3064_convert_to_preview(self._v3064_spec_temp_file(spec))
    finally:
        try: self.configure(cursor="")
        except Exception: pass
    if kind == "pdf":
        spec["preview_pdf_b64"] = base64.b64encode(data).decode("ascii")
    elif kind == "png":
        spec["preview_png_b64"] = base64.b64encode(data).decode("ascii")
    else:
        spec["preview_error"] = data
        return False
    spec.pop("preview_error", None)
    try: self._mark_project_dirty()
    except Exception: pass
    return True


def _v3064_spec_render(self, spec):
    """Только изображение страниц документа — без чтения таблиц и текста."""
    from PIL import Image, ImageSequence
    ext = str(spec.get("ext", "")).lower()

    def pdf_pages(data):
        try:
            import fitz
        except ImportError:
            return "none", "Для показа PDF нужен PyMuPDF (pip install pymupdf)."
        doc = fitz.open(stream=data, filetype="pdf")
        try:
            pages = []
            for i, pg in enumerate(doc):
                if i >= 80: break
                pix = pg.get_pixmap(matrix=fitz.Matrix(2, 2), alpha=False)
                pages.append(Image.frombytes("RGB", [pix.width, pix.height], pix.samples))
            return "pages", pages
        finally:
            doc.close()

    def image_pages(data):
        img = Image.open(io.BytesIO(data))
        return "pages", [f.convert("RGB") for i, f in enumerate(ImageSequence.Iterator(img)) if i < 100]

    if ext == ".pdf":
        return pdf_pages(base64.b64decode(spec["b64"]))
    if ext in _SPEC_IMAGE_EXT:
        return image_pages(base64.b64decode(spec["b64"]))
    if spec.get("preview_pdf_b64"):
        return pdf_pages(base64.b64decode(spec["preview_pdf_b64"]))
    if spec.get("preview_png_b64"):
        return image_pages(base64.b64decode(spec["preview_png_b64"]))
    return "none", spec.get("preview_error") or "Вид документа ещё не построен."


_v3064_orig_upload = ScreenDesigner._v3063_upload_specification
def _v3064_upload_specification(self, parent=None):
    ok = _v3064_orig_upload(self, parent)
    if ok:
        spec = self._v3063_spec()
        if spec is not None:
            self._v3064_ensure_preview(spec)
    return ok


def _v3064_quick_look(self, spec, parent=None):
    """macOS: системный быстрый просмотр (Quick Look) сохранённого файла."""
    try:
        path = self._v3064_spec_temp_file(spec)
        subprocess.Popen(["qlmanage", "-p", str(path)], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    except Exception as exc:
        messagebox.showerror("Спецификация", f"Не удалось открыть быстрый просмотр:\n{exc}", parent=parent or self)


def _v3064_open_specification_viewer(self):
    if self._v3063_spec() is None:
        if not messagebox.askyesno("Спецификация", "Файл спецификации в проекте ещё не загружен.\nЗагрузить сейчас?"):
            return
        if not self._v3063_upload_specification():
            return
    spec = self._v3063_spec()
    self._v3064_ensure_preview(spec)
    from PIL import Image, ImageTk
    win = tk.Toplevel(self)
    win.title(f"Спецификация — {spec.get('file_name', '')}")
    win.geometry("1100x800"); win.minsize(600, 420)
    try: win.transient(self)
    except Exception: pass
    top = ttk.Frame(win, padding=(10, 8)); top.pack(fill="x")
    ttk.Label(top, text=f"{spec.get('file_name', '')}  •  {spec.get('size', 0) / 1024:.0f} КБ  •  "
                        f"загружен {_v3063_date_only(spec.get('uploaded_at'))}",
              font=("Arial", 10, "bold")).pack(side="left")
    body = ttk.Frame(win); body.pack(fill="both", expand=True)
    bottom = ttk.Frame(win, padding=(10, 8)); bottom.pack(fill="x")

    def replace():
        if self._v3063_upload_specification(parent=win):
            win.destroy(); self._open_specification_viewer()

    def save_copy():
        s = self._v3063_spec()
        path = filedialog.asksaveasfilename(parent=win, title="Сохранить копию спецификации",
                                            initialfile=s.get("file_name") or "Спецификация",
                                            defaultextension=s.get("ext") or "")
        if path:
            Path(path).write_bytes(base64.b64decode(s["b64"]))
            messagebox.showinfo("Спецификация", f"Файл сохранён:\n{path}", parent=win)

    ttk.Button(bottom, text="Закрыть", command=win.destroy).pack(side="right")
    ttk.Button(bottom, text="Открыть в системной программе",
               command=lambda: self._v3063_spec_open_external(self._v3063_spec(), win)).pack(side="right", padx=(0, 8))
    if sys.platform == "darwin":
        ttk.Button(bottom, text="Быстрый просмотр (Quick Look)",
                   command=lambda: self._v3064_quick_look(self._v3063_spec(), win)).pack(side="right", padx=(0, 8))
    ttk.Button(bottom, text="Сохранить копию…", command=save_copy).pack(side="right", padx=(0, 8))
    ttk.Button(bottom, text="Заменить файл…", command=replace).pack(side="right", padx=(0, 8))

    try:
        kind, content = self._v3063_spec_render(spec)
    except Exception as exc:
        kind, content = "none", f"Не удалось показать файл:\n{exc}"

    if kind == "pages" and content:
        state = {"page": 0, "zoom": None, "photo": None}
        nav = ttk.Frame(top); nav.pack(side="right")
        pinfo = tk.StringVar()
        canvas = tk.Canvas(body, bg="#5F5F5F", highlightthickness=0)
        vbar = ttk.Scrollbar(body, orient="vertical", command=canvas.yview)
        hbar = ttk.Scrollbar(body, orient="horizontal", command=canvas.xview)
        canvas.configure(xscrollcommand=hbar.set, yscrollcommand=vbar.set)
        hbar.pack(side="bottom", fill="x"); vbar.pack(side="right", fill="y"); canvas.pack(fill="both", expand=True)

        def draw():
            src = content[state["page"]]
            z = state["zoom"] or 1
            w = max(1, round(src.width * z)); h = max(1, round(src.height * z))
            state["photo"] = ImageTk.PhotoImage(src.resize((w, h), Image.Resampling.LANCZOS if z < 1 else Image.Resampling.BICUBIC))
            canvas.delete("all")
            cw = max(canvas.winfo_width(), w + 40)
            canvas.create_image(cw // 2, 20, image=state["photo"], anchor="n")
            canvas.configure(scrollregion=(0, 0, cw, h + 40))
            pinfo.set(f"Стр. {state['page'] + 1} из {len(content)}   {z * 100:.0f}%")

        def fit():
            src = content[state["page"]]
            state["zoom"] = min(max(400, canvas.winfo_width() - 40) / src.width,
                                max(260, canvas.winfo_height() - 40) / src.height, 2.0); draw()

        def zoom(m):
            if state["zoom"] is None: fit()
            state["zoom"] = max(.1, min(4.0, state["zoom"] * m)); draw()

        def page(d):
            p = max(0, min(len(content) - 1, state["page"] + d))
            if p != state["page"]: state["page"] = p; draw(); canvas.yview_moveto(0)
        for txt_, cmd in (("◀", lambda: page(-1)), ("▶", lambda: page(1)), ("−", lambda: zoom(1 / 1.2)),
                          ("+", lambda: zoom(1.2)), ("По размеру", fit)):
            ttk.Button(nav, text=txt_, width=(10 if len(txt_) > 2 else 3), command=cmd).pack(side="left", padx=2)
        ttk.Label(nav, textvariable=pinfo).pack(side="left", padx=(8, 0))

        def wheel(e):
            d = getattr(e, "delta", 0)
            if not d: return
            if (e.state & 0x0004) or (e.state & 0x0008): zoom(1.15 if d > 0 else 1 / 1.15)
            else: canvas.yview_scroll(-1 if d > 0 else 1, "units")
            return "break"
        canvas.bind("<MouseWheel>", wheel)
        canvas.bind("<Configure>", lambda e: state["zoom"] is not None and draw())
        win.bind("<Prior>", lambda e: page(-1)); win.bind("<Next>", lambda e: page(1))
        win.after(120, fit)
    else:
        ttk.Label(body, text=content, foreground="#555555", font=("Arial", 11),
                  justify="center", wraplength=700).pack(expand=True)
    win.bind("<Escape>", lambda e: win.destroy())
    return win


# --------------------------- Поставщики: дерево закупок ---------------------------
def _v3064_norm_supplier(name):
    s = str(name or "").casefold().replace("ё", "е")
    s = re.sub(r"[\"'«»„“”]", " ", s)
    s = re.sub(r"\b(ооо|оао|зао|пао|ао|ип|индивидуальный предприниматель)\b", " ", s)
    return re.sub(r"\s+", " ", s).strip()


def _v3064_purchases_init(conn):
    conn.execute("""CREATE TABLE IF NOT EXISTS supplier_purchases(
        project_key TEXT, brand TEXT, project_name TEXT, supplier TEXT, supplier_norm TEXT,
        invoice_date TEXT, invoice_no TEXT, buyer TEXT, item TEXT, qty TEXT, unit TEXT)""")
    conn.execute("CREATE INDEX IF NOT EXISTS ix_sp_supplier ON supplier_purchases(supplier_norm)")
    conn.execute("CREATE INDEX IF NOT EXISTS ix_sp_project ON supplier_purchases(project_key)")


def _v3064_current_purchases(self):
    """Позиции счетов открытого проекта (с учётом ручных правок строк)."""
    try: self._sync_invoice_models_from_rows()
    except Exception: pass
    meta = self.project_metadata if isinstance(getattr(self, "project_metadata", None), dict) else {}
    key = str(meta.get("supplier_learning_id") or "")
    brand = str(getattr(self, "project_brand_context", None) or "")
    pname = str(self.project_name_var.get().strip() or self.project_name)
    out = []
    for inv in (getattr(self, "invoices", []) or []):
        for r in (inv.get("positions") or []):
            item = str(r.get("item") or "").strip()
            if not item:
                continue
            supplier = str(r.get("supplier") or inv.get("supplier") or "").strip()
            out.append({
                "project_key": key, "brand": brand, "project_name": pname,
                "supplier": supplier, "supplier_norm": _v3064_norm_supplier(supplier),
                "invoice_date": str(r.get("date") or inv.get("date") or "").strip(),
                "invoice_no": str(r.get("invoice") or inv.get("invoice") or "").strip(),
                "buyer": str(r.get("buyer") or inv.get("buyer") or "").strip(),
                "item": item, "qty": str(r.get("qty") or "").strip(), "unit": str(r.get("unit") or "").strip(),
            })
    return out


def _v3064_purchases_store(self):
    rows = self._v3064_current_purchases()
    key = rows[0]["project_key"] if rows else str((self.project_metadata or {}).get("supplier_learning_id") or "")
    if not key:
        return
    try:
        with self._supplier_db_connect() as conn:
            _v3064_purchases_init(conn)
            conn.execute("DELETE FROM supplier_purchases WHERE project_key=?", (key,))
            conn.executemany("""INSERT INTO supplier_purchases(project_key,brand,project_name,supplier,supplier_norm,
                                invoice_date,invoice_no,buyer,item,qty,unit) VALUES(?,?,?,?,?,?,?,?,?,?,?)""",
                             [(r["project_key"], r["brand"], r["project_name"], r["supplier"], r["supplier_norm"],
                               r["invoice_date"], r["invoice_no"], r["buyer"], r["item"], r["qty"], r["unit"]) for r in rows])
    except Exception as exc:
        try: self._print_debug_log(f"supplier_purchases: {exc!r}")
        except Exception: pass


def _v3064_all_purchases(self):
    """Закупки всех проектов из базы + актуальные данные открытого проекта."""
    current = self._v3064_current_purchases()
    cur_key = str((getattr(self, "project_metadata", None) or {}).get("supplier_learning_id") or "")
    rows = []
    try:
        with self._supplier_db_connect() as conn:
            _v3064_purchases_init(conn)
            rows = [dict(r) for r in conn.execute("SELECT * FROM supplier_purchases")]
    except Exception:
        rows = []
    rows = [r for r in rows if r.get("project_key") != cur_key] + current
    return rows


def _v3064_tree_icons(self):
    """Иконки дерева в стиле Finder: папка (контур), документ, таблица."""
    if getattr(self, "_v3064_icons", None):
        return self._v3064_icons
    from PIL import Image, ImageDraw, ImageTk
    def make(kind):
        s = 4; W = 18 * s
        im = Image.new("RGBA", (W, W), (0, 0, 0, 0)); d = ImageDraw.Draw(im)
        if kind == "folder":
            c = (214, 164, 64, 255)
            d.rounded_rectangle((1*s, 5*s, 17*s, 15*s), radius=2*s, outline=c, width=int(1.6*s))
            d.line((1.5*s, 5*s, 3*s, 3*s, 7*s, 3*s, 8.5*s, 5*s), fill=c, width=int(1.6*s), joint="curve")
        elif kind == "sheet":
            c = (88, 170, 110, 255)
            d.rounded_rectangle((3*s, 2*s, 15*s, 16*s), radius=2*s, outline=c, width=int(1.5*s))
            d.line((3*s, 7*s, 15*s, 7*s), fill=c, width=int(1.3*s)); d.line((3*s, 11.5*s, 15*s, 11.5*s), fill=c, width=int(1.3*s))
            d.line((8*s, 2*s, 8*s, 16*s), fill=c, width=int(1.3*s))
        else:
            c = (150, 150, 150, 255)
            d.rounded_rectangle((3*s, 2*s, 15*s, 16*s), radius=3*s, outline=c, width=int(1.5*s))
            for y in (6.5, 9.5, 12.5):
                d.line((6*s, y*s, 12*s, y*s), fill=c, width=int(1.2*s))
        return ImageTk.PhotoImage(im.resize((18, 18), Image.Resampling.LANCZOS))
    self._v3064_icons = {k: make(k) for k in ("folder", "doc", "sheet")}
    return self._v3064_icons


def _v3064_open_supplier_manager(self):
    win = tk.Toplevel(self)
    win.title("Общая база поставщиков")
    win.geometry("1180x560")
    try: win.transient(self)
    except Exception: pass
    top = ttk.Frame(win, padding=(10, 10, 10, 6)); top.pack(fill="x")
    ttk.Label(top, text="Общая база поставщиков программы", font=("Arial", 14, "bold")).pack(side="left")
    ttk.Button(top, text="+ Добавить", command=lambda: self._add_supplier_dialog(lambda _sid: refresh())).pack(side="right")
    ttk.Button(top, text="Свернуть всё", command=lambda: expand(False)).pack(side="right", padx=(0, 8))
    ttk.Button(top, text="Развернуть всё", command=lambda: expand(True)).pack(side="right", padx=(0, 6))
    ttk.Label(win, text="Поставщик → проект и счёт (тип проекта • название • дата счёта • № счёта) → закупки "
                        "(№ счёта • кто купил • что купили • кол-во). Закупки собираются из счетов всех "
                        "сохранённых и открытых на этом компьютере проектов.",
              foreground="#666666", wraplength=1120, justify="left").pack(fill="x", padx=10, pady=(0, 7))
    holder = ttk.Frame(win, padding=(10, 0, 10, 10)); holder.pack(fill="both", expand=True)
    cols = ("inn", "contact", "phone", "email", "uses", "last_used", "note")
    tree = ttk.Treeview(holder, columns=cols, show="tree headings")
    tree.heading("#0", text="Поставщик / проект / закупка", anchor="w")
    tree.column("#0", width=520, anchor="w", stretch=True)
    for c, title, w in [("inn", "ИНН", 105), ("contact", "Контакт", 120), ("phone", "Телефон", 110),
                        ("email", "E-mail", 140), ("uses", "Исп.", 50), ("last_used", "Последнее использование", 140),
                        ("note", "Примечание", 150)]:
        tree.heading(c, text=title); tree.column(c, width=w, anchor="w", stretch=False)
    tree.tag_configure("supplier", font=("Arial", 11, "bold"))
    tree.tag_configure("nodb", foreground="#8A6D3B")
    ys = ttk.Scrollbar(holder, orient="vertical", command=tree.yview)
    xs = ttk.Scrollbar(holder, orient="horizontal", command=tree.xview)
    tree.configure(yscrollcommand=ys.set, xscrollcommand=xs.set)
    xs.pack(side="bottom", fill="x"); ys.pack(side="right", fill="y"); tree.pack(side="left", fill="both", expand=True)
    icons = self._v3064_tree_icons()

    def expand(flag):
        def walk(iid):
            for ch in tree.get_children(iid):
                tree.item(ch, open=flag); walk(ch)
        walk("")

    def refresh():
        opened = {i for i in tree.get_children("") if tree.item(i, "open")}
        tree.delete(*tree.get_children())
        purchases = self._v3064_all_purchases()
        by_norm = {}
        for p in purchases:
            by_norm.setdefault(p["supplier_norm"], []).append(p)
        suppliers = sorted(self._supplier_db_all().items(), key=lambda kv: str(kv[1].get("name", "")).casefold())
        used_norms = set()
        entries = []
        for sid, rec in suppliers:
            norm = _v3064_norm_supplier(rec.get("name", ""))
            used_norms.add(norm)
            entries.append((f"s:{sid}", rec.get("name", ""), rec, by_norm.get(norm, []), False))
        for norm, plist in sorted(by_norm.items(), key=lambda kv: kv[0]):
            if norm and norm not in used_norms:
                entries.append((f"n:{norm}", plist[0]["supplier"] or "(поставщик не указан)", {}, plist, True))
        for iid, name, rec, plist, nodb in entries:
            values = ("", "", "", "", "", "", "")
            if rec:
                uses, last_used = self._supplier_db_stats_for_supplier(iid[2:])
                values = (rec.get("inn", ""), rec.get("contact", ""), rec.get("phone", ""), rec.get("email", ""),
                          uses, last_used.replace("T", " ")[:16] if last_used else "", rec.get("note", ""))
            label = name + ("   (нет в базе поставщиков)" if nodb else "") + (f"   — счетов: {len({(p['project_key'], p['invoice_no'], p['invoice_date']) for p in plist})}" if plist else "")
            tree.insert("", "end", iid=iid, text=label, image=icons["folder"], values=values,
                        open=(iid in opened), tags=("supplier",) + (("nodb",) if nodb else ()))
            groups = {}
            for p in plist:
                groups.setdefault((p["brand"], p["project_name"], p["invoice_date"], p["invoice_no"], p["project_key"]), []).append(p)
            for gi, (gkey, items) in enumerate(sorted(groups.items(), key=lambda kv: (kv[0][1].casefold(), kv[0][2], kv[0][3]))):
                brand, pname, idate, ino, _pk = gkey
                gtext = " • ".join(x for x in (brand or "—", pname or "без названия",
                                               f"счёт от {idate}" if idate else "дата не указана",
                                               f"№ {ino}" if ino else "без номера"))
                giid = f"{iid}|g{gi}"
                tree.insert(iid, "end", iid=giid, text=gtext, image=icons["folder"])
                for k, p in enumerate(items):
                    qty = f"{p['qty']} {p['unit']}".strip()
                    item = p["item"] if len(p["item"]) <= 70 else p["item"][:67] + "…"
                    t = " • ".join(x for x in (f"№ {p['invoice_no']}" if p["invoice_no"] else "без №",
                                               p["buyer"] or "покупатель не указан", item, qty or "—"))
                    tree.insert(giid, "end", iid=f"{giid}|{k}", text=t, image=icons["doc"])
    def on_double(event):
        iid = tree.identify_row(event.y)
        if iid and iid.startswith("s:") and "|" not in iid:
            try:
                self._v3012_supplier_card(iid[2:], on_change=refresh, picker=win)
            except Exception:
                pass
            return "break"
    tree.bind("<Double-1>", on_double)
    refresh()
    win.bind("<Escape>", lambda e: win.destroy())
    return win


# --- хуки: закупки проекта попадают в базу при сохранении и открытии
def _v3064_wrap_store(orig, check_ok=True):
    def wrapper(self, *a, **k):
        res = orig(self, *a, **k)
        if (res if check_ok else True):
            try: self._v3064_purchases_store()
            except Exception: pass
        return res
    return wrapper
ScreenDesigner._save_project = _v3064_wrap_store(ScreenDesigner._save_project)
ScreenDesigner._save_project_as = _v3064_wrap_store(ScreenDesigner._save_project_as)

_v3064_orig_open_project = ScreenDesigner._open_project
def _v3064_open_project(self):
    before = id(getattr(self, "project_metadata", None))
    _v3064_orig_open_project(self)
    if id(getattr(self, "project_metadata", None)) != before and getattr(self, "current_project_path", None):
        try: self._v3064_purchases_store()
        except Exception: pass
ScreenDesigner._open_project = _v3064_open_project

for _name, _fn in list({
    "_v3064_spec_temp_file": _v3064_spec_temp_file,
    "_v3064_ensure_preview": _v3064_ensure_preview,
    "_v3063_spec_render": _v3064_spec_render,
    "_v3063_upload_specification": _v3064_upload_specification,
    "_v3064_quick_look": _v3064_quick_look,
    "_open_specification_viewer": _v3064_open_specification_viewer,
    "_v3064_current_purchases": _v3064_current_purchases,
    "_v3064_purchases_store": _v3064_purchases_store,
    "_v3064_all_purchases": _v3064_all_purchases,
    "_v3064_tree_icons": _v3064_tree_icons,
    "_open_supplier_manager": _v3064_open_supplier_manager,
}.items()):
    setattr(ScreenDesigner, _name, _fn)


# =====================================================================
# V30.65 — список по поставщику: погонаж расписывается по артикулам и длинам реза,
# в конце — итоги по каждому материалу (м.п., хлысты по раскрою, хлысты +20%).
# Погонаж = материалы карты раскроя: П-профиль, профильная труба, уголки,
# Гефест, шпильки, DIN-рейка. Остальные позиции — как в V30.63.
# =====================================================================

CUT_RESERVE = 1.20


def _v3065_products(self):
    out = []
    for _o, _i, kind, i, rec in self._journal_product_records_in_order():
        if not _product_calc_enabled(rec):
            continue
        if kind == "dynamic":
            article = str(rec.get("module_article", "") or rec.get("screen_article", "") or f"LED {i+1}").strip()
            try: qty = max(1, int(rec.get("quantity", 1) or 1))
            except Exception: qty = 1
        else:
            article = str(rec.get("article", "") or rec.get("name", "") or f"Указатель {i+1}").strip()
            raw = str(rec.get("quantity", "") or "").strip()
            try: qty = max(1, int(raw)) if raw else 1
            except Exception: qty = 1
        out.append({"kind": kind, "index": i, "rec": rec, "article": article, "qty": qty})
    return out


def _v3065_kerf(self):
    try:
        return max(0, int(self.trial_kerf_var.get()))
    except Exception:
        return 3


def _v3065_stock_len(self, key):
    try:
        v = int(self._trial_get_stock_length(key))
        if v > 0:
            return v
    except Exception:
        pass
    return int(self._cut_stock_catalog()[key][1])


def _v3065_supplier_rows(self, supplier_name):
    base = [dict(r, kind="item") for r in self._v3063_supplier_rows_v3063(supplier_name)]
    catalog = self._cut_stock_catalog()
    products = self._v3065_products()
    article_order = {}
    for p in products:
        article_order.setdefault(p["article"], len(article_order))

    # Раскрой по артикулам: key → article → [(длина, радиус|None)]
    cut_cache = {}
    def cuts_for(article, key):
        if article not in cut_cache:
            per = {}
            for p in products:
                if p["article"] != article:
                    continue
                try:
                    entries = self._cut_map_entries_for_product(p["kind"], p["index"], p["rec"])
                except Exception:
                    entries = []
                for e in entries:
                    radius = e.get("bend_radius_mm")
                    per.setdefault(e["key"], []).extend((int(c), radius) for c in e.get("cuts", []))
            cut_cache[article] = per
        return cut_cache[article].get(key, [])

    items, linear = [], {}
    for r in base:
        key = self._cut_material_key(r["name"])
        if key in catalog and cuts_for(r["article"], key):
            linear.setdefault(r["group"], {}).setdefault(r["article"], {}).setdefault(key, r)
        else:
            items.append(r)

    groups_order = []
    for r in base:
        if r["group"] not in groups_order:
            groups_order.append(r["group"])

    out = []
    totals = {}
    for group in groups_order:
        out.extend(r for r in items if r["group"] == group)
        arts = linear.get(group, {})
        for article in sorted(arts, key=lambda a: article_order.get(a, 10**6)):
            n_prod = sum(p["qty"] for p in products if p["article"] == article)
            first = next(iter(arts[article].values()))
            out.append({"kind": "article", "group": group, "article": article, "name": f"Изделий: {n_prod} шт.",
                        "unit": "изд.", "qty": float(n_prod), "weight": None, "source": first["source"],
                        "supplier": supplier_name})
            for key, src_row in sorted(arts[article].items(), key=lambda kv: list(catalog).index(kv[0])):
                material = catalog[key][0]
                cuts = cuts_for(article, key)
                counted = {}
                for length, radius in cuts:
                    counted[(length, radius)] = counted.get((length, radius), 0) + 1
                for (length, radius), cnt in sorted(counted.items(), key=lambda kv: (-kv[0][0], kv[0][1] or 0)):
                    meters = length * cnt / 1000.0
                    label = f"{material} — {length} мм" + (f" (полукольцо R{self._format_component_qty(round(radius, 1))})" if radius else "")
                    out.append({"kind": "cut", "group": group, "article": "", "name": label, "unit": "шт.",
                                "qty": float(cnt), "weight": self._component_weight_kg(material, "м.п.", meters),
                                "source": src_row["source"], "supplier": supplier_name})
                t = totals.setdefault(key, {"cuts": [], "material": material})
                t["cuts"].extend(length for length, _r in cuts)

    if totals:
        kerf = self._v3065_kerf()
        group = "Итого по погонажу"
        for key in [k for k in catalog if k in totals]:
            t = totals[key]
            stock = self._v3065_stock_len(key)
            bins, oversize = self._cut_optimize(t["cuts"], stock, kerf)
            bars = len(bins)
            meters = sum(t["cuts"]) / 1000.0
            over_txt = f"; + {len(oversize)} отр. длинее хлыста" if oversize else ""
            out.append({"kind": "total", "group": group, "article": "", "name": f"{t['material']} — всего расчётное количество",
                        "unit": "м.п.", "qty": meters, "weight": self._component_weight_kg(t["material"], "м.п.", meters),
                        "source": "", "supplier": supplier_name})
            out.append({"kind": "total", "group": group, "article": "",
                        "name": f"{t['material']} — всего требуется в хлыстах (хлыст {stock} мм, пропил {kerf} мм){over_txt}",
                        "unit": "хлыст", "qty": float(bars), "weight": None, "source": "", "supplier": supplier_name})
            out.append({"kind": "total", "group": group, "article": "",
                        "name": f"{t['material']} — всего требуется +20% (хлыст {stock} мм)",
                        "unit": "хлыст", "qty": float(math.ceil(bars * CUT_RESERVE - 1e-9)), "weight": None,
                        "source": "", "supplier": supplier_name})
    return out


def _v3065_build_supplier_pages(self, rows, supplier_name):
    from PIL import Image, ImageDraw
    W, H = 2480, 3508
    margin = 120; header_h = 290; row_h = 76
    widths = [80, 330, 820, 120, 190, 180, 220, 300]
    cols = [margin]
    for w in widths:
        cols.append(cols[-1] + w)
    cols[-1] = W - margin
    labels = ["№", "Артикул", "Комплектующая", "Ед.", "Кол-во", "Вес, кг", "Источник", "Поставщик"]
    aligns = ["center", "left", "left", "center", "center", "center", "left", "left"]
    project = str(self.project_name_var.get().strip() or self.project_name)
    fills = {"article": (243, 246, 250), "total": (255, 242, 204)}
    pages = []

    def fit(text, maxw, size=24, bold=False):
        f = self._font_for_print(size, bold); t = str(text or "")
        while size > 13 and f.getbbox(t)[2] > maxw:
            size -= 1; f = self._font_for_print(size, bold)
        return f

    def new_page(page_no):
        im = Image.new("RGB", (W, H), "white"); d = ImageDraw.Draw(im)
        d.text((margin, 80), "КОМПЛЕКТУЮЩИЕ ПО ПОСТАВЩИКУ", font=self._font_for_print(44, True), fill="black")
        small = self._font_for_print(25, False)
        d.text((margin, 145), f"Проект: {project}", font=small, fill="black")
        d.text((margin, 185), f"Поставщик: {supplier_name}", font=self._font_for_print(27, True), fill="black")
        d.text((margin, 225), f"Страница {page_no}", font=small, fill="black")
        y = header_h
        for i in range(len(labels)):
            d.rectangle((cols[i], y, cols[i + 1], y + row_h), outline="black", width=2)
            d.text((cols[i] + 8, y + 20), labels[i], font=fit(labels[i], cols[i + 1] - cols[i] - 16, 24, True), fill="black")
        im._selectable_text_layer = []
        return im, d, y + row_h

    page, d, y = new_page(1)
    page_no = 1; n = 0; last_group = None
    for rec in rows:
        needed = row_h + (row_h if rec["group"] != last_group else 0)
        if y + needed > H - margin:
            pages.append(page); page_no += 1
            page, d, y = new_page(page_no); last_group = None
        if rec["group"] != last_group:
            d.rectangle((margin, y, W - margin, y + row_h), fill=(235, 239, 244), outline="black", width=2)
            d.text((margin + 10, y + 20), rec["group"], font=self._font_for_print(27, True), fill="black")
            page._selectable_text_layer.append({"text": rec["group"], "bbox": (margin + 10, y + 10, W - margin - 10, y + row_h - 10), "font_size": 27})
            y += row_h; last_group = rec["group"]
        kind = rec.get("kind", "item")
        bold = kind in ("article", "total")
        if kind in ("item", "cut"):
            n += 1
        num = str(n) if kind in ("item", "cut") else ""
        weight = self._format_component_weight(rec["weight"]) if rec.get("weight") is not None else ""
        qty = self._format_component_qty(round(rec["qty"], 3)) if rec.get("qty") is not None else ""
        name = ("    " + rec["name"]) if kind == "cut" else rec["name"]
        vals = [num, rec.get("article", ""), name, rec["unit"], qty, weight, rec.get("source", ""), rec.get("supplier", "")]
        for i, val in enumerate(vals):
            fill = fills.get(kind)
            d.rectangle((cols[i], y, cols[i + 1], y + row_h), outline="black", width=2, fill=fill)
            f = fit(val, cols[i + 1] - cols[i] - 16, 24, bold)
            box = d.textbbox((0, 0), val, font=f); tw = box[2] - box[0]
            x = cols[i] + 8 if aligns[i] == "left" else (cols[i] + cols[i + 1] - tw) // 2
            d.text((x, y + 22), val, font=f, fill="black")
            page._selectable_text_layer.append({"text": val, "bbox": (cols[i] + 5, y + 5, cols[i + 1] - 5, y + row_h - 5), "font_size": 24})
        y += row_h
    pages.append(page)
    return pages


def _v3065_save_supplier_xlsx(self, rows, supplier_name, path):
    from openpyxl import Workbook
    from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
    wb = Workbook(); ws = wb.active; ws.title = "По поставщику"
    thin = Side(style="thin", color="999999"); border = Border(left=thin, right=thin, top=thin, bottom=thin)
    ws["A1"] = "КОМПЛЕКТУЮЩИЕ ПО ПОСТАВЩИКУ"; ws["A1"].font = Font(bold=True, size=14)
    ws["A2"] = f"Проект: {self.project_name_var.get().strip() or self.project_name}    Поставщик: {supplier_name}"
    headers = ["№", "Артикул", "Комплектующая", "Ед.", "Кол-во", "Вес, кг", "Источник", "Поставщик"]
    for c, h in enumerate(headers, 1):
        cell = ws.cell(4, c, h); cell.font = Font(bold=True, color="FFFFFF")
        cell.fill = PatternFill("solid", fgColor="1F4E78"); cell.border = border
        cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
    fills = {"article": "F3F6FA", "total": "FFF2CC"}
    r = 5; n = 0; last_group = None
    for rec in rows:
        if rec["group"] != last_group:
            ws.cell(r, 1, rec["group"]).font = Font(bold=True)
            for c in range(1, 9):
                ws.cell(r, c).fill = PatternFill("solid", fgColor="E8EEF5"); ws.cell(r, c).border = border
            ws.merge_cells(start_row=r, start_column=1, end_row=r, end_column=8)
            r += 1; last_group = rec["group"]
        kind = rec.get("kind", "item")
        if kind in ("item", "cut"):
            n += 1
        vals = [n if kind in ("item", "cut") else None, rec.get("article", "") or None,
                ("    " + rec["name"]) if kind == "cut" else rec["name"], rec["unit"],
                round(rec["qty"], 3) if rec.get("qty") is not None else None,
                round(rec["weight"], 3) if rec.get("weight") is not None else None,
                rec.get("source", "") or None, rec.get("supplier", "")]
        for c, v in enumerate(vals, 1):
            cell = ws.cell(r, c, v); cell.border = border
            cell.alignment = Alignment(vertical="center", wrap_text=True, horizontal="center" if c in (1, 4, 5, 6) else "left")
            if kind in fills:
                cell.fill = PatternFill("solid", fgColor=fills[kind])
            if kind in ("article", "total"):
                cell.font = Font(bold=True)
        r += 1
    for c, w in enumerate([6, 26, 60, 8, 12, 12, 18, 30], 1):
        ws.column_dimensions[get_column_letter_v3063(c)].width = w
    ws.freeze_panes = "A5"
    wb.save(path)


ScreenDesigner._v3063_supplier_rows_v3063 = ScreenDesigner._v3063_supplier_rows
