# =====================================================================
# V30.74 — справочник: единое правило уголка 30×20×2 для прямоугольной
# статики МЦД (1 и 2 стороны). Заменяет старый текст в сохранённом
# пользовательском справочнике.
# =====================================================================
_V3074_ANGLE_RULE = (
    "Итоговая длина уголка = [2 × ((W − 180) + (H − 180)) / 1000] × 2. "
    "Правило одинаково для одностороннего и двустороннего изделия: 4 отрезка (W − 180) и 4 отрезка (H − 180). "
    "Для квадратного изделия со стороной менее 551 мм оба контура считаются по полным габаритам."
)


def _v3074_angle_rule(data):
    for section, rows in (data or {}).items():
        name = str(section)
        if not name.startswith("МЦД /") or "круглый" in name or "с подсветкой" not in name:
            continue
        for row in rows or []:
            if row and len(row) > 1 and str(row[0]).strip() == "Уголок алюминиевый 30×20×2 мм":
                if str(row[1]) != _V3074_ANGLE_RULE:
                    row[1] = _V3074_ANGLE_RULE
    return data


_v3074_orig_reference_defaults = ScreenDesigner._reference_defaults
ScreenDesigner._reference_defaults = lambda self: _v3074_angle_rule(_v3074_orig_reference_defaults(self))
_v3074_orig_reference_load = ScreenDesigner._reference_load
ScreenDesigner._reference_load = lambda self: _v3074_angle_rule(_v3074_orig_reference_load(self))



# =====================================================================
# V30.79 — шапка карты раскроя: блок «Изделия в раскрое» по артикулам.
# Название проекта перенесено в левый верхний угол, над заголовком,
# освободившаяся зона отдана под блок. Кегль и число колонок
# подбираются так, чтобы поместились ВСЕ артикулы листа.
# =====================================================================

V3079_TITLE = "ИЗДЕЛИЯ В РАСКРОЕ"
V3079_MAX_COLUMNS = 4
V3079_FONT_MAX_PT = 8.5
V3079_FONT_MIN_PT = 4.5

_v3079_quantities = {}      # артикул -> количество изделий в проекте
_v3079_order = {}           # артикул -> позиция в журнале проекта
_v3079_sheet_articles = {}  # материал -> артикулы изделий, детали которых режутся из него


def _v3079_articles_by_material(self):
    """Артикулы по материалам берутся из всех хлыстов, до объединения
    одинаковых схем: при объединении принадлежность деталей теряется."""
    out = {}
    for item in getattr(self, "wizard_bins", []) or []:
        try:
            material, _stock, bar = item
        except Exception:
            continue
        known = out.setdefault(str(material[0]), [])
        for segment in bar or []:
            article = str(segment[2] if len(segment) > 2 else "").strip()
            if article and article not in known:
                known.append(article)
    return out


def _v3079_collect_products(self):
    """Количества изделий по артикулам берутся из журнала проекта."""
    quantities, order = {}, {}
    try:
        products = self._v3065_products()
    except Exception:
        products = []
    for product in products:
        article = str(product.get("article", "") or "").strip()
        if not article:
            continue
        if article not in order:
            order[article] = len(order)
        try:
            qty = int(product.get("qty", 1) or 1)
        except Exception:
            qty = 1
        quantities[article] = quantities.get(article, 0) + qty
    return quantities, order


def _v3079_rows_for_groups(groups, material_key=""):
    """Артикулы, детали которых есть на этом листе, в порядке журнала проекта."""
    articles = list(_v3079_sheet_articles.get(str(material_key), []))
    if not articles:
        for group in groups or []:
            for segment in group.get("bar", []) or []:
                article = str(segment[2] if len(segment) > 2 else "").strip()
                if article and article not in articles:
                    articles.append(article)
    articles.sort(key=lambda a: _v3079_order.get(a, 10 ** 6))
    return [(a, _v3079_quantities.get(a)) for a in articles]


def _v3079_fit(d, rows, zone_w, zone_h):
    """Подбор кегля и числа колонок, при которых помещаются все артикулы."""
    mm = _v3048_mm
    gap = mm(3.0)
    # Предпочтительное число колонок: примерно по 6 строк в колонке,
    # чтобы блок заполнял зону, а не вытягивался одной узкой колонкой.
    preferred = min(V3079_MAX_COLUMNS, max(1, int(math.ceil(len(rows) / 6.0))))
    order = list(range(preferred, V3079_MAX_COLUMNS + 1)) + list(range(preferred - 1, 0, -1))
    best = None
    size = V3079_FONT_MAX_PT
    while size >= V3079_FONT_MIN_PT - 1e-9:
        k_font = _v3048_font(size)
        v_font = _v3048_font(size, True)
        t_font = _v3048_font(max(6.0, size * 0.85), True)
        line = _v3048_text_h(d, "Ag", k_font)
        row_h = line + max(mm(0.7), line * 0.35)
        title_h = _v3048_text_h(d, "Ag", t_font) + mm(1.4)
        for columns in order:
            per_col = int(math.ceil(len(rows) / float(columns)))
            if title_h + (per_col + 1) * row_h > zone_h:
                continue
            col_w = zone_w / float(columns)
            widest = 0.0
            for article, qty in rows:
                text = f"{qty} шт." if qty else "—"
                widest = max(widest, _v3048_text_w(d, str(article), k_font)
                             + mm(2.0) + _v3048_text_w(d, text, v_font))
            total_w = (_v3048_text_w(d, "Всего изделий", k_font) + mm(2.0)
                       + _v3048_text_w(d, f"{sum(q for _a, q in rows if q)} шт.", v_font))
            if max(widest, total_w) + gap <= col_w:
                return {"k_font": k_font, "v_font": v_font, "t_font": t_font,
                        "row_h": row_h, "title_h": title_h, "columns": columns,
                        "per_col": per_col, "col_w": col_w, "gap": gap, "size": size}
        size -= 0.25
    # Запасной вариант: минимальный кегль, максимум колонок.
    k_font = _v3048_font(V3079_FONT_MIN_PT)
    v_font = _v3048_font(V3079_FONT_MIN_PT, True)
    line = _v3048_text_h(d, "Ag", k_font)
    columns = V3079_MAX_COLUMNS
    best = {"k_font": k_font, "v_font": v_font, "t_font": _v3048_font(6.0, True),
            "row_h": line + mm(0.7), "title_h": _v3048_text_h(d, "Ag", k_font) + mm(1.4),
            "columns": columns, "per_col": int(math.ceil(len(rows) / float(columns))),
            "col_w": zone_w / float(columns), "gap": gap, "size": V3079_FONT_MIN_PT}
    return best


def _v3079_draw_products(image, rows, material, stock_mm=0, kerf_mm=0):
    """Блок артикулов в свободной зоне шапки листа."""
    from PIL import ImageDraw
    d = ImageDraw.Draw(image)
    mm = _v3048_mm
    W = image.size[0]
    M = mm(_V3048_MARGIN_MM)
    X0, X1 = M, W - M

    sk_w, sk_h = mm(55.0), mm(41.0)
    sk_x = X1 - sk_w
    right_limit = sk_x - (mm(12.0) if str(material[0]) == "u60" else 0.0) - mm(4.5)

    # Левая граница — правее всей левой части шапки.
    name_font = _v3048_font(10.5)
    info_font = _v3048_font(9.0)
    head_font = _v3048_font(13.5, True)
    full_name = _v3048_profile_names(material)[0]
    left_block = max(
        _v3048_text_w(d, "КАРТА РАСКРОЯ", head_font),
        _v3048_text_w(d, full_name, name_font),
        _v3048_text_w(d, f"Стандартный хлыст: {_v3048_group_int(int(stock_mm))} мм", info_font),
        mm(62.0) + _v3048_text_w(d, f"Пропил: {_v3048_group_int(int(kerf_mm))} мм", info_font),
    )
    x0 = X0 + left_block + mm(8.0)
    zone_w = right_limit - x0
    zone_h = sk_h + mm(1.0)
    if zone_w < mm(35.0) or not rows:
        return image

    fit = _v3079_fit(d, rows, zone_w, zone_h)
    top = M
    d.text((x0, top), V3079_TITLE, font=fit["t_font"], fill=_V3048_SUB)
    y = top + fit["title_h"]
    col_w, gap, row_h = fit["col_w"], fit["gap"], fit["row_h"]
    for i, (article, qty) in enumerate(rows):
        col, line = divmod(i, fit["per_col"])
        cx = x0 + col * col_w
        cy = y + line * row_h
        text = f"{qty} шт." if qty else "—"
        name = str(article)
        max_name = col_w - gap - _v3048_text_w(d, text, fit["v_font"]) - mm(1.5)
        while name and _v3048_text_w(d, name, fit["k_font"]) > max_name:
            name = name[:-1]
        d.text((cx, cy), name, font=fit["k_font"], fill=_V3048_INK)
        d.text((cx + col_w - gap - _v3048_text_w(d, text, fit["v_font"]), cy),
               text, font=fit["v_font"], fill=_V3048_INK)
        d.line([(cx, cy + row_h - mm(0.8)), (cx + col_w - gap, cy + row_h - mm(0.8))],
               fill=_V3048_SKETCH_LN, width=max(1, int(mm(0.15))))
    total = sum(q for _a, q in rows if q)
    ty = y + fit["per_col"] * row_h + mm(0.4)
    d.text((x0, ty), "Всего изделий", font=fit["k_font"], fill=_V3048_SUB)
    if total:
        d.text((x0 + col_w - gap - _v3048_text_w(d, f"{total} шт.", fit["v_font"]), ty),
               f"{total} шт.", font=fit["v_font"], fill=_V3048_INK)
    return image


_v3079_orig_build_page = _v3048_build_page


def _v3079_build_page(material, stock, groups, kerf, project_line):
    image = _v3079_orig_build_page(material, stock, groups, kerf, project_line)
    try:
        rows = _v3079_rows_for_groups(groups, material[0])
        if rows:
            _v3079_draw_products(image, rows, material, stock, kerf)
    except Exception:
        pass
    return image


_v3048_build_page = _v3079_build_page


_v3079_orig_print_cutmap = ScreenDesigner._v3048_print_cutmap_pdf


def _v3079_print_cutmap_pdf(self):
    global _v3079_quantities, _v3079_order, _v3079_sheet_articles
    try:
        _v3079_quantities, _v3079_order = _v3079_collect_products(self)
        _v3079_sheet_articles = _v3079_articles_by_material(self)
    except Exception:
        _v3079_quantities, _v3079_order, _v3079_sheet_articles = {}, {}, {}
    try:
        return _v3079_orig_print_cutmap(self)
    finally:
        _v3079_quantities, _v3079_order, _v3079_sheet_articles = {}, {}, {}


ScreenDesigner._v3048_print_cutmap_pdf = _v3079_print_cutmap_pdf
ScreenDesigner._v3079_collect_products = _v3079_collect_products
ScreenDesigner._v3079_articles_by_material = _v3079_articles_by_material


# =====================================================================
# V30.77 — журнал изделия: в блоке «Данные указателя» печатаются готовые
# детали после раскроя для каждого погонного материала изделия.
# Формат: «Уголок 30×20×2 — ширина 4×2320 мм; высота 4×220 мм».
# Значения берутся из карты раскроя, поэтому всегда совпадают с хлыстами.
# Кроме того, в имя PDF карты раскроя добавляются размеры материала.
# =====================================================================

V3077_MATERIAL_LABELS = {
    "angle30": "Уголок 30×20×2",
    "angle40": "Уголок 40×20×2",
    "u60": "П-профиль 60×20×2",
    "tube40": "Каркас 40×20×2",
    "gefest": "Профиль Гефест",
    "rod10": "Шпилька М10",
    "rod8": "Шпилька М8",
    "din": "DIN-рейка",
}
V3077_SKIP_KEYS = ()   # V30.87: DIN-рейка выводится как отрезки 100 мм
# Материалы, которые режутся контуром по габариту изделия.
V3077_CONTOUR_KEYS = ("angle30", "angle40", "u60", "tube40")


def _v3077_material_size(key):
    """«30×20×2 мм» -> «30x20x2» для имени файла."""
    material = next((m for m in TRIAL_MATERIALS if m[0] == str(key)), None)
    if not material:
        return ""
    size = str(material[3] or "").split(",")[0]
    if str(key) == "din":
        return "DIN"
    size = size.replace(" мм", "").replace("×", "x").replace("х", "x")
    return re.sub(r"\s+", "", size)


def _v3077_num(value):
    value = float(value or 0)
    return str(int(round(value))) if abs(value - round(value)) < 1e-9 else f"{value:.1f}".replace(".", ",")


def _v3077_cut_rows(self, sign):
    """Готовые детали изделия после раскроя: [(материал, описание), …].

    Количества — на одно изделие, независимо от количества в журнале.
    """
    rows = []
    try:
        record = dict(sign or {})
        record["quantity"] = "1"
        entries = self._cut_map_entries_for_product("static", 0, record)
    except Exception:
        return rows
    try:
        width = float(record.get("width", 0) or 0)
        height = float(record.get("height", 0) or 0)
    except Exception:
        width = height = 0.0
    for entry in entries:
        key = str(entry.get("key", ""))
        if key in V3077_SKIP_KEYS:
            continue
        label = V3077_MATERIAL_LABELS.get(key) or str(entry.get("material", ""))
        cuts = [int(round(float(c))) for c in entry.get("cuts", []) if float(c) > 0]
        if not cuts:
            continue
        radius = entry.get("bend_radius_mm")
        counted = {}
        for length in cuts:
            counted[length] = counted.get(length, 0) + 1
        lengths = sorted(counted, reverse=True)
        contour = key in V3077_CONTOUR_KEYS and not radius
        first, second = ("ширина", "высота") if width >= height else ("высота", "ширина")
        if not contour:
            parts = [f"{counted[length]}×{length} мм" + (f" (полукольцо R{_v3077_num(radius)})" if radius else "")
                     for length in lengths]
        elif len(lengths) == 1:
            # Квадратное изделие: контур делится поровну между сторонами.
            half = counted[lengths[0]] // 2
            parts = ([f"{first} {half}×{lengths[0]} мм", f"{second} {half}×{lengths[0]} мм"]
                     if half else [f"{counted[lengths[0]]}×{lengths[0]} мм"])
        else:
            long_side, short_side = lengths[0], lengths[-1]
            parts = [f"{first} {counted[long_side]}×{long_side} мм",
                     f"{second} {counted[short_side]}×{short_side} мм"]
            for middle in lengths[1:-1]:
                parts.append(f"{counted[middle]}×{middle} мм")
        rows.append((label, "; ".join(parts)))
    return rows


ScreenDesigner._v3077_cut_rows = _v3077_cut_rows


# =====================================================================
# V30.80 — миграция справочника через файл проекта.
#   • В .ledproj кладётся снимок справочника (сжатый), его хэш,
#     журнал правок и версия программы.
#   • При открытии проекта справочник из файла сравнивается с вашим.
#     Совпали — ничего не показывается. Разошлись — окно отличий
#     с выбором по строкам и галочкой «сохранить в мой справочник».
#   • Отдельной строкой предупреждение о другой версии программы.
# Расчёты и остальные данные проекта не затрагиваются.
# =====================================================================

import gzip as _v3080_gzip

V3080_FIELDS = ((1, "правило"), (2, "кол-во"), (3, "ед."), (4, "вес"))


def _v3080_row_list(row):
    out = list(row or [])
    while len(out) < 5:
        out.append("")
    return [str(x) for x in out[:5]]


def _v3080_sections_snapshot(data):
    """{раздел: {позиция: строка}} — сравнимый вид справочника."""
    out = {}
    for section, rows in (data or {}).items():
        bucket = out.setdefault(str(section), {})
        seen = {}
        for row in rows or []:
            if not isinstance(row, (list, tuple)) or not row:
                continue
            name = str(row[0]).strip()
            if not name:
                continue
            seen[name] = seen.get(name, 0) + 1
            key = name if seen[name] == 1 else f"{name} #{seen[name]}"
            bucket[key] = _v3080_row_list(row)
    return out


def _v3080_pack_reference(self):
    """Снимок справочника для файла проекта."""
    data = getattr(self, "_reference_data", None) or {}
    payload = {
        "sections": data,
        "history": list(getattr(self, "_reference_history", []) or [])[-400:],
    }
    text = json.dumps(payload, ensure_ascii=False, sort_keys=True)
    return {
        "app": APP_TITLE,
        "hash": hashlib.sha256(text.encode("utf-8")).hexdigest()[:32],
        "gz": base64.b64encode(_v3080_gzip.compress(text.encode("utf-8"))).decode("ascii"),
    }


def _v3080_unpack_reference(block):
    if not isinstance(block, dict):
        return None, []
    blob = block.get("gz")
    if not blob:
        return None, []
    try:
        text = _v3080_gzip.decompress(base64.b64decode(blob)).decode("utf-8")
        payload = json.loads(text)
    except Exception:
        return None, []
    sections = payload.get("sections")
    if not isinstance(sections, dict):
        return None, []
    return sections, list(payload.get("history", []) or [])


def _v3080_reference_diff(mine, theirs):
    """Расхождения справочников: [{section, name, mine, theirs, fields}]."""
    diffs = []
    for section in sorted(set(mine) | set(theirs)):
        my_rows = mine.get(section, {})
        their_rows = theirs.get(section, {})
        for name in sorted(set(my_rows) | set(their_rows)):
            a, b = my_rows.get(name), their_rows.get(name)
            if a == b:
                continue
            fields = []
            if a and b:
                for index, label in V3080_FIELDS:
                    if a[index] != b[index]:
                        fields.append((label, a[index], b[index]))
                if not fields:
                    continue
            diffs.append({"section": section, "name": name, "mine": a, "theirs": b, "fields": fields})
    return diffs


def _v3080_who_when(history, section, name):
    """Кто и когда правил позицию — по журналу правок справочника из файла."""
    best = None
    plain = str(name).split(" #")[0]
    for entry in history or []:
        if str(entry.get("section", "")) != str(section):
            continue
        row_name = str(entry.get("name", "") or "")
        if row_name and row_name != plain:
            continue
        if best is None or str(entry.get("date", "")) >= str(best.get("date", "")):
            best = entry
    if not best:
        return "", ""
    return str(best.get("by", "") or ""), str(best.get("date", "") or "")


def _v3080_apply_reference(self, taken, theirs_sections):
    """Применяет принятые позиции к справочнику открытого проекта."""
    data = getattr(self, "_reference_data", None)
    if not isinstance(data, dict):
        return 0
    applied = 0
    for section, name in taken:
        plain = str(name).split(" #")[0]
        their_row = (theirs_sections.get(section) or {}).get(name)
        rows = data.setdefault(section, [])
        position = next((i for i, r in enumerate(rows)
                         if r and str(r[0]).strip() == plain), None)
        if their_row is None:
            if position is not None:
                rows.pop(position)
                applied += 1
            continue
        if position is None:
            rows.append(list(their_row))
        else:
            rows[position] = list(their_row)
        applied += 1
    return applied


def _v3080_reference_window(self, diffs, history, file_app):
    """Окно отличий справочника. Возвращает (принятые, сохранять_ли) или None."""
    win = tk.Toplevel(self)
    win.title("Справочник проекта отличается от вашего")
    win.geometry("1420x700")
    win.transient(self)

    head = ttk.Frame(win, padding=(10, 10, 10, 4))
    head.pack(fill="x")
    ttk.Label(head, text="Справочник в файле проекта отличается от вашего",
              font=("Arial", 14, "bold")).pack(anchor="w")
    ttk.Label(head, text="Выберите, по каким нормам считать этот проект. "
                         "Расхождения показаны построчно.", foreground="#555555").pack(anchor="w")
    if file_app and file_app != APP_TITLE:
        ttk.Label(head, text=f"Внимание: файл сохранён в «{file_app}», у вас «{APP_TITLE}». "
                             "Часть правил задана в коде программы, справочник их не покрывает.",
                  foreground="#A33").pack(anchor="w", pady=(4, 0))

    body = ttk.Frame(win, padding=(10, 4, 10, 4))
    body.pack(fill="both", expand=True)
    cols = ("section", "name", "what", "mine", "theirs", "who", "when", "take")
    tree = ttk.Treeview(body, columns=cols, show="headings", selectmode="extended")
    for col, text, width, anchor in (
            ("section", "Раздел", 230, "w"), ("name", "Позиция", 230, "w"),
            ("what", "Что отличается", 150, "w"), ("mine", "У вас", 240, "w"),
            ("theirs", "В файле", 240, "w"), ("who", "Кто правил", 130, "w"),
            ("when", "Когда", 110, "center"), ("take", "Решение", 130, "center")):
        tree.heading(col, text=text)
        tree.column(col, width=width, anchor=anchor)
    vsb = ttk.Scrollbar(body, orient="vertical", command=tree.yview)
    tree.configure(yscrollcommand=vsb.set)
    tree.pack(side="left", fill="both", expand=True)
    vsb.pack(side="right", fill="y")

    state = {}
    for i, d in enumerate(diffs):
        iid = f"r{i}"
        who, when = _v3080_who_when(history, d["section"], d["name"])
        if d["fields"]:
            what = ", ".join(f for f, _a, _b in d["fields"])
            mine_text = "; ".join(_v3073_short(a, 28) for _f, a, _b in d["fields"])
            theirs_text = "; ".join(_v3073_short(b, 28) for _f, _a, b in d["fields"])
        elif d["mine"] is None:
            what, mine_text, theirs_text = "нет у вас, есть в файле", "— нет —", _v3073_short(d["theirs"][1], 28)
        else:
            what, mine_text, theirs_text = "есть у вас, нет в файле", _v3073_short(d["mine"][1], 28), "— нет —"
        state[iid] = dict(d, take="mine")
        tree.insert("", "end", iid=iid, values=(
            d["section"], d["name"], what, mine_text, theirs_text,
            who or "—", _v3073_when_text(when) or "—", "оставить своё"))

    def set_take(iids, value):
        for iid in iids:
            if iid in state:
                state[iid]["take"] = value
                values = list(tree.item(iid, "values"))
                values[7] = "из файла" if value == "theirs" else "оставить своё"
                tree.item(iid, values=values)

    tree.bind("<Double-1>", lambda e: [set_take([iid], "mine" if state[iid]["take"] == "theirs" else "theirs")
                                       for iid in tree.selection()])

    save_var = tk.BooleanVar(value=False)
    result = {"value": None}

    def finish():
        taken = [(s["section"], s["name"]) for s in state.values() if s["take"] == "theirs"]
        result["value"] = (taken, bool(save_var.get()))
        win.destroy()

    bar = ttk.Frame(win, padding=(10, 4, 10, 10))
    bar.pack(fill="x")
    ttk.Button(bar, text="Взять из файла", command=lambda: set_take(tree.selection(), "theirs")).pack(side="left")
    ttk.Button(bar, text="Оставить своё", command=lambda: set_take(tree.selection(), "mine")).pack(side="left", padx=(6, 0))
    ttk.Button(bar, text="Всё из файла", command=lambda: set_take(list(state), "theirs")).pack(side="left", padx=(18, 0))
    ttk.Button(bar, text="Всё своё", command=lambda: set_take(list(state), "mine")).pack(side="left", padx=(6, 0))
    ttk.Checkbutton(bar, text="Сохранить принятое в мой справочник", variable=save_var).pack(side="left", padx=(20, 0))
    ttk.Button(bar, text="Считать по своему", command=win.destroy).pack(side="right")
    ttk.Button(bar, text="Применить", command=finish).pack(side="right", padx=(0, 8))

    win.bind("<Escape>", lambda e: win.destroy())
    try:
        win.grab_set()
    except Exception:
        pass
    self.wait_window(win)
    return result["value"]


def _v3080_check_project_reference(self, path):
    """Сравнение справочника проекта с вашим при открытии файла."""
    payload = _v3073_read_project_file(path)
    if payload is None:
        return
    block = payload.get("reference")
    sections, history = _v3080_unpack_reference(block)
    if not sections:
        return
    mine = _v3080_sections_snapshot(getattr(self, "_reference_data", {}) or {})
    theirs = _v3080_sections_snapshot(sections)
    diffs = _v3080_reference_diff(mine, theirs)
    file_app = str((block or {}).get("app", "") or "")
    if not diffs:
        if file_app and file_app != APP_TITLE:
            messagebox.showinfo(
                "Справочник проекта",
                f"Справочник совпадает с вашим.\n\nФайл сохранён в «{file_app}», у вас «{APP_TITLE}». "
                "Часть правил задана в коде программы, справочник их не покрывает.")
        return
    answer = _v3080_reference_window(self, diffs, history, file_app)
    if not answer:
        return
    taken, save_local = answer
    if not taken:
        return
    applied = _v3080_apply_reference(self, taken, theirs)
    try:
        self._reference_refresh()
    except Exception:
        pass
    try:
        self._refresh_components_table()
    except Exception:
        pass
    if save_local:
        try:
            self._reference_save()
        except Exception as exc:
            messagebox.showerror("Справочник", f"Не удалось сохранить справочник:\n{exc}")
            return
    messagebox.showinfo(
        "Справочник проекта",
        f"Принято из файла позиций: {applied}.\n"
        + ("Изменения сохранены в ваш справочник." if save_local
           else "Изменения действуют только для открытого проекта."))


# --- снимок справочника уезжает вместе с проектом
_v3080_orig_project_payload = ScreenDesigner._project_payload


def _v3080_project_payload(self):
    payload = _v3080_orig_project_payload(self)
    try:
        payload["reference"] = _v3080_pack_reference(self)
        payload["app"] = APP_TITLE
    except Exception:
        pass
    return payload


ScreenDesigner._project_payload = _v3080_project_payload


_v3080_orig_open_project = ScreenDesigner._open_project


def _v3080_open_project(self):
    before = str(getattr(self, "current_project_path", "") or "")
    _v3080_orig_open_project(self)
    opened = str(getattr(self, "current_project_path", "") or "")
    if opened and opened != before:
        try:
            _v3080_check_project_reference(self, opened)
        except Exception as exc:
            try:
                self._print_debug_log(f"v3080 reference: {exc!r}")
            except Exception:
                pass


ScreenDesigner._open_project = _v3080_open_project

for _name, _fn in list({
    "_v3080_pack_reference": _v3080_pack_reference,
    "_v3080_check_project_reference": _v3080_check_project_reference,
    "_v3080_apply_reference": _v3080_apply_reference,
}.items()):
    setattr(ScreenDesigner, _name, _fn)



# =====================================================================
# V30.81 — журнал проектов: ручная правка записи под паролем.
# Меняются название проекта, дата спецификации, дата создания и
# плановая поставка. Правленые поля помечаются и больше не
# затираются при сохранении или открытии проекта.
# Файл проекта на диске не изменяется.
# =====================================================================

V3081_FIELDS = (
    ("name", "Название проекта", "text"),
    ("spec_date", "Дата спецификации", "date"),
    ("created_at", "Дата создания", "date"),
    ("delivery_date", "Плановая поставка", "date"),
)


def _v3081_parse_date(text, previous=""):
    """«ДД.ММ.ГГГГ» → хранимый вид. Пустое поле очищает значение."""
    s = str(text or "").strip()
    if not s:
        return ""
    prev = str(previous or "").strip()
    try:
        day = datetime.strptime(s, "%d.%m.%Y")
    except Exception:
        return s
    # Если раньше тут была ISO-дата, сохраняем ISO, иначе — как ввели.
    try:
        datetime.fromisoformat(prev[:19])
        iso = True
    except Exception:
        iso = False
    if iso or not prev:
        tail = prev[10:19] if len(prev) >= 19 else ""
        return day.strftime("%Y-%m-%d") + tail
    return s


def _v3081_log_columns(conn):
    try:
        return {str(r[1]) for r in conn.execute("PRAGMA table_info(project_log)")}
    except Exception:
        return set()


def _v3081_log_manual(self, project_key):
    """Ручные значения записи и значения проекта на момент правки."""
    try:
        with self._supplier_db_connect() as conn:
            self._v3063_log_init(conn)
            columns = _v3081_log_columns(conn)
            if "manual_fields" not in columns:
                return {}, {}
            row = conn.execute("SELECT * FROM project_log WHERE project_key=?", (str(project_key),)).fetchone()
    except Exception:
        return {}, {}
    if not row:
        return {}, {}
    marked = [f for f in str(row["manual_fields"] or "").split(",") if f]
    values = {f: row[f] for f in marked if f in row.keys()}
    base = {}
    if "manual_base" in row.keys():
        try:
            base = json.loads(str(row["manual_base"] or "") or "{}")
        except Exception:
            base = {}
    return values, base


def _v3081_log_edit(self, project_key, values):
    """Сохраняет ручную правку записи журнала.

    Запоминает и значения проекта на момент правки: пока в проекте они
    не изменились, ручные значения держатся; как только изменились —
    запись снова начинает следовать за проектом.
    """
    fields = [f for f, _label, _kind in V3081_FIELDS if f in values]
    if not fields:
        return False
    with self._supplier_db_connect() as conn:
        self._v3063_log_init(conn)
        row = conn.execute("SELECT * FROM project_log WHERE project_key=?", (str(project_key),)).fetchone()
        marked = {f for f in str((row["manual_fields"] if row else "") or "").split(",") if f}
        base = {}
        if row is not None and "manual_base" in row.keys():
            try:
                base = json.loads(str(row["manual_base"] or "") or "{}")
            except Exception:
                base = {}
        for field in fields:
            if field not in base and row is not None and field in row.keys():
                base[field] = row[field]
        marked.update(fields)
        sets = ", ".join(f"{f}=?" for f in fields)
        conn.execute(f"UPDATE project_log SET {sets}, manual_fields=?, manual_base=? WHERE project_key=?",
                     [values[f] for f in fields]
                     + [",".join(sorted(marked)), json.dumps(base, ensure_ascii=False), str(project_key)])
    return True


# Ручные значения переживают сохранение и открытие проекта.
_v3081_orig_log_upsert = ScreenDesigner._v3063_log_upsert


def _v3081_log_upsert(self, entry, revive=True):
    try:
        manual, base = _v3081_log_manual(self, entry.get("project_key"))
        if manual:
            entry = dict(entry)
            dropped = []
            for field, value in manual.items():
                if str(entry.get(field, "")) == str(base.get(field, entry.get(field, ""))):
                    entry[field] = value          # в проекте не меняли — держим ручное
                else:
                    dropped.append(field)         # в проекте изменили — ручное снимается
            if dropped:
                _v3081_log_drop_manual(self, entry.get("project_key"), dropped)
    except Exception:
        pass
    return _v3081_orig_log_upsert(self, entry, revive=revive)


def _v3081_log_drop_manual(self, project_key, fields):
    """Снимает пометку «правлено вручную» с полей, изменённых в проекте."""
    try:
        with self._supplier_db_connect() as conn:
            row = conn.execute("SELECT manual_fields, manual_base FROM project_log WHERE project_key=?",
                               (str(project_key),)).fetchone()
            if row is None:
                return
            marked = {f for f in str(row["manual_fields"] or "").split(",") if f} - set(fields)
            try:
                base = json.loads(str(row["manual_base"] or "") or "{}")
            except Exception:
                base = {}
            for field in fields:
                base.pop(field, None)
            conn.execute("UPDATE project_log SET manual_fields=?, manual_base=? WHERE project_key=?",
                         (",".join(sorted(marked)), json.dumps(base, ensure_ascii=False), str(project_key)))
    except Exception:
        pass


ScreenDesigner._v3063_log_upsert = _v3081_log_upsert


_v3081_orig_log_init = ScreenDesigner._v3063_log_init


def _v3081_log_init(self, conn):
    _v3081_orig_log_init(self, conn)
    try:
        columns = _v3081_log_columns(conn)
        if "manual_fields" not in columns:
            conn.execute("ALTER TABLE project_log ADD COLUMN manual_fields TEXT DEFAULT ''")
        if "manual_base" not in columns:
            conn.execute("ALTER TABLE project_log ADD COLUMN manual_base TEXT DEFAULT ''")
    except Exception:
        pass


ScreenDesigner._v3063_log_init = _v3081_log_init


def _v3081_edit_dialog(self, parent, record):
    """Окно правки записи журнала. Возвращает значения или None."""
    win = tk.Toplevel(parent)
    win.title("Изменить запись журнала")
    win.geometry("560x300")
    try:
        win.transient(parent)
    except Exception:
        pass
    frame = ttk.Frame(win, padding=12)
    frame.pack(fill="both", expand=True)
    ttk.Label(frame, text="Изменить запись журнала", font=("Arial", 13, "bold")).grid(
        row=0, column=0, columnspan=2, sticky="w", pady=(0, 2))
    ttk.Label(frame, text="Даты в формате ДД.ММ.ГГГГ. Файл проекта на диске не изменяется.",
              foreground="#666666").grid(row=1, column=0, columnspan=2, sticky="w", pady=(0, 10))
    frame.columnconfigure(1, weight=1)
    variables = {}
    for i, (field, label, kind) in enumerate(V3081_FIELDS):
        raw = str(record.get(field, "") or "")
        value = _v3063_date_only(raw) if kind == "date" else raw
        variables[field] = tk.StringVar(value=value)
        ttk.Label(frame, text=label).grid(row=2 + i, column=0, sticky="w", pady=4, padx=(0, 10))
        ttk.Entry(frame, textvariable=variables[field]).grid(row=2 + i, column=1, sticky="ew", pady=4)
    result = {"values": None}

    def save():
        out = {}
        for field, _label, kind in V3081_FIELDS:
            text = str(variables[field].get() or "").strip()
            out[field] = _v3081_parse_date(text, record.get(field, "")) if kind == "date" else text
        if not out.get("name"):
            messagebox.showerror("Изменить запись", "Название проекта не может быть пустым.", parent=win)
            return
        result["values"] = out
        win.destroy()

    bar = ttk.Frame(frame)
    bar.grid(row=2 + len(V3081_FIELDS), column=0, columnspan=2, sticky="e", pady=(14, 0))
    ttk.Button(bar, text="Отмена", command=win.destroy).pack(side="right")
    ttk.Button(bar, text="Сохранить", command=save).pack(side="right", padx=(0, 8))
    win.bind("<Escape>", lambda e: win.destroy())
    try:
        win.grab_set()
    except Exception:
        pass
    self.wait_window(win)
    return result["values"]


def _v3081_sync_open_project(self, record, values):
    """Если правили запись открытого проекта — те же значения в самом проекте."""
    meta = getattr(self, "project_metadata", None)
    if not isinstance(meta, dict):
        return False
    if str(meta.get("supplier_learning_id") or "") != str(record.get("project_key") or ""):
        return False
    try:
        if values.get("name"):
            self.project_name = values["name"]
            var = getattr(self, "project_name_var", None)
            if var is not None:
                var.set(values["name"])
        if values.get("created_at"):
            meta["created_at"] = values["created_at"]
        meta["planned_delivery"] = values.get("delivery_date", "")
        var = getattr(self, "planned_delivery_var", None)
        if var is not None:
            self._v3063_loading_delivery = True
            try:
                var.set(values.get("delivery_date", ""))
            finally:
                self._v3063_loading_delivery = False
        spec = meta.get("specification")
        if isinstance(spec, dict) and values.get("spec_date"):
            spec["uploaded_at"] = values["spec_date"]
    except Exception:
        return False
    return True


# --- кнопка «Изменить запись» добавлена прямо в окно журнала проектов
ScreenDesigner._v3081_log_edit = _v3081_log_edit
ScreenDesigner._v3081_log_manual = _v3081_log_manual


# =====================================================================
# V30.82 — списки по поставщикам: строка «БЕЗ ПОСТАВЩИКА».
# Собирает комплектующие всех подразделов, у которых поставщик не назначен.
# Графа «Поставщик» в таком списке остаётся пустой.
# =====================================================================

V3082_NO_SUPPLIER_ID = "__no_supplier__"
V3082_NO_SUPPLIER_LABEL = "БЕЗ ПОСТАВЩИКА"


def _v3082_is_no_supplier(supplier_id):
    return str(supplier_id or "").strip() == V3082_NO_SUPPLIER_ID


def _v3082_rows_without_supplier(self):
    """Позиции без назначенного поставщика: тот же сбор, фильтр по пустому поставщику."""
    return self._v3063_supplier_rows("")


def _v3082_choose_supplier(self, title, button_text, on_choose):
    """Окно выбора поставщика с дополнительной строкой «БЕЗ ПОСТАВЩИКА»."""
    suppliers = self._project_assigned_suppliers()
    win = tk.Toplevel(self); win.title(title); win.geometry("520x390")
    try: win.transient(self); win.grab_set()
    except Exception: pass
    body = ttk.Frame(win, padding=12); body.pack(fill="both", expand=True)
    ttk.Label(body, text="Выберите поставщика:", font=("Arial", 11, "bold")).pack(anchor="w", pady=(0, 10))
    tree = ttk.Treeview(body, columns=("name", "count"), show="headings", selectmode="browse", height=12)
    tree.heading("name", text="Поставщик"); tree.heading("count", text="Назначенных позиций")
    tree.column("name", width=350, anchor="w"); tree.column("count", width=120, anchor="center", stretch=False)
    assignments = getattr(self, "project_supplier_assignments", {}) or {}
    for sid, name in suppliers:
        tree.insert("", "end", iid=sid, values=(name, sum(1 for x in assignments.values() if str(x) == sid)))
    # V30.82: всё, что осталось без поставщика, — отдельной строкой.
    tree.insert("", "end", iid=V3082_NO_SUPPLIER_ID, values=(V3082_NO_SUPPLIER_LABEL, ""))
    tree.pack(fill="both", expand=True)
    actions = ttk.Frame(body); actions.pack(fill="x", pady=(10, 0))

    def go():
        sel = tree.selection()
        if not sel:
            messagebox.showwarning(title, "Выберите поставщика.", parent=win); return
        sid = sel[0]; win.destroy(); on_choose(sid)
    ttk.Button(actions, text="Отмена", command=win.destroy).pack(side="right")
    ttk.Button(actions, text=button_text, command=go).pack(side="right", padx=(0, 8))
    tree.bind("<Double-1>", lambda e: go())


ScreenDesigner._v3063_choose_supplier = _v3082_choose_supplier


def _v3082_print_components_by_supplier(self):
    """Окно «Печать по поставщикам» со строкой «БЕЗ ПОСТАВЩИКА»."""
    suppliers = self._project_assigned_suppliers()
    win = tk.Toplevel(self)
    win.title("Печать комплектующих по поставщику")
    win.geometry("520x390")
    try:
        win.transient(self); win.grab_set()
    except Exception:
        pass
    body = ttk.Frame(win, padding=12); body.pack(fill="both", expand=True)
    ttk.Label(body, text="Выберите поставщика, комплектующие которого нужно распечатать:",
              font=("Arial", 11, "bold"), wraplength=480, justify="left").pack(anchor="w", pady=(0, 10))
    tree = ttk.Treeview(body, columns=("name", "count"), show="headings", selectmode="browse", height=12)
    tree.heading("name", text="Поставщик"); tree.heading("count", text="Назначенных позиций")
    tree.column("name", width=350, anchor="w"); tree.column("count", width=120, anchor="center", stretch=False)
    assignments = getattr(self, "project_supplier_assignments", {}) or {}
    for sid, name in suppliers:
        tree.insert("", "end", iid=sid, values=(name, sum(1 for x in assignments.values() if str(x) == sid)))
    tree.insert("", "end", iid=V3082_NO_SUPPLIER_ID, values=(V3082_NO_SUPPLIER_LABEL, ""))
    tree.pack(fill="both", expand=True)
    actions = ttk.Frame(body); actions.pack(fill="x", pady=(10, 0))

    def do_print():
        sel = tree.selection()
        if not sel:
            messagebox.showwarning("Печать по поставщикам", "Выберите поставщика.", parent=win); return
        sid = sel[0]; win.destroy()
        self._print_components_for_supplier_id(sid)
    ttk.Button(actions, text="Отмена", command=win.destroy).pack(side="right")
    ttk.Button(actions, text="Печатать", command=do_print).pack(side="right", padx=(0, 8))
    tree.bind("<Double-1>", lambda e: do_print())
    return win


ScreenDesigner._print_components_by_supplier = _v3082_print_components_by_supplier


_v3082_orig_print_for_supplier = ScreenDesigner._print_components_for_supplier_id


def _v3082_print_components_for_supplier_id(self, supplier_id):
    if not _v3082_is_no_supplier(supplier_id):
        return _v3082_orig_print_for_supplier(self, supplier_id)
    rows = _v3082_rows_without_supplier(self)
    if not rows:
        messagebox.showwarning("Печать по поставщикам",
                               "В текущем проекте все комплектующие назначены поставщикам.")
        return
    try:
        pages = self._v3063_build_supplier_pages(rows, V3082_NO_SUPPLIER_LABEL)
        product = {"mode": MODE_RZD, "module_article": "Комплектующие_без_поставщика"}
        path = self._make_print_pdf_path(product, 1, False)
        self._save_pdf_with_text_layer(pages, path)
        self._open_pdf_path(path)
    except Exception as exc:
        import traceback; self._print_debug_log(traceback.format_exc())
        messagebox.showerror("Печать по поставщикам", f"Не удалось сформировать список комплектующих:\n{exc}")


ScreenDesigner._print_components_for_supplier_id = _v3082_print_components_for_supplier_id


def _v3082_download_components_by_supplier(self):
    def chosen(sid):
        if _v3082_is_no_supplier(sid):
            supplier_name, label = "", V3082_NO_SUPPLIER_LABEL
            rows = _v3082_rows_without_supplier(self)
            empty_text = "В текущем проекте все комплектующие назначены поставщикам."
        else:
            supplier_name = self._supplier_name_by_id(sid)
            label = supplier_name
            rows = self._v3063_supplier_rows(supplier_name)
            empty_text = f"В текущем проекте нет комплектующих, назначенных поставщику:\n{supplier_name}"
        if not rows:
            messagebox.showwarning("Скачать список по поставщикам", empty_text); return
        try:
            pages = self._v3063_build_supplier_pages(rows, label)
        except Exception as exc:
            import traceback; self._print_debug_log(traceback.format_exc())
            messagebox.showerror("Скачать список по поставщикам", f"Не удалось сформировать список:\n{exc}"); return
        self._v3063_preview_and_save(
            pages, "Список по поставщику",
            self._v3063_project_file_base(f"Комплектующие_{self._safe_filename_part(label)}"),
            lambda path: self._v3063_save_supplier_xlsx(rows, label, path))
    self._v3063_choose_supplier("Скачать список по поставщикам", "Предпросмотр", chosen)


ScreenDesigner._download_components_by_supplier = _v3082_download_components_by_supplier
ScreenDesigner._v3082_rows_without_supplier = _v3082_rows_without_supplier



# =====================================================================
# V30.83 — переименование позиции в справочнике меняет название
# и в комплектующих. Запоминается пара «старое имя → новое», и все
# расчётные названия выводятся уже новым именем: в комплектующих,
# расходе по изделиям, списках по поставщикам, журнале и печати.
# Внутренние привязки (поставщик, вес, материал раскроя, группа)
# продолжают работать по исходному имени.
#
# Кроме того: «Термоусадочная трубка» переименована в
# «Термоусадочная трубка ТТУ 3/1.5 + ТТУ 2/1» во всех расчётах
# и в справочнике, включая сохранённый пользовательский справочник.
# =====================================================================

V3083_SHRINK_OLD = "Термоусадочная трубка"
V3083_SHRINK_NEW = "Термоусадочная трубка ТТУ 3/1.5 + ТТУ 2/1"


def _v3083_norm(name):
    return re.sub(r"\s+", " ", str(name or "")).strip().casefold().replace("ё", "е")


def _v3083_renames(self):
    data = getattr(self, "_reference_renames", None)
    if not isinstance(data, dict):
        data = {}
        self._reference_renames = data
    return data


def _v3083_rename_src(self):
    """Исходное написание переименованных позиций (с регистром)."""
    data = getattr(self, "_reference_rename_src", None)
    if not isinstance(data, dict):
        data = {}
        self._reference_rename_src = data
    return data


def _v3083_rename_name(self, name):
    """Исходное название → пользовательское. Учитывает суффиксы вида «… — R391 мм»."""
    renames = _v3083_renames(self)
    if not renames:
        return name
    raw = str(name or "")
    direct = renames.get(_v3083_norm(raw))
    if direct:
        return direct
    for old_key, new_name in renames.items():
        prefix = old_key
        low = _v3083_norm(raw)
        if low.startswith(prefix) and len(raw) > len(prefix):
            tail = raw[len(prefix):]
            if tail[:1] in (" ", ",", "—", "-"):
                return new_name + tail
    return raw


def _v3083_original_name(self, name):
    """Пользовательское название → исходное, для внутренних привязок."""
    renames = _v3083_renames(self)
    if not renames:
        return name
    raw = str(name or "")
    low = _v3083_norm(raw)
    source = _v3083_rename_src(self)
    for old_key, new_name in renames.items():
        original = source.get(old_key, old_key)
        new_low = _v3083_norm(new_name)
        if low == new_low:
            return original
        if low.startswith(new_low) and len(raw) > len(new_name):
            tail = raw[len(new_name):]
            if tail[:1] in (" ", ",", "—", "-"):
                return original + tail
    return raw


def _v3083_rename_rows(self, rows):
    return [(_v3083_rename_name(self, n), u, q) for n, u, q in rows]


# --- расчётные списки комплектующих выводятся переименованными
for _name in ("_static_mcd_component_rows", "_static_rzd_component_rows",
              "_dynamic_mcd_component_rows_v1972"):
    def _make(original):
        def wrapper(self, items):
            return _v3083_rename_rows(self, original(self, items))
        return wrapper
    setattr(ScreenDesigner, _name, _make(getattr(ScreenDesigner, _name)))


# --- внутренние привязки продолжают работать по исходному имени
_v3083_orig_cut_key = ScreenDesigner._cut_material_key


def _v3083_cut_material_key(self, name):
    key = _v3083_orig_cut_key(self, name)
    if key:
        return key
    return _v3083_orig_cut_key(self, _v3083_original_name(self, name))


ScreenDesigner._cut_material_key = _v3083_cut_material_key


_v3083_orig_weight = ScreenDesigner._component_weight_kg


def _v3083_component_weight_kg(self, name, unit, qty):
    value = _v3083_orig_weight(self, name, unit, qty)
    if value:
        return value
    original = _v3083_original_name(self, name)
    if original != name:
        return _v3083_orig_weight(self, original, unit, qty)
    return value


ScreenDesigner._component_weight_kg = _v3083_component_weight_kg


_v3083_orig_group = ScreenDesigner._reference_group_for_component


def _v3083_reference_group_for_component(self, name):
    return _v3083_orig_group(self, _v3083_original_name(self, name))


ScreenDesigner._reference_group_for_component = _v3083_reference_group_for_component


# --- привязка поставщика: старые назначения продолжают действовать
_v3083_orig_supplier_key = ScreenDesigner._component_supplier_key


def _v3083_component_supplier_key(self, name):
    key = _v3083_orig_supplier_key(self, name)
    assignments = getattr(self, "project_supplier_assignments", {}) or {}
    if key in assignments:
        return key
    original = _v3083_orig_supplier_key(self, _v3083_original_name(self, name))
    return original if original in assignments else key


ScreenDesigner._component_supplier_key = _v3083_component_supplier_key


def _v3083_register_rename(self, old_name, new_name):
    """Запоминает переименование и переносит назначение поставщика."""
    old_name = str(old_name or "").strip()
    new_name = str(new_name or "").strip()
    if not old_name or not new_name or old_name == new_name:
        return
    renames = _v3083_renames(self)
    source = _v3083_norm(old_name)
    # Если позицию переименовывают повторно, храним связь с исходным именем.
    for key, value in list(renames.items()):
        if _v3083_norm(value) == source:
            source = key
            break
    src = _v3083_rename_src(self)
    if _v3083_norm(new_name) == source:
        renames.pop(source, None)
        src.pop(source, None)
    else:
        renames[source] = new_name
        src.setdefault(source, old_name)
    assignments = getattr(self, "project_supplier_assignments", None)
    if isinstance(assignments, dict):
        old_key = _v3083_orig_supplier_key(self, old_name)
        new_key = _v3083_orig_supplier_key(self, new_name)
        if old_key in assignments and new_key not in assignments:
            assignments[new_key] = assignments[old_key]
    try:
        self._reference_save()
    except Exception:
        pass
    try:
        self._refresh_components_table()
    except Exception:
        pass


ScreenDesigner._v3083_register_rename = _v3083_register_rename
ScreenDesigner._v3083_rename_name = _v3083_rename_name
ScreenDesigner._v3083_original_name = _v3083_original_name


# --- переименования хранятся рядом со справочником
_v3083_orig_reference_save = ScreenDesigner._reference_save


def _v3083_reference_save(self):
    _atomic_write_text(self._reference_file(), json.dumps(
        {"sections": self._reference_data,
         "history": self._reference_history,
         "renames": _v3083_renames(self),
         "rename_src": _v3083_rename_src(self)},
        ensure_ascii=False, indent=2))


ScreenDesigner._reference_save = _v3083_reference_save


_v3083_orig_reference_load = ScreenDesigner._reference_load


def _v3083_reference_load(self):
    data = _v3083_orig_reference_load(self)
    renames, source = {}, {}
    try:
        path = self._reference_file()
        if path.exists():
            saved = json.loads(path.read_text(encoding="utf-8"))
            for key, value in (saved.get("renames", {}) or {}).items():
                if str(value or "").strip():
                    renames[_v3083_norm(key)] = str(value)
            for key, value in (saved.get("rename_src", {}) or {}).items():
                if str(value or "").strip():
                    source[_v3083_norm(key)] = str(value)
    except Exception:
        renames, source = {}, {}
    self._reference_renames = renames
    self._reference_rename_src = source
    return _v3083_shrink_rule(data)


ScreenDesigner._reference_load = _v3083_reference_load


def _v3083_shrink_rule(data):
    """Миграция сохранённого справочника: новое название термоусадочной трубки."""
    for rows in (data or {}).values():
        for row in rows or []:
            if row and str(row[0]).strip() == V3083_SHRINK_OLD:
                row[0] = V3083_SHRINK_NEW
    return data


_v3083_orig_reference_defaults = ScreenDesigner._reference_defaults
ScreenDesigner._reference_defaults = lambda self: _v3083_shrink_rule(_v3083_orig_reference_defaults(self))


# --- переименования уезжают вместе с проектом
_v3083_orig_pack_reference = _v3080_pack_reference


def _v3083_pack_reference(self):
    block = _v3083_orig_pack_reference(self)
    try:
        block["renames"] = dict(_v3083_renames(self))
        block["rename_src"] = dict(_v3083_rename_src(self))
    except Exception:
        pass
    return block


_v3080_pack_reference = _v3083_pack_reference
ScreenDesigner._v3080_pack_reference = _v3083_pack_reference


# =====================================================================
# V30.84 — переименование уплотнителей и копирование строк из вкладки
# «Комплектующие».
#   • «Уплотнитель МЦД» → «Уплотнитель 12х10мм»
#   • «Уплотнитель резиновый коричневый» → «Уплотнитель 9х7,4мм»
#     (в расчётах, справочнике и в сохранённом справочнике при загрузке)
#   • В таблице комплектующих работает выделение нескольких строк,
#     Ctrl/Cmd+C копирует их целиком, Ctrl/Cmd+A выделяет всё,
#     правый щелчок открывает «Копировать». Новых кнопок не добавлено.
# =====================================================================

V3084_RENAMES = {
    "Уплотнитель МЦД": "Уплотнитель 12х10мм",
    "Уплотнитель резиновый коричневый": "Уплотнитель 9х7,4мм",
}


def _v3084_reference_rule(data):
    """Миграция сохранённого справочника на новые названия уплотнителей."""
    for rows in (data or {}).values():
        for row in rows or []:
            if row:
                new = V3084_RENAMES.get(str(row[0]).strip())
                if new:
                    row[0] = new
    return data


_v3084_orig_reference_defaults = ScreenDesigner._reference_defaults
ScreenDesigner._reference_defaults = lambda self: _v3084_reference_rule(_v3084_orig_reference_defaults(self))
_v3084_orig_reference_load = ScreenDesigner._reference_load
ScreenDesigner._reference_load = lambda self: _v3084_reference_rule(_v3084_orig_reference_load(self))


# ---------------------------------------------------------------------
# Копирование строк из таблицы комплектующих
# ---------------------------------------------------------------------
def _v3084_cell_text(value):
    text = str(value if value is not None else "")
    return text.replace(".", ",") if re.fullmatch(r"-?\d+\.\d+", text) else text


def _v3084_row_text(tree, iid):
    cells = [str(tree.item(iid, "text") or "")]
    cells += [_v3084_cell_text(v) for v in (tree.item(iid, "values") or [])]
    while cells and not cells[-1].strip():
        cells.pop()
    return "\t".join(cells)


def _v3084_copy_components(self, _event=None):
    """Копирует выделенные строки целиком: ячейки через табуляцию."""
    tree = getattr(self, "components_tree", None)
    if tree is None:
        return "break"
    selection = list(tree.selection())
    if not selection:
        return "break"
    order = []

    def walk(parent=""):
        for iid in tree.get_children(parent):
            order.append(iid)
            walk(iid)
    walk()
    index = {iid: i for i, iid in enumerate(order)}
    selection.sort(key=lambda iid: index.get(iid, 0))
    text = "\n".join(_v3084_row_text(tree, iid) for iid in selection)
    try:
        self.clipboard_clear()
        self.clipboard_append(text)
    except Exception:
        return "break"
    var = getattr(self, "component_summary_var", None)
    if var is not None:
        try:
            base = str(var.get()).split("   ✓", 1)[0]
            var.set(f"{base}   ✓ Скопировано строк: {len(selection)}")
        except Exception:
            pass
    return "break"


def _v3084_select_all_components(self, _event=None):
    tree = getattr(self, "components_tree", None)
    if tree is None:
        return "break"
    items = []

    def walk(parent=""):
        for iid in tree.get_children(parent):
            items.append(iid)
            walk(iid)
    walk()
    if items:
        tree.selection_set(items)
    return "break"


def _v3084_components_menu(self, event):
    tree = getattr(self, "components_tree", None)
    if tree is None:
        return
    iid = tree.identify_row(event.y)
    if iid and iid not in tree.selection():
        tree.selection_set(iid)
    menu = tk.Menu(self, tearoff=0)
    menu.add_command(label="Копировать", command=self._v3084_copy_components)
    menu.add_command(label="Выделить всё", command=self._v3084_select_all_components)
    try:
        menu.tk_popup(event.x_root, event.y_root)
    finally:
        menu.grab_release()


_v3084_orig_build_ui = ScreenDesigner._build_ui


def _v3084_build_ui(self):
    _v3084_orig_build_ui(self)
    tree = getattr(self, "components_tree", None)
    if tree is None:
        return
    try:
        tree.configure(selectmode="extended")
        for sequence in ("<Control-c>", "<Control-C>", "<Command-c>", "<Command-C>",
                         "<Control-Insert>"):
            tree.bind(sequence, self._v3084_copy_components, add="+")
        for sequence in ("<Control-a>", "<Control-A>", "<Command-a>", "<Command-A>"):
            tree.bind(sequence, self._v3084_select_all_components, add="+")
        for sequence in ("<Button-3>", "<Button-2>"):
            tree.bind(sequence, self._v3084_components_menu, add="+")
    except Exception:
        pass


ScreenDesigner._build_ui = _v3084_build_ui
ScreenDesigner._v3084_copy_components = _v3084_copy_components
ScreenDesigner._v3084_select_all_components = _v3084_select_all_components
ScreenDesigner._v3084_components_menu = _v3084_components_menu



# =====================================================================
# V30.85 — списки по поставщикам: сводный первый лист и столбец «Заказ».
#   • Первым листом идут жёлтые итоги (погонаж, блоки питания,
#     светодиоды), а под ними — сумма одинаковых комплектующих
#     без разбивки по изделиям.
#   • Дальше, с новой страницы, прежний подробный список по артикулам.
#   • Столбец «Вес, кг» заменён на пустой столбец «Заказ».
# Расчёты и состав позиций не меняются.
# =====================================================================

V3085_SUMMARY_GROUP_SUFFIX = " — сводно"


def _v3085_summary_rows(self, supplier_name):
    """Сумма одинаковых комплектующих без разбивки по изделиям."""
    merged, order, groups = {}, [], []
    for row in self._v3063_supplier_rows_v3063(supplier_name):
        group = str(row.get("group", "") or "")
        if group not in groups:
            groups.append(group)
        key = (group, str(row.get("name", "")).casefold(), str(row.get("unit", "")).casefold())
        if key not in merged:
            merged[key] = {"kind": "item", "group": group, "article": "",
                           "name": str(row.get("name", "")), "unit": str(row.get("unit", "")),
                           "qty": 0.0, "weight": None, "sources": [],
                           "supplier": str(row.get("supplier", "") or "")}
            order.append(key)
        item = merged[key]
        item["qty"] += float(row.get("qty") or 0)
        source = str(row.get("source", "") or "")
        if source and source not in item["sources"]:
            item["sources"].append(source)
    out = []
    for key in sorted(order, key=lambda k: (groups.index(k[0]), k[1])):
        item = merged[key]
        item["source"] = " / ".join(item["sources"])
        item.pop("sources", None)
        item["group"] = item["group"] + V3085_SUMMARY_GROUP_SUFFIX
        out.append(item)
    return out


_v3085_orig_supplier_rows = ScreenDesigner._v3063_supplier_rows


def _v3085_supplier_rows(self, supplier_name):
    detail = _v3085_orig_supplier_rows(self, supplier_name)
    if not detail:
        return detail
    totals = [r for r in detail if r.get("kind") == "total"]
    body = [r for r in detail if r.get("kind") != "total"]
    summary = _v3085_summary_rows(self, supplier_name)
    if not summary and not totals:
        return body
    first = totals + summary
    if not body:
        return first
    return first + [{"kind": "pagebreak", "group": "", "article": "", "name": "",
                     "unit": "", "qty": None, "weight": None, "source": "",
                     "supplier": supplier_name}] + body


ScreenDesigner._v3063_supplier_rows = _v3085_supplier_rows


def _v3085_build_supplier_pages(self, rows, supplier_name, page_offset=0):
    from PIL import Image, ImageDraw
    W, H = 2480, 3508
    margin = 120; header_h = 290; row_h = 76
    widths = [80, 330, 820, 120, 190, 180, 220, 300]
    cols = [margin]
    for w in widths:
        cols.append(cols[-1] + w)
    cols[-1] = W - margin
    labels = ["№", "Артикул", "Комплектующая", "Ед.", "Кол-во", "Заказ", "Источник", "Поставщик"]
    aligns = ["center", "left", "left", "center", "center", "center", "left", "left"]
    project = str(self.project_name_var.get().strip() or self.project_name)
    fills = {"article": (243, 246, 250), "total": (255, 242, 204)}
    pages = []

    def fit(text, maxw, size=24, bold=False):
        f = self._font_for_print(size, bold); t = str(text or "")
        while size > 13 and f.getbbox(t)[2] > maxw:
            size -= 1; f = self._font_for_print(size, bold)
        return f

    def new_page(page_no):
        im = Image.new("RGB", (W, H), "white"); d = ImageDraw.Draw(im)
        d.text((margin, 80), "КОМПЛЕКТУЮЩИЕ ПО ПОСТАВЩИКУ", font=self._font_for_print(44, True), fill="black")
        small = self._font_for_print(25, False)
        d.text((margin, 145), f"Проект: {project}", font=small, fill="black")
        d.text((margin, 185), f"Поставщик: {supplier_name}", font=self._font_for_print(27, True), fill="black")
        d.text((margin, 225), f"Страница {page_no + page_offset}", font=small, fill="black")
        y = header_h
        for i in range(len(labels)):
            d.rectangle((cols[i], y, cols[i + 1], y + row_h), outline="black", width=2)
            d.text((cols[i] + 8, y + 20), labels[i], font=fit(labels[i], cols[i + 1] - cols[i] - 16, 24, True), fill="black")
        im._selectable_text_layer = []
        return im, d, y + row_h

    page, d, y = new_page(1)
    page_no = 1; n = 0; last_group = None
    for rec in rows:
        if rec.get("kind") == "pagebreak":
            # V30.85: сводный лист всегда заканчивается здесь.
            pages.append(page); page_no += 1
            page, d, y = new_page(page_no); last_group = None
            continue
        needed = row_h + (row_h if rec["group"] != last_group else 0)
        if y + needed > H - margin:
            pages.append(page); page_no += 1
            page, d, y = new_page(page_no); last_group = None
        if rec["group"] != last_group:
            d.rectangle((margin, y, W - margin, y + row_h), fill=(235, 239, 244), outline="black", width=2)
            d.text((margin + 10, y + 20), rec["group"], font=self._font_for_print(27, True), fill="black")
            page._selectable_text_layer.append({"text": rec["group"], "bbox": (margin + 10, y + 10, W - margin - 10, y + row_h - 10), "font_size": 27})
            y += row_h; last_group = rec["group"]
        kind = rec.get("kind", "item")
        bold = kind in ("article", "total")
        if kind in ("item", "cut"):
            n += 1
        num = str(n) if kind in ("item", "cut") else ""
        qty = self._format_component_qty(round(rec["qty"], 3)) if rec.get("qty") is not None else ""
        name = ("    " + rec["name"]) if kind == "cut" else rec["name"]
        vals = [num, rec.get("article", ""), name, rec["unit"], qty, "", rec.get("source", ""), rec.get("supplier", "")]
        for i, val in enumerate(vals):
            fill = fills.get(kind)
            d.rectangle((cols[i], y, cols[i + 1], y + row_h), outline="black", width=2, fill=fill)
            f = fit(val, cols[i + 1] - cols[i] - 16, 24, bold)
            box = d.textbbox((0, 0), val, font=f); tw = box[2] - box[0]
            x = cols[i] + 8 if aligns[i] == "left" else (cols[i] + cols[i + 1] - tw) // 2
            d.text((x, y + 22), val, font=f, fill="black")
            page._selectable_text_layer.append({"text": val, "bbox": (cols[i] + 5, y + 5, cols[i + 1] - 5, y + row_h - 5), "font_size": 24})
        y += row_h
    pages.append(page)
    return pages


def _v3085_save_supplier_xlsx(self, rows, supplier_name, path):
    from openpyxl import Workbook
    from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
    wb = Workbook(); ws = wb.active; ws.title = "По поставщику"
    thin = Side(style="thin", color="999999"); border = Border(left=thin, right=thin, top=thin, bottom=thin)
    ws["A1"] = "КОМПЛЕКТУЮЩИЕ ПО ПОСТАВЩИКУ"; ws["A1"].font = Font(bold=True, size=14)
    ws["A2"] = f"Проект: {self.project_name_var.get().strip() or self.project_name}    Поставщик: {supplier_name}"
    headers = ["№", "Артикул", "Комплектующая", "Ед.", "Кол-во", "Заказ", "Источник", "Поставщик"]
    for c, h in enumerate(headers, 1):
        cell = ws.cell(4, c, h); cell.font = Font(bold=True, color="FFFFFF")
        cell.fill = PatternFill("solid", fgColor="1F4E78"); cell.border = border
        cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
    fills = {"article": "F3F6FA", "total": "FFF2CC"}
    r = 5; n = 0; last_group = None
    for rec in rows:
        if rec.get("kind") == "pagebreak":
            r += 1
            last_group = None
            continue
        if rec["group"] != last_group:
            ws.cell(r, 1, rec["group"]).font = Font(bold=True)
            for c in range(1, 9):
                ws.cell(r, c).fill = PatternFill("solid", fgColor="E8EEF5"); ws.cell(r, c).border = border
            ws.merge_cells(start_row=r, start_column=1, end_row=r, end_column=8)
            r += 1; last_group = rec["group"]
        kind = rec.get("kind", "item")
        if kind in ("item", "cut"):
            n += 1
        vals = [n if kind in ("item", "cut") else None, rec.get("article", "") or None,
                ("    " + rec["name"]) if kind == "cut" else rec["name"], rec["unit"],
                round(rec["qty"], 3) if rec.get("qty") is not None else None,
                None,
                rec.get("source", "") or None, rec.get("supplier", "")]
        for c, v in enumerate(vals, 1):
            cell = ws.cell(r, c, v); cell.border = border
            cell.alignment = Alignment(vertical="center", wrap_text=True, horizontal="center" if c in (1, 4, 5, 6) else "left")
            if kind in fills:
                cell.fill = PatternFill("solid", fgColor=fills[kind])
            if kind in ("article", "total"):
                cell.font = Font(bold=True)
        r += 1
    for c, w in enumerate([6, 26, 60, 8, 12, 12, 18, 30], 1):
        ws.column_dimensions[get_column_letter_v3063(c)].width = w
    ws.freeze_panes = "A5"
    wb.save(path)



for _name, _fn in list({
    "_v3063_build_supplier_pages": _v3085_build_supplier_pages,
    "_v3063_save_supplier_xlsx": _v3085_save_supplier_xlsx,
    "_v3085_summary_rows": _v3085_summary_rows,
}.items()):
    setattr(ScreenDesigner, _name, _fn)



